class _InputChannelRouteOption {
  final int channelStart;
  final int channelCount;

  const _InputChannelRouteOption({
    required this.channelStart,
    required this.channelCount,
  });

  String get label {
    if (channelCount <= 1) {
      return 'Mono ${channelStart + 1}';
    }
    return 'Stereo ${channelStart + 1}+${channelStart + channelCount}';
  }
}

class _AutomationTargetMeta {
  final String targetId;
  final String label;
  final int effectIndex; // -1 = row volume
  final String paramId;
  final String type; // float|bool|choice
  final double min;
  final double max;
  final double initialNormalized;
  final bool isOrphan;
  final bool uiVisible;

  const _AutomationTargetMeta({
    required this.targetId,
    required this.label,
    required this.effectIndex,
    required this.paramId,
    required this.type,
    required this.min,
    required this.max,
    this.initialNormalized = 0.5,
    this.isOrphan = false,
    this.uiVisible = true,
  });

  bool get isVolume => targetId == 'volume';

  _AutomationTargetMeta copyWith({
    String? targetId,
    String? label,
    int? effectIndex,
    String? paramId,
    String? type,
    double? min,
    double? max,
    double? initialNormalized,
    bool? isOrphan,
    bool? uiVisible,
  }) {
    return _AutomationTargetMeta(
      targetId: targetId ?? this.targetId,
      label: label ?? this.label,
      effectIndex: effectIndex ?? this.effectIndex,
      paramId: paramId ?? this.paramId,
      type: type ?? this.type,
      min: min ?? this.min,
      max: max ?? this.max,
      initialNormalized: initialNormalized ?? this.initialNormalized,
      isOrphan: isOrphan ?? this.isOrphan,
      uiVisible: uiVisible ?? this.uiVisible,
    );
  }

  Map<String, dynamic> toUiMap() => <String, dynamic>{
        'id': targetId,
        'label': label,
        'fullLabel': label,
        'isVolume': isVolume,
        'isOrphan': isOrphan,
        'effectIndex': effectIndex,
        'paramId': paramId,
        'type': type,
        'min': min,
        'max': max,
        'initialNormalized': initialNormalized.clamp(0.0, 1.0),
        'uiVisible': uiVisible,
      };

  AutomationLaneSnapshot toLaneSnapshot(List<AutomationPoint> points) {
    return AutomationLaneSnapshot(
      targetId: targetId,
      label: label,
      effectIndex: effectIndex,
      paramId: paramId,
      type: type,
      min: min,
      max: max,
      points: points.map((p) => p.copy()).toList(growable: false),
    );
  }

  static _AutomationTargetMeta fromLaneSnapshot(AutomationLaneSnapshot lane) {
    final laneInitial = lane.points.isNotEmpty
        ? lane.points.first.volume.clamp(0.0, 1.0).toDouble()
        : (lane.targetId == 'volume' ? 0.75 : 0.5);
    return _AutomationTargetMeta(
      targetId: lane.targetId,
      label: lane.label,
      effectIndex: lane.effectIndex,
      paramId: lane.paramId,
      type: lane.type,
      min: lane.min,
      max: lane.max,
      initialNormalized: laneInitial,
      isOrphan: false,
    );
  }
}

class _ParsedAutomationTargetId {
  final String scope;
  final String section;
  final bool isVolume;
  final int legacyEffectIndex;
  final String effectKey;
  final String paramId;
  final String mixParamId;

  const _ParsedAutomationTargetId({
    required this.scope,
    required this.section,
    required this.isVolume,
    required this.legacyEffectIndex,
    required this.effectKey,
    required this.paramId,
    this.mixParamId = '',
  });

  bool get isMaster => scope == 'master';
  bool get isRowScoped => !isMaster;
  bool get isEffectParameter => section == 'effect';
  bool get isMixParameter => section == 'mix' || isVolume;
}

