  Future<void> _trackPluginParameterCommitted({
    required String scope,
    required String paramId,
    required Object? oldValue,
    required Object? newValue,
    int? rowIndex,
    int? effectIndex,
  }) async {
    try {
      String pluginName = '';
      if (scope == 'track' && rowIndex != null && effectIndex != null) {
        final names = await JuceAudioEngine.getTrackEffectsForRow(rowIndex);
        if (effectIndex >= 0 && effectIndex < names.length) {
          pluginName = names[effectIndex];
        }
      } else if (scope == 'master' && effectIndex != null) {
        final names = await JuceAudioEngine.getMasterEffects();
        if (effectIndex >= 0 && effectIndex < names.length) {
          pluginName = names[effectIndex];
        }
      }
      unawaited(
        AnalyticsService.instance.track(
          AnalyticsEvents.pluginParameterCommitted(
            pluginName: pluginName.isEmpty ? 'unknown_plugin' : pluginName,
            paramId: paramId,
            scope: scope,
            projectId: _projectId,
            rowIndex: rowIndex,
            oldValue: _analyticsPropertyValue(oldValue),
            newValue: _analyticsPropertyValue(newValue),
          ),
        ),
      );
    } catch (_) {}
  }

  Map<String, dynamic> _buildProjectTelemetrySnapshot(
    Map<String, dynamic> projectJson,
  ) {
    final tracks = (projectJson['tracks'] as List?)
            ?.whereType<Map>()
            .toList(growable: false) ??
        const <Map>[];
    final rowEffects = (projectJson['rowEffects'] as List?)
            ?.whereType<Map>()
            .toList(growable: false) ??
        const <Map>[];
    final master = projectJson['master'];
    final masterEffectsRaw = master is Map ? master['effects'] : null;
    final masterEffects = master is Map
        ? (masterEffectsRaw is List
            ? masterEffectsRaw.whereType<Map>().toList(growable: false)
            : masterEffectsRaw is Map
                ? (masterEffectsRaw['effects'] as List?)
                        ?.whereType<Map>()
                        .toList(growable: false) ??
                    const <Map>[]
                : const <Map>[])
        : const <Map>[];
    final assistantChat = projectJson['assistantChat'];

    final instrumentIds = tracks
        .map((track) => (track['instrumentId'] ?? '').toString().trim())
        .where((value) => value.isNotEmpty)
        .toSet()
        .toList(growable: false)
      ..sort();
    final trackEffectIds = rowEffects
        .expand((row) => ((row['effects'] as List?) ?? const <Object?>[])
            .whereType<Map>()
            .map((fx) => (fx['effectId'] ?? '').toString().trim()))
        .where((value) => value.isNotEmpty)
        .toList(growable: false);
    final masterEffectIds = masterEffects
        .map((fx) => (fx['effectId'] ?? '').toString().trim())
        .where((value) => value.isNotEmpty)
        .toList(growable: false);
    final chatMessages =
        assistantChat is List ? assistantChat.whereType<Map>().length : 0;

    return <String, dynamic>{
      'captured_at': DateTime.now().toUtc().toIso8601String(),
      'tempo_bpm': projectJson['tempoBpm'],
      'row_count': (projectJson['rows'] as List?)?.length ?? _rows.length,
      'track_count': tracks.length,
      'instrument_ids': instrumentIds,
      'track_effect_ids': trackEffectIds,
      'master_effect_ids': masterEffectIds,
      'has_assistant_chat': assistantChat != null,
      'assistant_message_count': chatMessages,
      'producer_capture_enabled': _showProducerCaptureUi,
    };
  }

  Map<String, dynamic> _buildFeedbackProjectSettings() {
    final selectedClip = (_timelinePrimarySelectedClipIndex >= 0 &&
            _timelinePrimarySelectedClipIndex < _audioTracks.length)
        ? _audioTracks[_timelinePrimarySelectedClipIndex]
        : null;
    final visibleRowNames = _rows
        .take(12)
        .map((row) => row.name.trim())
        .where((name) => name.isNotEmpty)
        .toList(growable: false);
    return <String, dynamic>{
      'project_id': _projectId,
      'project_name': _projectName,
      'mode': _resolvedMode,
      'tempo_bpm': _tempo,
      'metronome_enabled': _metronomeEnabled,
      'loop_enabled': _loopEnabled,
      if (_loopEnabled) 'loop_start_ms': _loopStartMs,
      if (_loopEnabled) 'loop_end_ms': _loopEndMs,
      'row_count': _rows.length,
      'track_count': _audioTracks.length,
      'selected_row_index': _selectedRow,
      if (selectedClip != null) 'selected_clip_label': selectedClip.label,
      if (_producerCaptureAllowlistUsername.isNotEmpty)
        'producer_capture_allowlist_username':
            _producerCaptureAllowlistUsername,
      'producer_capture_enabled':
          _isProducerCaptureUiVisible || _producerDataMode,
      'sample_browser_open': _sampleBrowserVisible,
      'master_rack_open': _showMasterRack,
      if (visibleRowNames.isNotEmpty) 'row_names': visibleRowNames,
    };
  }

  List<String> _visibleAiRowNames() {
    return _rows.map((row) => row.name.trim()).toList(growable: false);
  }

  Future<FeedbackScreenshotAttachment> _captureFeedbackScreenshot() async {
    final previousChatExpanded = _chatExpanded;
    final previousChatInputActive = _chatInputActive;
    final pixelRatio =
        MediaQuery.maybeDevicePixelRatioOf(context)?.clamp(1.0, 2.0) ?? 1.0;

    if (mounted) {
      setState(() {
        _chatExpanded = false;
        _chatInputActive = false;
      });
    }
    _chatFocusNode.unfocus();

    await Future<void>.delayed(const Duration(milliseconds: 90));
    await WidgetsBinding.instance.endOfFrame;

    try {
      final boundaryContext = _feedbackScreenshotBoundaryKey.currentContext;
      final boundaryRenderObject = boundaryContext?.findRenderObject();
      if (boundaryRenderObject is! RenderRepaintBoundary) {
        throw StateError('Could not capture the editor screenshot.');
      }

      final capturedImage =
          await boundaryRenderObject.toImage(pixelRatio: pixelRatio);
      final byteData =
          await capturedImage.toByteData(format: ui.ImageByteFormat.png);
      capturedImage.dispose();
      if (byteData == null) {
        throw StateError('Could not capture the editor screenshot.');
      }

      final pngBytes = byteData.buffer.asUint8List();
      final decoded = img.decodeImage(pngBytes);
      if (decoded == null) {
        throw StateError('Could not capture the editor screenshot.');
      }

      img.Image workingImage = decoded;
      if (workingImage.width > 1280) {
        workingImage = img.copyResize(workingImage, width: 1280);
      }

      Uint8List encoded = Uint8List.fromList(
        img.encodeJpg(workingImage, quality: 74),
      );
      int quality = 74;
      while (encoded.lengthInBytes > 120 * 1024 && quality > 38) {
        quality -= 8;
        encoded = Uint8List.fromList(
          img.encodeJpg(workingImage, quality: quality),
        );
      }
      while (encoded.lengthInBytes > 120 * 1024 && workingImage.width > 720) {
        final nextWidth = (workingImage.width * 0.82).round();
        workingImage = img.copyResize(workingImage, width: nextWidth);
        encoded = Uint8List.fromList(
          img.encodeJpg(workingImage, quality: quality),
        );
      }

      if (encoded.lengthInBytes > 120 * 1024) {
        throw StateError('Screenshot is too large to attach.');
      }

      return FeedbackScreenshotAttachment(
        bytes: encoded,
        mimeType: 'image/jpeg',
        width: workingImage.width,
        height: workingImage.height,
      );
    } finally {
      if (mounted) {
        setState(() {
          _chatExpanded = previousChatExpanded;
          _chatInputActive = previousChatInputActive;
        });
      }
    }
  }

  Future<void> _openDawFeedbackComposer() async {
    if (_feedbackSubmissionInFlight) return;

    final authService = context.read<AuthService>();
    final draft = await showFeedbackSheet(
      context,
      source: FeedbackSource.dawChat,
    );
    if (draft == null || !mounted) return;

    setState(() => _feedbackSubmissionInFlight = true);
    try {
      FeedbackContextPayload? contextPayload;
      if (draft.includeDawContext) {
        contextPayload = FeedbackContextPayload(
          chatHistory:
              ProjectChatHistory.fromChatMessages(_chatController.messages)
                  .toConversation(),
          projectSettings: _buildFeedbackProjectSettings(),
        );
      }

      FeedbackScreenshotAttachment? screenshot;
      if (draft.includeDawScreenshot) {
        screenshot = await _captureFeedbackScreenshot();
      }

      await FeedbackService.instance.submit(
        auth: authService,
        request: FeedbackSubmissionRequest(
          category: draft.category,
          source: FeedbackSource.dawChat,
          message: draft.message,
          allowEmailContact: draft.allowEmailContact,
          context: contextPayload,
          screenshot: screenshot,
        ),
      );
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
            content: Text(
                L10n.translate(context, 'Thank you for your submission!'))),
      );
    } catch (e) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text(e.toString().replaceFirst('Bad state: ', ''))),
      );
    } finally {
      if (mounted) {
        setState(() => _feedbackSubmissionInFlight = false);
      }
    }
  }

  // This is needed in iOS so that hold actions (like track headers) are immediately responsive
  // without gesture gate issues. But the tradeoff is that swipe to go back/forward will not work.
  // Since those actions might be needed in other parts of app, make it toggleable like this.
  Future<void> _setIOSSystemGestureDeferral(bool enabled) async {
    if (!Platform.isIOS) return;
    try {
      await _edgeGesturesChannel
          .invokeMethod<void>('setDeferred', {'enabled': enabled});
    } catch (_) {}
  }

