  bool _toggleTopPopup(_TopPopupType popupType) {
    final bool willOpen = _activeTopPopup != popupType;
    setState(() {
      _setActiveTopPopup(willOpen ? popupType : _TopPopupType.none);
    });
    if (willOpen && popupType == _TopPopupType.tempo) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (!mounted) return;
        _syncTempoPickerSelection();
      });
    }
    return willOpen;
  }

  void _closeTopPopup([_TopPopupType popupType = _TopPopupType.none]) {
    if (_activeTopPopup == _TopPopupType.none) return;
    if (popupType != _TopPopupType.none && _activeTopPopup != popupType) return;
    setState(() {
      _setActiveTopPopup(_TopPopupType.none);
    });
  }

  void _onTopPopupTapAwayPointerDown(PointerDownEvent event) {
    _topPopupTapPointerId = event.pointer;
    _topPopupTapDownGlobalPos = event.position;
    _topPopupTapMoved = false;
  }

  void _onTopPopupTapAwayPointerMove(PointerMoveEvent event) {
    if (_topPopupTapPointerId != event.pointer ||
        _topPopupTapDownGlobalPos == null) {
      return;
    }
    if (_topPopupTapMoved) return;
    final movedDistance =
        (event.position - _topPopupTapDownGlobalPos!).distance;
    if (movedDistance > 10.0) {
      _topPopupTapMoved = true;
    }
  }

  void _onTopPopupTapAwayPointerCancel(PointerCancelEvent event) {
    if (_topPopupTapPointerId == event.pointer) {
      _topPopupTapPointerId = null;
      _topPopupTapDownGlobalPos = null;
      _topPopupTapMoved = false;
    }
  }

  bool _consumeTopPopupTapAwayPointerUp(PointerUpEvent event) {
    final pointerMatches = _topPopupTapPointerId == event.pointer;
    final down = _topPopupTapDownGlobalPos;
    final moved = _topPopupTapMoved;
    _topPopupTapPointerId = null;
    _topPopupTapDownGlobalPos = null;
    _topPopupTapMoved = false;
    if (!pointerMatches || down == null || moved) return false;
    return (event.position - down).distance <= 10.0;
  }

  bool _isGlobalPointInsideKeyRect(GlobalKey key, Offset globalPosition) {
    final context = key.currentContext;
    if (context == null) return false;
    final renderObject = context.findRenderObject();
    if (renderObject is! RenderBox || !renderObject.hasSize) return false;
    final origin = renderObject.localToGlobal(Offset.zero);
    final rect = origin & renderObject.size;
    return rect.contains(globalPosition);
  }

  Rect? _topPopupAnchorRect(GlobalKey key) {
    final BuildContext? anchorContext = key.currentContext;
    final BuildContext? stackContext = _editorContentStackKey.currentContext;
    if (anchorContext == null || stackContext == null) return null;

    final RenderObject? anchorObject = anchorContext.findRenderObject();
    final RenderObject? stackObject = stackContext.findRenderObject();
    if (anchorObject is! RenderBox ||
        stackObject is! RenderBox ||
        !anchorObject.hasSize ||
        !stackObject.hasSize) {
      return null;
    }

    final Offset topLeft =
        anchorObject.localToGlobal(Offset.zero, ancestor: stackObject);
    final Offset topRight = anchorObject.localToGlobal(
      Offset(anchorObject.size.width, 0),
      ancestor: stackObject,
    );
    final Offset bottomLeft = anchorObject.localToGlobal(
      Offset(0, anchorObject.size.height),
      ancestor: stackObject,
    );
    final Offset bottomRight = anchorObject.localToGlobal(
      Offset(anchorObject.size.width, anchorObject.size.height),
      ancestor: stackObject,
    );

    final double left = math.min(math.min(topLeft.dx, topRight.dx),
        math.min(bottomLeft.dx, bottomRight.dx));
    final double top = math.min(math.min(topLeft.dy, topRight.dy),
        math.min(bottomLeft.dy, bottomRight.dy));
    final double right = math.max(math.max(topLeft.dx, topRight.dx),
        math.max(bottomLeft.dx, bottomRight.dx));
    final double bottom = math.max(math.max(topLeft.dy, topRight.dy),
        math.max(bottomLeft.dy, bottomRight.dy));
    return Rect.fromLTRB(left, top, right, bottom);
  }

  _TopPopupLayout _resolveTopPopupLayout({
    required GlobalKey anchorKey,
    required double desiredWidth,
    required double connectorWidth,
    bool centerOnToolbarPill = false,
    bool matchToolbarWidth = false,
  }) {
    final BuildContext? stackContext = _editorContentStackKey.currentContext;
    final RenderObject? stackObject = stackContext?.findRenderObject();
    if (stackObject is! RenderBox || !stackObject.hasSize) {
      final fallbackWidth = desiredWidth;
      return _TopPopupLayout(
        top: 48,
        left: _kTopPopupHorizontalMargin,
        width: fallbackWidth,
        connectorLeft: (fallbackWidth - connectorWidth) / 2,
      );
    }

    final Rect? anchorRect = _topPopupAnchorRect(anchorKey);
    final Rect? toolbarRect =
        centerOnToolbarPill ? _topPopupAnchorRect(_toolbarPillKey) : null;
    final double targetWidth = matchToolbarWidth && toolbarRect != null
        ? toolbarRect.width
        : desiredWidth;
    final double maxWidth = math.max(
      0,
      stackObject.size.width - (_kTopPopupHorizontalMargin * 2),
    );
    final double resolvedWidth = math.min(targetWidth, maxWidth);
    final double centerX = toolbarRect?.center.dx ??
        anchorRect?.center.dx ??
        (stackObject.size.width / 2);
    final double centeredLeft = centerX - (resolvedWidth / 2);
    final double maxLeft = math.max(
      _kTopPopupHorizontalMargin,
      stackObject.size.width - resolvedWidth - _kTopPopupHorizontalMargin,
    );
    final double left = centeredLeft.clamp(
      _kTopPopupHorizontalMargin,
      maxLeft,
    );
    final Rect? topAnchorRect = toolbarRect ?? anchorRect;
    final double connectorLeft = anchorRect == null
        ? (resolvedWidth - connectorWidth) / 2
        : (anchorRect.center.dx - left - (connectorWidth / 2)).clamp(
            14.0,
            math.max(14.0, resolvedWidth - connectorWidth - 14.0),
          );

    return _TopPopupLayout(
      top: topAnchorRect == null
          ? 56
          : topAnchorRect.bottom + _kTopPopupVerticalGap,
      left: left,
      width: resolvedWidth,
      connectorLeft: connectorLeft,
    );
  }

  String _sanitizeInstrumentIdToken(String raw) {
    final lower = raw.toLowerCase();
    final collapsed = lower.replaceAll(RegExp(r'[^a-z0-9]+'), '_');
    return collapsed.replaceAll(RegExp(r'^_+|_+$'), '');
  }

  String _prettyInstrumentNameFromSfzPreset(String presetFileName) {
    var stem = presetFileName.trim();
    if (stem.toLowerCase().endsWith('.sfz')) {
      stem = stem.substring(0, stem.length - 4);
    }
    stem = stem.replaceAllMapped(
      RegExp(r'([a-z])([A-Z])'),
      (m) => '${m.group(1)} ${m.group(2)}',
    );
    stem = stem.replaceAll(RegExp(r'[_\-]+'), ' ');
    stem = stem.replaceAll(RegExp(r'\s+'), ' ').trim();
    if (stem.isEmpty) return 'Instrument';
    return stem
        .split(' ')
        .map((w) => w.isEmpty
            ? w
            : '${w[0].toUpperCase()}${w.substring(1).toLowerCase()}')
        .join(' ');
  }

  String _normalizePickerCategory(String raw) {
    return normalizeInstrumentPickerCategory(raw);
  }

  Map<String, dynamic> _defaultInstrumentSpec() {
    for (final spec in _instrumentCatalog) {
      if ((spec['id'] as String?)?.trim() == kPreferredPianoInstrumentId) {
        return _platformResolvedInstrumentSpec(spec);
      }
    }
    for (final spec in kBundledSfzFallbackCatalog) {
      if ((spec['id'] as String?)?.trim() == kPreferredPianoInstrumentId) {
        return _platformResolvedInstrumentSpec(spec);
      }
    }
    for (final spec in _instrumentCatalog) {
      if (!_isSampledInstrumentSpec(spec)) {
        return _platformResolvedInstrumentSpec(spec);
      }
    }
    if (kInstrumentCatalog.isNotEmpty) {
      return _platformResolvedInstrumentSpec(kInstrumentCatalog.first);
    }
    if (_instrumentCatalog.isNotEmpty) {
      return _platformResolvedInstrumentSpec(_instrumentCatalog.first);
    }
    if (kBundledSfzFallbackCatalog.isNotEmpty) {
      return _platformResolvedInstrumentSpec(kBundledSfzFallbackCatalog.first);
    }
    return <String, dynamic>{
      'id': 'mixroom.basic_synth',
      'name': 'Basic Synth',
      'category': 'instrument',
    };
  }

  bool _isSampledInstrumentSpec(Map<String, dynamic> spec) {
    if (spec['isSampled'] == true) return true;
    final id = (spec['id'] as String? ?? '').toLowerCase();
    return id.startsWith('sfz.');
  }

  bool _isSampledInstrumentId(String instrumentId) {
    final id = instrumentId.trim().toLowerCase();
    if (id.startsWith('sfz.') || id.startsWith('sfz_asset:')) return true;
    final spec = _findInstrumentSpecById(instrumentId);
    if (spec == null) return false;
    return _isSampledInstrumentSpec(spec);
  }

  Future<String?> _ensureAndroidBundledInstrumentRootPath() async {
    if (!Platform.isAndroid) return null;
    return _androidBundledInstrumentRootPathFuture ??= () async {
      final root =
          (await JuceAudioEngine.getBundledInstrumentRootPath())?.trim();
      if (root == null || root.isEmpty) {
        _androidBundledInstrumentRootPath = null;
        return null;
      }
      _androidBundledInstrumentRootPath = p.normalize(root);
      return _androidBundledInstrumentRootPath;
    }();
  }

  String _resolveBundledInstrumentPathForCurrentPlatform(String rawPath) {
    final trimmed = rawPath.trim();
    if (trimmed.isEmpty) return trimmed;
    if (!Platform.isAndroid) return trimmed;
    if (p.isAbsolute(trimmed)) return p.normalize(trimmed);
    final root = _androidBundledInstrumentRootPath?.trim() ?? '';
    if (root.isEmpty) return trimmed;
    const prefix = 'assets/instruments/';
    if (!trimmed.startsWith(prefix)) return trimmed;
    final relative = trimmed.substring(prefix.length);
    return p.normalize(p.join(root, relative));
  }

  Map<String, dynamic> _platformResolvedInstrumentSpec(
    Map<String, dynamic> spec,
  ) {
    if (!Platform.isAndroid || spec['isSampled'] != true) {
      return Map<String, dynamic>.from(spec);
    }
    final resolved = Map<String, dynamic>.from(spec);
    final sfzAssetPath = (resolved['sfzAssetPath'] as String?)?.trim() ?? '';
    if (sfzAssetPath.isNotEmpty) {
      resolved['sfzAssetPath'] =
          _resolveBundledInstrumentPathForCurrentPlatform(sfzAssetPath);
    }
    return resolved;
  }

  List<Map<String, dynamic>> _platformResolvedInstrumentCatalog(
    List<Map<String, dynamic>> specs,
  ) {
    return specs
        .map((spec) => _platformResolvedInstrumentSpec(spec))
        .toList(growable: false);
  }

  Future<void> _loadBundledInstrumentCatalog() async {
    try {
      String raw;
      if (Platform.isAndroid) {
        final root = await _ensureAndroidBundledInstrumentRootPath();
        if (root != null && root.isNotEmpty) {
          final indexFile = File(p.join(root, 'index.json'));
          raw = await indexFile.readAsString();
        } else {
          raw = await rootBundle.loadString('assets/instruments/index.json');
        }
      } else {
        raw = await rootBundle.loadString('assets/instruments/index.json');
      }
      final decoded = jsonDecode(raw);
      if (decoded is! Map<String, dynamic>) {
        return;
      }

      final pack = (decoded['pack'] as String?)?.trim();
      final presets = decoded['presets'];
      if (presets is! List) {
        return;
      }

      final loaded = <Map<String, dynamic>>[];
      for (final entry in presets) {
        if (entry is! Map) continue;
        final map = entry.cast<String, dynamic>();
        final presetFile = (map['preset'] as String?)?.trim() ?? '';
        if (presetFile.isEmpty) continue;
        final categoryRaw = (map['category'] as String?) ?? '';
        final pickerCategory = _normalizePickerCategory(categoryRaw);
        final displayName = (map['name'] as String?)?.trim().isNotEmpty == true
            ? (map['name'] as String).trim()
            : _prettyInstrumentNameFromSfzPreset(presetFile);
        final defaultOutputGain = pickerCategory == 'Drums' ? 0.84 : 0.72;
        final defaultAttackMs = pickerCategory == 'Drums' ? 2.0 : 6.0;
        final defaultReleaseMs = pickerCategory == 'Drums' ? 320.0 : 520.0;
        final explicitId = (map['id'] as String?)?.trim() ?? '';
        final idToken = _sanitizeInstrumentIdToken(
            '${pack ?? 'sfz'}_${presetFile.replaceAll('.sfz', '')}');
        loaded.add(<String, dynamic>{
          'id': explicitId.isNotEmpty ? explicitId : 'sfz.$idToken',
          'name': displayName,
          'category': 'instrument',
          'pickerCategory': pickerCategory,
          'sourceProject': pack ?? 'Bundled SFZ',
          'sourceLicense': 'See bundled LICENSE',
          'isSampled': true,
          'sfzAssetPath': 'assets/instruments/${pack ?? ''}/$presetFile',
          'outputGain':
              ((map['outputGain'] as num?)?.toDouble() ?? defaultOutputGain)
                  .clamp(0.2, 2.0),
          'attackMs': ((map['attackMs'] as num?)?.toDouble() ?? defaultAttackMs)
              .clamp(0.0, 2400.0),
          'releaseMs':
              ((map['releaseMs'] as num?)?.toDouble() ?? defaultReleaseMs)
                  .clamp(20.0, 3600.0),
        });
      }

      if (loaded.isEmpty) {
        return;
      }
      final merged = _platformResolvedInstrumentCatalog(
        _mergeInstrumentCatalogs([
          kInstrumentCatalog,
          loaded,
          kBundledSfzFallbackCatalog,
        ]),
      );
      if (!mounted) {
        _instrumentCatalog = merged;
        _instrumentCatalogReady = true;
        return;
      }
      setState(() {
        _instrumentCatalog = merged;
        _instrumentCatalogReady = true;
      });
    } catch (_) {
      if (_instrumentCatalogReady) return;
      final fallback = _platformResolvedInstrumentCatalog(
        _mergeInstrumentCatalogs([
          kInstrumentCatalog,
          kBundledSfzFallbackCatalog,
        ]),
      );
      if (!mounted) {
        _instrumentCatalog = fallback;
        _instrumentCatalogReady = true;
        return;
      }
      setState(() {
        _instrumentCatalog = fallback;
        _instrumentCatalogReady = true;
      });
    }
  }

  void _syncRowLocalStateToRowCount() {
    while (_rowPan.length < _rowCount) {
      final nextRow = _rowPan.length;
      _rowPan.add(0.5);
      _rowGain.add(_kGainUiUnity);
      _rowVolumeAutomation.add([AutomationPoint(x: 0.0, volume: 0.75)]);
      _rowPluginAutomation[nextRow] = <String, List<AutomationPoint>>{};
      _rowAutomationClips[nextRow] = <String, List<AutomationClipSnapshot>>{};
      _rowAutomationTargets[nextRow] = _defaultAutomationTargetsForRow(nextRow);
      _rowSelectedAutomationTarget[nextRow] = 'volume';
      _rowMuted.add(false);
      _rowSoloed.add(false);
      _rowMuteApplied.add(null);
      _rowExpanded.add(false);
      _rowExpandedTab.add(0);
      _rowGainSnapshot.add(_kGainUiUnity);
      _rowPanSnapshot.add(0.5);
      _rowAutomationSnapshot.add([]);
    }
    if (_rowPan.length > _rowCount) {
      _rowPan.removeRange(_rowCount, _rowPan.length);
      _rowGain.removeRange(_rowCount, _rowGain.length);
      _rowVolumeAutomation.removeRange(_rowCount, _rowVolumeAutomation.length);
      _rowMuted.removeRange(_rowCount, _rowMuted.length);
      _rowSoloed.removeRange(_rowCount, _rowSoloed.length);
      _rowMuteApplied.removeRange(_rowCount, _rowMuteApplied.length);
      _rowExpanded.removeRange(_rowCount, _rowExpanded.length);
      _rowExpandedTab.removeRange(_rowCount, _rowExpandedTab.length);
      _rowGainSnapshot.removeRange(_rowCount, _rowGainSnapshot.length);
      _rowPanSnapshot.removeRange(_rowCount, _rowPanSnapshot.length);
      _rowAutomationSnapshot.removeRange(
          _rowCount, _rowAutomationSnapshot.length);
    }

    _rowPluginAutomation.removeWhere((row, _) => row < 0 || row >= _rowCount);
    _rowAutomationClips.removeWhere((row, _) => row < 0 || row >= _rowCount);
    _rowAutomationTargets.removeWhere((row, _) => row < 0 || row >= _rowCount);
    _rowSelectedAutomationTarget
        .removeWhere((row, _) => row < 0 || row >= _rowCount);

    for (int row = 0; row < _rowCount; row++) {
      _rowPluginAutomation.putIfAbsent(
          row, () => <String, List<AutomationPoint>>{});
      _rowAutomationClips.putIfAbsent(
          row, () => <String, List<AutomationClipSnapshot>>{});
      _rowAutomationTargets.putIfAbsent(
          row,
          () => <String, _AutomationTargetMeta>{
                'volume': _volumeAutomationTargetMeta(),
              });
      _rowSelectedAutomationTarget.putIfAbsent(row, () => 'volume');
    }

    if (_selectedRow >= _rowCount) {
      _selectedRow = _rowCount == 0 ? 0 : _rowCount - 1;
    }
    if (_meters.rows.length != _rowCount) {
      _meters.dispose();
      _meters = MeterBus(numRows: _rowCount);
    }
    _rowPeakHoldDb
        .removeWhere((row, _) => row != -1 && (row < 0 || row >= _rowCount));
    _rowPeakHoldLastUpdate
        .removeWhere((row, _) => row != -1 && (row < 0 || row >= _rowCount));
    _rowPeakHoldFreezeUntil
        .removeWhere((row, _) => row != -1 && (row < 0 || row >= _rowCount));
  }

  Future<void> _refreshPlatformCapabilities() async {
    final capabilities = await PlatformCapabilities.refresh();
    if (!mounted) return;
    setState(() {
      _platformCapabilities = capabilities;
    });
  }

  bool _isEditableTextFocused() {
    final focusedContext = FocusManager.instance.primaryFocus?.context;
    if (focusedContext == null) return false;
    return focusedContext.widget is EditableText;
  }

  Future<void> _handleMacSpacebarPlayPauseShortcut() async {
    if (!mounted) return;
    if (_isRecording) {
      await _stopRecordingJuce(keepPlaying: false);
      return;
    }
    await _togglePlayPauseAudio(_safeAudioEditorStateSetter);
  }

  bool _handleMacEditorKeyEvent(KeyEvent event) {
    if (!Platform.isMacOS) return false;
    if (event is! KeyDownEvent) return false;
    if (event.logicalKey != LogicalKeyboardKey.space) return false;
    if (_isEditableTextFocused()) return false;

    final keyboard = HardwareKeyboard.instance;
    final hasModifier = keyboard.isMetaPressed ||
        keyboard.isControlPressed ||
        keyboard.isAltPressed;
    if (hasModifier) return false;

    unawaited(_handleMacSpacebarPlayPauseShortcut());
    return true;
  }

  @override
  void initState() {
    super.initState();
    if (Platform.isMacOS) {
      HardwareKeyboard.instance.addHandler(_handleMacEditorKeyEvent);
    }
    unawaited(_setIOSSystemGestureDeferral(true));
    WidgetsBinding.instance.addObserver(this);
    unawaited(_refreshPlatformCapabilities());
    unawaited(_loadBluetoothRecordingPrefs());
    // prewarmFFT(); // so that AI sync first run is not heavy (this was for video/audio sync)

    _transportTicker = Ticker((_) {
      if (!_isPlaying) return;
      _setGlobalAudioClock(_estimateTransportClockFromSample());
      unawaited(_pollTransportFromJuceIfNeeded());
      _refreshFxUiForPlaybackTick();

      // ===== END / LOOP LOGIC (same as before) =====
      final endPoint = Duration(
        milliseconds: math.max(_audioOnlyOverallDuration.inMilliseconds,
            msFor128Bars(_tempo).toInt()),
      );
      final withinEndGuard =
          _transportUiStopwatch.elapsed < _transportEndCheckGraceUntil;

      final reachedEnd = _globalAudioClock >= endPoint;
      final reachedLoopEnd = _loopEnabled &&
          _globalAudioClock >= Duration(milliseconds: _loopEndMs);

      if (reachedLoopEnd && !withinEndGuard) {
        if (_isRecording) {
          _transportTicker?.stop();
          _stopRecordingJuce(keepPlaying: false);
          return;
        }
        if (!_loopWrapInFlight) {
          unawaited(_wrapPlaybackToLoopStart());
        }
        return;
      }

      if (reachedEnd && !withinEndGuard) {
        if (_isRecording) return;
        unawaited(_togglePlayPauseAudio(_safeAudioEditorStateSetter));
      }
    });

    _projectDir = widget.projectDir;
    _projectCreatedAtMs = DateTime.now().millisecondsSinceEpoch;
    _projectPersistence = JsonAudioProjectPersistence();
    _projectAutosaveCoordinator = AutosaveCoordinator(
      performSave: _performAutosaveWrite,
      onError: (error, _) {
        debugPrint('Project autosave failed: $error');
      },
    );
    _undoManager.addListener(_handleUndoHistoryChanged);

    _classifier = InstrumentClassifier();
    _spleeterStemSeparator = SpleeterStemSeparator();
    // Warm model availability early so stem separation doesn't block on first tap.
    unawaited(_spleeterStemSeparator.prewarm(includeSession: false));
    // _classifier.debugLog = (msg) {
    //   print('msg: $msg');
    //   ScaffoldMessenger.of(context).showSnackBar(
    //     SnackBar(
    //       content: Text(msg),
    //       duration: const Duration(seconds: 3),
    //     ),
    //   );
    // };
    // Defer AI model loads until AI features are actually used.
    _producerCollector = ProducerDataCollector();
    _producerCollector.setEnabled(_producerDataMode);
    final authService = context.read<AuthService>();
    _magnitudePredictor = !kUseLearnedMagnitudePredictor
        ? const NoopMixingMagnitudePredictor()
        : kUseRemoteLearnedMagnitudePredictor
            ? RemoteMixingMagnitudePredictor(
                enabled: true,
                proxyApiBaseUrl: LlmConfig.effectiveProxyApiBaseUrl,
                proxyPath: LlmConfig.mixResolvePath,
                authTokenProvider: authService.getIdTokenOrNull,
                refreshAuthTokenProvider: authService.refreshIdTokenOrNull,
                requestTimeout:
                    Duration(seconds: LlmConfig.requestTimeoutSeconds),
              )
            : OnnxMixingMagnitudePredictor(
                enabled: true,
                applyModelAsset: kMixApplyClassifierAsset,
                magnitudeModelAsset: kMixMagnitudeRegressorAsset,
              );
    unawaited(_magnitudePredictor.startBackgroundRefresh());

    _chatPipeline = ChatPipeline(
      llm: CloudLlmService(
        apiKey: LlmConfig.canUseDirectOpenAi ? LlmConfig.openAiApiKey : '',
        model: LlmConfig.openAiModel,
        proxyApiBaseUrl: LlmConfig.effectiveProxyApiBaseUrl,
        proxyPath: LlmConfig.proxyPath,
        requestTimeout: Duration(seconds: LlmConfig.requestTimeoutSeconds),
        authTokenProvider: authService.getIdTokenOrNull,
        refreshAuthTokenProvider: authService.refreshIdTokenOrNull,
      ), // LocalLlmService(),
      projectBuilder: ProjectStateBuilder(classifier: _classifier),
      mixModel: LocalMixingModel(),
      magnitudePredictor: _magnitudePredictor,
      onThinkingChanged: (isThinking) {
        if (!mounted) return;
        if (isThinking && _isThinking && !_chatScrollHintEnabled) {
          _scrollChatToLatest();
        }
      },
    );

    _tempoPickerController = FixedExtentScrollController(
      initialItem: _tempoPickerItemFor(_tempo),
    );
    _chatController = InMemoryChatController();
    _chatTextController.addListener(_handleChatTextChanged);
    _chatFocusNode.addListener(_handleChatFocusChanged);
    unawaited(_refreshPromptRateLimitStatus());

    _samplePreviewPlayer = ja.AudioPlayer(handleAudioSessionActivation: false);
    _samplePreviewStateSub =
        _samplePreviewPlayer.playerStateStream.listen((state) {
      if (!mounted) return;
      setState(() {
        _samplePreviewPlaying = state.playing;
        if (state.processingState == ja.ProcessingState.completed) {
          _auditioningSamplePath = null;
          _samplePreviewPlaying = false;
        }
      });
    });
    WidgetsBinding.instance.addPostFrameCallback((_) {
      setState(() {
        _chatWarm = true;
      });
    });

    _meters = MeterBus(numRows: 0);
    // _startMeterPolling();

    WidgetsBinding.instance.addPostFrameCallback((_) async {
      await JuceAudioEngine.initialise(); // heavy blocking native call
      JuceAudioEngine.initialiseEventListeners();
      await _refreshMicrophonePermissionState();
      await _maybePromptMicrophonePermissionOnDawEntry();
      await _loadInputDevicesFromJuce();
      await _refreshAudioRouteInfo();
      await _loadBundledInstrumentCatalog();
      final engineSupportsLiveMidi =
          await JuceAudioEngine.supportsLiveMidiClipPlayback();
      _liveMidiEventPlaybackSupported =
          !_kForceRenderedMidiPlaybackForBeta && engineSupportsLiveMidi;
      if (_kForceRenderedMidiPlaybackForBeta && engineSupportsLiveMidi) {
        debugPrint(
          '🎹 Live MIDI clip playback disabled for beta quality; using rendered MIDI WAV playback.',
        );
      }
      if (_liveMidiEventPlaybackSupported) {
        _startMidiDeviceConnectionPolling();
      }
      await _reloadRowsFromEngine();
      await _refreshProducerCaptureUiAllowlistAccess();
      await _loadProjectIfAny();
      setState(() => _isLoadingNextScreen = false);
      unawaited(_flushDeferredAndroidRouteRefreshIfNeeded());
      await _runInitialActionIfNeeded();
      await _maybeShowDawOnboarding();
    });
  }

  Future<void> _runInitialActionIfNeeded() async {
    if (_handledInitialAction || !mounted) return;
    final action = widget.initialAction;
    if (action == null) return;
    _handledInitialAction = true;

    final nextFormat = action == AudioEditorInitialAction.exportMp3
        ? _ExportAudioFormat.mp3
        : _ExportAudioFormat.wav;
    final current = _audioExportSettings;
    setState(() {
      _audioExportSettings = _AudioExportSettings(
        format: nextFormat,
        sampleRate: current.sampleRate,
        wavBitDepth: current.wavBitDepth,
        wavDithering: current.wavDithering,
        mp3BitrateKbps: current.mp3BitrateKbps,
        mp3Mode: current.mp3Mode,
        mp3VbrQuality: current.mp3VbrQuality,
        channelMode: current.channelMode,
        normalize: current.normalize,
        normalizeTargetDb: current.normalizeTargetDb,
        resampleQuality: current.resampleQuality,
      );
    });

    await Future.delayed(const Duration(milliseconds: 120));
    if (!mounted) return;
    await _exportAndNavigate();
  }

  String? _currentOnboardingUserId() {
    try {
      return context.read<AuthService>().signedInUser?.userId;
    } catch (_) {
      return null;
    }
  }

  int get _safeDawOnboardingStepIndex {
    if (_kDawTutorialSequence.isEmpty) return 0;
    if (_dawOnboardingStepIndex < 0) return 0;
    if (_dawOnboardingStepIndex >= _kDawTutorialSequence.length) {
      return _kDawTutorialSequence.length - 1;
    }
    return _dawOnboardingStepIndex;
  }

  int get _dawTutorialTargetRow {
    if (_rowCount <= 0) return 0;
    final stored = _dawTutorialRowIndex;
    if (stored != null && stored >= 0 && stored < _rowCount) {
      return stored;
    }
    return _selectedRow.clamp(0, _rowCount - 1).toInt();
  }

  _DawTutorialStepId get _currentDawOnboardingStepId =>
      _kDawTutorialSequence[_safeDawOnboardingStepIndex];

  _DawTutorialStepSpec get _currentDawOnboardingStep =>
      _buildDawTutorialStepSpec(_currentDawOnboardingStepId);

