  void _handleDawOnboardingChatPromptSubmitted() {
    if (!_showDawOnboarding) return;
    if (_currentDawOnboardingStepId == _DawTutorialStepId.chatSend) {
      setState(() {
        _dawTutorialAwaitingChatReply = true;
        _dawTutorialChatAdvanceInFlight = false;
        _dawTutorialAssistantCountAtPromptSend =
            _chatTextMessageCount(authorId: 'assistant');
      });
      _advanceDawOnboardingStep();
    }
  }

  Future<void> _handleDawOnboardingChatReplyReady() async {
    if (!_showDawOnboarding || !_dawTutorialAwaitingChatReply) return;
    if (_currentDawOnboardingStepId != _DawTutorialStepId.chatWaiting) return;
    if (_dawTutorialChatAdvanceInFlight) return;
    setState(() {
      _dawTutorialChatAdvanceInFlight = true;
    });

    final hasAssistantReply = _chatTextMessageCount(authorId: 'assistant') >
        _dawTutorialAssistantCountAtPromptSend;
    if (!hasAssistantReply) {
      if (!mounted) return;
      setState(() {
        _dawTutorialChatAdvanceInFlight = false;
      });
      return;
    }

    _scrollChatToLatest();
    await Future.delayed(const Duration(milliseconds: 350));

    if (!mounted || !_showDawOnboarding) return;
    if (_currentDawOnboardingStepId != _DawTutorialStepId.chatWaiting) return;
    setState(() {
      _dawTutorialAwaitingChatReply = false;
      _dawTutorialChatAdvanceInFlight = false;
    });
    _advanceDawOnboardingStep();
  }

  Map<int, _RowUiStateSnapshot> _captureRowUiStateById() {
    final snapshots = <int, _RowUiStateSnapshot>{};
    for (int i = 0; i < _rows.length; i++) {
      final id = _rows[i].rowId;
      snapshots[id] = _RowUiStateSnapshot(
        pan: i < _rowPan.length ? _rowPan[i] : 0.5,
        gain: i < _rowGain.length ? _rowGain[i] : _kGainUiUnity,
        muted: i < _rowMuted.length ? _rowMuted[i] : false,
        soloed: i < _rowSoloed.length ? _rowSoloed[i] : false,
        muteApplied: i < _rowMuteApplied.length ? _rowMuteApplied[i] : null,
        expanded: i < _rowExpanded.length ? _rowExpanded[i] : false,
        expandedTab: i < _rowExpandedTab.length ? _rowExpandedTab[i] : 0,
        volumeAutomation: i < _rowVolumeAutomation.length
            ? _rowVolumeAutomation[i].map((p) => p.copy()).toList()
            : <AutomationPoint>[AutomationPoint(x: 0.0, volume: 0.75)],
        pluginAutomation:
            (_rowPluginAutomation[i] ?? const <String, List<AutomationPoint>>{})
                .map(
          (key, value) =>
              MapEntry(key, value.map((p) => p.copy()).toList(growable: false)),
        ),
        automationClips: (_rowAutomationClips[i] ??
                const <String, List<AutomationClipSnapshot>>{})
            .map(
          (key, value) => MapEntry(
            key,
            value.map((clip) => clip.copyWith()).toList(growable: false),
          ),
        ),
        automationTargets: Map<String, _AutomationTargetMeta>.from(
          _rowAutomationTargets[i] ?? _defaultAutomationTargetsForRow(i),
        ),
        selectedAutomationTarget: _rowSelectedAutomationTarget[i] ?? 'volume',
        gainSnapshot:
            i < _rowGainSnapshot.length ? _rowGainSnapshot[i] : _kGainUiUnity,
        panSnapshot: i < _rowPanSnapshot.length ? _rowPanSnapshot[i] : 0.5,
        automationSnapshot: i < _rowAutomationSnapshot.length
            ? _rowAutomationSnapshot[i].map((p) => p.copy()).toList()
            : <AutomationPoint>[],
        peakHoldDb: _rowPeakHoldDb[i],
        peakHoldLastUpdate: _rowPeakHoldLastUpdate[i],
        peakHoldFreezeUntil: _rowPeakHoldFreezeUntil[i],
      );
    }
    return snapshots;
  }

  void _syncAudioTrackRowsToCurrentRows() {
    for (final clip in _audioTracks) {
      final idx = _rowIndexForId(clip.rowId);
      if (idx >= 0) {
        clip.rowIndex = idx;
      } else if (_rowCount == 0) {
        clip.rowIndex = 0;
      } else {
        clip.rowId = _rowIdAt(0);
        clip.rowIndex = 0;
      }
    }
  }

  Future<void> _applyRowsToEditorState(
    List<TimelineRow> nextRows, {
    bool refreshAutomationTargets = true,
    bool setStateWhenDone = true,
    bool syncClipRows = true,
  }) async {
    final previousStateById = _captureRowUiStateById();
    _rows = List<TimelineRow>.from(nextRows);
    _syncRowLocalStateToRowCount();

    _rowPeakHoldDb.removeWhere((_, __) => true);
    _rowPeakHoldLastUpdate.removeWhere((_, __) => true);
    _rowPeakHoldFreezeUntil.removeWhere((_, __) => true);

    for (int i = 0; i < _rows.length; i++) {
      final state = previousStateById[_rows[i].rowId];
      if (state == null) continue;
      _rowPan[i] = state.pan;
      _rowGain[i] = state.gain.clamp(_kGainUiMin, _kGainUiMax);
      _rowMuted[i] = state.muted;
      _rowSoloed[i] = state.soloed;
      _rowMuteApplied[i] = state.muteApplied;
      _rowExpanded[i] = state.expanded;
      _rowExpandedTab[i] = state.expandedTab;
      _rowVolumeAutomation[i] =
          state.volumeAutomation.map((p) => p.copy()).toList(growable: false);
      _rowPluginAutomation[i] = state.pluginAutomation.map(
        (key, value) =>
            MapEntry(key, value.map((p) => p.copy()).toList(growable: false)),
      );
      _rowAutomationClips[i] = state.automationClips.map(
        (key, value) => MapEntry(
          key,
          value.map((clip) => clip.copyWith()).toList(growable: false),
        ),
      );
      _rowAutomationTargets[i] =
          Map<String, _AutomationTargetMeta>.from(state.automationTargets);
      _rowSelectedAutomationTarget[i] = state.selectedAutomationTarget;
      if (i < _rowGainSnapshot.length) {
        _rowGainSnapshot[i] = state.gainSnapshot;
      }
      if (i < _rowPanSnapshot.length) {
        _rowPanSnapshot[i] = state.panSnapshot;
      }
      if (i < _rowAutomationSnapshot.length) {
        _rowAutomationSnapshot[i] = state.automationSnapshot
            .map((point) => point.copy())
            .toList(growable: false);
      }
      if (state.peakHoldDb != null) {
        _rowPeakHoldDb[i] = state.peakHoldDb!;
      }
      if (state.peakHoldLastUpdate != null) {
        _rowPeakHoldLastUpdate[i] = state.peakHoldLastUpdate!;
      }
      if (state.peakHoldFreezeUntil != null) {
        _rowPeakHoldFreezeUntil[i] = state.peakHoldFreezeUntil!;
      }
    }

    if (syncClipRows) {
      _syncAudioTrackRowsToCurrentRows();
    }
    _pruneAutomationDiscoveryCaches();

    if (refreshAutomationTargets && !_isProjectLoading) {
      await _refreshAutomationTargetsForAllRows();
    }

    if (setStateWhenDone) {
      _refreshAudioEditorView();
    }
  }

  Future<void> _reloadRowsFromEngine({
    bool refreshAutomationTargets = true,
  }) async {
    final rawRows = await JuceAudioEngine.getRows();
    final nextRows = rawRows
        .map(
          (m) => TimelineRow(
            rowId: (m['rowId'] as num?)?.toInt() ?? -1,
            name: (m['name'] as String?) ?? '',
            iconId: (m['iconId'] as num?)?.toInt() ?? 0,
          ),
        )
        .where((r) => r.rowId >= 0)
        .toList(growable: false);
    await _applyRowsToEditorState(
      nextRows,
      refreshAutomationTargets: refreshAutomationTargets,
    );
  }

  Future<void> _ensureRowExistsForClipInsertion() async {
    if (_rowCount > 0) return;
    final id = await JuceAudioEngine.addRow('Track 1', iconId: 0);
    if (id >= 0) {
      await _applyRowsToEditorState(
        <TimelineRow>[
          TimelineRow(rowId: id, name: 'Track 1', iconId: 0),
        ],
        refreshAutomationTargets: !_isProjectLoading,
        syncClipRows: false,
      );
    }
  }

  Future<void> _ensureRowIndexExists(int rowIndex) async {
    if (rowIndex < 0) return;
    while (_rowCount <= rowIndex) {
      final next = _rowCount + 1;
      final id = await JuceAudioEngine.addRow('Track $next', iconId: 0);
      if (id < 0) break;
      await _applyRowsToEditorState(
        <TimelineRow>[
          ..._rows,
          TimelineRow(rowId: id, name: 'Track $next', iconId: 0),
        ],
        refreshAutomationTargets: !_isProjectLoading,
        syncClipRows: false,
      );
    }
  }

  Future<void> _restoreRowsFromProjectJson(
      List<Map<String, dynamic>> savedRows, List tracks) async {
    const int kDefaultRows = 5;
    final bool isFreshProject = savedRows.isEmpty && tracks.isEmpty;
    int targetRowCount = savedRows.length;
    if (targetRowCount <= 0 && tracks.isNotEmpty) {
      int maxTrackRow = -1;
      for (final t in tracks) {
        final map = (t as Map).cast<String, dynamic>();
        final row = (map["rowIndex"] as num?)?.toInt() ?? 0;
        if (row > maxTrackRow) maxTrackRow = row;
      }
      targetRowCount = maxTrackRow + 1;
    }
    if (targetRowCount <= 0) {
      targetRowCount =
          isFreshProject ? kDefaultRows : (_rowCount > 0 ? _rowCount : 1);
    }

    final currentIds = _rows.map((r) => r.rowId).toList();

    while (currentIds.length < targetRowCount) {
      final next = currentIds.length + 1;
      final id = await JuceAudioEngine.addRow('Track $next', iconId: 0);
      if (id < 0) break;
      currentIds.add(id);
    }

    while (currentIds.length > targetRowCount && currentIds.length > 1) {
      final rowId = currentIds.removeLast();
      final ok = await JuceAudioEngine.removeRow(rowId);
      if (!ok) break;
    }

    await _reloadRowsFromEngine(
      refreshAutomationTargets: false,
    );

    if (isFreshProject) {
      for (int i = 0; i < _rowCount; i++) {
        final rowId = _rowIdAt(i);
        if (rowId < 0) continue;
        await JuceAudioEngine.renameRow(rowId, 'Track ${i + 1}');
        await JuceAudioEngine.setRowIcon(rowId, 0);
      }
      await _reloadRowsFromEngine(
        refreshAutomationTargets: false,
      );
      await _recomputeAudibleState();
      return;
    }

    for (int i = 0; i < savedRows.length && i < _rowCount; i++) {
      final row = savedRows[i];
      final name = (row["name"] as String?)?.trim() ?? "";
      final iconId = (row["iconId"] as num?)?.toInt() ?? 0;
      final rowId = _rowIdAt(i);
      if (rowId < 0) continue;
      if (name.isNotEmpty) {
        await JuceAudioEngine.renameRow(rowId, name);
      }
      await JuceAudioEngine.setRowIcon(rowId, iconId);
    }

    await _reloadRowsFromEngine(
      refreshAutomationTargets: false,
    );
  }

  @override
  void dispose() {
    if (Platform.isMacOS) {
      HardwareKeyboard.instance.removeHandler(_handleMacEditorKeyEvent);
    }
    unawaited(_setIOSSystemGestureDeferral(false));
    unawaited(_producerCollector.closeSession(reason: 'screen_dispose'));
    WidgetsBinding.instance.removeObserver(this);
    _undoManager.removeListener(_handleUndoHistoryChanged);
    _amplitudeSub?.cancel();
    _micRecorder.dispose();
    unawaited(_spleeterStemSeparator.dispose());
    unawaited(_classifier.dispose());
    unawaited(_magnitudePredictor.dispose());
    for (var track in _audioTracks) {
      track.audioStartTimer?.cancel();
    }
    _transportTicker?.dispose();
    _tempoPickerController.dispose();
    _chatTextController.removeListener(_handleChatTextChanged);
    _chatFocusNode.removeListener(_handleChatFocusChanged);
    _chatTextController.dispose();
    _chatFocusNode.dispose();
    _chatListScrollController.dispose();
    _projectAutosaveCoordinator.dispose();
    _producerCaptureAccessHttpClient.close();
    _copiedChatMessageTimer?.cancel();
    _copiedChatMessageTimer = null;
    _promptRateLimitRefreshTimer?.cancel();
    _promptRateLimitRefreshTimer = null;
    _samplePreviewStateSub?.cancel();
    _samplePreviewPlayer.dispose();
    _recordingRoutePolicyTimer?.cancel();
    _recordingRoutePolicyTimer = null;
    _stopAllSecurityScopedAccess();
    _stopMidiDeviceConnectionPolling();
    _midiInputPollTimer?.cancel();
    _midiInputPollTimer = null;
    _midiHeldNotesByKey.clear();
    _midiRecordingClipEngineId = null;
    if (_liveMidiEventPlaybackSupported) {
      _lastLiveMidiInputTargetClipId = -1;
      unawaited(
        _setLiveMidiInputTargetClipIfNeeded(-1, clearPendingEvents: false),
      );
    }
    _midiClipEngineRefreshTokens.clear();
    _midiClipEngineRefreshChains.clear();
    _sfzDefinitionCache.clear();
    _sfzSampleCache.clear();

    _stopMeterPolling(decayToZero: false);
    _meterTimer?.cancel();
    _meterTimer = null;
    _meterDecayTimer?.cancel();
    _meters.dispose();
    _transportClock.dispose();
    unawaited(JuceAudioEngine.shutdown());
    super.dispose();
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (defaultTargetPlatform == TargetPlatform.android) {
      if (state == AppLifecycleState.resumed) {
        debugPrint("App Resumed on Android - Re-initializing.");
        unawaited(_handleAndroidEditorResumed());
      } else if (state == AppLifecycleState.paused ||
          state == AppLifecycleState.inactive ||
          state == AppLifecycleState.hidden ||
          state == AppLifecycleState.detached) {
        _markProjectDirty(immediate: true);
        debugPrint("App Paused or Inactive on Android - Disposing.");
        unawaited(_pausePlayback());
        setState(() {
          _isPlaying = false;
        });
      }
    } else if (defaultTargetPlatform == TargetPlatform.iOS) {
      if (state == AppLifecycleState.resumed) {
        unawaited(_refreshMicrophonePermissionAndInputs());
        unawaited(_refreshAudioRouteInfo());
      } else if (state == AppLifecycleState.paused ||
          state == AppLifecycleState.inactive ||
          state == AppLifecycleState.hidden ||
          state == AppLifecycleState.detached) {
        _markProjectDirty(immediate: true);
        unawaited(_pauseAudio(_safeAudioEditorStateSetter));
        setState(() {
          _isPlaying = false;
        });
      }
    }
  }

  bool get _shouldDeferAndroidRouteRefresh =>
      defaultTargetPlatform == TargetPlatform.android &&
      (_isLoadingNextScreen ||
          _isProjectLoading ||
          _isLoadingAudio ||
          _androidEngineCriticalSectionDepth > 0);

  Future<T> _runWithAndroidEngineCriticalSection<T>(
    Future<T> Function() action,
  ) async {
    if (defaultTargetPlatform != TargetPlatform.android) {
      return action();
    }
    _androidEngineCriticalSectionDepth += 1;
    try {
      return await action();
    } finally {
      _androidEngineCriticalSectionDepth =
          math.max(0, _androidEngineCriticalSectionDepth - 1);
      if (_androidEngineCriticalSectionDepth == 0) {
        unawaited(_flushDeferredAndroidRouteRefreshIfNeeded());
      }
    }
  }

  Future<void> _requestAndroidRouteRefresh({
    required String reason,
  }) async {
    if (defaultTargetPlatform != TargetPlatform.android) {
      await JuceAudioEngine.refreshAudioRoute(reason: reason);
      return;
    }
    if (_androidRouteRefreshInFlight || _shouldDeferAndroidRouteRefresh) {
      _pendingAndroidRouteRefresh = true;
      _pendingAndroidRouteRefreshReason = reason;
      debugPrint(
        'Deferring Android audio route refresh while engine is busy: $reason',
      );
      return;
    }

    _androidRouteRefreshInFlight = true;
    try {
      await JuceAudioEngine.refreshAudioRoute(reason: reason);
    } finally {
      _androidRouteRefreshInFlight = false;
    }

    if (_pendingAndroidRouteRefresh) {
      unawaited(_flushDeferredAndroidRouteRefreshIfNeeded());
    }
  }

  Future<void> _flushDeferredAndroidRouteRefreshIfNeeded() async {
    if (defaultTargetPlatform != TargetPlatform.android) return;
    if (!_pendingAndroidRouteRefresh ||
        _androidRouteRefreshInFlight ||
        _shouldDeferAndroidRouteRefresh) {
      return;
    }

    final reason = _pendingAndroidRouteRefreshReason ?? 'deferred';
    _pendingAndroidRouteRefresh = false;
    _pendingAndroidRouteRefreshReason = null;
    await _requestAndroidRouteRefresh(reason: 'deferred:$reason');
    await _refreshAudioRouteInfo(refreshNativeRoute: false);
  }

  Future<void> _handleAndroidEditorResumed() async {
    await _requestAndroidRouteRefresh(reason: 'appResumed');
    await _refreshMicrophonePermissionAndInputs();
    await _refreshAudioRouteInfo(refreshNativeRoute: false);
  }

  Uri _producerCaptureUiAccessUri() {
    final base = AppApiConfig.apiBaseUrl.trim().replaceFirst(RegExp(r'/$'), '');
    return Uri.parse('$base/v1/users/me/producer-capture-ui-access');
  }

  Future<http.Response> _fetchProducerCaptureUiAccess(String token) {
    return _producerCaptureAccessHttpClient.get(
      _producerCaptureUiAccessUri(),
      headers: <String, String>{
        'Authorization': 'Bearer $token',
        'Accept': 'application/json',
      },
    ).timeout(
      Duration(
        seconds: math.max(
          1,
          math.min(AppApiConfig.requestTimeoutSeconds, 6),
        ),
      ),
    );
  }

  Future<http.Response?> _fetchProducerCaptureUiAccessWithCandidates(
    List<String> tokenCandidates,
  ) async {
    http.Response? lastResponse;
    for (final token in tokenCandidates) {
      final response = await _fetchProducerCaptureUiAccess(token);
      if (!_isUnauthorizedStatusCode(response.statusCode)) {
        return response;
      }
      lastResponse = response;
    }
    return lastResponse;
  }

  bool _isUnauthorizedStatusCode(int statusCode) {
    return statusCode == 401 || statusCode == 403;
  }

  String _normalizedProducerCaptureUsername(String raw) {
    return raw.trim().toLowerCase();
  }

  String _fallbackProducerCaptureUsername() {
    try {
      final snapshot = context.read<AppUserService>().current;
      final fromProfile = _normalizedProducerCaptureUsername(
        snapshot?.username ?? '',
      );
      if (fromProfile.isNotEmpty) return fromProfile;
      final fromCognito = _normalizedProducerCaptureUsername(
        snapshot?.cognitoUsername ?? '',
      );
      if (fromCognito.contains('@')) return '';
      return fromCognito;
    } catch (_) {
      return '';
    }
  }

  void _applyProducerCaptureUiAllowlistAccess({
    required bool allowlisted,
    required String username,
  }) {
    final normalizedUsername = _normalizedProducerCaptureUsername(username);
    final shouldDisableUi = !allowlisted && _showProducerCaptureUi;
    final shouldDisableMode = !allowlisted && _producerDataMode;
    final changed = _producerCaptureUiAllowlisted != allowlisted ||
        _producerCaptureAllowlistUsername != normalizedUsername ||
        shouldDisableUi ||
        shouldDisableMode;
    if (!changed) return;

    _setStateAndRefreshProjectSettings(() {
      _producerCaptureUiAllowlisted = allowlisted;
      _producerCaptureAllowlistUsername = normalizedUsername;
      if (!allowlisted) {
        _showProducerCaptureUi = false;
        _producerDataMode = false;
        _producerUiBusy = false;
        _producerGuidedPromptAwaitingFinal = false;
        _producerCapturePanelMinimized = true;
        _producerPromptSubmitting = false;
        _producerPromptQueueIds = <String>[];
        _producerPromptQueueIndex = 0;
      }
    });
    _scheduleProjectAutosave();
    if (!allowlisted) {
      unawaited(_producerCollector.setEnabled(false));
    }
  }

  Future<void> _refreshProducerCaptureUiAllowlistAccess() async {
    final fallbackUsername = _fallbackProducerCaptureUsername();
    var resolvedUsername = fallbackUsername;
    var allowlisted =
        kDefaultProducerCaptureUsernameAllowlist.contains(fallbackUsername);

    if (AppApiConfig.hasApiBaseUrl) {
      try {
        final auth = context.read<AuthService>();
        final initialCandidates = await auth.getRequestTokenCandidates();
        if (initialCandidates.isEmpty) {
          if (!mounted) return;
          _applyProducerCaptureUiAllowlistAccess(
            allowlisted: allowlisted,
            username: resolvedUsername,
          );
          return;
        }
        var response = await _fetchProducerCaptureUiAccessWithCandidates(
          initialCandidates,
        );
        if (response != null &&
            _isUnauthorizedStatusCode(response.statusCode)) {
          final refreshedCandidates = await auth.getRequestTokenCandidates(
            forceRefresh: true,
          );
          final retryCandidates = refreshedCandidates
              .where((token) => !initialCandidates.contains(token))
              .toList();
          if (retryCandidates.isNotEmpty) {
            response = await _fetchProducerCaptureUiAccessWithCandidates(
              retryCandidates,
            );
          }
        }
        if (response != null &&
            response.statusCode >= 200 &&
            response.statusCode < 300) {
          final decoded = jsonDecode(response.body);
          if (decoded is Map) {
            final usernameFromApi = _normalizedProducerCaptureUsername(
              (decoded['username'] ?? '').toString(),
            );
            if (usernameFromApi.isNotEmpty) {
              resolvedUsername = usernameFromApi;
            }
            allowlisted = decoded['enabled'] == true;
          }
        }
      } catch (error) {
        debugPrint(
          'Producer capture allowlist access fallback applied: $error',
        );
      }
    }

    if (!mounted) return;
    _applyProducerCaptureUiAllowlistAccess(
      allowlisted: allowlisted,
      username: resolvedUsername,
    );
  }

  Future<void> _loadProjectIfAny() async {
    if (_loadedOnce) return;
    _loadedOnce = true;
    _isProjectLoading = true;

    try {
      // File browser roots should be per-session only, not persisted per project.
      _sampleBrowserRoots.clear();
      _sampleDurationCache.clear();
      _waveformCacheByPath.clear();
      _waveformFutureByPath.clear();
      _waveformPendingTracksByPath.clear();
      _sampleBrowserVisible = false;
      _sampleBrowserExpanded = false;
      _sampleDragActive = false;
      _reopenSampleBrowserAfterDrag = false;
      _reopenSampleBrowserExpanded = false;
      _invalidateAiLibrarySnapshotCache();
      await _ensureDefaultSampleBrowserRoots();
      final json = await _projectPersistence.loadProjectState(_projectDir);
      await _restoreChatHistoryFromProjectJson(json);
      _projectId = ProjectManager.ensureProjectIdInJson(json);
      _projectCreatedAtMs = (json["createdAt"] as num?)?.toInt() ??
          DateTime.now().millisecondsSinceEpoch;
      final projectVersion = (json["version"] as num?)?.toInt() ?? 1;
      _projectName = (json["name"] ?? "Untitled Project") as String;
      _requiresProjectNaming = _projectRequiresNameConfirmation(json);
      _tempo = (((json["tempoBpm"] as num?) ?? (json["bpm"] as num?) ?? _tempo)
              .toDouble())
          .clamp(20.0, 999.0);
      _syncTempoPickerSelection();
      _tempoStretchEnabled = (json["tempoStretchEnabled"] as bool?) ?? false;
      _tempoStretchPreservePitchDefault =
          (json["tempoStretchPreservePitchDefault"] as bool?) ?? false;
      final uiSettings = (json["ui"] as Map?)?.cast<String, dynamic>();
      final savedProducerCaptureUi =
          (uiSettings?["showProducerCaptureUi"] as bool?) ?? false;
      _showProducerCaptureUi =
          _canShowProducerCaptureUiSetting && savedProducerCaptureUi;
      await JuceAudioEngine.setMetronomeBpm(_tempo);

      // mark opened time
      json["lastOpenedAt"] = DateTime.now().millisecondsSinceEpoch;
      unawaited(() async {
        try {
          await _projectPersistence.saveProjectState(
            projectDir: _projectDir,
            projectState: json,
            mode: AudioProjectSaveMode.autosave,
          );
        } catch (e) {
          debugPrint('Failed to update project lastOpenedAt during load: $e');
        }
      }());

      final rowsJson = ((json["rows"] as List?) ?? [])
          .whereType<Map>()
          .map((e) => e.cast<String, dynamic>())
          .toList();
      final persistedRowIndexById =
          ProjectManager.persistedRowOrderIndexById(rowsJson);
      final tracks = (json["tracks"] as List?) ?? [];
      final loadedTracksForWaveforms = <AudioTrack>[];
      final ensuredRowIndexes = <int>{};
      await _restoreRowsFromProjectJson(rowsJson, tracks);

      Future<void> ensureTrackRowReady(int rowIndex) async {
        if (ensuredRowIndexes.contains(rowIndex)) return;
        await _ensureRowIndexExists(rowIndex);
        await _ensureRowExistsForClipInsertion();
        ensuredRowIndexes.add(rowIndex);
      }

      await JuceAudioEngine.beginProjectClipLoad();
      try {
        // Load all clips (audio + MIDI/instrument)
        for (final t in tracks) {
          final map = (t as Map).cast<String, dynamic>();
          final fileName = (map["fileName"] as String?)?.trim() ?? '';
          if (fileName.isEmpty) {
            debugPrint('Skipping malformed track entry without fileName: $map');
            continue;
          }
          final label = (map["label"] as String?) ?? '';
          int rowIndex = ProjectManager.resolveSavedTrackRowIndex(
            track: map,
            persistedRowIndexById: persistedRowIndexById,
          );

          final clipKind =
              ClipKindWire.fromWire((map['clipType'] as String?) ?? 'audio');
          final instrumentId = (map['instrumentId'] as String?) ?? '';
          final fallbackName =
              instrumentId.isEmpty ? '' : _instrumentNameFromId(instrumentId);
          final instrumentName =
              (map['instrumentName'] as String?) ?? fallbackName;
          final rawParams =
              (map['instrumentParams'] as Map?)?.cast<String, dynamic>() ??
                  const <String, dynamic>{};
          final instrumentParams = <String, double>{};
          for (final e in rawParams.entries) {
            if (e.value is num) {
              instrumentParams[e.key] = (e.value as num).toDouble();
            }
          }
          final defaultSpec = _defaultInstrumentSpec();
          final defaultInstrumentId =
              (defaultSpec['id'] as String?) ?? 'mixroom.basic_synth';
          final defaultInstrumentName =
              (defaultSpec['name'] as String?) ?? 'Instrument';
          final midiNotes = ((map['midiNotes'] as List?) ?? [])
              .whereType<Map>()
              .map((e) => MidiNote.fromJson(e.cast<String, dynamic>()))
              .toList();

          final trimStartMs =
              ((map["trimStartMs"] as num?)?.round() ?? 0).clamp(0, 1 << 30);
          final rawTrimEndMs = (map["trimEndMs"] as num?)?.round();
          final trimStartRequested =
              Duration(milliseconds: trimStartMs.toInt());
          final trimEndRequested =
              (rawTrimEndMs != null && rawTrimEndMs > trimStartMs)
                  ? Duration(milliseconds: rawTrimEndMs)
                  : null;
          final offsetSec = ((map["offset"] as num?) ?? 0).toDouble();
          final crossfade = ((map["crossfade"] as num?) ?? 0).toDouble();
          final gain = _normalizeLoadedGainUi(
            (map["gain"] as num?)?.toDouble(),
            projectVersion: projectVersion,
          );
          final pitchSemitones =
              ((map["pitchSemitones"] as num?) ?? 0.0).toDouble();
          final isReversed = (map["isReversed"] as bool?) ?? false;
          final parsedSourceTempoBpm =
              ((map["sourceTempoBpm"] as num?) ?? 0.0).toDouble();
          double sourceTempoBpm = parsedSourceTempoBpm;
          bool stretchToProjectTempo =
              (map["stretchToProjectTempo"] as bool?) ?? false;
          bool tempoStretchPreservePitch =
              (map["tempoStretchPreservePitch"] as bool?) ??
                  _tempoStretchPreservePitchDefault;
          if (clipKind == ClipKind.midi) {
            if (sourceTempoBpm <= 0.0) {
              sourceTempoBpm = _tempo;
            }
            stretchToProjectTempo = true;
            tempoStretchPreservePitch = true;
          }

          final automationList = (map["automation"] as List?) ?? [];
          final automation = automationList
              .map((e) => AutomationPointJson.fromJson(
                  (e as Map).cast<String, dynamic>()))
              .toList();

          final audioFile =
              File(p.join(ProjectManager.audioDir(_projectDir).path, fileName));
          if (!audioFile.existsSync()) {
            if (clipKind == ClipKind.midi) {
              await ensureTrackRowReady(rowIndex);
              final beforeCount = _audioTracks.length;
              await _addMidiTrack(
                instrumentId:
                    instrumentId.isEmpty ? defaultInstrumentId : instrumentId,
                instrumentName: instrumentName.isEmpty
                    ? defaultInstrumentName
                    : instrumentName,
                instrumentParams: instrumentParams.isNotEmpty
                    ? instrumentParams
                    : _instrumentParamsFromSpec(
                        _instrumentSpecById(instrumentId.isEmpty
                            ? defaultInstrumentId
                            : instrumentId),
                      ),
                midiNotes: midiNotes,
                row: rowIndex,
                timeMs: offsetSec * 1000.0,
                trimStartRequested: trimStartRequested,
                trimEndRequested: trimEndRequested,
                label: label.isEmpty ? instrumentName : label,
                gain: gain,
                pitchSemitones: pitchSemitones,
                sourceTempoBpm: sourceTempoBpm,
                stretchToProjectTempo: stretchToProjectTempo,
                tempoStretchPreservePitch: tempoStretchPreservePitch,
                crossfade: crossfade,
                automation: automation.isNotEmpty ? automation : null,
                rowAlreadyEnsured: true,
                notifyUi: false,
                updateProjectDuration: false,
                startWaveform: false,
                assumeFreshEngineDefaults: true,
              );
              if (_audioTracks.length > beforeCount) {
                final tr = _audioTracks.last;
                tr.crossfade = crossfade;
                tr.gain = gain;
                tr.pitchSemitones = pitchSemitones;
                tr.isReversed = isReversed;
                tr.sourceTempoBpm = sourceTempoBpm;
                tr.stretchToProjectTempo = stretchToProjectTempo;
                tr.tempoStretchPreservePitch = tempoStretchPreservePitch;
                tr.volumeAutomation = automation.isNotEmpty
                    ? automation
                    : [
                        AutomationPoint(x: 0.0, volume: 1.0),
                        AutomationPoint(x: 1.0, volume: 1.0)
                      ];
                loadedTracksForWaveforms.add(tr);
              }
              continue;
            }
            debugPrint("Missing audio file: ${audioFile.path}");
            continue;
          }

          await ensureTrackRowReady(rowIndex);
          final beforeCount = _audioTracks.length;
          if (clipKind == ClipKind.midi) {
            await _addMidiTrackFromProjectFile(
              projectAudioFile: audioFile,
              label: label.isEmpty ? instrumentName : label,
              row: rowIndex,
              timeMs: offsetSec * 1000.0,
              instrumentId:
                  instrumentId.isEmpty ? defaultInstrumentId : instrumentId,
              instrumentName: instrumentName.isEmpty
                  ? defaultInstrumentName
                  : instrumentName,
              instrumentParams: instrumentParams.isNotEmpty
                  ? instrumentParams
                  : _instrumentParamsFromSpec(
                      _instrumentSpecById(instrumentId.isEmpty
                          ? defaultInstrumentId
                          : instrumentId),
                    ),
              midiNotes: midiNotes,
              trimStartRequested: trimStartRequested,
              trimEndRequested: trimEndRequested,
              gain: gain,
              pitchSemitones: pitchSemitones,
              sourceTempoBpm: sourceTempoBpm,
              stretchToProjectTempo: stretchToProjectTempo,
              tempoStretchPreservePitch: tempoStretchPreservePitch,
              crossfade: crossfade,
              automation: automation.isNotEmpty ? automation : null,
              rowAlreadyEnsured: true,
              notifyUi: false,
              updateProjectDuration: false,
              startWaveform: false,
              assumeFreshEngineDefaults: true,
            );
          } else {
            await _addAudioTrackFromProjectFile(
              projectAudioFile: audioFile,
              label: label,
              row: rowIndex,
              timeMs: offsetSec * 1000.0,
              trimStartRequested: trimStartRequested,
              trimEndRequested: trimEndRequested,
              gain: gain,
              pitchSemitones: pitchSemitones,
              isReversed: isReversed,
              sourceTempoBpm: sourceTempoBpm,
              stretchToProjectTempo: stretchToProjectTempo,
              tempoStretchPreservePitch: tempoStretchPreservePitch,
              crossfade: crossfade,
              automation: automation.isNotEmpty ? automation : null,
              rowAlreadyEnsured: true,
              notifyUi: false,
              updateProjectDuration: false,
              startWaveform: false,
              assumeFreshEngineDefaults: true,
            );
          }
          if (_audioTracks.length <= beforeCount) {
            continue;
          }

          // After _addAudioTrackFromFile, the newest track is last
          // I think this code is deprecated
          final tr = _audioTracks.last;
          tr.crossfade = crossfade;
          tr.gain = gain;
          tr.pitchSemitones = pitchSemitones;
          tr.isReversed = isReversed;
          tr.sourceTempoBpm = sourceTempoBpm;
          tr.stretchToProjectTempo = stretchToProjectTempo;
          tr.tempoStretchPreservePitch = tempoStretchPreservePitch;
          tr.volumeAutomation = automation.isNotEmpty
              ? automation
              : [
                  AutomationPoint(x: 0.0, volume: 1.0),
                  AutomationPoint(x: 1.0, volume: 1.0)
                ];
          loadedTracksForWaveforms.add(tr);
        }
      } finally {
        await JuceAudioEngine.endProjectClipLoad();
      }

      _updateOverallDurationIfNeeded();

      final rowStatesList = (json["rowStates"] as List?) ?? [];

      for (final rs in rowStatesList) {
        final snap =
            RowStateSnapshot.fromJson((rs as Map).cast<String, dynamic>());
        // Row IDs are session-scoped and can be reassigned after reopen.
        // Prefer persisted row order index, and only fall back to rowId lookup.
        var r = snap.row;
        if (r < 0 || r >= _rowCount) {
          r = snap.rowId >= 0 ? _rowIndexForId(snap.rowId) : -1;
        }

        // Safety check
        if (r < 0 || r >= _rowCount) continue;

        // Restore pan & gain
        _rowPan[r] = snap.pan;
        _rowGain[r] = _normalizeLoadedGainUi(
          snap.gain,
          projectVersion: projectVersion,
        );

        // Restore automation (deep copy!)
        _rowVolumeAutomation[r] =
            snap.volumeAutomation.map((p) => p.copy()).toList();
        _restoreAutomationLanesForRow(
          r,
          snap.automationLanes,
          selectedTargetId: snap.selectedAutomationTargetId,
        );
        _restoreAutomationClipsForRow(r, snap.automationClips);

        await JuceAudioEngine.setRowGain(r, _rowGain[r]);
        await JuceAudioEngine.setRowPan(r, snap.pan);
      }

      await _ensureLoadedAutomationDisplayRowsExist();

      // Restore FX snapshots after tracks exist
      final rowFxList = (json["rowEffects"] as List?) ?? [];
      _rowEffectSnapshotsByRowId.clear();
      for (final rf in rowFxList) {
        final snap = RowEffectsSnapshotJson.fromJson(
            (rf as Map).cast<String, dynamic>());
        if (snap.rowId >= 0) {
          _rowEffectSnapshotsByRowId[snap.rowId] = snap;
        }
        // Same reasoning as rowStates above: saved index is the stable restore
        // anchor across sessions; rowId is a best-effort fallback.
        var resolvedRow = snap.row;
        if (resolvedRow < 0 || resolvedRow >= _rowCount) {
          resolvedRow = snap.rowId >= 0 ? _rowIndexForId(snap.rowId) : -1;
        }
        if (resolvedRow < 0 || resolvedRow >= _rowCount) {
          continue;
        }
        await restoreRowSnapshot(
          RowEffectsSnapshot(
            resolvedRow,
            snap.effects,
            rowId: snap.rowId,
          ),
        );
      }
      final master = json["master"] as Map<String, dynamic>?;

      if (master != null) {
        // Restore FX chain FIRST
        final masterFx = master["effects"];
        if (masterFx != null) {
          final ms = MasterEffectsSnapshotJson.fromJson(masterFx);
          _masterEffectSnapshot = ms;
          await restoreMasterSnapshot(ms);
        }

        // THEN restore gain & pan
        final gain = _normalizeLoadedGainUi(
          (master["gain"] as num?)?.toDouble(),
          projectVersion: projectVersion,
        );
        final pan = (master["pan"] as num?)?.toDouble() ?? 0.5;

        _masterGain = gain;
        _masterPan = pan;
        await JuceAudioEngine.setMasterGain(_masterGain);
        await JuceAudioEngine.setMasterPan(_masterPan);
      }
      _syncEffectSnapshotCacheToCurrentRows();

      await _refreshAutomationTargetsForAllRows(
        syncNativeWhenDone: false,
      );

      // Prime transport state and, on iOS, recover any missing output route
      // before the first user-driven play.
      _setGlobalAudioClock(Duration.zero);
      await JuceAudioEngine.setTransportSeconds(0.001);
      await JuceAudioEngine.setTransportSeconds(0.0);
      await JuceAudioEngine.setMetronomeTransportMs(0.0);
      if (Platform.isIOS) {
        await JuceAudioEngine.preparePlaybackRoute(reason: 'projectLoad');
      }
      await _syncNativeAutomationForAllRows();
      await _stabilizeAutomationTargetsAfterProjectLoad();
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (!mounted) return;
        for (final track in loadedTracksForWaveforms) {
          _startWaveformExtraction(track);
        }
        for (int row = 0; row < _rowCount; row++) {
          _refreshRowFx(row);
        }
      });
      unawaited(
        AnalyticsService.instance.trackScreen(
          AnalyticsScreenNames.projectEditor,
          properties: <String, Object?>{
            'project_id': _projectId,
          },
        ),
      );
      unawaited(
        AnalyticsService.instance.track(
          AnalyticsEvents.projectOpened(
            projectId: _projectId,
            trackCount: ProjectManager.extractTrackCount(json),
          ),
        ),
      );
      setState(() {});
    } catch (e) {
      debugPrint("Project load failed: $e");
    } finally {
      _isProjectLoading = false;
      unawaited(_flushDeferredAndroidRouteRefreshIfNeeded());
    }
  }

  AudioTrack? _primarySelectedClipOrNull() {
    final index = _timelinePrimarySelectedClipIndex;
    if (index >= 0 && index < _audioTracks.length) {
      return _audioTracks[index];
    }
    return null;
  }

  AudioTrack? _armedMidiClipOrNull() {
    return resolveArmedMidiClip(
      tracks: _audioTracks,
      activeMidiClipEngineId: _activeMidiClipEngineId,
      primarySelectedClipIndex: _timelinePrimarySelectedClipIndex,
    );
  }

  Future<bool> _setLiveMidiInputTargetClipIfNeeded(
    int clipId, {
    bool clearPendingEvents = true,
    bool force = false,
  }) async {
    if (!_liveMidiEventPlaybackSupported) return false;
    final safeClipId = clipId < 0 ? -1 : clipId;
    if (!force && _lastLiveMidiInputTargetClipId == safeClipId) {
      return true;
    }
    final ok = await JuceAudioEngine.setLiveMidiInputTargetClip(safeClipId);
    if (!ok && safeClipId >= 0) {
      return false;
    }
    _lastLiveMidiInputTargetClipId = safeClipId;
    if (clearPendingEvents) {
      await JuceAudioEngine.consumeLiveMidiInputEvents();
    }
    return true;
  }

  Future<void> _syncLiveMidiInputTargetClip() async {
    if (!_liveMidiEventPlaybackSupported || _isMidiClipRecording) return;
    final targetClipId = _armedMidiClipOrNull()?.engineClipId ?? -1;
    await _setLiveMidiInputTargetClipIfNeeded(targetClipId);
  }

  void _handleUndoHistoryChanged() {
    final action = _undoManager.lastAction;
    if (action == null) {
      _scheduleProjectAutosave();
      return;
    }
    unawaited(_refreshAutosaveCachesForUndoAction(action));
  }

  Future<void> _refreshAutosaveCachesForUndoAction(
    EditorUndoAction action,
  ) async {
    try {
      switch (action) {
        case final BypassEffectAction effectAction:
          await _refreshPersistedEffectSnapshotForRow(effectAction.row);
        case final InsertEffectAction effectAction:
          await _refreshPersistedEffectSnapshotForRow(effectAction.row);
        case final RemoveEffectAction effectAction:
          await _refreshPersistedEffectSnapshotForRow(effectAction.row);
        case final ReorderEffectAction effectAction:
          await _refreshPersistedEffectSnapshotForRow(effectAction.row);
        case final SetEffectParamAction effectAction:
          await _refreshPersistedEffectSnapshotForRow(effectAction.row);
        case final TrackPresetChangeAction trackPresetAction:
          await _refreshPersistedEffectSnapshotForRow(
            trackPresetAction.after.row,
          );
        case _RowEffectsAutomationSnapshotAction():
          await _refreshAllPersistedEffectSnapshots();
        case BypassMasterEffectAction():
          await _refreshPersistedMasterEffectSnapshot();
        case InsertMasterEffectAction():
          await _refreshPersistedMasterEffectSnapshot();
        case RemoveMasterEffectAction():
          await _refreshPersistedMasterEffectSnapshot();
        case ReorderMasterEffectAction():
          await _refreshPersistedMasterEffectSnapshot();
        case SetMasterEffectParamAction():
          await _refreshPersistedMasterEffectSnapshot();
        case MasterPresetChangeAction():
          await _refreshPersistedMasterEffectSnapshot();
        case _MasterEffectsSnapshotAction():
          await _refreshPersistedMasterEffectSnapshot();
        default:
          break;
      }
    } catch (e) {
      debugPrint('Autosave cache refresh failed: $e');
    }
    _scheduleProjectAutosave();
  }

  void _markProjectDirty({
    Duration debounce = const Duration(seconds: 1),
    bool immediate = false,
  }) {
    if (!_loadedOnce) return;
    if (_isProjectLoading) return;
    _projectAutosaveCoordinator.markDirty();
    if (immediate) {
      unawaited(_projectAutosaveCoordinator.flush());
      return;
    }
    _projectAutosaveCoordinator.schedule(debounce: debounce);
  }

  void _scheduleProjectAutosave({
    Duration debounce = const Duration(seconds: 1),
  }) {
    if (!_loadedOnce || _isProjectLoading) return;
    if (_isRecording || _isMidiClipRecording || _recordTransitionInFlight) {
      _projectAutosaveCoordinator.markDirty();
      return;
    }
    _projectAutosaveCoordinator.schedule(debounce: debounce);
  }

  Future<void> _refreshPersistedEffectSnapshotForRow(int row) async {
    if (row < 0 || row >= _rowCount) return;
    final snapshot = await captureRowSnapshot(row, rowId: _rowIdAt(row));
    if (snapshot.rowId >= 0) {
      _rowEffectSnapshotsByRowId[snapshot.rowId] = snapshot;
    }
  }

  Future<void> _refreshPersistedMasterEffectSnapshot() async {
    _masterEffectSnapshot = await captureMasterSnapshot();
  }

  void _syncEffectSnapshotCacheToCurrentRows() {
    final activeRowIds =
        _rows.map((row) => row.rowId).where((rowId) => rowId >= 0).toSet();
    _rowEffectSnapshotsByRowId.removeWhere(
      (rowId, _) => !activeRowIds.contains(rowId),
    );
    for (int row = 0; row < _rowCount; row++) {
      final rowId = _rowIdAt(row);
      if (rowId < 0 || _rowEffectSnapshotsByRowId.containsKey(rowId)) continue;
      _rowEffectSnapshotsByRowId[rowId] = RowEffectsSnapshot(
        row,
        <EffectSnapshot>[],
        rowId: rowId,
      );
    }
  }

  Map<String, dynamic> _buildProjectJsonSnapshot() {
    final now = DateTime.now().millisecondsSinceEpoch;
    final rowsJson = _rows
        .map((r) => {
              "rowId": r.rowId,
              "name": r.name,
              "iconId": r.iconId,
            })
        .toList(growable: false);

    final tracksJson = <Map<String, dynamic>>[];
    for (final tr in _audioTracks) {
      final src = tr.file;
      if (!tr.isMidi && !src.existsSync()) continue;
      final fileName = p.basename(src.path).trim();
      if (fileName.isEmpty) continue;
      tracksJson.add({
        "fileName": fileName,
        "label": tr.label,
        "clipType": tr.clipKind.wireName,
        "trimStartMs": tr.trimStart.inMilliseconds,
        "trimEndMs": tr.trimEnd.inMilliseconds,
        "offset": tr.offset,
        "crossfade": tr.crossfade,
        "gain": tr.gain,
        "pitchSemitones": tr.pitchSemitones,
        "isReversed": tr.isReversed,
        "sourceTempoBpm": tr.sourceTempoBpm,
        "stretchToProjectTempo": tr.stretchToProjectTempo,
        "tempoStretchPreservePitch": tr.tempoStretchPreservePitch,
        "rowIndex": tr.rowIndex,
        "rowId": tr.rowId,
        "automation": tr.volumeAutomation.map((p) => p.toJson()).toList(),
        "instrumentId": tr.instrumentId,
        "instrumentName": tr.instrumentName,
        "instrumentParams": tr.instrumentParams,
        "midiNotes": tr.midiNotes.map((n) => n.toJson()).toList(),
      });
    }

    final rowStates = <Map<String, dynamic>>[];
    final rowEffects = <Map<String, dynamic>>[];
    for (int row = 0; row < _rowCount; row++) {
      final rowId = _rowIdAt(row);
      rowStates.add(
        RowStateSnapshot(
          row: row,
          rowId: rowId,
          gain: _rowGain[row],
          pan: _rowPan[row],
          volumeAutomation:
              _rowVolumeAutomation[row].map((p) => p.copy()).toList(),
          automationLanes: _automationLanesForRowSave(row),
          automationClips: _automationClipsForRowSave(row),
          selectedAutomationTargetId: _rowSelectedAutomationTarget[row],
        ).toJson(),
      );

      final cached = rowId >= 0 ? _rowEffectSnapshotsByRowId[rowId] : null;
      rowEffects.add(
        RowEffectsSnapshot(
          row,
          cached?.effects ?? const <EffectSnapshot>[],
          rowId: rowId,
        ).toJson(),
      );
    }

    final assistantChat =
        ProjectChatHistory.fromChatMessages(_chatController.messages)
            .toJsonValue();
    final json = <String, dynamic>{
      "version": 5,
      "name": _projectName,
      "nameConfirmed": !_requiresProjectNaming,
      "createdAt": _projectCreatedAtMs > 0
          ? _projectCreatedAtMs
          : DateTime.now().millisecondsSinceEpoch,
      "lastOpenedAt": now,
      "projectId": _projectId,
      "tempoBpm": _tempo,
      "tempoStretchEnabled": _tempoStretchEnabled,
      "tempoStretchPreservePitchDefault": _tempoStretchPreservePitchDefault,
      "rows": rowsJson,
      "tracks": tracksJson,
      "rowStates": rowStates,
      "rowEffects": rowEffects,
      "master": {
        "gain": _masterGain,
        "pan": _masterPan,
        "effects": _masterEffectSnapshot.toJson(),
      },
      "ui": {
        "showProducerCaptureUi": _showProducerCaptureUi,
      },
    };
    if (assistantChat != null) {
      json["assistantChat"] = assistantChat;
    }
    return json;
  }

  Future<void> _performAutosaveWrite() async {
    _syncEffectSnapshotCacheToCurrentRows();
    final json = _buildProjectJsonSnapshot();
    await _projectPersistence.saveProjectState(
      projectDir: _projectDir,
      projectState: json,
      mode: AudioProjectSaveMode.autosave,
    );
  }

  Future<void> _uploadProjectTelemetrySnapshot(
    Map<String, dynamic> json,
  ) async {
    if (!mounted) return;
    final auth = context.read<AuthService>();
    try {
      final telemetrySnapshot = _buildProjectTelemetrySnapshot(json);
      unawaited(
        ProjectTelemetryService.instance.uploadProjectSnapshot(
          auth: auth,
          projectId: _projectId.trim(),
          projectName: _projectName,
          projectJson: Map<String, dynamic>.from(json),
          projectSnapshot: telemetrySnapshot,
        ),
      );
    } catch (e) {
      debugPrint("Project telemetry snapshot failed: $e");
    }
  }

  Future<void> _normalizeProjectAudioAssetsForCheckpoint() async {
    final audioDir = ProjectManager.audioDir(_projectDir);
    if (!await audioDir.exists()) {
      await audioDir.create(recursive: true);
    }

    final assignedFileNameBySourcePath = <String, String>{};
    final usedSavedFileNamesLower = <String>{};
    final referenced = <String>{};

    for (final tr in _audioTracks) {
      final src = tr.file;
      if (!src.existsSync()) continue;

      final normalizedSourcePath = p.normalize(src.path);
      final existingAssigned =
          assignedFileNameBySourcePath[normalizedSourcePath];
      final fileName = existingAssigned ??
          ProjectManager.uniqueAudioFileName(
            preferredName: _displayNameForFilePath(src.path),
            usedNamesLower: usedSavedFileNamesLower,
          );
      assignedFileNameBySourcePath[normalizedSourcePath] = fileName;
      referenced.add(fileName);
      final dst = File(p.join(audioDir.path, fileName));
      if (src.path != dst.path) {
        if (await dst.exists()) {
          await dst.delete();
        }
        await src.copy(dst.path);
      }
    }

    final files = audioDir.listSync().whereType<File>();
    for (final f in files) {
      final name = p.basename(f.path);
      if (!referenced.contains(name)) {
        try {
          await f.delete();
        } catch (_) {}
      }
    }
  }

  Future<void> _refreshAllPersistedEffectSnapshots() async {
    _syncEffectSnapshotCacheToCurrentRows();
    for (int row = 0; row < _rowCount; row++) {
      await _refreshPersistedEffectSnapshotForRow(row);
    }
    await _refreshPersistedMasterEffectSnapshot();
  }

  Future<void> _saveProject({bool showSnackBar = true}) async {
    try {
      await _projectAutosaveCoordinator.flush();
      await _normalizeProjectAudioAssetsForCheckpoint();
      await _refreshAllPersistedEffectSnapshots();
      final json = _buildProjectJsonSnapshot();
      await _projectPersistence.saveProjectState(
        projectDir: _projectDir,
        projectState: json,
        mode: AudioProjectSaveMode.checkpoint,
      );
      _projectAutosaveCoordinator.clearDirty();
      await _uploadProjectTelemetrySnapshot(json);

      if (mounted && showSnackBar) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text(L10n.translate(context, 'Project saved'))),
        );
      }
    } catch (e) {
      debugPrint("Project save failed: $e");
      if (mounted && showSnackBar) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text('${L10n.translate(context, 'Save failed')}: $e'),
          ),
        );
      }
    }
  }

  Future<String?> _showProjectNameDialog({
    required String title,
    required String initialName,
    String? hint,
  }) async {
    final resolvedHint = hint ?? L10n.translate(context, 'Project name');
    return showDialog<String>(
      context: context,
      builder: (ctx) => _ProjectNameInputDialog(
        title: title,
        initialName: initialName,
        hintText: resolvedHint,
      ),
    );
  }

  bool _looksLikeGeneratedUntitledProjectName(String name) {
    return RegExp(r'^Untitled Project(?: #\d+)?$').hasMatch(name.trim());
  }

  bool _projectRequiresNameConfirmation(Map<String, dynamic> json) {
    final confirmed = json['nameConfirmed'];
    if (confirmed is bool) {
      return !confirmed;
    }
    final currentName = (json['name'] as String?) ?? _projectName;
    return _looksLikeGeneratedUntitledProjectName(currentName);
  }

  void _remapProjectAudioPaths({
    required Directory oldProjectDir,
    required Directory newProjectDir,
  }) {
    final oldAudioDir = ProjectManager.audioDir(oldProjectDir).path;
    final newAudioDir = ProjectManager.audioDir(newProjectDir).path;

    for (final tr in _audioTracks) {
      final oldFilePath = tr.file.path;
      final oldOriginalPath = tr.originalFile.path;
      final fileName = p.basename(oldFilePath);
      final originalName = p.basename(oldOriginalPath);

      final shouldRemapFile = oldFilePath.startsWith(oldAudioDir) ||
          !File(oldFilePath).existsSync();
      final shouldRemapOriginal = oldOriginalPath.startsWith(oldAudioDir) ||
          !File(oldOriginalPath).existsSync();

      if (shouldRemapFile) {
        tr.file = File(p.join(newAudioDir, fileName));
      }
      if (shouldRemapOriginal) {
        tr.originalFile = File(p.join(newAudioDir, originalName));
      }
    }
  }

  Future<bool> _renameProjectAndSyncState(
    String nextName, {
    bool showSuccessSnackBar = true,
  }) async {
    final renamed = nextName.trim();
    if (renamed.isEmpty) return false;

    if (renamed == _projectName) {
      _setStateAndRefreshProjectSettings(() {
        _requiresProjectNaming = false;
      });
      _scheduleProjectAutosave();
      return true;
    }

    try {
      final oldProjectDir = _projectDir;
      final newDir = await ProjectManager.renameProject(_projectDir, renamed);
      _setStateAndRefreshProjectSettings(() {
        _projectDir = newDir;
        _projectName = p.basename(newDir.path);
        _requiresProjectNaming = false;
        _remapProjectAudioPaths(
          oldProjectDir: oldProjectDir,
          newProjectDir: newDir,
        );
      });
      _scheduleProjectAutosave();
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text('${L10n.translate(context, 'Rename failed')}: $e'),
          ),
        );
      }
      return false;
    }

    if (mounted && showSuccessSnackBar) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text(L10n.translate(context, 'Project renamed'))),
      );
    }
    return true;
  }

  Future<bool> _ensureProjectNamedOnFirstExit() async {
    if (!_requiresProjectNaming) return true;
    final renamed = await _showProjectNameDialog(
      title: L10n.translate(context, 'Name Your Project'),
      initialName: _projectName,
      hint: L10n.translate(context, 'Project name'),
    );
    if (renamed == null) return false;
    final newName = renamed.trim();
    if (newName.isEmpty) return false;
    if (newName == _projectName) {
      setState(() => _requiresProjectNaming = false);
      return true;
    }
    return _renameProjectAndSyncState(
      newName,
      showSuccessSnackBar: false,
    );
  }

  Future<void> _handleBackPressed() async {
    if (_isDialogOpen) return;
    _isDialogOpen = true;

    if (_isPlaying) {
      _isPlaying = false;
      await _pauseAudio(_audioEditorStateSetter ?? (fn) {});
    }

    final canExit = await _ensureProjectNamedOnFirstExit();
    if (!canExit) {
      _isDialogOpen = false;
      return;
    }

    await _saveProject(showSnackBar: false);
    _setDawPanelVisible('add_actions', false);
    _setDawPanelVisible('chat_panel', false);
    _setDawPanelVisible('chat_input', false);
    _setDawPanelVisible('sample_browser', false);
    _setDawPanelVisible('piano_roll', false);
    final activeTopPopupPanelId = _topPopupPanelId(_activeTopPopup);
    if (activeTopPopupPanelId != null) {
      _setDawPanelVisible(activeTopPopupPanelId, false);
    }

    if (mounted) {
      _pausePlayback();
      for (var track in _audioTracks) {
        track.audioStartTimer?.cancel();
      }
      await JuceAudioEngine.shutdown();
      Navigator.of(context).pop();
    }
  }

  void _handleBackButtonTap() {
    if (_backButtonExitInFlight) return;
    _trackUiClick(
      controlId: 'back_button',
      surface: 'top_bar',
    );
    unawaited(_runBackButtonExitSequence());
  }

  Future<void> _runBackButtonExitSequence() async {
    _backButtonExitInFlight = true;
    if (mounted) {
      setState(() {
        _backButtonTapFeedbackActive = true;
      });
    }
    unawaited(AppHaptics.impact(AppHapticImpact.light));
    await SchedulerBinding.instance.endOfFrame;
    await Future<void>.delayed(const Duration(milliseconds: 48));
    if (mounted && _backButtonTapFeedbackActive) {
      setState(() {
        _backButtonTapFeedbackActive = false;
      });
    }
    try {
      await _handleBackPressed();
    } finally {
      _backButtonExitInFlight = false;
      if (mounted && (_backButtonTapFeedbackActive || _backButtonPressed)) {
        setState(() {
          _backButtonTapFeedbackActive = false;
          _backButtonPressed = false;
        });
      }
    }
  }

  // Helper: Format Duration as mm:ss:xx (first two digits of ms).
  String _formatDuration(Duration duration) {
    String twoDigits(int n) => n.toString().padLeft(2, '0');
    String firstTwoMsDigits(int milliseconds) {
      final msString = milliseconds.toString().padLeft(3, '0');
      return msString.substring(0, 2);
    }

    final minutes = twoDigits(duration.inMinutes.remainder(60));
    final seconds = twoDigits(duration.inSeconds.remainder(60));
    final millisecondsFirstTwo =
        firstTwoMsDigits(duration.inMilliseconds.remainder(1000));

    return "$minutes:$seconds:$millisecondsFirstTwo";
  }

  void prewarmFFT() async {
    // Create a small dummy signal
    List<double> dummySignal = List.filled(1024, 0.0);
    // Fill it with some dummy data
    for (int i = 0; i < dummySignal.length; i++) {
      dummySignal[i] = sin(2 * pi * i / dummySignal.length);
    }
    // Get a padded length for the dummy signal (e.g., next power of 2)
    int paddedLength = _nextPowerOf2(dummySignal.length);
    final fft = FFT(paddedLength);
    // Perform a dummy FFT
    List<double> paddedDummy = List.filled(paddedLength, 0.0);
    paddedDummy.setAll(0, dummySignal);
    normalize(paddedDummy);
    fft.realFft(paddedDummy);
  }

  void _startMeterPolling() {
    if (!_shouldPollMetersDuringPlayback) return;
    if (_meterPolling) return;
    _meterPolling = true;

    // Defensive: re-enable native metering whenever polling starts.
    unawaited(_setNativeMeteringEnabled(true));

    _meterTimer?.cancel();
    _meterDecayTimer?.cancel();

    _meterTimer = Timer.periodic(const Duration(milliseconds: 33), (_) async {
      // prevent overlapping async ticks (super important)
      if (!_meterPolling) return; // stopped mid-flight
      if (_meterPollingBusy) return; // prevent overlap
      _meterPollingBusy = true;

      try {
        final packed = await JuceAudioEngine.getAllMeterValues();
        if (!_meterPolling || packed.isEmpty) return;

        // expected length: 5 * (1 + kNumRows)
        final stride = _meterStride;

        // ---- MASTER ----
        if (packed.length >= stride) {
          final m0 = 0;

          _meters.setMaster(
            MeterFrame(
              peakL: packed[m0 + 0].clamp(0.0, 1.0),
              peakR: packed[m0 + 1].clamp(0.0, 1.0),
              rmsL: packed[m0 + 2].clamp(0.0, 1.0),
              rmsR: packed[m0 + 3].clamp(0.0, 1.0),
              clip: packed[m0 + 4] > 0.5,
            ),
          );
        }

        // ---- ROWS ----
        // Use whichever source of truth you already have:
        // - kNumRows (your constant)
        // - or _meters.rows.length
        final rowCount = _rowCount; // or: _meters.rows.length

        for (int row = 0; row < rowCount; row++) {
          final base = stride * (1 + row);
          if (base + 4 >= packed.length) break;

          _meters.setRow(
            row,
            MeterFrame(
              peakL: packed[base + 0].clamp(0.0, 1.0),
              peakR: packed[base + 1].clamp(0.0, 1.0),
              rmsL: packed[base + 2].clamp(0.0, 1.0),
              rmsR: packed[base + 3].clamp(0.0, 1.0),
              clip: packed[base + 4] > 0.5,
            ),
          );
        }
      } catch (_) {
        // ignore transient channel errors
      } finally {
        _meterPollingBusy = false;
      }
    });
  }

  void _stopMeterPolling({bool decayToZero = true}) {
    _meterPolling = false;
    _meterTimer?.cancel();
    _meterTimer = null;

    // in case we stopped while an await was in-flight
    _meterPollingBusy = false;
    unawaited(_setNativeMeteringEnabled(false));

    if (!decayToZero) {
      _meterDecayTimer?.cancel();
      _meters.zeroAll();
      return;
    }

    _startMeterDecayToZero();
  }

  void _startMeterDecayToZero() {
    _meterDecayTimer?.cancel();

    // ~30fps-ish but cheap
    _meterDecayTimer = Timer.periodic(const Duration(milliseconds: 33), (_) {
      // if we started polling again, stop decaying
      if (_meterPolling) {
        _meterDecayTimer?.cancel();
        _meterDecayTimer = null;
        return;
      }

      _meters.decayAll(mul: 0.82); // tweak feel: 0.75 faster, 0.9 slower

      if (_meters.isAllZero) {
        _meterDecayTimer?.cancel();
        _meterDecayTimer = null;
      }
    });
  }

  bool get _shouldPollMetersDuringPlayback =>
      _isPlaying && !(_showPianoRoll && _pianoRollFullscreen);

  void _syncMeterPollingForVisibility() {
    if (_shouldPollMetersDuringPlayback) {
      _startMeterPolling();
    } else {
      _stopMeterPolling();
    }
  }

  Future<void> _setNativeMeteringEnabled(bool enabled) async {
    try {
      await JuceAudioEngine.setMasterMeterEnabled(enabled);
      await JuceAudioEngine.setRowMetersEnabled(enabled);
    } catch (_) {
      // Native bridge can race shutdown/teardown; ignore best-effort toggles.
    }
  }

  /// Calculate effective audio position for a given track based on video position.
  Duration _calculateEffectiveAudioPositionForTrack(
      AudioTrack track, Duration videoPos) {
    final offsetDuration =
        Duration(milliseconds: (track.offset * 1000).toInt());
    if (videoPos < offsetDuration) {
      return track.trimStart;
    } else {
      var effectiveAudioPos = track.trimStart + (videoPos - offsetDuration);
      if (effectiveAudioPos > track.trimEnd) {
        effectiveAudioPos = track.trimEnd;
      }
      return effectiveAudioPos;
    }
  }

  // PLAY/PAUSE TOGGLE using a global _audioStarted flag.
  Future<void> _togglePlayPause() async {
    await _togglePlayPauseAudio(_safeAudioEditorStateSetter);
    return;
  }

  Future<void> _togglePlayPauseAudio(StateSetter setLocalState) async {
    // if (_audioTracks.isEmpty) {
    //   return;
    // }

    setState(() {
      //NOTE: before it was setLocalState, shouldn't have broke anything tho
      _isPlaying = !_isPlaying;
    });

    if (_isPlaying) {
      await _resumeAudio(setLocalState);
    } else {
      await _pauseAudio(setLocalState);
    }
  }

  Future<void> _resumeAudio(StateSetter setLocalState) async {
    if (_loopEnabled &&
        _loopEndMs > _loopStartMs &&
        _globalAudioClock >= Duration(milliseconds: _loopEndMs)) {
      final loopStart = Duration(milliseconds: _loopStartMs);
      _syncTransportClock(loopStart, playing: false);
    }
    _transportPlayStartSyncGraceUntil =
        _transportUiStopwatch.elapsed + _kTransportPlayStartSyncGrace;
    _transportEndCheckGraceUntil =
        _transportUiStopwatch.elapsed + const Duration(milliseconds: 420);
    await JuceAudioEngine.setTransportSeconds(
        _globalAudioClock.inMilliseconds / 1000.0);
    await JuceAudioEngine.setMetronomeTransportMs(
        _globalAudioClock.inMilliseconds.toDouble());
    await JuceAudioEngine.play();
    _syncTransportClock(_globalAudioClock, playing: true);

    if (!(_transportTicker?.isActive ?? false)) {
      _transportTicker?.start();
    }

    _syncMeterPollingForVisibility();

    // Android can occasionally miss the first transport start edge.
    await Future<void>.delayed(const Duration(milliseconds: 90));
    if (!_isPlaying) return;
    await _pollTransportFromJuceIfNeeded(force: true);
    if (_transportRateSecPerSec <= 0.0) {
      await JuceAudioEngine.play();
    }
  }

  Future<void> _pauseAudio(StateSetter setLocalState) async {
    // On pause, cancel the timer, pause each track, and importantly, reset audioStarted.
    // _audioAutomationTimer?.cancel();
    _transportTicker?.stop();

    for (var track in _audioTracks) {
      // await track.player.pause();
      // maybe below deprecated?
      track.audioStarted =
          false; // Reset flag on pause so that resume triggers play.
    }
    await JuceAudioEngine.pause();
    await _pollTransportFromJuceIfNeeded(force: true);
    _syncTransportClock(_globalAudioClock, playing: false);

    _stopMeterPolling();
  }

  Future<void> _restartAudio(StateSetter setLocalState) async {
    // Pause all tracks and seek them to their trimStart.
    // _audioAutomationTimer?.cancel();
    _transportTicker?.stop();

    Duration newStartPoint = Duration.zero;

    // Case of loop is enabled
    if (_loopEnabled) {
      newStartPoint = Duration(milliseconds: _loopStartMs);
    }

    for (final track in _audioTracks) {
      track.audioStarted = false;
      track.audioStartTimer?.cancel();
      track.currentPosition = newStartPoint;
    }
    await JuceAudioEngine.pause();
    await JuceAudioEngine.setTransportSeconds(
        newStartPoint.inMilliseconds / 1000.0);

    // Reset the global audio clock.
    setState(() {
      _syncTransportClock(newStartPoint, playing: false);
      _isPlaying = false;
    });

    _stopMeterPolling();
  }

  Future<void> _wrapPlaybackToLoopStart() async {
    if (_loopWrapInFlight) return;
    _loopWrapInFlight = true;
    try {
      await _restartAudio(_safeAudioEditorStateSetter);
      if (!mounted) return;
      await _togglePlayPauseAudio(_safeAudioEditorStateSetter);
    } finally {
      _loopWrapInFlight = false;
    }
  }

  // Pause helper
  Future<void> _pausePlayback() async {
    _transportTicker?.stop();

    // Pause all audio tracks at precise position
    for (var track in _audioTracks) {
      track.audioStartTimer
          ?.cancel(); // NEED THIS IN CASE THERE WAS A TIMER STARTED
    }
    await JuceAudioEngine.pause();
    await _pollTransportFromJuceIfNeeded(force: true);
    _syncTransportClock(_globalAudioClock, playing: false);
    _stopMeterPolling();
  }

  Future<_AudioExportSettings?> _showAudioExportSettingsSheet() async {
    final normalizedCurrentSettings =
        _normalizeAudioExportSettings(_audioExportSettings);
    _ExportAudioFormat selectedFormat = normalizedCurrentSettings.format;
    int selectedSampleRate = normalizedCurrentSettings.sampleRate;
    int selectedWavBitDepth = _audioExportSettings.wavBitDepth;
    bool selectedWavDithering = _audioExportSettings.wavDithering;
    int selectedMp3Bitrate = _audioExportSettings.mp3BitrateKbps;
    _ExportMp3Mode selectedMp3Mode = _audioExportSettings.mp3Mode;
    int selectedMp3VbrQuality = _audioExportSettings.mp3VbrQuality;
    _ExportChannelMode selectedChannelMode = _audioExportSettings.channelMode;
    bool selectedNormalize = _audioExportSettings.normalize;
    double selectedNormalizeTargetDb = _audioExportSettings.normalizeTargetDb;
    _ExportResampleQuality selectedResampleQuality =
        _audioExportSettings.resampleQuality;
    bool showAdvanced = false;
    final nativeWavOnly = _desktopNativeWavOnlyExport;
    if (nativeWavOnly) {
      selectedFormat = _ExportAudioFormat.wav;
      selectedChannelMode = _ExportChannelMode.stereo;
      selectedNormalize = false;
      selectedResampleQuality = _ExportResampleQuality.best;
    }
    selectedSampleRate = _normalizeExportSampleRateForFormat(
      selectedFormat,
      selectedSampleRate,
    );
    if (!_kExportWavBitDepths.contains(selectedWavBitDepth)) {
      selectedWavBitDepth = _kExportWavBitDepths.first;
    }
    if (!_kExportMp3Bitrates.contains(selectedMp3Bitrate)) {
      selectedMp3Bitrate = _kExportMp3Bitrates.first;
    }
    if (!_kExportMp3VbrQualities.contains(selectedMp3VbrQuality)) {
      selectedMp3VbrQuality = _kExportMp3VbrQualities.first;
    }
    selectedNormalizeTargetDb = selectedNormalizeTargetDb
        .clamp(
          _kExportNormalizeTargetDbMin,
          _kExportNormalizeTargetDbMax,
        )
        .toDouble();
    if (!_ExportMp3Mode.values.contains(selectedMp3Mode)) {
      selectedMp3Mode = _ExportMp3Mode.cbr;
    }
    if (!_ExportChannelMode.values.contains(selectedChannelMode)) {
      selectedChannelMode = _ExportChannelMode.stereo;
    }
    if (!_ExportResampleQuality.values.contains(selectedResampleQuality)) {
      selectedResampleQuality = _ExportResampleQuality.best;
    }

    if (mounted) {
      setState(() => _isExportSheetOpen = true);
    }
