  bool _matchesLegacyBuiltInParams(
    Map<String, double> params,
    Map<String, double> legacy,
  ) {
    if (params.length != legacy.length) return false;
    for (final entry in legacy.entries) {
      final value = params[entry.key];
      if (value == null || (value - entry.value).abs() > 0.0001) {
        return false;
      }
    }
    return true;
  }

  Map<String, double> _migrateLegacyBuiltInParams(
    String instrumentId,
    Map<String, double> params,
    Map<String, double> normalizedDefaults,
  ) {
    final snapshots = _kLegacyBuiltInInstrumentParamSnapshots[instrumentId];
    if (snapshots == null) return params;
    for (final legacy in snapshots) {
      if (_matchesLegacyBuiltInParams(params, legacy)) {
        return Map<String, double>.from(normalizedDefaults);
      }
    }
    return params;
  }

  Map<String, double> _normalizedInstrumentParamsForPlayback(
    String instrumentId,
    Map<String, double> params,
  ) {
    final spec = _findInstrumentSpecById(instrumentId);
    if (spec == null || _isSampledInstrumentSpec(spec)) {
      return Map<String, double>.from(params);
    }

    final normalized = _instrumentParamsFromSpec(spec);
    final lowerId = instrumentId.trim().toLowerCase();
    final merged = Map<String, double>.from(
      _migrateLegacyBuiltInParams(lowerId, params, normalized),
    );
    final legacyOscillator = _kLegacyBuiltInOscillatorDefaults[lowerId];
    if (legacyOscillator != null) {
      final currentOscillator = merged['oscillator'];
      if (currentOscillator == null ||
          (currentOscillator - legacyOscillator).abs() < 0.0001) {
        merged.remove('oscillator');
      }
    }

    normalized.addAll(merged);
    return normalized;
  }

  List<MidiNote> _defaultMidiNotesForInstrument(String instrumentId) {
    final now = DateTime.now().microsecondsSinceEpoch;
    int noteIndex = 0;
    MidiNote seededNote(
      int pitch,
      double startBeat,
      double lengthBeats,
      double velocity,
    ) {
      return MidiNote(
        id: '${now}_${noteIndex++}',
        pitch: pitch,
        startBeat: startBeat,
        lengthBeats: lengthBeats,
        velocity: velocity,
      );
    }

    List<MidiNote> seededPattern(List<List<num>> data) {
      return data
          .map(
            (entry) => seededNote(
              entry[0].toInt(),
              entry[1].toDouble(),
              entry[2].toDouble(),
              entry[3].toDouble(),
            ),
          )
          .toList(growable: false);
    }

    if (instrumentId == 'mixroom.drum_808_starter') {
      return <MidiNote>[
        MidiNote(
            id: '${now}_0',
            pitch: 49,
            startBeat: 0.0,
            lengthBeats: 0.25,
            velocity: 0.76),
        MidiNote(
            id: '${now}_1',
            pitch: 36,
            startBeat: 0.0,
            lengthBeats: 0.25,
            velocity: 0.98),
        MidiNote(
            id: '${now}_2',
            pitch: 42,
            startBeat: 0.5,
            lengthBeats: 0.125,
            velocity: 0.62),
        MidiNote(
            id: '${now}_3',
            pitch: 38,
            startBeat: 1.0,
            lengthBeats: 0.25,
            velocity: 0.84),
        MidiNote(
            id: '${now}_4',
            pitch: 42,
            startBeat: 1.5,
            lengthBeats: 0.125,
            velocity: 0.58),
        MidiNote(
            id: '${now}_5',
            pitch: 44,
            startBeat: 1.75,
            lengthBeats: 0.125,
            velocity: 0.66),
        MidiNote(
            id: '${now}_6',
            pitch: 36,
            startBeat: 2.0,
            lengthBeats: 0.25,
            velocity: 0.96),
        MidiNote(
            id: '${now}_7',
            pitch: 42,
            startBeat: 2.5,
            lengthBeats: 0.125,
            velocity: 0.6),
        MidiNote(
            id: '${now}_8',
            pitch: 45,
            startBeat: 2.75,
            lengthBeats: 0.25,
            velocity: 0.72),
        MidiNote(
            id: '${now}_9',
            pitch: 38,
            startBeat: 3.0,
            lengthBeats: 0.25,
            velocity: 0.86),
        MidiNote(
            id: '${now}_10',
            pitch: 36,
            startBeat: 3.25,
            lengthBeats: 0.25,
            velocity: 0.92),
        MidiNote(
            id: '${now}_11',
            pitch: 47,
            startBeat: 3.5,
            lengthBeats: 0.25,
            velocity: 0.7),
      ];
    }
    if (_isSampledInstrumentId(instrumentId)) {
      final name = _instrumentNameFromId(instrumentId).toLowerCase();
      if (instrumentId == 'sfz.vsco.organ_quiet' ||
          instrumentId == 'sfz.vsco.organ_loud' ||
          name.contains('organ')) {
        return seededPattern(<List<num>>[
