  Future<void> _addInstrumentClipFromPicker() async {
    if (!await _ensureCanAddAnotherClip(
      basicModeMessage: 'Upgrade to Pro mode to add more than 3 clips.',
    )) {
      return;
    }

    if (!mounted) return;
    if (!mounted) return;
    final catalog = _activeInstrumentCatalog();
    if (catalog.isEmpty) return;
    final categories = _instrumentPickerCategories();
    final selected = await showDialog<Map<String, dynamic>>(
      context: context,
      builder: (ctx) {
        var selectedCategory = categories.first;
        return StatefulBuilder(
          builder: (ctx, setModalState) {
            final viewport = MediaQuery.of(ctx).size;
            final dialogWidth = math.min(560.0, viewport.width - 48.0);
            final dialogHeight =
                math.min(480.0, math.max(320.0, viewport.height * 0.68));
            final filtered = catalog.where((spec) {
              if (selectedCategory == 'All') return true;
              return _instrumentPickerCategory(spec) == selectedCategory;
            }).toList(growable: true)
              ..sort(_compareInstrumentSpecsForPicker);
            return Dialog(
              backgroundColor: Colors.transparent,
              elevation: 0,
              insetPadding:
                  const EdgeInsets.symmetric(horizontal: 22, vertical: 26),
              child: SizedBox(
                width: dialogWidth,
                child: _buildDawConnectedSurface(
                  borderRadius: BorderRadius.circular(28),
                  active: true,
                  showOverlay: false,
                  padding: const EdgeInsets.fromLTRB(16, 14, 16, 12),
                  child: SizedBox(
                    height: dialogHeight,
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Row(
                          children: [
                            Expanded(
                              child: Text(
                                L10n.translate(ctx, 'Choose Instrument'),
                                style: const TextStyle(
                                  fontFamily: 'Pretendard',
                                  color: Color(0xFFF4F4F4),
                                  fontSize: 15,
                                  fontWeight: FontWeight.w600,
                                  letterSpacing: -0.2,
                                ),
                              ),
                            ),
                            IconButton(
                              visualDensity: VisualDensity.compact,
                              constraints: const BoxConstraints.tightFor(
                                width: 30,
                                height: 30,
                              ),
                              padding: EdgeInsets.zero,
                              splashRadius: 14,
                              onPressed: () => Navigator.pop(ctx),
                              icon: const Icon(
                                Icons.close_rounded,
                                size: 16,
                                color: Color(0xB8F4F4F4),
                              ),
                            ),
                          ],
                        ),
                        const SizedBox(height: 10),
                        SizedBox(
                          height: 36,
                          child: ListView.separated(
                            scrollDirection: Axis.horizontal,
                            itemCount: categories.length,
                            separatorBuilder: (_, __) =>
                                const SizedBox(width: 7),
                            itemBuilder: (context, index) {
                              final category = categories[index];
                              final selected = category == selectedCategory;
                              final accent = _instrumentPickerAccent(category);
                              return InkWell(
                                onTap: () => setModalState(
                                    () => selectedCategory = category),
                                borderRadius: BorderRadius.circular(999),
                                child: AnimatedContainer(
                                  duration: const Duration(milliseconds: 120),
                                  constraints: const BoxConstraints(
                                    minHeight: 30,
                                    minWidth: 74,
                                  ),
                                  alignment: Alignment.center,
                                  padding: const EdgeInsets.symmetric(
                                      horizontal: 10, vertical: 4),
                                  decoration: BoxDecoration(
                                    color: selected
                                        ? const Color.fromRGBO(
                                            244, 244, 244, 0.20)
                                        : const Color.fromRGBO(
                                            80, 91, 107, 0.24),
                                    borderRadius: BorderRadius.circular(999),
                                    border: Border.all(
                                      color: selected
                                          ? Colors.white.withValues(alpha: 0.20)
                                          : Colors.white
                                              .withValues(alpha: 0.10),
                                    ),
                                  ),
                                  child: Row(
                                    mainAxisSize: MainAxisSize.min,
                                    children: [
                                      Icon(
                                        _instrumentPickerIcon(category),
                                        size: 12.4,
                                        color: selected
                                            ? accent
                                            : const Color(0xB8F4F4F4),
                                      ),
                                      const SizedBox(width: 5),
                                      Text(
                                        category,
                                        textAlign: TextAlign.center,
                                        style: TextStyle(
                                          color: selected
                                              ? const Color(0xFFF4F4F4)
                                              : const Color(0xB8F4F4F4),
                                          fontSize: 11.1,
                                          fontWeight: FontWeight.w700,
                                          height: 1.0,
                                          fontFamily: 'Pretendard',
                                        ),
                                      ),
                                    ],
                                  ),
                                ),
                              );
                            },
                          ),
                        ),
                        const SizedBox(height: 10),
                        Expanded(
                          child: filtered.isEmpty
                              ? Center(
                                  child: Text(
                                    L10n.translate(
                                      ctx,
                                      'No instruments in this category.',
                                    ),
                                    style: TextStyle(
                                      color: const Color(0xFFF4F4F4)
                                          .withValues(alpha: 0.66),
                                      fontSize: 13,
                                      fontFamily: 'Pretendard',
                                    ),
                                  ),
                                )
                              : ListView.separated(
                                  padding: const EdgeInsets.symmetric(
                                      horizontal: 6, vertical: 6),
                                  itemCount: filtered.length,
                                  separatorBuilder: (_, __) => Padding(
                                    padding: const EdgeInsets.symmetric(
                                        horizontal: 8),
                                    child: Divider(
                                      height: 1,
                                      thickness: 1,
                                      color:
                                          Colors.white.withValues(alpha: 0.07),
                                    ),
                                  ),
                                  itemBuilder: (_, index) {
                                    final spec = filtered[index];
                                    return _buildInstrumentPickerRow(
                                      spec: spec,
                                      onTap: () => Navigator.pop(ctx, spec),
                                    );
                                  },
                                ),
                        ),
                        const SizedBox(height: 8),
                        Align(
                          alignment: Alignment.centerRight,
                          child: TextButton(
                            onPressed: () => Navigator.pop(ctx),
                            style: TextButton.styleFrom(
                              foregroundColor: const Color(0xFFF4F4F4),
                              textStyle: const TextStyle(
                                fontFamily: 'Pretendard',
                                fontWeight: FontWeight.w600,
                              ),
                            ),
                            child: Text(L10n.translate(ctx, 'Cancel')),
                          ),
                        ),
                      ],
                    ),
                  ),
                ),
              ),
            );
          },
        );
      },
    );

    if (selected == null) return;

    final defaultSpec = _defaultInstrumentSpec();
    final instrumentId =
        (selected['id'] as String?) ?? (defaultSpec['id'] as String?) ?? '';
    final instrumentName = (selected['name'] as String?) ??
        (defaultSpec['name'] as String?) ??
        'Instrument';
    final params = _instrumentParamsFromSpec(selected);
    final notes = _defaultMidiNotesForInstrument(instrumentId);

    await _undoManager.execute(
      AddMidiClipAction(
        addMidiClip: ({
          required String instrumentId,
          required String instrumentName,
          required Map<String, double> instrumentParams,
          required List<MidiNote> midiNotes,
          required int row,
          required double timeMs,
        }) =>
            _addMidiTrack(
          instrumentId: instrumentId,
          instrumentName: instrumentName,
          instrumentParams: instrumentParams,
          midiNotes: midiNotes,
          row: row,
          timeMs: timeMs,
        ),
        tracks: _audioTracks,
        instrumentId: instrumentId,
        instrumentName: instrumentName,
        instrumentParams: params,
        midiNotes: notes,
        row: _selectedRow,
        timeMs: _globalAudioClock.inMilliseconds.toDouble(),
      ),
    );
  }

  Future<void> _handleAddActionSelection(String action) async {
    _trackUiClick(
      controlId: action,
      surface: 'add_actions',
      extra: <String, Object?>{
        'action_id': action,
      },
    );
    if (mounted) {
      setState(() {
        _activeAddActionId = action;
      });
    }
    await Future<void>.delayed(const Duration(milliseconds: 65));
    _closeAddActionsPanel();
    if (action == 'audio') {
      await _pickAndInsertAudioTrack();
      return;
    }
    if (action == 'sample_browser') {
      await _openSampleBrowser(
          promptFolderIfEmpty: _sampleBrowserRoots.isEmpty);
      return;
    }
    if (action == 'instrument') {
      await _addInstrumentClipFromPicker();
    }
  }

