  Future<void> _selectInputDevice(MediaDeviceInfo device) async {
    final stream = await navigator.mediaDevices.getUserMedia({
      'audio': {'deviceId': device.deviceId},
      'video': false,
    });

    // Stop immediately — we are only probing
    for (var t in stream.getTracks()) {
      t.stop();
    }

    setState(() {
      _selectedInput = device;
    });
  }

  // iOS restricts this from happening, so give some message indicating it will have no effect, or prevent it
  Future<void> _selectOutputDevice(MediaDeviceInfo device) async {
    try {
      await Helper.selectAudioOutput(device.deviceId);
    } catch (e) {
      debugPrint("selectAudioOutput failed (falling back): $e");
    }
  }

  List<_InputChannelRouteOption> _buildInputChannelRouteOptions(
      int numInputChannels) {
    if (numInputChannels <= 0) return const <_InputChannelRouteOption>[];

    final options = <_InputChannelRouteOption>[
      for (int ch = 0; ch < numInputChannels; ch++)
        _InputChannelRouteOption(channelStart: ch, channelCount: 1),
      for (int ch = 0; ch + 1 < numInputChannels; ch += 2)
        _InputChannelRouteOption(channelStart: ch, channelCount: 2),
    ];
    return options;
  }

  _InputChannelRouteOption? _findSelectedInputChannelRouteOption(
      List<_InputChannelRouteOption> options) {
    for (final option in options) {
      if (option.channelStart == _selectedChannelStart &&
          option.channelCount == _selectedChannelCount) {
        return option;
      }
    }
    return null;
  }

  void _normalizeInputChannelSelection() {
    if (_numInputChannels <= 0) {
      _selectedChannelStart = 0;
      _selectedChannelCount = 1;
      return;
    }

    _selectedChannelStart =
        _selectedChannelStart.clamp(0, (_numInputChannels - 1).clamp(0, 999));
    _selectedChannelCount = _selectedChannelCount.clamp(
        1, (_numInputChannels - _selectedChannelStart).clamp(1, 999));

    final options = _buildInputChannelRouteOptions(_numInputChannels);
    final selected = _findSelectedInputChannelRouteOption(options);
    if (selected != null) return;

    final monoFallback = options.firstWhere(
      (option) =>
          option.channelCount == 1 &&
          option.channelStart == _selectedChannelStart,
      orElse: () => options.first,
    );
    _selectedChannelStart = monoFallback.channelStart;
    _selectedChannelCount = monoFallback.channelCount;
  }

  int _desiredRecordingInputOpenChannels() {
    if (_numInputChannels <= 0) {
      if (Platform.isAndroid || Platform.isIOS) {
        // Unknown route state: request a single input first to wake/arm the
        // input path, then refresh real channel metadata.
        return 1;
      }
      return 0;
    }
    final desiredInputs = _selectedChannelStart + _selectedChannelCount;
    return math.max(1, math.min(_numInputChannels, desiredInputs));
  }

  bool _recordingInputsPreparedFor({
    required String selectedDevice,
    required int desiredInputChannels,
  }) {
    return _lastPreparedRecordingDevice == selectedDevice &&
        _lastPreparedRecordingInputOpenChannels == desiredInputChannels;
  }

  bool _supportsNativeBluetoothMonitorPolicy() {
    return Platform.isAndroid || Platform.isIOS;
  }

  bool _sameAudioRouteInfo(AudioRouteInfo a, AudioRouteInfo b) {
    return a.outputRouteKind == b.outputRouteKind &&
        a.outputRouteName == b.outputRouteName &&
        a.inputDeviceName == b.inputDeviceName &&
        a.inputIsBluetoothHeadset == b.inputIsBluetoothHeadset;
  }

  String _normalizeBluetoothRouteKeyToken(String raw) {
    return raw
        .trim()
        .toLowerCase()
        .replaceAll(RegExp(r'[^a-z0-9]+'), ' ')
        .replaceAll(RegExp(r'\s+'), ' ')
        .trim();
  }

  String _bluetoothMicOptInKey([AudioRouteInfo? info]) {
    final routeInfo = info ?? _audioRouteInfo;
    final inputName = routeInfo.inputDeviceName.isNotEmpty
        ? routeInfo.inputDeviceName
        : (_selectedDevice ?? '');
    final normalized = _normalizeBluetoothRouteKeyToken(inputName);
    if (normalized.isEmpty) return 'bluetooth headset mic';
    return '$normalized::bluetooth headset mic';
  }

  bool _looksLikeBluetoothDeviceName(String name) {
    final normalized = _normalizeBluetoothRouteKeyToken(name);
    if (normalized.isEmpty) return false;
    return normalized.contains('airpods') ||
        normalized.contains('bluetooth') ||
        normalized.contains('buds') ||
        normalized.contains('beats') ||
        normalized.contains('headset');
  }

  Future<void> _loadBluetoothRecordingPrefs() async {
    final prefs = await SharedPreferences.getInstance();
    if (!mounted) return;
    _setStateAndRefreshProjectSettings(() {
      _advancedBluetoothMonitorOverride =
          prefs.getBool(_kBluetoothMonitorOverridePref) ?? false;
      _allowedBluetoothMicKeys
        ..clear()
        ..addAll(
            prefs.getStringList(_kAllowedBluetoothMicKeysPref) ?? const []);
    });
  }

  Future<void> _persistBluetoothMonitorOverride() async {
    final prefs = await SharedPreferences.getInstance();
    await prefs.setBool(
      _kBluetoothMonitorOverridePref,
      _advancedBluetoothMonitorOverride,
    );
  }

  Future<void> _persistBluetoothMicOptInKeys() async {
    final prefs = await SharedPreferences.getInstance();
    await prefs.setStringList(
      _kAllowedBluetoothMicKeysPref,
      _allowedBluetoothMicKeys.toList()..sort(),
    );
  }

  bool _isBluetoothMicOptedIn([AudioRouteInfo? info]) {
    return _allowedBluetoothMicKeys.contains(_bluetoothMicOptInKey(info));
  }

  String? _recommendedNonBluetoothInputDevice() {
    for (final device in _inputDevices) {
      if (!_looksLikeBluetoothDeviceName(device)) {
        return device;
      }
    }
    return null;
  }

  bool _shouldEnableLiveInputMonitoring(AudioRouteInfo info) {
    if (info.isBluetoothOutput && !_advancedBluetoothMonitorOverride) {
      return false;
    }
    return true;
  }

  Future<void> _applyCurrentLiveMonitoringPolicy({
    AudioRouteInfo? info,
    bool force = false,
  }) async {
    if (!_supportsNativeBluetoothMonitorPolicy()) return;
    final routeInfo = info ?? _audioRouteInfo;
    final shouldEnable = _shouldEnableLiveInputMonitoring(routeInfo);
    if (!force && _liveInputMonitoringEffective == shouldEnable) {
      return;
    }
    _liveInputMonitoringEffective = shouldEnable;
    await JuceAudioEngine.setLiveInputMonitoringEnabled(shouldEnable);
  }

  Future<void> _refreshAudioRouteInfo({
    bool refreshNativeRoute = false,
  }) async {
    if (!_supportsNativeBluetoothMonitorPolicy()) return;
    if (refreshNativeRoute) {
      await _requestAndroidRouteRefresh(reason: 'editorRouteInfo');
    }
    final info = await JuceAudioEngine.getAudioRouteInfo();
    if (!mounted) return;

    final routeLabel = info.outputRouteName.trim();
    final changed = !_sameAudioRouteInfo(_audioRouteInfo, info) ||
        _androidOutputRouteName != (routeLabel.isEmpty ? null : routeLabel);
    if (changed) {
      _setStateAndRefreshProjectSettings(() {
        _audioRouteInfo = info;
        if (Platform.isAndroid) {
          _androidOutputRouteName = routeLabel.isEmpty ? null : routeLabel;
        }
      });
    } else {
      _audioRouteInfo = info;
    }

    if (_isRecording && !_isMidiClipRecording) {
      await _applyCurrentLiveMonitoringPolicy(info: info);
    }
  }

  Future<void> _refreshAndroidOutputRouteLabel({
    bool refreshNativeRoute = false,
  }) async {
    await _refreshAudioRouteInfo(refreshNativeRoute: refreshNativeRoute);
  }

  Future<bool> _confirmBluetoothMicMode(AudioRouteInfo info) async {
    final fallbackDevice = _recommendedNonBluetoothInputDevice();
    final selectedDeviceName = (_selectedDevice ?? '').trim();
    final selectedInputLooksBluetooth = selectedDeviceName.isNotEmpty &&
        _looksLikeBluetoothDeviceName(selectedDeviceName);

    final shouldAutoFallbackToNonBluetoothInput = info.isBluetoothOutput &&
        (info.inputIsBluetoothHeadset ||
            selectedInputLooksBluetooth ||
            selectedDeviceName.isEmpty);

    if (Platform.isAndroid &&
        shouldAutoFallbackToNonBluetoothInput &&
        fallbackDevice != null) {
      final ok = await JuceAudioEngine.selectInputDevice(fallbackDevice);
      if (!ok) return false;
      final channels = await JuceAudioEngine.getNumInputChannels();
      if (!mounted) return false;
      _setStateAndRefreshProjectSettings(() {
        _selectedDevice = fallbackDevice;
        _numInputChannels = channels;
        _normalizeInputChannelSelection();
      });
      _lastPreparedRecordingDevice = null;
      _lastPreparedRecordingInputOpenChannels = null;
      await _refreshAudioRouteInfo();
      if (!mounted) return false;
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text(
            'Using built-in/default mic while Bluetooth output is active.',
          ),
        ),
      );
      return true;
    }

    if (Platform.isIOS && shouldAutoFallbackToNonBluetoothInput) {
      final ok = await JuceAudioEngine.preferNonBluetoothRecordingInput();
      if (!ok) return false;
      final channels = await JuceAudioEngine.getNumInputChannels();
      if (!mounted) return false;
      _setStateAndRefreshProjectSettings(() {
        _numInputChannels = channels;
        _normalizeInputChannelSelection();
      });
      _lastPreparedRecordingDevice = null;
      _lastPreparedRecordingInputOpenChannels = null;
      await _refreshAudioRouteInfo();
      if (!mounted) return false;
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text(
            'Using built-in/default mic while Bluetooth output is active.',
          ),
        ),
      );
      return true;
    }

    if (!info.inputIsBluetoothHeadset || _isBluetoothMicOptedIn(info)) {
      return true;
    }

    final decision = await showDialog<String>(
      context: context,
      builder: (dialogContext) {
        return AlertDialog(
          backgroundColor: const Color(0xFF181B24),
          title: Text(
            L10n.translate(dialogContext, 'Bluetooth headset mic'),
            style: const TextStyle(color: Colors.white),
          ),
          content: Text(
            fallbackDevice == null
                ? L10n.translate(
                    dialogContext,
                    'Bluetooth headset mic can reduce audio quality and increase latency. Continue with this mic?',
                  )
                : L10n.translate(
                    dialogContext,
                    'Bluetooth headset mic can reduce audio quality and increase latency. Use your built-in/default mic instead, or continue with this mic?',
                  ),
            style: const TextStyle(color: Colors.white70),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.of(dialogContext).pop('cancel'),
              child: Text(L10n.translate(dialogContext, 'Cancel')),
            ),
            if (fallbackDevice != null)
              TextButton(
                onPressed: () => Navigator.of(dialogContext).pop('fallback'),
                child: Text(L10n.translate(dialogContext, 'Use default mic')),
              ),
            FilledButton(
              onPressed: () => Navigator.of(dialogContext).pop('continue'),
              child: Text(L10n.translate(dialogContext, 'Continue')),
            ),
          ],
        );
      },
    );

    if (!mounted || decision == null || decision == 'cancel') {
      return false;
    }

    if (decision == 'fallback') {
      final fallbackDeviceName = fallbackDevice;
      if (fallbackDeviceName == null) return false;
      final ok = Platform.isIOS
          ? await JuceAudioEngine.preferNonBluetoothRecordingInput()
          : await JuceAudioEngine.selectInputDevice(fallbackDeviceName);
      if (!ok) return false;
      final channels = await JuceAudioEngine.getNumInputChannels();
      if (!mounted) return false;
      _setStateAndRefreshProjectSettings(() {
        if (!Platform.isIOS) {
          _selectedDevice = fallbackDeviceName;
        }
        _numInputChannels = channels;
        _normalizeInputChannelSelection();
      });
      _lastPreparedRecordingDevice = null;
      _lastPreparedRecordingInputOpenChannels = null;
      await _refreshAudioRouteInfo();
      return !_audioRouteInfo.inputIsBluetoothHeadset ||
          _isBluetoothMicOptedIn();
    }

    _allowedBluetoothMicKeys.add(_bluetoothMicOptInKey(info));
    await _persistBluetoothMicOptInKeys();
    return true;
  }

  void _startRecordingRoutePolicyPolling() {
    _recordingRoutePolicyTimer?.cancel();
    if (!_supportsNativeBluetoothMonitorPolicy()) return;
    _recordingRoutePolicyTimer =
        Timer.periodic(const Duration(seconds: 1), (_) {
      if (!_isRecording || _isMidiClipRecording) {
        _recordingRoutePolicyTimer?.cancel();
        _recordingRoutePolicyTimer = null;
        return;
      }
      unawaited(_refreshAudioRouteInfo());
    });
  }

  void _stopRecordingRoutePolicyPolling() {
    _recordingRoutePolicyTimer?.cancel();
    _recordingRoutePolicyTimer = null;
  }

  Future<bool> _prepareRecordingInputs({
    required int desiredInputChannels,
    required String selectedDevice,
    required String reason,
    bool rescheduleOnConfigChange = false,
  }) {
    _recordingInputPrewarmInFlight = true;

    late final Future<bool> future;
    future = (() async {
      var preparedForRequestedConfig = false;
      try {
        final prepared = await JuceAudioEngine.prepareRecordingInputs(
          desiredInputChannels,
          reason: reason,
        );
        if (!mounted || !prepared) return false;
        _lastPreparedRecordingDevice = selectedDevice;
        _lastPreparedRecordingInputOpenChannels = desiredInputChannels;
        preparedForRequestedConfig = true;
        return true;
      } finally {
        _recordingInputPrewarmInFlight = false;
        if (identical(_recordingInputPrewarmFuture, future)) {
          _recordingInputPrewarmFuture = null;
        }
        // Only chain another prewarm when the current prewarm succeeded.
        // This prevents infinite retry loops on persistent native-route errors.
        if (rescheduleOnConfigChange && mounted && preparedForRequestedConfig) {
          final currentDevice = (_selectedDevice ?? '').trim();
          final currentDesiredInputChannels =
              _desiredRecordingInputOpenChannels();
          if (currentDesiredInputChannels <= 0) {
            _lastPreparedRecordingDevice = null;
            _lastPreparedRecordingInputOpenChannels = null;
          } else if (!_recordingInputsPreparedFor(
            selectedDevice: currentDevice,
            desiredInputChannels: currentDesiredInputChannels,
          )) {
            _scheduleRecordingInputPrewarm(reason: 'configChanged');
          }
        }
      }
    })();

    _recordingInputPrewarmFuture = future;
    return future;
  }

  Future<void> _ensureMobileRecordingRouteReady() async {
    if (!mounted || _isRecording) return;
    if (!(Platform.isAndroid || Platform.isIOS)) return;

    final desiredInputChannels = _desiredRecordingInputOpenChannels();
    if (desiredInputChannels <= 0) return;

    final selectedDevice = (_selectedDevice ?? '').trim();
    if (_recordingInputsPreparedFor(
      selectedDevice: selectedDevice,
      desiredInputChannels: desiredInputChannels,
    )) {
      return;
    }

    final inFlight = _recordingInputPrewarmFuture;
    if (inFlight != null) {
      final prepared = await inFlight;
      if (prepared &&
          _recordingInputsPreparedFor(
            selectedDevice: selectedDevice,
            desiredInputChannels: desiredInputChannels,
          )) {
        return;
      }
    }

    await _prepareRecordingInputs(
      desiredInputChannels: desiredInputChannels,
      selectedDevice: selectedDevice,
      reason: 'recordStart',
    );
  }

  void _scheduleRecordingInputPrewarm({required String reason}) {
    if (!mounted || _isRecording) return;
    final desiredInputChannels = _desiredRecordingInputOpenChannels();
    final selectedDevice = (_selectedDevice ?? '').trim();

    if (Platform.isAndroid) {
      _lastPreparedRecordingDevice = null;
      _lastPreparedRecordingInputOpenChannels = null;
      _recordingInputPrewarmFuture = null;
      return;
    }

    // Avoid audible route churn while playback is already active on iOS.
    if (Platform.isIOS && _isPlaying) {
      return;
    }

    if (desiredInputChannels <= 0) {
      _lastPreparedRecordingDevice = null;
      _lastPreparedRecordingInputOpenChannels = null;
      return;
    }
    if (selectedDevice.isEmpty && _inputDevices.isEmpty) {
      return;
    }
    if (_recordingInputPrewarmInFlight) {
      return;
    }
    if (_recordingInputsPreparedFor(
      selectedDevice: selectedDevice,
      desiredInputChannels: desiredInputChannels,
    )) {
      return;
    }

    unawaited(_prepareRecordingInputs(
      desiredInputChannels: desiredInputChannels,
      selectedDevice: selectedDevice,
      reason: reason,
      rescheduleOnConfigChange: true,
    ));
  }

  Future<void> _loadInputDevicesFromJuce({
    bool scheduleRecordingPrewarm = false,
  }) async {
    if (_loadingDevices) return;
    _setStateAndRefreshProjectSettings(() => _loadingDevices = true);

    try {
      final micStatus = await _getMicrophonePermissionStatus();
      final micBlocked = !(micStatus.isGranted || micStatus.isLimited);

      final devices = await JuceAudioEngine.getInputDevices();
      final current = await JuceAudioEngine.getCurrentDeviceName();
      final channels = await JuceAudioEngine.getNumInputChannels();
      _setStateAndRefreshProjectSettings(() {
        final currentDeviceName = current.trim();
        _microphonePermissionStatus = micStatus;
        _microphoneAccessBlocked = micBlocked;
        _inputDevices = devices;
        _selectedDevice = devices.contains(current)
            ? current
            : (devices.isNotEmpty ? devices.first : null);
        _macOutputDeviceName =
            currentDeviceName.isEmpty ? null : currentDeviceName;
        _numInputChannels = channels;
        _normalizeInputChannelSelection();
        _loadingDevices = false;
      });
      unawaited(_refreshAudioRouteInfo());
      if (scheduleRecordingPrewarm) {
        _scheduleRecordingInputPrewarm(reason: 'loadInputDevices');
      }
    } catch (_) {
      final micStatus = await _getMicrophonePermissionStatus();
      _setStateAndRefreshProjectSettings(() {
        _microphonePermissionStatus = micStatus;
        _microphoneAccessBlocked =
            !(micStatus.isGranted || micStatus.isLimited);
        _inputDevices = const <String>[];
        _selectedDevice = null;
        _numInputChannels = 0;
        _normalizeInputChannelSelection();
        _loadingDevices = false;
        _androidOutputRouteName = null;
        _macOutputDeviceName = null;
      });
      _lastPreparedRecordingDevice = null;
      _lastPreparedRecordingInputOpenChannels = null;
      _audioRouteInfo = AudioRouteInfo.unknown;
      if (Platform.isAndroid) {
        unawaited(JuceAudioEngine.prepareRecordingInputs(
          0,
          reason: 'loadInputDevices:error',
        ));
      }
    }
  }

  Widget _buildMicrophonePermissionNotice() {
    final actionLabel = _microphonePermissionStatus.isPermanentlyDenied ||
            _microphonePermissionStatus.isRestricted
        ? L10n.translate(context, 'Open settings')
        : L10n.translate(context, 'Allow access');
    final helperText = _microphonePermissionStatus.isPermanentlyDenied ||
            _microphonePermissionStatus.isRestricted
        ? L10n.translate(
            context,
            'Built-in microphone recording needs access in Settings. External audio interfaces can still be used below when available.',
          )
        : L10n.translate(
            context,
            'Built-in microphone recording needs access. External audio interfaces can still be used below when available.',
          );

    return Container(
      width: double.infinity,
      padding: const EdgeInsets.all(12),
      decoration: BoxDecoration(
        color: Colors.white.withValues(alpha: 0.08),
        border: Border.all(color: Colors.white.withValues(alpha: 0.14)),
        borderRadius: BorderRadius.circular(18),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(
            L10n.translate(context, 'Microphone access is turned off'),
            style: const TextStyle(
              color: Colors.white,
              fontWeight: FontWeight.w600,
            ),
          ),
          const SizedBox(height: 6),
          Text(
            helperText,
            style: const TextStyle(color: Colors.white70),
          ),
          const SizedBox(height: 10),
          Align(
            alignment: Alignment.centerLeft,
            child: TextButton(
              onPressed: _microphonePermissionStatus.isPermanentlyDenied ||
                      _microphonePermissionStatus.isRestricted
                  ? _openAppPermissionsSettings
                  : _requestMicrophoneAccessFromSettingsPanel,
              child: Text(actionLabel),
            ),
          ),
        ],
      ),
    );
  }

  Future<void> _loadAudioDevices() async {
    final devices = await navigator.mediaDevices.enumerateDevices();

    final inputs = devices.where((d) => d.kind == 'audioinput').toList();
    final outputs = devices.where((d) => d.kind == 'audiooutput').toList();

    MediaDeviceInfo? newSelectedInput;
    MediaDeviceInfo? newSelectedOutput;

    // --- Preserve input selection if possible ---
    if (_selectedInput != null) {
      try {
        newSelectedInput =
            inputs.firstWhere((d) => d.deviceId == _selectedInput!.deviceId);
      } catch (_) {
        newSelectedInput = inputs.isNotEmpty ? inputs.first : null;
      }
    } else {
      newSelectedInput = inputs.isNotEmpty ? inputs.first : null;
    }

    // --- Preserve output selection if possible ---
    if (_selectedOutput != null) {
      try {
        newSelectedOutput =
            outputs.firstWhere((d) => d.deviceId == _selectedOutput!.deviceId);
      } catch (_) {
        newSelectedOutput = outputs.isNotEmpty ? outputs.first : null;
      }
    } else {
      newSelectedOutput = outputs.isNotEmpty ? outputs.first : null;
    }

    setState(() {
      _inputs = inputs;
      _outputs = outputs;
      _selectedInput = newSelectedInput;
      _selectedOutput = newSelectedOutput;
      _loadingDevices = false;
    });

    navigator.mediaDevices.ondevicechange = (event) {
      _loadAudioDevices(); // refresh device list
      // ScaffoldMessenger.of(context).showSnackBar(
      //   SnackBar(content: Text("Audio devices updated")),
      // );
    };
  }

  Widget _buildInputSelector() {
    if (_loadingDevices) {
      return const Padding(
        padding: EdgeInsets.all(8),
        child: Center(child: CircularProgressIndicator(color: Colors.white)),
      );
    }

    if (_inputDevices.isEmpty) {
      if (!_microphoneAccessBlocked) {
        return Text(
          L10n.translate(context, 'No input devices available'),
          style: const TextStyle(color: Colors.white54),
        );
      }
      return Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          _buildMicrophonePermissionNotice(),
          const SizedBox(height: 12),
          Text(
            L10n.translate(context, 'No input devices available'),
            style: const TextStyle(color: Colors.white54),
          ),
        ],
      );
    }

    final selector = DropdownButtonFormField<String>(
      value: _selectedDevice,
      isExpanded: true,
      dropdownColor: kMixroomGlassDropdownMenuColor,
      style: const TextStyle(color: Colors.white),
      selectedItemBuilder: (context) {
        return _inputDevices
            .map(
              (d) => Align(
                alignment: Alignment.centerLeft,
                child: Text(
                  d,
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                ),
              ),
            )
            .toList(growable: false);
      },
      decoration: _projectSettingsFieldDecoration(
        labelText: L10n.translate(context, 'Input Device'),
        suffixIcon: IconButton(
          tooltip: L10n.translate(context, 'Refresh audio devices'),
          icon: const Icon(Icons.refresh, color: Colors.white70),
          onPressed: () async {
            _loadInputDevicesFromJuce(scheduleRecordingPrewarm: true);
            print("audio devices reloaded from JUCE");
          },
        ),
      ),
      items: _inputDevices
          .map(
            (d) => DropdownMenuItem(
              value: d,
              child: Text(
                d,
                maxLines: 1,
                overflow: TextOverflow.ellipsis,
              ),
            ),
          )
          .toList(),
      onChanged: (name) async {
        if (name == null) return;

        final ok = await JuceAudioEngine.selectInputDevice(name);
        if (!ok) return;

        final channels = await JuceAudioEngine.getNumInputChannels();

        _setStateAndRefreshProjectSettings(() {
          _selectedDevice = name;
          _numInputChannels = channels;
          _normalizeInputChannelSelection();
        });
        _scheduleRecordingInputPrewarm(reason: 'selectInputDevice');
        unawaited(_refreshAndroidOutputRouteLabel());
      },
    );

    if (!_microphoneAccessBlocked) {
      return selector;
    }

    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        _buildMicrophonePermissionNotice(),
        const SizedBox(height: 12),
        selector,
      ],
    );
  }

  Widget _buildInputChannelRouteSelector() {
    final options = _buildInputChannelRouteOptions(_numInputChannels);
    if (options.isEmpty) return const SizedBox.shrink();

    final selected =
        _findSelectedInputChannelRouteOption(options) ?? options.first;

    return DropdownButtonFormField<_InputChannelRouteOption>(
      key: ValueKey(_numInputChannels),
      value: selected,
      isExpanded: true,
      dropdownColor: kMixroomGlassDropdownMenuColor,
      style: const TextStyle(color: Colors.white),
      decoration: _projectSettingsFieldDecoration(
        labelText: L10n.translate(context, 'Input Channel'),
      ),
      items: options
          .map(
            (option) => DropdownMenuItem<_InputChannelRouteOption>(
              value: option,
              child: Text(
                option.label,
                style: const TextStyle(color: Colors.white),
              ),
            ),
          )
          .toList(),
      onChanged: _isRecording
          ? null
          : (option) {
              if (option == null) return;
              _setStateAndRefreshProjectSettings(() {
                _selectedChannelStart = option.channelStart;
                _selectedChannelCount = option.channelCount;
              });
              _scheduleRecordingInputPrewarm(reason: 'selectInputChannels');
            },
    );
  }

  Widget _buildOutputSelector() {
    if (_loadingDevices) {
      return const Padding(
        padding: EdgeInsets.all(8),
        child: Center(child: CircularProgressIndicator(color: Colors.white)),
      );
    }

    if (Platform.isAndroid) {
      final routeLabel = _androidOutputRouteName?.trim();
      final effectiveLabel = (routeLabel == null || routeLabel.isEmpty)
          ? L10n.translate(
              context,
              'System default (speaker / Bluetooth / audio interface)',
            )
          : routeLabel;
      return InputDecorator(
        decoration: _projectSettingsFieldDecoration(
          labelText: L10n.translate(context, 'Output Route'),
          suffixIcon: IconButton(
            tooltip: L10n.translate(context, 'Refresh output route'),
            icon: const Icon(Icons.refresh, color: Colors.white70),
            onPressed: () {
              unawaited(_refreshAndroidOutputRouteLabel());
            },
          ),
        ),
        child: Text(
          effectiveLabel,
          style: const TextStyle(color: Colors.white),
        ),
      );
    }

    if (Platform.isIOS) {
      final routeLabel = _audioRouteInfo.outputRouteName.trim();
      final effectiveLabel = routeLabel.isEmpty
          ? L10n.translate(
              context,
              'System default (speaker / Bluetooth / audio interface)',
            )
          : routeLabel;
      return InputDecorator(
        decoration: _projectSettingsFieldDecoration(
          labelText: L10n.translate(context, 'Output Route'),
          suffixIcon: IconButton(
            tooltip: L10n.translate(context, 'Refresh output route'),
            icon: const Icon(Icons.refresh, color: Colors.white70),
            onPressed: () {
              unawaited(_refreshAudioRouteInfo());
            },
          ),
        ),
        child: Text(
          effectiveLabel,
          style: const TextStyle(color: Colors.white),
        ),
      );
    }

    if (Platform.isMacOS) {
      final routeLabel = _macOutputDeviceName?.trim();
      final effectiveLabel = (routeLabel == null || routeLabel.isEmpty)
          ? L10n.translate(
              context,
              'System default (managed by macOS audio settings)',
            )
          : routeLabel;
      return InputDecorator(
        decoration: _projectSettingsFieldDecoration(
          labelText: L10n.translate(context, 'Output Device'),
          suffixIcon: IconButton(
            tooltip: L10n.translate(context, 'Refresh output device'),
            icon: const Icon(Icons.refresh, color: Colors.white70),
            onPressed: () {
              unawaited(_loadInputDevicesFromJuce());
            },
          ),
        ),
        child: Text(
          effectiveLabel,
          style: const TextStyle(color: Colors.white),
        ),
      );
    }

    // Non-Android fallback path uses WebRTC device enumeration.
    if (_outputs.isEmpty) {
      return Text(L10n.translate(context, 'No selectable output devices'),
          style: const TextStyle(color: Colors.white54));
    }

    return DropdownButtonFormField<MediaDeviceInfo>(
      dropdownColor: kMixroomGlassDropdownMenuColor,
      initialValue: _selectedOutput,
      isExpanded: true,
      style: const TextStyle(color: Colors.white),
      decoration: _projectSettingsFieldDecoration(
        labelText: L10n.translate(context, 'Output Device'),
      ),
      items: _outputs.map((d) {
        return DropdownMenuItem(
          value: d,
          child: Text(d.label.isNotEmpty ? d.label : d.deviceId,
              style: const TextStyle(color: Colors.white)),
        );
      }).toList(),
      onChanged: (d) {
        if (d == null) return;
        _setStateAndRefreshProjectSettings(() => _selectedOutput = d);
        _selectOutputDevice(d);
      },
    );
  }

  Future<void> _setAdvancedBluetoothMonitorOverride(bool enabled) async {
    _setStateAndRefreshProjectSettings(() {
      _advancedBluetoothMonitorOverride = enabled;
    });
    await _persistBluetoothMonitorOverride();
    if (_isRecording && !_isMidiClipRecording) {
      await _applyCurrentLiveMonitoringPolicy(force: true);
    }
  }

  Future<void> _resetBluetoothMicOptIns() async {
    _setStateAndRefreshProjectSettings(() {
      _allowedBluetoothMicKeys.clear();
    });
    await _persistBluetoothMicOptInKeys();
  }

  Widget _buildBluetoothRecordingPolicyCard() {
    final showBluetoothOutput = _audioRouteInfo.isBluetoothOutput;
    final showBluetoothMic = _audioRouteInfo.inputIsBluetoothHeadset;
    final hasOptIns = _allowedBluetoothMicKeys.isNotEmpty;

    if (!showBluetoothOutput && !showBluetoothMic && !hasOptIns) {
      return const SizedBox.shrink();
    }

    final routeName = _audioRouteInfo.outputRouteName.trim();
    return Padding(
      padding: const EdgeInsets.symmetric(horizontal: 2),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(
            L10n.translate(context, 'Bluetooth recording policy'),
            style: TextStyle(
              color: Colors.white,
              fontSize: 14,
              fontWeight: FontWeight.w700,
            ),
          ),
          if (showBluetoothOutput) ...[
            const SizedBox(height: 8),
            Text(
              routeName.isEmpty
                  ? L10n.translate(
                      context,
                      'Bluetooth playback and recording are supported. Real-time monitoring is off by default.',
                    )
                  : '$routeName ${L10n.translate(context, 'is using Bluetooth output. Real-time monitoring is off by default.')}',
              style: const TextStyle(color: Colors.white70, height: 1.35),
            ),
            const SizedBox(height: 10),
            SwitchListTile.adaptive(
              contentPadding: EdgeInsets.zero,
              value: _advancedBluetoothMonitorOverride,
              activeColor: const Color(0xFF4C8DFF),
              title: Text(
                L10n.translate(context, 'Advanced: monitor anyway'),
                style: const TextStyle(color: Colors.white),
              ),
              subtitle: Text(
                L10n.translate(
                  context,
                  'May sound choppy or unstable on Bluetooth earphones.',
                ),
                style: const TextStyle(color: Colors.white60),
              ),
              onChanged: (value) {
                unawaited(_setAdvancedBluetoothMonitorOverride(value));
              },
            ),
          ],
          if (showBluetoothMic) ...[
            const SizedBox(height: 8),
            Text(
              _isBluetoothMicOptedIn()
                  ? L10n.translate(
                      context,
                      'Bluetooth headset mic can reduce audio quality and increase latency. This device is currently allowed for recording.',
                    )
                  : L10n.translate(
                      context,
                      'Bluetooth headset mic can reduce audio quality and increase latency. You will be asked to confirm before recording.',
                    ),
              style: const TextStyle(color: Colors.white70, height: 1.35),
            ),
          ],
          if (hasOptIns) ...[
            const SizedBox(height: 6),
            Align(
              alignment: Alignment.centerLeft,
              child: TextButton(
                onPressed: () {
                  unawaited(_resetBluetoothMicOptIns());
                },
                child: Text(
                    L10n.translate(context, 'Reset Bluetooth mic approvals')),
              ),
            ),
          ],
        ],
      ),
    );
  }

