  String _normalizeEffectText(String raw) {
    return raw
        .toLowerCase()
        .replaceAll(RegExp(r'[^a-z0-9]+'), ' ')
        .replaceAll(RegExp(r'\s+'), ' ')
        .trim();
  }

  String? pickMixroomEffect(String effectContains) {
    final needle = _normalizeEffectText(effectContains);
    if (needle.isEmpty) return null;

    // Alias-first matching for natural language phrases
    const aliasToEffect = <String, String>{
      'gain': 'Gain',
      'reverb': 'Reverb',
      'verb': 'Reverb',
      'plate': 'Reverb',
      'room': 'Reverb',
      'hall': 'Reverb',
      'delay': 'Delay',
      'echo': 'Delay',
      'slapback': 'Delay',
      'compressor': 'Compressor',
      'comp': 'Compressor',
      'limiter': 'Limiter',
      'clipper': 'Clipper',
      'de esser': 'De-Esser',
      'deesser': 'De-Esser',
      'saturator': 'Distortion',
      'saturation': 'Distortion',
      'distortion': 'Distortion',
      'drive': 'Distortion',
      'degrade': 'Degrade',
      'pitch': 'Pitch Shift',
      'chorus': 'Chorus',
      'vibrato': 'Vibrato',
      'parametric eq': 'EQ Parametric',
      'eq parametric': 'EQ Parametric',
      '3 band eq': 'EQ 3-Band',
      'eq 3 band': 'EQ 3-Band',
      'equalizer': 'EQ Parametric',
      'eq': 'EQ Parametric',
    };
    for (final entry in aliasToEffect.entries) {
      if (needle.contains(entry.key)) {
        return entry.value;
      }
    }

    for (final name in kMixroomBuiltInEffects) {
      final candidate = _normalizeEffectText(name);
      if (candidate == needle ||
          candidate.contains(needle) ||
          needle.contains(candidate)) {
        return name;
      }
    }

    // Last-resort token overlap (handles strings like "add reverb on track 1").
    final tokens = needle
        .split(' ')
        .where((t) =>
            t.isNotEmpty &&
            t != 'plugin' &&
            t != 'effect' &&
            t != 'track' &&
            t != 'row' &&
            t != 'add' &&
            t != 'remove')
        .toList(growable: false);
    if (tokens.isEmpty) return null;
    String? best;
    int bestScore = 0;
    for (final name in kMixroomBuiltInEffects) {
      final candidate = _normalizeEffectText(name);
      int score = 0;
      for (final token in tokens) {
        if (candidate.contains(token)) score++;
      }
      if (score > bestScore) {
        bestScore = score;
        best = name;
      }
    }
    if (bestScore > 0) {
      return best;
    }
    return null;
  }

  Map<String, dynamic> _toActionMap(dynamic raw) {
    return AssistantActionUtils.toActionMap(raw);
  }

  double? _toActionDouble(dynamic raw) {
    return AssistantActionUtils.toActionDouble(raw);
  }

  int? _toActionInt(dynamic raw) {
    return AssistantActionUtils.toActionInt(raw);
  }

  bool _toActionBool(dynamic raw, {bool fallback = false}) {
    return AssistantActionUtils.toActionBool(raw, fallback: fallback);
  }

  Map<String, dynamic> _actionTarget(Map<String, dynamic> data) {
    return _toActionMap(data['target']);
  }

  List<String> _actionStringList(dynamic raw) {
    if (raw is! List) return const <String>[];
    return raw
        .map((e) => e.toString().trim())
        .where((s) => s.isNotEmpty)
        .toList(growable: false);
  }

  int? _parseRowIndexValue(dynamic raw, {bool preferOneBased = false}) {
    final parsed = _toActionInt(raw);
    if (parsed == null) return null;
    final direct = parsed;
    final oneBased = parsed - 1;

    bool inRange(int idx) {
      if (_rowCount <= 0) return idx >= 0;
      return idx >= 0 && idx < _rowCount;
    }

    if (preferOneBased) {
      if (parsed > 0 && inRange(oneBased)) return oneBased;
      if (inRange(direct)) return direct;
      return null;
    }
    if (inRange(direct)) return direct;
    if (parsed > 0 && inRange(oneBased)) return oneBased;
    return null;
  }

  int? _resolveActionRowIndexFromData(
    Map<String, dynamic> data, {
    int? fallbackClipIndex,
    bool includeSelectionFallback = true,
  }) {
    final target = _actionTarget(data);

    int? pick(List<String> keys, {bool preferOneBased = false}) {
      for (final key in keys) {
        final parsed =
            _parseRowIndexValue(data[key], preferOneBased: preferOneBased) ??
                _parseRowIndexValue(
                  target[key],
                  preferOneBased: preferOneBased,
                );
        if (parsed != null) return parsed;
      }
      return null;
    }

    int? row = pick(
      const ['row_index', 'track_index', 'target_row_index'],
      preferOneBased: false,
    );
    row ??= pick(
      const ['row', 'target_row'],
      preferOneBased: false,
    );
    row ??= pick(
      const ['row_number', 'track_number', 'track'],
      preferOneBased: true,
    );
    if (row != null) return row;

    if (fallbackClipIndex != null &&
        fallbackClipIndex >= 0 &&
        fallbackClipIndex < _audioTracks.length) {
      return _audioTracks[fallbackClipIndex].rowIndex;
    }
    if (includeSelectionFallback && _rowCount > 0) {
      return _selectedRow.clamp(0, _rowCount - 1);
    }
    return null;
  }

  int? _resolveClipIndexFromActionTarget(
    Map<String, dynamic> data, {
    bool requireAudio = false,
    bool requireMidi = false,
  }) {
    bool passesKind(AudioTrack clip) {
      if (requireAudio && clip.isMidi) return false;
      if (requireMidi && !clip.isMidi) return false;
      return true;
    }

    bool isValidIndex(int idx) =>
        idx >= 0 && idx < _audioTracks.length && passesKind(_audioTracks[idx]);

    final target = _actionTarget(data);
    final direct = _toActionInt(data['clip_index']) ??
        _toActionInt(target['clip_index']) ??
        _toActionInt(data['clip']) ??
        _toActionInt(target['clip']);
    if (direct != null && isValidIndex(direct)) return direct;

    final preferSelected = _toActionBool(
      target['prefer_selected'] ?? data['prefer_selected'],
      fallback: true,
    );
    if (preferSelected && isValidIndex(_timelinePrimarySelectedClipIndex)) {
      return _timelinePrimarySelectedClipIndex;
    }

    final selected = _timelineSelectedClipIndices
        .where((i) => isValidIndex(i))
        .toList(growable: false);
    if (preferSelected && selected.length == 1) {
      return selected.first;
    }

    final rowIndex =
        _resolveActionRowIndexFromData(data, includeSelectionFallback: false);
    final fileContains =
        (target['file_name_contains'] ?? data['file_name_contains'])
            ?.toString()
            .trim()
            .toLowerCase();
    final labelContains = (target['label_contains'] ?? data['label_contains'])
        ?.toString()
        .trim()
        .toLowerCase();

    final candidates = <int>[];
    for (int i = 0; i < _audioTracks.length; i++) {
      final clip = _audioTracks[i];
      if (!passesKind(clip)) continue;
      if (rowIndex != null && clip.rowIndex != rowIndex) continue;
      if (fileContains != null &&
          fileContains.isNotEmpty &&
          !_displayNameForFilePath(clip.file.path)
              .toLowerCase()
              .contains(fileContains)) {
        continue;
      }
      if (labelContains != null &&
          labelContains.isNotEmpty &&
          !clip.label.toLowerCase().contains(labelContains)) {
        continue;
      }
      candidates.add(i);
    }

    if (candidates.length == 1) return candidates.first;
    if (candidates.length > 1) {
      final selectedIntersect =
          selected.where((i) => candidates.contains(i)).toList();
      if (selectedIntersect.length == 1) return selectedIntersect.first;
      return null;
    }

    if (isValidIndex(_timelinePrimarySelectedClipIndex)) {
      return _timelinePrimarySelectedClipIndex;
    }

    return null;
  }

  List<int> _resolveClipIndicesFromActionTarget(
    Map<String, dynamic> data, {
    bool requireAudio = false,
    bool requireMidi = false,
  }) {
    bool passesKind(AudioTrack clip) {
      if (requireAudio && clip.isMidi) return false;
      if (requireMidi && !clip.isMidi) return false;
      return true;
    }

    bool isValidIndex(int idx) =>
        idx >= 0 && idx < _audioTracks.length && passesKind(_audioTracks[idx]);

    final target = _actionTarget(data);
    final out = LinkedHashSet<int>();
    final rowIndex =
        _resolveActionRowIndexFromData(data, includeSelectionFallback: false);

    void add(int? idx) {
      if (idx != null && isValidIndex(idx)) {
        out.add(idx);
      }
    }

    final directListRaw =
        (data['clip_indices'] as List?) ?? (target['clip_indices'] as List?);
    if (directListRaw != null) {
      for (final raw in directListRaw) {
        add(_toActionInt(raw));
      }
    }

    final scope = (target['scope'] ?? data['scope'] ?? '')
        .toString()
        .trim()
        .toLowerCase();
    if (scope == 'selected' || scope == 'selection') {
      for (final idx in _timelineSelectedClipIndices) {
        add(idx);
      }
      add(_timelinePrimarySelectedClipIndex);
      if (out.isEmpty && _rowCount > 0) {
        final selectedRow = _selectedRow.clamp(0, _rowCount - 1).toInt();
        for (int i = 0; i < _audioTracks.length; i++) {
          final clip = _audioTracks[i];
          if (clip.rowIndex != selectedRow) continue;
          if (!passesKind(clip)) continue;
          out.add(i);
        }
      }
    } else if (scope == 'all' ||
        scope == 'all_audio' ||
        scope == 'all_selected_audio') {
      if (rowIndex != null) {
        for (int i = 0; i < _audioTracks.length; i++) {
          final clip = _audioTracks[i];
          if (clip.rowIndex != rowIndex) continue;
          if (!passesKind(clip)) continue;
          out.add(i);
        }
      } else {
        for (int i = 0; i < _audioTracks.length; i++) {
          if (isValidIndex(i)) out.add(i);
        }
      }
    }

    if (rowIndex != null) {
      for (int i = 0; i < _audioTracks.length; i++) {
        final clip = _audioTracks[i];
        if (clip.rowIndex != rowIndex) continue;
        if (!passesKind(clip)) continue;
        out.add(i);
      }
    }

    final single = _resolveClipIndexFromActionTarget(
      data,
      requireAudio: requireAudio,
      requireMidi: requireMidi,
    );
    add(single);

    if (out.isEmpty) {
      for (final idx in _timelineSelectedClipIndices) {
        add(idx);
      }
      add(_timelinePrimarySelectedClipIndex);
    }

    final sorted = out.toList()..sort();
    return sorted;
  }

  int? _pickPreferredClipIndex(List<int> candidates) {
    if (candidates.isEmpty) return null;
    final set = candidates.toSet();
    if (set.contains(_timelinePrimarySelectedClipIndex)) {
      return _timelinePrimarySelectedClipIndex;
    }
    for (final idx in _timelineSelectedClipIndices) {
      if (set.contains(idx)) return idx;
    }
    final sorted = candidates.toList(growable: false)
      ..sort((a, b) {
        final ao =
            (a >= 0 && a < _audioTracks.length) ? _audioTracks[a].offset : 0.0;
        final bo =
            (b >= 0 && b < _audioTracks.length) ? _audioTracks[b].offset : 0.0;
        final byOffset = ao.compareTo(bo);
        if (byOffset != 0) return byOffset;
        return a.compareTo(b);
      });
    return sorted.first;
  }

  int? _resolveSingleClipIndexWithFallback(
    Map<String, dynamic> data, {
    bool requireAudio = false,
    bool requireMidi = false,
  }) {
    final direct = _resolveClipIndexFromActionTarget(
      data,
      requireAudio: requireAudio,
      requireMidi: requireMidi,
    );
    if (direct != null) return direct;
    final candidates = _resolveClipIndicesFromActionTarget(
      data,
      requireAudio: requireAudio,
      requireMidi: requireMidi,
    );
    return _pickPreferredClipIndex(candidates);
  }

  int? _resolveRowIndexFromActionTarget(
    Map<String, dynamic> data, {
    int? fallbackClipIndex,
  }) {
    final row = _resolveActionRowIndexFromData(data,
        fallbackClipIndex: fallbackClipIndex);
    if (row == null || _rowCount <= 0) return null;
    return row.clamp(0, _rowCount - 1);
  }

  int _resolveInsertionRowIndexFromActionTarget(
    Map<String, dynamic> data, {
    int? fallbackClipIndex,
  }) {
    final row = _resolveActionRowIndexFromData(
      data,
      fallbackClipIndex: fallbackClipIndex,
    );
    if (row != null && row >= 0) {
      return row;
    }
    if (_rowCount > 0) {
      return _selectedRow.clamp(0, _rowCount - 1).toInt();
    }
    return 0;
  }

  bool _isKickLikeText(String raw) {
    final text = raw.trim().toLowerCase();
    if (text.isEmpty) return false;
    return text.contains('kick') ||
        text.contains('808') ||
        text.contains('bd') ||
        text.contains('bassdrum') ||
        text.contains('bass drum');
  }

  int? _resolveKickSourceClipIndexFromAction(
    Map<String, dynamic> data, {
    int? targetRow,
  }) {
    final target = _actionTarget(data);

    int? parseSourceIndex() {
      final idx = _toActionInt(
        data['source_clip_index'] ??
            target['source_clip_index'] ??
            data['kick_clip_index'] ??
            target['kick_clip_index'] ??
            data['trigger_clip_index'] ??
            target['trigger_clip_index'],
      );
      if (idx == null || idx < 0 || idx >= _audioTracks.length) return null;
      if (_audioTracks[idx].isMidi) return null;
      return idx;
    }

    int? fromIndex = parseSourceIndex();
    if (fromIndex != null) return fromIndex;

    int? sourceRow = _toActionInt(
      data['source_row_index'] ??
          target['source_row_index'] ??
          data['kick_row_index'] ??
          target['kick_row_index'],
    );
    if (sourceRow == null) {
      final sourceRole = (data['source_role'] ??
              target['source_role'] ??
              data['kick_role'] ??
              target['kick_role'] ??
              '')
          .toString()
          .trim()
          .toLowerCase();
      if (sourceRole == 'drums' || sourceRole == 'kick') {
        sourceRow = _selectedRow;
      }
    }

    List<int> candidatesForRow(int row) {
      if (row < 0 || row >= _rowCount) return const <int>[];
      final out = <int>[];
      for (int i = 0; i < _audioTracks.length; i++) {
        final clip = _audioTracks[i];
        if (clip.isMidi) continue;
        if (clip.rowIndex != row) continue;
        out.add(i);
      }
      return out;
    }

    if (sourceRow != null) {
      final pick = _pickPreferredClipIndex(candidatesForRow(sourceRow));
      if (pick != null) return pick;
    }

    final kickNameCandidates = <int>[];
    for (int i = 0; i < _audioTracks.length; i++) {
      final clip = _audioTracks[i];
      if (clip.isMidi) continue;
      final file = _displayNameForFilePath(clip.file.path);
      if (_isKickLikeText(clip.label) || _isKickLikeText(file)) {
        kickNameCandidates.add(i);
      }
    }
    final namedKickPick = _pickPreferredClipIndex(kickNameCandidates);
    if (namedKickPick != null) return namedKickPick;

    final selectedAudioCandidates = _timelineSelectedClipIndices
        .where(
            (i) => i >= 0 && i < _audioTracks.length && !_audioTracks[i].isMidi)
        .toList(growable: false);
    final selectedPick = _pickPreferredClipIndex(selectedAudioCandidates);
    if (selectedPick != null) return selectedPick;

    if (targetRow != null) {
      final rowPick = _pickPreferredClipIndex(candidatesForRow(targetRow));
      if (rowPick != null) return rowPick;
    }

    final anyAudio = <int>[];
    for (int i = 0; i < _audioTracks.length; i++) {
      if (!_audioTracks[i].isMidi) anyAudio.add(i);
    }
    return _pickPreferredClipIndex(anyAudio);
  }

  static const Set<String> _supportedTutorialHaloTargets = <String>{
    'tutorial:chatbar',
    'tutorial:chat_send',
    'tutorial:prompt_limits',
    'tutorial:toolbar',
    'tutorial:transport:play',
    'tutorial:transport:record',
    'tutorial:transport:restart',
    'tutorial:mute',
    'tutorial:solo',
    'tutorial:add_button',
    'tutorial:add_audio',
    'tutorial:add_instrument',
    'tutorial:export',
    'tutorial:project_settings',
    'tutorial:master_button',
    'tutorial:plugins',
    'tutorial:one_button_mix',
    'tutorial:piano_roll',
    'tutorial:timeline',
  };

  String _tutorialSlug(String raw) {
    return raw
        .trim()
        .toLowerCase()
        .replaceAll(RegExp(r'[^a-z0-9]+'), '_')
        .replaceAll(RegExp(r'_+'), '_')
        .replaceAll(RegExp(r'^_|_$'), '');
  }

  String? _normalizeTutorialTargetId(String raw) {
    final normalized = AssistantActionUtils.normalizeTutorialTargetId(raw);
    if (normalized == null) return null;
    if (normalized.startsWith('row:')) {
      return normalized;
    }
    if (normalized == 'tutorial:effects_tab' ||
        normalized == 'tutorial:fx_list' ||
        normalized == 'tutorial:add_effect' ||
        normalized == 'tutorial:volume_tab') {
      if (_rowCount <= 0) return 'tutorial:timeline';
      final row = _selectedRow.clamp(0, _rowCount - 1);
      switch (normalized) {
        case 'tutorial:effects_tab':
          return 'row:$row:effects_tab';
        case 'tutorial:fx_list':
          return 'row:$row:fx_list';
        case 'tutorial:add_effect':
          return 'row:$row:add_effect';
        case 'tutorial:volume_tab':
          return 'row:$row:volume_tab';
      }
    }
    if (normalized == 'tutorial:automation_tab') {
      return 'tutorial:timeline';
    }
    if (normalized == 'tutorial:piano_roll' &&
        (!_showPianoRoll || _activeMidiClipEngineId == null)) {
      return 'tutorial:timeline';
    }
    if (_supportedTutorialHaloTargets.contains(normalized)) {
      return normalized;
    }
    if (normalized.startsWith('tutorial:')) {
      // Never no-op tutorial actions on unknown anchors; fall back to timeline.
      return 'tutorial:timeline';
    }
    return normalized;
  }

  List<String> _tutorialTargetSequenceForStep(
    Map<String, dynamic> step,
    Map<String, dynamic> rootData,
  ) {
    final out = <String>[];
    void add(String? key) {
      if (key == null) return;
      final trimmed = key.trim();
      if (trimmed.isEmpty || out.contains(trimmed)) return;
      out.add(trimmed);
    }

    final target = _toActionMap(step['target']);
    if (_rowCount <= 0) {
      final rawTarget = (step['target_id'] ??
              target['target_id'] ??
              rootData['target_id'] ??
              _toActionMap(rootData['target'])['target_id'] ??
              '')
          .toString();
      final fallback =
          _normalizeTutorialTargetId(rawTarget) ?? 'tutorial:timeline';
      return <String>[fallback];
    }
    final row = _toActionInt(
          step['row_index'] ??
              target['row_index'] ??
              rootData['row_index'] ??
              _toActionMap(rootData['target'])['row_index'],
        ) ??
        _selectedRow.clamp(0, _rowCount - 1);

    final effectName = (step['effect_name'] ??
            step['plugin_name'] ??
            target['effect_name'] ??
            target['plugin_name'] ??
            rootData['effect_name'] ??
            rootData['plugin_name'])
        .toString()
        .trim();
    final effectSlug = _tutorialSlug(effectName);
    final effectLower = effectName.toLowerCase();
    final effectIndex = _toActionInt(
      step['effect_index'] ??
          target['effect_index'] ??
          rootData['effect_index'] ??
          _toActionMap(rootData['target'])['effect_index'],
    );
    final paramName = (step['param_name'] ??
            step['param_id'] ??
            step['parameter'] ??
            target['param_name'] ??
            target['param_id'] ??
            rootData['param_name'] ??
            rootData['param_id'])
        .toString()
        .trim();
    final paramSlug = _tutorialSlug(paramName);
    final paramLower = paramName.toLowerCase();
    final addEffect = _toActionBool(
      step['show_add_effect'] ??
          step['effect_missing'] ??
          target['show_add_effect'] ??
          target['effect_missing'] ??
          rootData['show_add_effect'] ??
          rootData['effect_missing'],
      fallback: false,
    );

    final rawTarget = (step['target_id'] ??
            target['target_id'] ??
            rootData['target_id'] ??
            _toActionMap(rootData['target'])['target_id'] ??
            '')
        .toString();
    final normalized = _normalizeTutorialTargetId(rawTarget);

    final hasFxDrill =
        effectIndex != null || effectName.isNotEmpty || paramName.isNotEmpty;
    if (hasFxDrill || addEffect) {
      add('row:$row');
      add('row:$row:effects_tab');
      add('row:$row:fx_list');
      if (addEffect) add('row:$row:add_effect');
      if (effectIndex != null) add('row:$row:fx_index:$effectIndex');
      if (effectLower.isNotEmpty) add('row:$row:fx_contains:$effectLower');
      if (effectSlug.isNotEmpty) add('row:$row:fx_contains:$effectSlug');
      if (paramLower.isNotEmpty) add('row:$row:param:$paramLower');
      if (paramSlug.isNotEmpty) add('row:$row:param:$paramSlug');
      if (effectIndex != null && paramLower.isNotEmpty) {
        add('row:$row:fx_index:$effectIndex:param:$paramLower');
      }
      if (effectIndex != null && paramSlug.isNotEmpty) {
        add('row:$row:fx_index:$effectIndex:param:$paramSlug');
      }
      if (effectSlug.isNotEmpty && paramSlug.isNotEmpty) {
        add('row:$row:fx_contains:$effectSlug:param:$paramSlug');
      }
      if (effectLower.isNotEmpty && paramLower.isNotEmpty) {
        add('row:$row:fx_contains:$effectLower:param:$paramLower');
      }
    }

    if (normalized == 'tutorial:mute') {
      add('row:$row:mute');
    } else if (normalized == 'tutorial:solo') {
      add('row:$row:solo');
    } else if (normalized == 'tutorial:plugins') {
      add('row:$row:effects_tab');
      add('row:$row:fx_list');
    } else if (normalized == 'tutorial:timeline') {
      add('row:$row');
    }

    if (normalized != null && normalized.isNotEmpty) {
      add(normalized);
    }
    if (out.isEmpty) {
      add('tutorial:timeline');
    }
    return out;
  }

  Future<bool> _applyAssistantActions(
    List<AssistantAction> actions, {
    int? chatFlowId,
  }) async {
    var hadFailure = false;
    for (final action in actions) {
      final type = action.type.trim().toLowerCase();
      final data = _toActionMap(action.data);
      try {
        if (chatFlowId != null) {
          _throwIfChatFlowStopped(chatFlowId);
        }
        switch (type) {
          case 'tutorial':
            await _applyTutorialAction(data);
            if (chatFlowId != null) {
              _throwIfChatFlowStopped(chatFlowId);
            }
            break;
          case 'clip_edit':
            await _applyClipEditAction(data);
            if (chatFlowId != null) {
              _throwIfChatFlowStopped(chatFlowId);
            }
            break;
          case 'project_edit':
            await _applyProjectEditAction(data);
            if (chatFlowId != null) {
              _throwIfChatFlowStopped(chatFlowId);
            }
            break;
          case 'sample_insert':
            await _applySampleInsertAction(data);
            if (chatFlowId != null) {
              _throwIfChatFlowStopped(chatFlowId);
            }
            break;
          case 'effect_edit':
            await _applyEffectEditAction(data);
            if (chatFlowId != null) {
              _throwIfChatFlowStopped(chatFlowId);
            }
            break;
          case 'automation_edit':
            await _applyAutomationEditAction(data);
            if (chatFlowId != null) {
              _throwIfChatFlowStopped(chatFlowId);
            }
            break;
          case 'midi_compose':
            await _applyMidiComposeAction(data, chatFlowId: chatFlowId);
            if (chatFlowId != null) {
              _throwIfChatFlowStopped(chatFlowId);
            }
            break;
          case 'stem_separate':
            await _applyStemSeparateAction(data);
            if (chatFlowId != null) {
              _throwIfChatFlowStopped(chatFlowId);
            }
            break;
          case 'role_override':
            await _applyRoleOverrideAction(data);
            if (chatFlowId != null) {
              _throwIfChatFlowStopped(chatFlowId);
            }
            break;
          case 'clarify':
            final q = (data['question'] ?? '').toString().trim();
            if (q.isNotEmpty) {
              final options = _actionStringList(data['options']);
              if (options.isEmpty) {
                _insertAssistantChatText(q);
              } else {
                _insertAssistantChatText(
                    '$q\n\nOptions: ${options.join(' / ')}');
              }
            }
            break;
          default:
            break;
        }
      } on _ChatFlowCancelledException {
        rethrow;
      } catch (e, st) {
        debugPrint('Assistant action failed ($type): $e\n$st');
        hadFailure = true;
        throw _AssistantActionApplyException(
          actionType: type,
          cause: e,
          stackTrace: st,
        );
      }
    }
    return !hadFailure;
  }

  String _normalizeEffectEditOperation(String raw) {
    switch (raw.trim().toLowerCase()) {
      case 'delete':
      case 'remove':
      case 'delete_effect':
      case 'remove_effect':
      case 'take_out':
        return 'remove';
      case 'add':
      case 'insert':
      case 'ensure':
      case 'ensure_effect':
      case 'add_effect':
      case 'insert_effect':
        return 'add';
      case 'disable':
      case 'bypass':
      case 'mute':
        return 'bypass';
      case 'enable':
      case 'unbypass':
      case 'unmute':
        return 'unbypass';
      case 'toggle':
      case 'toggle_bypass':
        return 'toggle_bypass';
      default:
        return raw.trim().toLowerCase();
    }
  }

  int? _resolveEffectIndexFromActionData(
    List<String> effects,
    Map<String, dynamic> data,
  ) {
    if (effects.isEmpty) return null;
    final target = _actionTarget(data);
    final explicitIndex = _toActionInt(
      data['effect_index'] ??
          target['effect_index'] ??
          data['plugin_index'] ??
          target['plugin_index'],
    );
    if (explicitIndex != null &&
        explicitIndex >= 0 &&
        explicitIndex < effects.length) {
      return explicitIndex;
    }

    final effectNeedles = <String>[];
    void addNeedle(dynamic raw) {
      final needle = raw?.toString().trim().toLowerCase() ?? '';
      if (needle.isEmpty || needle == 'plugin' || needle == 'effect') return;
      effectNeedles.add(needle);
    }

    addNeedle(data['effect_name']);
    addNeedle(target['effect_name']);
    addNeedle(data['plugin_name']);
    addNeedle(target['plugin_name']);
    addNeedle(data['effect_name_contains']);
    addNeedle(target['effect_name_contains']);
    addNeedle(data['plugin']);
    addNeedle(target['plugin']);
    addNeedle(data['effect']);
    addNeedle(target['effect']);
    addNeedle(data['fx']);
    addNeedle(target['fx']);
    addNeedle(data['name']);
    addNeedle(target['name']);
    addNeedle(data['kind']);
    addNeedle(target['kind']);

    for (final needle in effectNeedles) {
      final exact = <int>[];
      final fuzzy = <int>[];
      for (int i = 0; i < effects.length; i++) {
        final candidate = effects[i].trim().toLowerCase();
        if (candidate == needle) {
          exact.add(i);
        } else if (candidate.contains(needle) || needle.contains(candidate)) {
          fuzzy.add(i);
        }
      }
      if (exact.length == 1) return exact.first;
      if (exact.isEmpty && fuzzy.length == 1) return fuzzy.first;
    }

    if (effects.length == 1) return 0;
    return null;
  }

  Future<void> _applyEffectEditAction(Map<String, dynamic> data) async {
    final target = _actionTarget(data);
    final operation = _normalizeEffectEditOperation(
      (data['operation'] ?? '').toString(),
    );
    final scope = (data['scope'] ?? target['scope'] ?? '')
        .toString()
        .trim()
        .toLowerCase();
    final isMaster = scope == 'master' ||
        scope == 'master_bus' ||
        scope == 'master-bus' ||
        scope == 'masterbus';

    final row = isMaster ? null : _resolveRowIndexFromActionTarget(data);
    if (!isMaster && row == null) {
      _insertAssistantChatText(
          "I couldn't resolve which track plugin to edit.");
      return;
    }

    final effects = isMaster
        ? await JuceAudioEngine.getMasterEffects()
        : await JuceAudioEngine.getTrackEffectsForRow(row!);
    final effectIndex = _resolveEffectIndexFromActionData(effects, data);

    if (operation == 'remove') {
      if (effectIndex == null) {
        final rowName = row == null ? 'this track' : _rowDisplayName(row);
        _insertAssistantChatText(
          isMaster
              ? "I couldn't resolve which master plugin to remove."
              : "I couldn't resolve which plugin to remove on $rowName.",
        );
        return;
      }
      final effectName = effects[effectIndex];
      final onTrackChange = () {
        _refreshAudioEditorView();
        if (row != null) {
          _refreshRowFx(row);
          unawaited(_refreshAutomationTargetsForRow(row));
        } else {
          unawaited(_refreshAutomationTargetsForAllRows());
        }
      };
      final EditorUndoAction action = isMaster
          ? RemoveMasterEffectAction(
              effectIndex: effectIndex,
              pathOrName: effectName,
              onChange: onTrackChange,
            )
          : RemoveEffectAction(
              row: row!,
              effectIndex: effectIndex,
              pathOrName: effectName,
              onChange: onTrackChange,
            );
      final beforeCount = effects
          .where(
            (e) => e.trim().toLowerCase() == effectName.trim().toLowerCase(),
          )
          .length;
      await _undoManager.execute(action);
      final effectsAfter = isMaster
          ? await JuceAudioEngine.getMasterEffects()
          : await JuceAudioEngine.getTrackEffectsForRow(row!);
      final afterCount = effectsAfter
          .where(
            (e) => e.trim().toLowerCase() == effectName.trim().toLowerCase(),
          )
          .length;
      final removed = afterCount < beforeCount;
      if (!removed) {
        debugPrint(
          'effect_edit remove verification failed (master=$isMaster row=$row effect=$effectName)',
        );
        return;
      }
      if (!isMaster) {
        _mixHighlighter.trigger([
          HaloKey('row:$row'),
          HaloKey('row:$row:effects_tab'),
          HaloKey('row:$row:fx_list'),
        ]);
      }
      _insertSystemChatText(
        isMaster
            ? '• Removed $effectName from Master Bus •'
            : '• Removed $effectName from ${_rowDisplayName(row!)} •',
      );
      return;
    }

    if (operation == 'add') {
      final effectNeedle = (data['effect_name'] ??
              target['effect_name'] ??
              data['plugin_name'] ??
              target['plugin_name'] ??
              data['effect_name_contains'] ??
              target['effect_name_contains'] ??
              data['plugin'] ??
              target['plugin'] ??
              data['fx'] ??
              target['fx'] ??
              data['name'] ??
              target['name'] ??
              data['kind'] ??
              target['kind'] ??
              data['effect'] ??
              target['effect'])
          .toString()
          .trim()
          .toLowerCase();
      final effectName = pickMixroomEffect(effectNeedle);
      if (effectName == null) {
        _insertAssistantChatText("I couldn't resolve which plugin to add.");
        return;
      }
      final alreadyIndex = effects.indexWhere(
          (e) => e.trim().toLowerCase() == effectName.toLowerCase());
      if (alreadyIndex != -1) {
        return;
      }
      final onTrackChange = () {
        _refreshAudioEditorView();
        if (row != null) {
          _refreshRowFx(row);
          unawaited(_refreshAutomationTargetsForRow(row));
        } else {
          unawaited(_refreshAutomationTargetsForAllRows());
        }
      };
      final EditorUndoAction action = isMaster
          ? InsertMasterEffectAction(
              pathOrName: effectName,
              onChange: onTrackChange,
            )
          : InsertEffectAction(
              row: row!,
              pathOrName: effectName,
              onChange: onTrackChange,
            );
      await _undoManager.execute(action);
      final effectsAfter = isMaster
          ? await JuceAudioEngine.getMasterEffects()
          : await JuceAudioEngine.getTrackEffectsForRow(row!);
      final inserted = effectsAfter.any(
        (e) => e.trim().toLowerCase() == effectName.trim().toLowerCase(),
      );
      if (!inserted) {
        debugPrint(
          'effect_edit add verification failed (master=$isMaster row=$row effect=$effectName)',
        );
        return;
      }
      if (!isMaster) {
        _mixHighlighter.trigger([
          HaloKey('row:$row'),
          HaloKey('row:$row:effects_tab'),
          HaloKey('row:$row:fx_list'),
        ]);
      }
      _insertSystemChatText(
        isMaster
            ? '• Added $effectName to Master Bus •'
            : '• Added $effectName to ${_rowDisplayName(row!)} •',
      );
      return;
    }

    if (operation == 'bypass' ||
        operation == 'unbypass' ||
        operation == 'toggle_bypass') {
      if (effectIndex == null) {
        final rowName = row == null ? 'this track' : _rowDisplayName(row);
        _insertAssistantChatText(
          isMaster
              ? "I couldn't resolve which master plugin to toggle."
              : "I couldn't resolve which plugin to toggle on $rowName.",
        );
        return;
      }
      final effectName = effects[effectIndex];
      final currentState = isMaster
          ? await JuceAudioEngine.getMasterEffectBypassState(effectIndex)
          : await JuceAudioEngine.getRowEffectBypassState(row!, effectIndex);
      final nextState = switch (operation) {
        'bypass' => true,
        'unbypass' => false,
        _ => !currentState,
      };
      final onTrackChange = () {
        _refreshAudioEditorView();
        if (row != null) {
          _refreshRowFx(row);
          unawaited(_refreshAutomationTargetsForRow(row));
        } else {
          unawaited(_refreshAutomationTargetsForAllRows());
        }
      };
      final EditorUndoAction action = isMaster
          ? BypassMasterEffectAction(
              effectIndex: effectIndex,
              oldState: currentState,
              newState: nextState,
              onChange: onTrackChange,
            )
          : BypassEffectAction(
              row: row!,
              effectIndex: effectIndex,
              oldState: currentState,
              newState: nextState,
              onChange: onTrackChange,
            );
      await _undoManager.execute(action);
      if (!isMaster) {
        _mixHighlighter.trigger([
          HaloKey('row:$row'),
          HaloKey('row:$row:effects_tab'),
          HaloKey('row:$row:fx_list'),
        ]);
      }
      _insertSystemChatText(
        isMaster
            ? '• ${nextState ? 'Bypassed' : 'Enabled'} $effectName on Master Bus •'
            : '• ${nextState ? 'Bypassed' : 'Enabled'} $effectName on ${_rowDisplayName(row!)} •',
      );
      return;
    }

    _insertAssistantChatText("I couldn't apply that plugin edit.");
  }

  Future<void> _applyTutorialAction(Map<String, dynamic> data) async {
    final rawSteps = (data['steps'] as List?) ?? const [];
    final parsed = rawSteps.map(_toActionMap).toList(growable: false);
    final steps = parsed.isEmpty
        ? <Map<String, dynamic>>[data]
        : parsed.take(12).toList(growable: false);

    for (int i = 0; i < steps.length; i++) {
      final step = steps[i];
      final sequence = _tutorialTargetSequenceForStep(step, data);
      final drilldown = _toActionBool(
        step['drilldown'] ?? data['drilldown'],
        fallback: true,
      );
      final targets = drilldown
          ? AssistantActionUtils.compactTutorialPlaybackTargets(sequence)
          : <String>[sequence.isEmpty ? 'tutorial:timeline' : sequence.last];
      if (targets.isEmpty) continue;

      final baseDurationMs = (_toActionInt(step['duration_ms']) ??
              _toActionInt(data['duration_ms']) ??
              3200)
          .clamp(1200, 18000);
      final previewDurationMs =
          AssistantActionUtils.tutorialPreviewDurationMs(baseDurationMs);
      final previewPauseMs = (_toActionInt(step['pause_ms']) ??
              AssistantActionUtils.tutorialPreviewPauseMs(previewDurationMs))
          .clamp(480, 1400);
      final finalDurationMs =
          AssistantActionUtils.tutorialFinalDurationMs(baseDurationMs);

      for (int j = 0; j < targets.length; j++) {
        final key = targets[j];
        final isLastOverall = i == steps.length - 1 && j == targets.length - 1;
        final durationMs = isLastOverall ? finalDurationMs : previewDurationMs;
        _mixHighlighter.clear();
        _mixHighlighter.trigger(
          [HaloKey(key)],
          duration: Duration(milliseconds: durationMs),
        );
        if (isLastOverall) continue;
        final pauseMs = previewPauseMs;
        await Future<void>.delayed(Duration(milliseconds: pauseMs));
      }
    }
  }

  String _normalizeClipEditOperation(String raw) {
    return AssistantActionUtils.normalizeClipEditOperation(raw);
  }

  String _normalizeMidiComposeOperation(String raw) {
    return AssistantActionUtils.normalizeMidiComposeOperation(raw);
  }

  MapEntry<double, double>? _estimateAutoTrimBoundsMs(
    AudioTrack clip, {
    double thresholdFloor = 0.012,
    double thresholdRatio = 0.08,
    double paddingMs = 8.0,
  }) {
    return AssistantActionUtils.estimateAutoTrimBoundsMs(
      waveform: clip.normWaveformData,
      fullMs: _clipFullDurationMsForTrim(clip),
      trimStartMs: clip.trimStart.inMilliseconds.toDouble(),
      trimEndMs: clip.trimEnd.inMilliseconds.toDouble(),
      thresholdFloor: thresholdFloor,
      thresholdRatio: thresholdRatio,
      paddingMs: paddingMs,
    );
  }

  Future<void> _applyTrimActionForClip(
    int clipIndex, {
    required double newTrimStartMs,
    required double newTrimEndMs,
    double? newOffsetSec,
  }) async {
    if (clipIndex < 0 || clipIndex >= _audioTracks.length) return;
    final clip = _audioTracks[clipIndex];

    final fullMs = _clipFullDurationMsForTrim(clip).clamp(1.0, 1e12);
    final safeTrimStart = newTrimStartMs.clamp(0.0, fullMs - 50.0).toDouble();
    final safeTrimEnd =
        newTrimEndMs.clamp(safeTrimStart + 50.0, fullMs).toDouble();

    await _undoManager.execute(
      TrimClipAction(
        tracks: _audioTracks,
        originalIndex: clipIndex,
        oldTrimStart: clip.trimStart,
        oldTrimEnd: clip.trimEnd,
        oldOffset: clip.offset,
        newTrimStart: Duration(milliseconds: safeTrimStart.round()),
        newTrimEnd: Duration(milliseconds: safeTrimEnd.round()),
        newOffset: newOffsetSec,
        onChange: () {
          unawaited(_syncClipTimingToEngine(clipIndex));
          _updateOverallDurationIfNeeded();
          if (mounted) setState(() {});
        },
      ),
    );
  }

  Future<void> _setProjectTempoFromDetectedClip(int clipIndex) async {
    if (clipIndex < 0 || clipIndex >= _audioTracks.length) return;
    final clip = _audioTracks[clipIndex];
    if (clip.isMidi) return;

    final detected = await _detectClipTempoBpm(clip);
    if (detected == null || !detected.isFinite) return;
    final roundedTempo = detected.round().clamp(40, 240).toDouble();

    _setStateAndRefreshProjectSettings(() {
      clip.sourceTempoBpm = detected;
      _tempoStretchEnabled = true;
    });
    await _applyProjectTempoChange(roundedTempo);
  }

  Future<void> _applyAutoBpmAlignAction(Map<String, dynamic> data) async {
    final target = _actionTarget(data);
    final clipIndices =
        _resolveClipIndicesFromActionTarget(data, requireAudio: true);
    if (clipIndices.isEmpty) {
      _insertAssistantChatText(
          "I couldn't resolve which audio clips to align. Select clips and ask again.");
      return;
    }

    final preservePitch = _toActionBool(data['preserve_pitch'], fallback: true);
    final setProjectTempo = _toActionBool(
      data['set_project_tempo'] ?? data['detect_set_project_tempo'],
      fallback: false,
    );
    final explicitProjectTempo = _toActionDouble(
        data['project_tempo_bpm'] ?? target['project_tempo_bpm']);

    if (explicitProjectTempo != null && explicitProjectTempo.isFinite) {
      final clampedTempo = _clampTempo(explicitProjectTempo);
      if (clampedTempo != _tempo) {
        await _applyProjectTempoChange(clampedTempo);
      }
    } else if (setProjectTempo) {
      final sourceIdx = _toActionInt(
            data['project_tempo_source_clip_index'] ??
                target['project_tempo_source_clip_index'],
          ) ??
          (clipIndices.contains(_timelinePrimarySelectedClipIndex)
              ? _timelinePrimarySelectedClipIndex
              : clipIndices.first);
      await _setProjectTempoFromDetectedClip(sourceIdx);
    }

    for (final idx in clipIndices) {
      await _setClipTempoFollowMode(
        idx,
        preservePitch: preservePitch,
        showFeedback: false,
      );
    }
    _showSmallNotice(
        'Tempo-aligned ${clipIndices.length} clip${clipIndices.length == 1 ? '' : 's'}.');
  }

  double _clipTimelineStartMs(AudioTrack clip) => clip.offset * 1000.0;

  double _clipTimelineEndMs(AudioTrack clip) =>
      _clipTimelineStartMs(clip) + _clipTimelineDurationMs(clip);

  String _normalizedClipPath(String path) => p.normalize(path);

  String _decodeDisplayPathSegment(String value) {
    final trimmed = value.trim();
    if (trimmed.isEmpty || !trimmed.contains('%')) return trimmed;
    try {
      return Uri.decodeFull(trimmed);
    } catch (_) {
      return trimmed;
    }
  }

  String _displayNameForFilePath(String path) {
    final base = p.basename(path).trim();
    final rawLabel = base.isEmpty ? path.trim() : base;
    final decodedLabel = _decodeDisplayPathSegment(rawLabel);
    return decodedLabel.isEmpty ? rawLabel : decodedLabel;
  }

  String _displayStemForFilePath(String path) {
    final fileName = _displayNameForFilePath(path);
    final extension = p.extension(fileName);
    if (extension.isEmpty) return fileName;
    return fileName.substring(0, fileName.length - extension.length);
  }

  int? _findAudioClipIndexAtTimelineMs(
    double timelineMs, {
    int? rowIndex,
    String? filePath,
    int? preferEngineClipId,
  }) {
    if (!timelineMs.isFinite) return null;
    final expectedPath =
        filePath == null ? null : _normalizedClipPath(filePath);
    final candidates = <int>[];
    for (int i = 0; i < _audioTracks.length; i++) {
      final clip = _audioTracks[i];
      if (clip.isMidi) continue;
      if (rowIndex != null && clip.rowIndex != rowIndex) continue;
      if (expectedPath != null &&
          _normalizedClipPath(clip.file.path) != expectedPath) {
        continue;
      }
      final startMs = _clipTimelineStartMs(clip);
      final endMs = _clipTimelineEndMs(clip);
      if (timelineMs < startMs - 0.5 || timelineMs > endMs + 0.5) continue;
      candidates.add(i);
    }
    if (candidates.isEmpty) return null;
    if (preferEngineClipId != null && preferEngineClipId >= 0) {
      for (final idx in candidates) {
        if (_audioTracks[idx].engineClipId == preferEngineClipId) {
          return idx;
        }
      }
    }
    candidates.sort((a, b) {
      final aStart = _clipTimelineStartMs(_audioTracks[a]);
      final bStart = _clipTimelineStartMs(_audioTracks[b]);
      final aDist = (aStart - timelineMs).abs();
      final bDist = (bStart - timelineMs).abs();
      final byDist = aDist.compareTo(bDist);
      if (byDist != 0) return byDist;
      return a.compareTo(b);
    });
    return candidates.first;
  }

  List<MapEntry<double, double>> _mergeTimelineRangesMs(
    Iterable<MapEntry<double, double>> ranges, {
    double minGapMs = 45.0,
    double minLengthMs = 25.0,
    double? minMs,
    double? maxMs,
  }) {
    final normalized = <MapEntry<double, double>>[];
    for (final r in ranges) {
      double start = r.key;
      double end = r.value;
      if (!start.isFinite || !end.isFinite) continue;
      if (end < start) {
        final tmp = start;
        start = end;
        end = tmp;
      }
      if (minMs != null || maxMs != null) {
        final lo = minMs ?? double.negativeInfinity;
        final hi = maxMs ?? double.infinity;
        start = start.clamp(lo, hi).toDouble();
        end = end.clamp(lo, hi).toDouble();
      }
      if (!start.isFinite || !end.isFinite) continue;
      if (end - start < minLengthMs) continue;
      normalized.add(MapEntry(start, end));
    }
    if (normalized.isEmpty) return const <MapEntry<double, double>>[];
    normalized.sort((a, b) => a.key.compareTo(b.key));

    final merged = <MapEntry<double, double>>[];
    double currentStart = normalized.first.key;
    double currentEnd = normalized.first.value;

    for (int i = 1; i < normalized.length; i++) {
      final next = normalized[i];
      if (next.key <= currentEnd + minGapMs) {
        currentEnd = math.max(currentEnd, next.value);
      } else {
        merged.add(MapEntry(currentStart, currentEnd));
        currentStart = next.key;
        currentEnd = next.value;
      }
    }
    merged.add(MapEntry(currentStart, currentEnd));
    return merged
        .where((r) => (r.value - r.key) >= minLengthMs)
        .toList(growable: false);
  }

  double _quantile(List<double> values, double q) {
    if (values.isEmpty) return 0.0;
    final sorted = List<double>.from(values)..sort();
    final safeQ = q.clamp(0.0, 1.0).toDouble();
    final pos = safeQ * (sorted.length - 1);
    final lo = pos.floor();
    final hi = pos.ceil();
    if (lo == hi) return sorted[lo];
    final t = pos - lo;
    return sorted[lo] * (1.0 - t) + sorted[hi] * t;
  }

  Future<_ClipMono16kSegment?> _decodeTrimmedClipMono16k(
    AudioTrack clip,
  ) async {
    if (clip.isMidi) return null;
    const sampleRate = 16000;
    Float32List decoded = Float32List(0);
    try {
      decoded = await JuceAudioEngine.decodeAudioMono16k(clip.file.path);
    } catch (_) {
      return null;
    }
    if (decoded.isEmpty) return null;

    int start = (clip.trimStart.inMilliseconds * sampleRate / 1000).round();
    int end = (clip.trimEnd.inMilliseconds * sampleRate / 1000).round();
    start = start.clamp(0, decoded.length);
    end = end.clamp(start, decoded.length);
    if (end <= start + 32) return null;

    final samples = Float32List.fromList(decoded.sublist(start, end));
    if (samples.isEmpty) return null;

    final localDurationMs = samples.length * 1000.0 / sampleRate;
    final timelineDurationMs =
        _clipTimelineDurationMs(clip).clamp(1.0, 1.0e12).toDouble();
    final timelineScale =
        localDurationMs > 0.0 ? timelineDurationMs / localDurationMs : 1.0;
    final timelineStartMs = _clipTimelineStartMs(clip);
    final timelineEndMs = timelineStartMs + localDurationMs * timelineScale;

    return _ClipMono16kSegment(
      samples: samples,
      sampleRate: sampleRate,
      timelineStartMs: timelineStartMs,
      timelineEndMs: timelineEndMs,
      timelineMsPerLocalMs: timelineScale,
    );
  }

  List<double> _frameRmsSeries(
    Float32List samples, {
    int frameSize = 320,
    int hopSize = 160,
  }) {
    if (samples.length < frameSize || hopSize <= 0) return const <double>[];
    final out = <double>[];
    for (int i = 0; i + frameSize <= samples.length; i += hopSize) {
      double sumSq = 0.0;
      for (int j = 0; j < frameSize; j++) {
        final s = samples[i + j];
        sumSq += s * s;
      }
      out.add(math.sqrt(sumSq / frameSize));
    }
    return out;
  }

  Float32List _downsampleMonoSamples(
    Float32List samples, {
    int factor = 4,
  }) {
    if (factor <= 1 || samples.isEmpty) return Float32List.fromList(samples);
    final outLength = (samples.length / factor).floor();
    if (outLength <= 0) return Float32List(0);
    final out = Float32List(outLength);
    for (int i = 0; i < outLength; i++) {
      final start = i * factor;
      double sum = 0.0;
      for (int j = 0; j < factor; j++) {
        sum += samples[start + j];
      }
      out[i] = sum / factor;
    }
    return out;
  }

  int? _medianIntValue(List<int> values) {
    if (values.isEmpty) return null;
    final sorted = List<int>.from(values)..sort();
    return sorted[sorted.length ~/ 2];
  }

  _PitchEstimate? _estimatePitchForWindow(
    Float32List samples, {
    required int start,
    required int length,
    required int sampleRate,
    double minHz = 45.0,
    double maxHz = 1000.0,
  }) {
    if (sampleRate <= 0 || length <= 16) return null;
    final safeStart = start.clamp(0, samples.length);
    final safeEnd = math.min(samples.length, safeStart + length);
    final windowLength = safeEnd - safeStart;
    if (windowLength < 32) return null;

    double mean = 0.0;
    for (int i = safeStart; i < safeEnd; i++) {
      mean += samples[i];
    }
    mean /= windowLength;

    final minLag = math.max(2, (sampleRate / maxHz).floor());
    final maxLag = math.min(
        windowLength - 2, math.max(minLag + 1, (sampleRate / minHz).ceil()));
    if (maxLag <= minLag) return null;

    double bestCorr = 0.0;
    int bestLag = 0;
    double? prevCorr;
    double currCorr = 0.0;

    for (int lag = minLag; lag <= maxLag; lag++) {
      double numerator = 0.0;
      double leftEnergy = 0.0;
      double rightEnergy = 0.0;
      for (int i = safeStart; i + lag < safeEnd; i++) {
        final a = samples[i] - mean;
        final b = samples[i + lag] - mean;
        numerator += a * b;
        leftEnergy += a * a;
        rightEnergy += b * b;
      }
      final denom = math.sqrt(leftEnergy * rightEnergy);
      final nextCorr = denom > 1.0e-9 ? numerator / denom : 0.0;
      if (prevCorr != null &&
          currCorr >= prevCorr &&
          currCorr >= nextCorr &&
          currCorr > bestCorr) {
        bestCorr = currCorr;
        bestLag = lag - 1;
      }
      prevCorr = currCorr;
      currCorr = nextCorr;
    }

    if (currCorr > bestCorr) {
      bestCorr = currCorr;
      bestLag = maxLag;
    }
    if (bestLag <= 0 || bestCorr < 0.38) return null;

    return _PitchEstimate(
      frequencyHz: sampleRate / bestLag,
      clarity: bestCorr,
    );
  }

  List<MidiNote> _basicPitchEventsToMidiNotes(
    _ClipMono16kSegment segment,
    List<BasicPitchNoteEvent> events,
  ) {
    if (events.isEmpty) return const <MidiNote>[];
    final tempo = _clampTempo(_tempo);
    final msPerBeat = 60000.0 / tempo;
    final notes = <MidiNote>[];

    for (final event in events) {
      final localStartMs = event.startSeconds * 1000.0;
      final localEndMs = event.endSeconds * 1000.0;
      if (!localStartMs.isFinite ||
          !localEndMs.isFinite ||
          localEndMs <= localStartMs) {
        continue;
      }

      final timelineStartMs =
          segment.timelineStartMs + localStartMs * segment.timelineMsPerLocalMs;
      final timelineEndMs =
          segment.timelineStartMs + localEndMs * segment.timelineMsPerLocalMs;
      final startBeat = math.max(
        0.0,
        (timelineStartMs - segment.timelineStartMs) / msPerBeat,
      );
      final lengthBeats = math.max(
        0.0625,
        (timelineEndMs - timelineStartMs) / msPerBeat,
      );
      notes.add(
        MidiNote(
          id: 'ai_audio_midi_${DateTime.now().microsecondsSinceEpoch}_${notes.length}',
          pitch: event.pitchMidi.clamp(0, 127).toInt(),
          startBeat: startBeat,
          lengthBeats: lengthBeats,
          velocity: event.amplitude.clamp(0.25, 1.0),
        ),
      );
    }

    notes.sort((a, b) => a.startBeat.compareTo(b.startBeat));
    if (notes.length <= 1024) return notes;
    return notes.take(1024).map((note) => note.copy()).toList(growable: false);
  }

  List<MidiNote> _transcribeAudioClipToMidiNotesHeuristic(
    _ClipMono16kSegment segment,
  ) {
    const sourceSampleRate = 16000;
    const analysisSampleRate = 4000;
    const downsampleFactor = sourceSampleRate ~/ analysisSampleRate;
    const frameSize = 384;
    const hopSize = 128;
    final analysisSamples = _downsampleMonoSamples(
      segment.samples,
      factor: downsampleFactor,
    );
    if (analysisSamples.length < frameSize) return const <MidiNote>[];

    final rms = _frameRmsSeries(
      analysisSamples,
      frameSize: frameSize,
      hopSize: hopSize,
    );
    if (rms.isEmpty) return const <MidiNote>[];

    final noiseFloor = _quantile(rms, 0.2);
    final activeThreshold = math.max(0.006, noiseFloor * 2.25).toDouble();
    final activeRms =
        rms.where((value) => value >= activeThreshold).toList(growable: false);
    if (activeRms.isEmpty) return const <MidiNote>[];
    final velocityReference = math.max(
      _quantile(activeRms, 0.85),
      activeThreshold,
    );

    final rawMidi = List<int?>.filled(rms.length, null, growable: false);
    for (int i = 0; i < rms.length; i++) {
      if (rms[i] < activeThreshold) continue;
      final estimate = _estimatePitchForWindow(
        analysisSamples,
        start: i * hopSize,
        length: frameSize,
        sampleRate: analysisSampleRate,
      );
      if (estimate == null || estimate.clarity < 0.42) continue;
      final midiValue =
          69.0 + 12.0 * (math.log(estimate.frequencyHz / 440.0) / math.ln2);
      if (!midiValue.isFinite) continue;
      rawMidi[i] = midiValue.round().clamp(0, 127).toInt();
    }

    final smoothedMidi =
        List<int?>.filled(rawMidi.length, null, growable: false);
    for (int i = 0; i < rawMidi.length; i++) {
      final current = rawMidi[i];
      if (current == null) continue;
      final neighborhood = <int>[];
      for (int j = math.max(0, i - 1);
          j <= math.min(rawMidi.length - 1, i + 1);
          j++) {
        final candidate = rawMidi[j];
        if (candidate != null) neighborhood.add(candidate);
      }
      smoothedMidi[i] = _medianIntValue(neighborhood) ?? current;
    }

    final notes = <MidiNote>[];
    final tempo = _clampTempo(_tempo);
    final msPerBeat = 60000.0 / tempo;
    int? noteStartFrame;
    int lastFrame = -1;
    final notePitches = <int>[];
    final noteLevels = <double>[];

    void flushNote() {
      if (noteStartFrame == null || lastFrame < noteStartFrame!) {
        noteStartFrame = null;
        notePitches.clear();
        noteLevels.clear();
        return;
      }

      final startSample = noteStartFrame! * hopSize;
      final endSample =
          math.min(analysisSamples.length, lastFrame * hopSize + frameSize);
      final localStartMs = startSample * 1000.0 / analysisSampleRate;
      final localEndMs = endSample * 1000.0 / analysisSampleRate;
      final localDurationMs = localEndMs - localStartMs;
      if (localDurationMs < 85.0 || notePitches.isEmpty) {
        noteStartFrame = null;
        notePitches.clear();
        noteLevels.clear();
        return;
      }

      final medianPitch = _medianIntValue(notePitches);
      if (medianPitch == null) {
        noteStartFrame = null;
        notePitches.clear();
        noteLevels.clear();
        return;
      }

      final timelineStartMs =
          segment.timelineStartMs + localStartMs * segment.timelineMsPerLocalMs;
      final timelineEndMs =
          segment.timelineStartMs + localEndMs * segment.timelineMsPerLocalMs;
      final startBeat = math.max(
          0.0, (timelineStartMs - segment.timelineStartMs) / msPerBeat);
      final lengthBeats = math.max(
        0.0625,
        (timelineEndMs - timelineStartMs) / msPerBeat,
      );
      final velocity = ((noteLevels.isEmpty
                  ? 0.72
                  : _quantile(noteLevels, 0.6) / velocityReference)
              .clamp(0.3, 1.0))
          .toDouble();
      notes.add(
        MidiNote(
          id: 'ai_audio_midi_${DateTime.now().microsecondsSinceEpoch}_${notes.length}',
          pitch: medianPitch.clamp(0, 127).toInt(),
          startBeat: startBeat,
          lengthBeats: lengthBeats,
          velocity: velocity,
        ),
      );

      noteStartFrame = null;
      notePitches.clear();
      noteLevels.clear();
    }

    for (int i = 0; i < smoothedMidi.length; i++) {
      final pitch = smoothedMidi[i];
      if (pitch == null) {
        flushNote();
        continue;
      }
      if (noteStartFrame == null) {
        noteStartFrame = i;
        lastFrame = i;
        notePitches.add(pitch);
        noteLevels.add(rms[i]);
        continue;
      }

      final currentMedian = _medianIntValue(notePitches) ?? pitch;
      if ((pitch - currentMedian).abs() <= 1) {
        lastFrame = i;
        notePitches.add(pitch);
        noteLevels.add(rms[i]);
        continue;
      }

      flushNote();
      noteStartFrame = i;
      lastFrame = i;
      notePitches.add(pitch);
      noteLevels.add(rms[i]);
    }
    flushNote();

    if (notes.isEmpty) return const <MidiNote>[];
    notes.sort((a, b) => a.startBeat.compareTo(b.startBeat));

    final merged = <MidiNote>[];
    for (final note in notes) {
      if (merged.isNotEmpty) {
        final prev = merged.last;
        final prevEnd = prev.startBeat + prev.lengthBeats;
        if (prev.pitch == note.pitch && note.startBeat - prevEnd <= 0.125) {
          prev.lengthBeats = math.max(prev.lengthBeats,
              note.startBeat + note.lengthBeats - prev.startBeat);
          prev.velocity = math.max(prev.velocity, note.velocity);
          continue;
        }
      }
      merged.add(note.copy());
    }

    if (merged.length <= 512) return merged;
    final trimmed = merged
        .where((note) => note.lengthBeats >= 0.08)
        .toList(growable: false);
    if (trimmed.isEmpty) {
      return merged
          .take(512)
          .map((note) => note.copy())
          .toList(growable: false);
    }
    return trimmed.take(512).map((note) => note.copy()).toList(growable: false);
  }

  Future<List<MidiNote>> _transcribeAudioClipToMidiNotes(
    AudioTrack clip,
  ) async {
    final segment = await _decodeTrimmedClipMono16k(clip);
    if (segment == null) return const <MidiNote>[];
    try {
      final events = await BasicPitchTranscriber.instance
          .transcribeMono16k(segment.samples);
      final notes = _basicPitchEventsToMidiNotes(segment, events);
      if (notes.isNotEmpty) {
        return notes;
      }
      aiDebugLog('basic-pitch',
          'transcription returned no notes -> heuristic fallback');
    } catch (error) {
      aiDebugLog('basic-pitch', 'transcription failed error=$error');
    }

    return _transcribeAudioClipToMidiNotesHeuristic(segment);
  }

  List<MapEntry<double, double>> _rangesFromFrameMask(
    List<bool> mask, {
    required int frameSize,
    required int hopSize,
    required int sampleRate,
    required int totalSamples,
    double minDurationMs = 80.0,
  }) {
    if (mask.isEmpty) return const <MapEntry<double, double>>[];
    final out = <MapEntry<double, double>>[];
    int startFrame = -1;

    for (int i = 0; i < mask.length; i++) {
      final active = mask[i];
      if (active && startFrame < 0) {
        startFrame = i;
      }
      final ended = startFrame >= 0 && (!active || i == mask.length - 1);
      if (!ended) continue;

      final endExclusive = (!active) ? i : i + 1;
      final startSample = startFrame * hopSize;
      final endSample =
          math.min(totalSamples, (endExclusive - 1) * hopSize + frameSize);
      final startMs = startSample * 1000.0 / sampleRate;
      final endMs = endSample * 1000.0 / sampleRate;
      if (endMs - startMs >= minDurationMs) {
        out.add(MapEntry(startMs, endMs));
      }
      startFrame = -1;
    }

    return out;
  }

  Future<List<MapEntry<double, double>>> _detectDialogActiveSpeechRangesForClip(
    AudioTrack clip, {
    double minDurationMs = 110.0,
    double mergeGapMs = 120.0,
    double floorRms = 0.01,
    double thresholdMultiplier = 2.35,
  }) async {
    final segment = await _decodeTrimmedClipMono16k(clip);
    if (segment == null) return const <MapEntry<double, double>>[];

    const frameSize = 320;
    const hopSize = 160;
    final rms = _frameRmsSeries(
      segment.samples,
      frameSize: frameSize,
      hopSize: hopSize,
    );
    if (rms.isEmpty) return const <MapEntry<double, double>>[];

    final noiseFloor = _quantile(rms, 0.2);
    final threshold =
        math.max(floorRms, noiseFloor * thresholdMultiplier).toDouble();
    final activeMask = rms.map((v) => v >= threshold).toList(growable: false);
    final localRanges = _rangesFromFrameMask(
      activeMask,
      frameSize: frameSize,
      hopSize: hopSize,
      sampleRate: segment.sampleRate,
      totalSamples: segment.samples.length,
      minDurationMs: minDurationMs,
    );
    if (localRanges.isEmpty) return const <MapEntry<double, double>>[];

    final localDurationMs =
        segment.samples.length * 1000.0 / segment.sampleRate.toDouble();
    final mergedLocal = _mergeTimelineRangesMs(
      localRanges,
      minGapMs: mergeGapMs,
      minLengthMs: minDurationMs,
      minMs: 0.0,
      maxMs: localDurationMs,
    );
    if (mergedLocal.isEmpty) return const <MapEntry<double, double>>[];

    final timelineRanges = mergedLocal
        .map((r) => MapEntry(
              segment.timelineStartMs + r.key * segment.timelineMsPerLocalMs,
              segment.timelineStartMs + r.value * segment.timelineMsPerLocalMs,
            ))
        .toList(growable: false);
    return _mergeTimelineRangesMs(
      timelineRanges,
      minGapMs: mergeGapMs * segment.timelineMsPerLocalMs,
      minLengthMs: minDurationMs * segment.timelineMsPerLocalMs,
      minMs: segment.timelineStartMs,
      maxMs: segment.timelineEndMs,
    );
  }

  MapEntry<double, double>? _deriveDialogPhraseRangeAroundAnchor(
    AudioTrack clip,
    List<MapEntry<double, double>> activeRanges,
    double anchorMs, {
    double prePadMs = 35.0,
    double postPadMs = 70.0,
  }) {
    if (activeRanges.isEmpty) return null;
    final clipStart = _clipTimelineStartMs(clip);
    final clipEnd = _clipTimelineEndMs(clip);
    final probe = anchorMs.clamp(clipStart, clipEnd).toDouble();

    MapEntry<double, double>? best;
    double bestScore = double.infinity;
    for (final r in activeRanges) {
      if (probe >= r.key && probe <= r.value) {
        best = r;
        break;
      }
      final center = (r.key + r.value) * 0.5;
      final dist = (center - probe).abs();
      if (dist < bestScore) {
        bestScore = dist;
        best = r;
      }
    }
    if (best == null) return null;

    final start = (best.key - prePadMs).clamp(clipStart, clipEnd).toDouble();
    final end =
        (best.value + postPadMs).clamp(start + 15.0, clipEnd).toDouble();
    if (end - start < 20.0) return null;
    return MapEntry(start, end);
  }

  List<MapEntry<double, double>> _dialogRangesFromActionDataForClip(
    Map<String, dynamic> data,
    AudioTrack clip, {
    bool preferClipRelative = false,
  }) {
    final target = _actionTarget(data);
    final clipStartMs = _clipTimelineStartMs(clip);
    final clipEndMs = _clipTimelineEndMs(clip);

    bool resolveClipRelative(Map<String, dynamic> source) {
      final explicit = _toActionBool(
        source['clip_relative'] ??
            source['local_ms'] ??
            source['relative_to_clip'],
        fallback: false,
      );
      if (explicit) return true;
      final domain = (source['time_domain'] ??
              source['range_domain'] ??
              source['domain'] ??
              '')
          .toString()
          .trim()
          .toLowerCase();
      if (domain == 'clip' ||
          domain == 'local' ||
          domain == 'clip_local' ||
          domain == 'clip_relative') {
        return true;
      }
      return false;
    }

    final out = <MapEntry<double, double>>[];

    void parseRange(Map<String, dynamic> src) {
      final clipRelative = resolveClipRelative(src);
      double? from = _toActionDouble(
        src['from_ms'] ?? src['start_ms'] ?? src['begin_ms'] ?? src['in_ms'],
      );
      double? to = _toActionDouble(
        src['to_ms'] ?? src['end_ms'] ?? src['out_ms'],
      );
      final length = _toActionDouble(src['length_ms'] ?? src['duration_ms']);
      final at = _toActionDouble(src['at_ms'] ?? src['time_ms']);

      if (from == null && at != null && length != null) {
        from = at;
        to = at + length;
      } else if (to == null && from != null && length != null) {
        to = from + length;
      }
      if (from == null || to == null) return;

      if (clipRelative) {
        from += clipStartMs;
        to += clipStartMs;
      }
      if (!from.isFinite || !to.isFinite) return;
      out.add(MapEntry(from, to));
    }

    final rangeLists = <List?>[
      data['ranges'] as List?,
      target['ranges'] as List?,
      data['regions'] as List?,
      target['regions'] as List?,
      data['segments'] as List?,
      target['segments'] as List?,
    ];
    for (final rawList in rangeLists) {
      if (rawList == null) continue;
      for (final raw in rawList) {
        final m = _toActionMap(raw);
        if (m.isEmpty) continue;
        parseRange(m);
      }
    }

    final topRange = <String, dynamic>{
      ...target,
      ...data,
      if (preferClipRelative) 'clip_relative': true,
    };
    parseRange(topRange);

    return _mergeTimelineRangesMs(
      out,
      minGapMs: 10.0,
      minLengthMs: 18.0,
      minMs: clipStartMs,
      maxMs: clipEndMs,
    );
  }

  Future<List<MapEntry<double, double>>> _detectDialogCoughRangesForClip(
    AudioTrack clip, {
    double thresholdStd = 2.2,
    double minDurationMs = 40.0,
    double maxDurationMs = 650.0,
    double prePadMs = 18.0,
    double postPadMs = 120.0,
    double minHighFreqRatio = 0.42,
    int maxRanges = 12,
  }) async {
    final segment = await _decodeTrimmedClipMono16k(clip);
    if (segment == null) return const <MapEntry<double, double>>[];
    const frameSize = 256;
    const hopSize = 128;
    if (segment.samples.length < frameSize) {
      return const <MapEntry<double, double>>[];
    }

    final low = _lowPassMono(
      segment.samples,
      sampleRate: segment.sampleRate,
      cutoffHz: 900.0,
    );

    final scores = <double>[];
    final hfRatios = <double>[];
    for (int i = 0; i + frameSize <= segment.samples.length; i += hopSize) {
      double absSum = 0.0;
      double hfSum = 0.0;
      for (int j = 0; j < frameSize; j++) {
        final s = segment.samples[i + j];
        absSum += s.abs();
        hfSum += (s - low[i + j]).abs();
      }
      final energy = absSum / frameSize;
      final hfRatio = hfSum / (absSum + 1e-9);
      final score = energy * (0.35 + hfRatio);
      scores.add(score);
      hfRatios.add(hfRatio);
    }
    if (scores.length < 6) return const <MapEntry<double, double>>[];

    double mean = 0.0;
    for (final s in scores) {
      mean += s;
    }
    mean /= scores.length;

    double variance = 0.0;
    for (final s in scores) {
      final d = s - mean;
      variance += d * d;
    }
    variance /= scores.length;
    final std = math.sqrt(math.max(variance, 0.0));
    final threshold = math.max(mean + std * thresholdStd, mean * 2.6);

    final local = <MapEntry<double, double>>[];
    int startFrame = -1;
    for (int i = 0; i < scores.length; i++) {
      final hit = scores[i] >= threshold;
      if (hit && startFrame < 0) {
        startFrame = i;
      }
      final ended = startFrame >= 0 && (!hit || i == scores.length - 1);
      if (!ended) continue;

      final endExclusive = (!hit) ? i : i + 1;
      final segmentStartSample = startFrame * hopSize;
      final segmentEndSample = math.min(
        segment.samples.length,
        (endExclusive - 1) * hopSize + frameSize,
      );
      final durMs =
          (segmentEndSample - segmentStartSample) * 1000.0 / segment.sampleRate;
      if (durMs >= minDurationMs && durMs <= maxDurationMs) {
        double ratioSum = 0.0;
        int count = 0;
        for (int f = startFrame; f < endExclusive; f++) {
          ratioSum += hfRatios[f];
          count++;
        }
        final avgRatio = count > 0 ? ratioSum / count : 0.0;
        if (avgRatio >= minHighFreqRatio) {
          final startMs = segmentStartSample * 1000.0 / segment.sampleRate;
          final endMs = segmentEndSample * 1000.0 / segment.sampleRate;
          local.add(
            MapEntry(
              math.max(0.0, startMs - prePadMs),
              endMs + postPadMs,
            ),
          );
        }
      }
      startFrame = -1;
    }

    if (local.isEmpty) return const <MapEntry<double, double>>[];
    final localDurationMs =
        segment.samples.length * 1000.0 / segment.sampleRate.toDouble();
    final mergedLocal = _mergeTimelineRangesMs(
      local,
      minGapMs: 70.0,
      minLengthMs: minDurationMs,
      minMs: 0.0,
      maxMs: localDurationMs,
    );
    if (mergedLocal.isEmpty) return const <MapEntry<double, double>>[];

    final timeline = mergedLocal
        .take(maxRanges)
        .map((r) => MapEntry(
              segment.timelineStartMs + r.key * segment.timelineMsPerLocalMs,
              segment.timelineStartMs + r.value * segment.timelineMsPerLocalMs,
            ))
        .toList(growable: false);

    return _mergeTimelineRangesMs(
      timeline,
      minGapMs: 80.0,
      minLengthMs: minDurationMs * segment.timelineMsPerLocalMs,
      minMs: segment.timelineStartMs,
      maxMs: segment.timelineEndMs,
    );
  }

  Future<List<MapEntry<double, double>>> _detectDialogQuietRangesForClip(
    AudioTrack clip, {
    double quietRatio = 0.62,
    double minDurationMs = 180.0,
    int maxRanges = 10,
  }) async {
    final segment = await _decodeTrimmedClipMono16k(clip);
    if (segment == null) return const <MapEntry<double, double>>[];

    const frameSize = 320;
    const hopSize = 160;
    final rms = _frameRmsSeries(
      segment.samples,
      frameSize: frameSize,
      hopSize: hopSize,
    );
    if (rms.length < 6) return const <MapEntry<double, double>>[];

    final noiseFloor = _quantile(rms, 0.2);
    final activeThreshold = math.max(0.008, noiseFloor * 2.2);
    final activeMask = rms.map((v) => v >= activeThreshold).toList();
    final activeRms = <double>[];
    for (int i = 0; i < rms.length; i++) {
      if (activeMask[i]) activeRms.add(rms[i]);
    }
    if (activeRms.length < 3) return const <MapEntry<double, double>>[];

    final speechTargetRms = _quantile(activeRms, 0.68);
    final quietThreshold =
        math.max(noiseFloor * 2.0, speechTargetRms * quietRatio);
    final quietMask = List<bool>.generate(
      rms.length,
      (i) => activeMask[i] && rms[i] < quietThreshold,
      growable: false,
    );
    final localRanges = _rangesFromFrameMask(
      quietMask,
      frameSize: frameSize,
      hopSize: hopSize,
      sampleRate: segment.sampleRate,
      totalSamples: segment.samples.length,
      minDurationMs: minDurationMs,
    );
    if (localRanges.isEmpty) return const <MapEntry<double, double>>[];

    final localDurationMs =
        segment.samples.length * 1000.0 / segment.sampleRate.toDouble();
    final mergedLocal = _mergeTimelineRangesMs(
      localRanges,
      minGapMs: 80.0,
      minLengthMs: minDurationMs,
      minMs: 0.0,
      maxMs: localDurationMs,
    );
    if (mergedLocal.isEmpty) return const <MapEntry<double, double>>[];

    final timeline = mergedLocal
        .take(maxRanges)
        .map((r) => MapEntry(
              segment.timelineStartMs + r.key * segment.timelineMsPerLocalMs,
              segment.timelineStartMs + r.value * segment.timelineMsPerLocalMs,
            ))
        .toList(growable: false);

    return _mergeTimelineRangesMs(
      timeline,
      minGapMs: 90.0,
      minLengthMs: minDurationMs * segment.timelineMsPerLocalMs,
      minMs: segment.timelineStartMs,
      maxMs: segment.timelineEndMs,
    );
  }

  Future<List<MapEntry<double, double>>> _detectDialogPauseRemovalRangesForClip(
    AudioTrack clip, {
    double minPauseMs = 260.0,
    double keepPauseMs = 90.0,
    int maxRanges = 14,
  }) async {
    final activeRanges = await _detectDialogActiveSpeechRangesForClip(
      clip,
      minDurationMs: 110.0,
      mergeGapMs: 120.0,
    );
    if (activeRanges.length < 2) return const <MapEntry<double, double>>[];

    final clipStart = _clipTimelineStartMs(clip);
    final clipEnd = _clipTimelineEndMs(clip);
    final out = <MapEntry<double, double>>[];

    for (int i = 1; i < activeRanges.length; i++) {
      final prev = activeRanges[i - 1];
      final next = activeRanges[i];
      final pauseStart = prev.value;
      final pauseEnd = next.key;
      final pauseLength = pauseEnd - pauseStart;
      if (pauseLength < minPauseMs) continue;

      final keep = keepPauseMs.clamp(20.0, pauseLength - 20.0).toDouble();
      if (pauseLength <= keep + 20.0) continue;

      final removeStart =
          (pauseStart + keep * 0.5).clamp(clipStart, clipEnd).toDouble();
      final removeEnd =
          (pauseEnd - keep * 0.5).clamp(removeStart + 15.0, clipEnd).toDouble();
      if (removeEnd - removeStart >= 20.0) {
        out.add(MapEntry(removeStart, removeEnd));
      }
      if (out.length >= maxRanges) break;
    }

    return _mergeTimelineRangesMs(
      out,
      minGapMs: 50.0,
      minLengthMs: 20.0,
      minMs: clipStart,
      maxMs: clipEnd,
    );
  }

  Future<int?> _isolateTimelineRangeAsClipSegment({
    required double fromMs,
    required double toMs,
    required int rowIndex,
    required String filePath,
    int? preferEngineClipId,
  }) async {
    if (!fromMs.isFinite || !toMs.isFinite) return null;
    double safeFrom = math.min(fromMs, toMs);
    double safeTo = math.max(fromMs, toMs);
    if (safeTo - safeFrom < 20.0) return null;

    final midProbeInitial = (safeFrom + safeTo) * 0.5;
    int? targetIdx = _findAudioClipIndexAtTimelineMs(
      midProbeInitial,
      rowIndex: rowIndex,
      filePath: filePath,
      preferEngineClipId: preferEngineClipId,
    );
    if (targetIdx == null) return null;

    final targetClip = _audioTracks[targetIdx];
    final clipStart = _clipTimelineStartMs(targetClip);
    final clipEnd = _clipTimelineEndMs(targetClip);
    safeFrom = safeFrom.clamp(clipStart, clipEnd - 2.0).toDouble();
    safeTo = safeTo.clamp(safeFrom + 2.0, clipEnd).toDouble();
    if (safeTo - safeFrom < 20.0) return null;

    if (safeFrom > clipStart + 1.0) {
      await _handleCutClipAt(targetIdx, safeFrom);
    }

    final midProbe = (safeFrom + safeTo) * 0.5;
    int? midIdx = _findAudioClipIndexAtTimelineMs(
      midProbe,
      rowIndex: rowIndex,
      filePath: filePath,
      preferEngineClipId: preferEngineClipId,
    );
    if (midIdx == null) return null;

    final midClip = _audioTracks[midIdx];
    final midStart = _clipTimelineStartMs(midClip);
    final midEnd = _clipTimelineEndMs(midClip);
    final cutEnd = safeTo.clamp(midStart + 1.0, midEnd).toDouble();
    if (cutEnd < midEnd - 1.0) {
      await _handleCutClipAt(midIdx, cutEnd);
    }

    return _findAudioClipIndexAtTimelineMs(
      midProbe,
      rowIndex: rowIndex,
      filePath: filePath,
      preferEngineClipId: preferEngineClipId,
    );
  }

  Future<bool> _removeTimelineRangeFromClip({
    required double fromMs,
    required double toMs,
    required int rowIndex,
    required String filePath,
    int? preferEngineClipId,
  }) async {
    final isolatedIdx = await _isolateTimelineRangeAsClipSegment(
      fromMs: fromMs,
      toMs: toMs,
      rowIndex: rowIndex,
      filePath: filePath,
      preferEngineClipId: preferEngineClipId,
    );
    if (isolatedIdx == null ||
        isolatedIdx < 0 ||
        isolatedIdx >= _audioTracks.length) {
      return false;
    }
    await _handleDeleteClip(isolatedIdx);
    return true;
  }

  Future<bool> _boostTimelineRangeOnClip({
    required double fromMs,
    required double toMs,
    required int rowIndex,
    required String filePath,
    required double gainMultiplier,
    required double maxGain,
    int? preferEngineClipId,
  }) async {
    final isolatedIdx = await _isolateTimelineRangeAsClipSegment(
      fromMs: fromMs,
      toMs: toMs,
      rowIndex: rowIndex,
      filePath: filePath,
      preferEngineClipId: preferEngineClipId,
    );
    if (isolatedIdx == null ||
        isolatedIdx < 0 ||
        isolatedIdx >= _audioTracks.length) {
      return false;
    }
    final clip = _audioTracks[isolatedIdx];
    final oldGain = clip.gain;
    final nextGain = (oldGain * gainMultiplier).clamp(0.0, maxGain).toDouble();
    if ((nextGain - oldGain).abs() < 0.015) return false;

    await _undoManager.execute(
      SetClipGainAction(
        tracks: _audioTracks,
        originalIndex: isolatedIdx,
        oldGain: oldGain,
        newGain: nextGain,
        applyToState: (target, gain) {
          target.gain = gain;
          if (mounted) setState(() {});
        },
      ),
    );
    return true;
  }

  Future<int> _applyDialogRangeDeletesForClip(
    AudioTrack clip,
    List<MapEntry<double, double>> ranges, {
    int maxEdits = 12,
  }) async {
    if (ranges.isEmpty) return 0;
    final row = clip.rowIndex;
    final filePath = clip.file.path;
    final preferredEngine = clip.engineClipId >= 0 ? clip.engineClipId : null;
    final ordered = List<MapEntry<double, double>>.from(ranges)
      ..sort((a, b) => b.key.compareTo(a.key));

    int applied = 0;
    for (final range in ordered.take(maxEdits)) {
      final ok = await _removeTimelineRangeFromClip(
        fromMs: range.key,
        toMs: range.value,
        rowIndex: row,
        filePath: filePath,
        preferEngineClipId: preferredEngine,
      );
      if (ok) applied++;
    }
    return applied;
  }

  Future<int> _applyDialogLiftForClip(
    AudioTrack clip,
    List<MapEntry<double, double>> ranges, {
    required double gainMultiplier,
    required double maxGain,
    int maxEdits = 8,
  }) async {
    if (ranges.isEmpty) return 0;
    final row = clip.rowIndex;
    final filePath = clip.file.path;
    final preferredEngine = clip.engineClipId >= 0 ? clip.engineClipId : null;
    final ordered = List<MapEntry<double, double>>.from(ranges)
      ..sort((a, b) => b.key.compareTo(a.key));

    int applied = 0;
    for (final range in ordered.take(maxEdits)) {
      final ok = await _boostTimelineRangeOnClip(
        fromMs: range.key,
        toMs: range.value,
        rowIndex: row,
        filePath: filePath,
        preferEngineClipId: preferredEngine,
        gainMultiplier: gainMultiplier,
        maxGain: maxGain,
      );
      if (ok) applied++;
    }
    return applied;
  }

  Future<void> _applyDialogClipEditOperation(
    Map<String, dynamic> data, {
    required String operation,
  }) async {
    final target = _actionTarget(data);
    final clipIndices =
        _resolveClipIndicesFromActionTarget(data, requireAudio: true);
    if (clipIndices.isEmpty) {
      _insertAssistantChatText(
          "I couldn't resolve which audio clip to edit. Select a clip and ask again.");
      return;
    }

    final maxEdits = (_toActionInt(
              data['max_edits'] ?? target['max_edits'] ?? data['max_events'],
            ) ??
            10)
        .clamp(1, 48);
    final anchorMs = (_toActionDouble(
              data['at_ms'] ??
                  target['at_ms'] ??
                  data['time_ms'] ??
                  target['time_ms'],
            ) ??
            _globalAudioClock.inMilliseconds.toDouble())
        .toDouble();

    int deletedSegments = 0;
    int liftedSegments = 0;
    int touchedClips = 0;

    for (final clipIndex in clipIndices) {
      if (clipIndex < 0 || clipIndex >= _audioTracks.length) continue;
      final clip = _audioTracks[clipIndex];
      if (clip.isMidi) continue;

      if (operation == 'dialog_cleanup') {
        final manual = _dialogRangesFromActionDataForClip(
          data,
          clip,
          preferClipRelative: true,
        );
        final detected = await _detectDialogCoughRangesForClip(
          clip,
          thresholdStd: (_toActionDouble(data['artifact_threshold_std'] ??
                      target['artifact_threshold_std'] ??
                      data['transient_threshold_std'] ??
                      target['transient_threshold_std']) ??
                  2.2)
              .clamp(0.8, 4.8)
              .toDouble(),
          minDurationMs: (_toActionDouble(
                      data['min_event_ms'] ?? target['min_event_ms']) ??
                  40.0)
              .clamp(15.0, 1200.0)
              .toDouble(),
          maxDurationMs: (_toActionDouble(
                      data['max_event_ms'] ?? target['max_event_ms']) ??
                  650.0)
              .clamp(80.0, 2500.0)
              .toDouble(),
          minHighFreqRatio: (_toActionDouble(
                      data['min_hf_ratio'] ?? target['min_hf_ratio']) ??
                  0.42)
              .clamp(0.2, 0.9)
              .toDouble(),
          maxRanges: maxEdits,
        );
        final ranges = manual.isNotEmpty ? manual : detected;
        if (ranges.isEmpty) continue;
        final removed = await _applyDialogRangeDeletesForClip(
          clip,
          ranges,
          maxEdits: maxEdits,
        );
        if (removed > 0) {
          deletedSegments += removed;
          touchedClips++;
        }
        continue;
      }

      if (operation == 'dialog_remove_range') {
        var ranges = _dialogRangesFromActionDataForClip(
          data,
          clip,
          preferClipRelative: true,
        );
        if (ranges.isEmpty) {
          final clipStart = _clipTimelineStartMs(clip);
          final clipEnd = _clipTimelineEndMs(clip);
          final inClip = anchorMs >= clipStart && anchorMs <= clipEnd;
          if (!inClip && clipIndices.length > 1) {
            continue;
          }
          final active = await _detectDialogActiveSpeechRangesForClip(clip);
          final phrase = _deriveDialogPhraseRangeAroundAnchor(
            clip,
            active,
            anchorMs,
            prePadMs: (_toActionDouble(data['phrase_pre_pad_ms'] ??
                        target['phrase_pre_pad_ms']) ??
                    35.0)
                .clamp(0.0, 400.0)
                .toDouble(),
            postPadMs: (_toActionDouble(data['phrase_post_pad_ms'] ??
                        target['phrase_post_pad_ms']) ??
                    70.0)
                .clamp(0.0, 500.0)
                .toDouble(),
          );
          if (phrase != null) {
            ranges = <MapEntry<double, double>>[phrase];
          }
        }
        if (ranges.isEmpty) continue;
        final removed = await _applyDialogRangeDeletesForClip(
          clip,
          ranges,
          maxEdits: maxEdits,
        );
        if (removed > 0) {
          deletedSegments += removed;
          touchedClips++;
        }
        continue;
      }

      if (operation == 'dialog_tighten_pauses') {
        final ranges = await _detectDialogPauseRemovalRangesForClip(
          clip,
          minPauseMs: (_toActionDouble(
                      data['min_pause_ms'] ?? target['min_pause_ms']) ??
                  260.0)
              .clamp(80.0, 6000.0)
              .toDouble(),
          keepPauseMs: (_toActionDouble(
                      data['keep_pause_ms'] ?? target['keep_pause_ms']) ??
                  90.0)
              .clamp(20.0, 1400.0)
              .toDouble(),
          maxRanges: maxEdits,
        );
        if (ranges.isEmpty) continue;
        final removed = await _applyDialogRangeDeletesForClip(
          clip,
          ranges,
          maxEdits: maxEdits,
        );
        if (removed > 0) {
          deletedSegments += removed;
          touchedClips++;
        }
        continue;
      }

      if (operation == 'dialog_lift_quiet') {
        var ranges = _dialogRangesFromActionDataForClip(
          data,
          clip,
          preferClipRelative: true,
        );
        if (ranges.isEmpty) {
          ranges = await _detectDialogQuietRangesForClip(
            clip,
            quietRatio: (_toActionDouble(
                        data['quiet_ratio'] ?? target['quiet_ratio']) ??
                    0.62)
                .clamp(0.2, 0.95)
                .toDouble(),
            minDurationMs: (_toActionDouble(
                        data['min_quiet_ms'] ?? target['min_quiet_ms']) ??
                    180.0)
                .clamp(40.0, 3000.0)
                .toDouble(),
            maxRanges: maxEdits,
          );
        }
        if (ranges.isEmpty) continue;

        final boostDb = (_toActionDouble(
                  data['boost_db'] ??
                      target['boost_db'] ??
                      data['gain_db'] ??
                      target['gain_db'],
                ) ??
                4.0)
            .clamp(0.5, 12.0)
            .toDouble();
        final gainMultiplier = math.pow(10.0, boostDb / 20.0).toDouble();
        final maxGain =
            (_toActionDouble(data['max_gain'] ?? target['max_gain']) ?? 3.0)
                .clamp(0.2, 3.0)
                .toDouble();

        final lifted = await _applyDialogLiftForClip(
          clip,
          ranges,
          gainMultiplier: gainMultiplier,
          maxGain: maxGain,
          maxEdits: maxEdits,
        );
        if (lifted > 0) {
          liftedSegments += lifted;
          touchedClips++;
        }
      }
    }

    final totalEdits = deletedSegments + liftedSegments;
    if (totalEdits <= 0) {
      switch (operation) {
        case 'dialog_cleanup':
          _insertAssistantChatText(
              'No clear cough/noise events were detected in the target clip.');
          break;
        case 'dialog_remove_range':
          _insertAssistantChatText(
              "I couldn't resolve a dialog segment to remove. Provide a time range or place the playhead near the sentence.");
          break;
        case 'dialog_tighten_pauses':
          _insertAssistantChatText('No long pauses were found to tighten.');
          break;
        case 'dialog_lift_quiet':
          _insertAssistantChatText(
              'No quiet speech ranges were found to lift.');
          break;
        default:
          break;
      }
      return;
    }

    if (operation == 'dialog_lift_quiet' && liftedSegments > 0) {
      _showSmallNotice(
          'Boosted $liftedSegments quiet segment${liftedSegments == 1 ? '' : 's'} on $touchedClips clip${touchedClips == 1 ? '' : 's'}.');
      return;
    }

    _showSmallNotice(
        'Edited $deletedSegments dialog segment${deletedSegments == 1 ? '' : 's'} on $touchedClips clip${touchedClips == 1 ? '' : 's'}.');
  }

  Future<void> _applyClipEditAction(Map<String, dynamic> data) async {
    final rawOperation =
        (data['operation'] ?? '').toString().trim().toLowerCase();
    final operation = _normalizeClipEditOperation(
      rawOperation,
    );

    if (operation == 'auto_bpm_align') {
      await _applyAutoBpmAlignAction(data);
      return;
    }

    if (operation == 'auto_trim') {
      final clipIndices =
          _resolveClipIndicesFromActionTarget(data, requireAudio: true);
      if (clipIndices.isEmpty) {
        _insertAssistantChatText(
            "I couldn't resolve which audio clips to trim. Select clips and ask again.");
        return;
      }

      final thresholdFloor =
          _toActionDouble(data['threshold_floor'])?.clamp(0.001, 1.0) ?? 0.012;
      final thresholdRatio =
          _toActionDouble(data['threshold_ratio'])?.clamp(0.001, 1.0) ?? 0.08;
      final paddingMs =
          _toActionDouble(data['padding_ms'])?.clamp(0.0, 500.0) ?? 8.0;
      final preserveContentPosition =
          _toActionBool(data['preserve_content_position'], fallback: true);

      bool anyApplied = false;
      for (final clipIndex in clipIndices) {
        if (clipIndex < 0 || clipIndex >= _audioTracks.length) continue;
        final clip = _audioTracks[clipIndex];
        if (clip.isMidi) continue;

        final explicitTrimStartMs = _toActionDouble(data['trim_start_ms']);
        final explicitTrimEndMs = _toActionDouble(data['trim_end_ms']);
        final estimated = _estimateAutoTrimBoundsMs(
          clip,
          thresholdFloor: thresholdFloor.toDouble(),
          thresholdRatio: thresholdRatio.toDouble(),
          paddingMs: paddingMs.toDouble(),
        );

        final nextTrimStartMs = explicitTrimStartMs ?? estimated?.key;
        final nextTrimEndMs = explicitTrimEndMs ?? estimated?.value;
        if (nextTrimStartMs == null || nextTrimEndMs == null) continue;

        final startDeltaSec =
            (nextTrimStartMs - clip.trimStart.inMilliseconds.toDouble()) /
                1000.0;
        final nextOffset = preserveContentPosition
            ? math.max(0.0, clip.offset + startDeltaSec)
            : null;

        await _applyTrimActionForClip(
          clipIndex,
          newTrimStartMs: nextTrimStartMs,
          newTrimEndMs: nextTrimEndMs,
          newOffsetSec: nextOffset,
        );
        anyApplied = true;
      }

      if (!anyApplied) {
        _insertAssistantChatText(
            'No silence boundaries were detected for the target clip(s).');
      }
      return;
    }

    if (operation == 'trim') {
      final target = _actionTarget(data);
      final clipIndices =
          _resolveClipIndicesFromActionTarget(data, requireAudio: true);
      if (clipIndices.isEmpty) {
        _insertAssistantChatText(
            "I couldn't resolve which audio clips to trim. Select clips and ask again.");
        return;
      }

      final explicitTrimStartMs =
          _toActionDouble(data['trim_start_ms'] ?? target['trim_start_ms']);
      final explicitTrimEndMs =
          _toActionDouble(data['trim_end_ms'] ?? target['trim_end_ms']);
      final deltaTrimStartMs = _toActionDouble(
          data['delta_trim_start_ms'] ?? target['delta_trim_start_ms']);
      final deltaTrimEndMs = _toActionDouble(
          data['delta_trim_end_ms'] ?? target['delta_trim_end_ms']);
      final hasExplicitTrimValues = explicitTrimStartMs != null ||
          explicitTrimEndMs != null ||
          deltaTrimStartMs != null ||
          deltaTrimEndMs != null;

      final sideHint = (data['trim_side'] ??
              target['trim_side'] ??
              data['side'] ??
              target['side'] ??
              data['edge'] ??
              target['edge'] ??
              '')
          .toString()
          .trim()
          .toLowerCase();
      final trimStartOnlyHint = sideHint.contains('start') ||
          sideHint.contains('left') ||
          sideHint == 'in' ||
          sideHint == 'head' ||
          sideHint.contains('begin');
      final trimEndOnlyHint = sideHint.contains('end') ||
          sideHint.contains('right') ||
          sideHint == 'out' ||
          sideHint == 'tail';

      final thresholdFloor = _toActionDouble(
            data['threshold_floor'] ?? target['threshold_floor'],
          )?.clamp(0.001, 1.0) ??
          0.012;
      final thresholdRatio = _toActionDouble(
            data['threshold_ratio'] ?? target['threshold_ratio'],
          )?.clamp(0.001, 1.0) ??
          0.08;
      final paddingMs =
          _toActionDouble(data['padding_ms'] ?? target['padding_ms'])
                  ?.clamp(0.0, 500.0) ??
              8.0;
      final preserveContentPosition = _toActionBool(
        data['preserve_content_position'] ??
            target['preserve_content_position'],
        fallback: true,
      );
      final fallbackTrimNudgeMs = (_toActionDouble(
                  data['fallback_trim_ms'] ?? target['fallback_trim_ms']) ??
              120.0)
          .clamp(10.0, 2000.0)
          .toDouble();

      bool anyApplied = false;
      for (final clipIndex in clipIndices) {
        if (clipIndex < 0 || clipIndex >= _audioTracks.length) continue;
        final clip = _audioTracks[clipIndex];
        if (clip.isMidi) continue;

        final oldTrimStartMs = clip.trimStart.inMilliseconds.toDouble();
        final oldTrimEndMs = clip.trimEnd.inMilliseconds.toDouble();
        double? nextTrimStartMs = explicitTrimStartMs;
        double? nextTrimEndMs = explicitTrimEndMs;

        if (nextTrimStartMs == null && deltaTrimStartMs != null) {
          nextTrimStartMs = oldTrimStartMs + deltaTrimStartMs;
        }
        if (nextTrimEndMs == null && deltaTrimEndMs != null) {
          nextTrimEndMs = oldTrimEndMs + deltaTrimEndMs;
        }

        if (!hasExplicitTrimValues &&
            nextTrimStartMs == null &&
            nextTrimEndMs == null) {
          final estimated = _estimateAutoTrimBoundsMs(
            clip,
            thresholdFloor: thresholdFloor.toDouble(),
            thresholdRatio: thresholdRatio.toDouble(),
            paddingMs: paddingMs.toDouble(),
          );
          if (estimated != null) {
            if (trimEndOnlyHint && !trimStartOnlyHint) {
              nextTrimEndMs = estimated.value;
            } else if (trimStartOnlyHint && !trimEndOnlyHint) {
              nextTrimStartMs = estimated.key;
            } else {
              nextTrimStartMs = estimated.key;
              nextTrimEndMs = estimated.value;
            }
          }
        }

        nextTrimStartMs ??= oldTrimStartMs;
        nextTrimEndMs ??= oldTrimEndMs;

        if ((nextTrimStartMs - oldTrimStartMs).abs() < 0.5 &&
            (nextTrimEndMs - oldTrimEndMs).abs() < 0.5) {
          if (trimEndOnlyHint && !trimStartOnlyHint) {
            nextTrimEndMs = oldTrimEndMs - fallbackTrimNudgeMs;
          } else {
            nextTrimStartMs = oldTrimStartMs + fallbackTrimNudgeMs;
          }
        }

        if ((nextTrimStartMs - oldTrimStartMs).abs() < 0.5 &&
            (nextTrimEndMs - oldTrimEndMs).abs() < 0.5) {
          continue;
        }

        final explicitNewStartMs = _toActionDouble(
          data['new_start_ms'] ??
              target['new_start_ms'] ??
              data['start_ms'] ??
              target['start_ms'],
        );
        final startDeltaSec = (nextTrimStartMs - oldTrimStartMs) / 1000.0;
        final newOffsetSec = explicitNewStartMs != null
            ? math.max(0.0, explicitNewStartMs / 1000.0)
            : (preserveContentPosition
                ? math.max(0.0, clip.offset + startDeltaSec)
                : null);

        await _applyTrimActionForClip(
          clipIndex,
          newTrimStartMs: nextTrimStartMs,
          newTrimEndMs: nextTrimEndMs,
          newOffsetSec: newOffsetSec,
        );
        anyApplied = true;
      }

      if (!anyApplied) {
        _insertAssistantChatText(
            'Could not trim the target clip(s). Try selecting the clip and asking again.');
      } else {
        _showSmallNotice(
            'Trimmed ${clipIndices.length} clip${clipIndices.length == 1 ? '' : 's'}.');
      }
      return;
    }

    if (operation == 'dialog_cleanup' ||
        operation == 'dialog_remove_range' ||
        operation == 'dialog_tighten_pauses' ||
        operation == 'dialog_lift_quiet') {
      await _applyDialogClipEditOperation(
        data,
        operation: operation,
      );
      return;
    }

    int? resolveSingleClipIndex({
      bool requireAudio = false,
      bool requireMidi = false,
      String failureMessage =
          "I couldn't resolve which clip to edit. Select a clip and ask again.",
    }) {
      final idx = _resolveSingleClipIndexWithFallback(
        data,
        requireAudio: requireAudio,
        requireMidi: requireMidi,
      );
      if (idx == null) {
        _insertAssistantChatText(failureMessage);
        return null;
      }
      if (idx < 0 || idx >= _audioTracks.length) return null;
      return idx;
    }

    switch (operation) {
      case 'cut':
        {
          final target = _actionTarget(data);
          final scope = (target['scope'] ?? data['scope'] ?? '')
              .toString()
              .trim()
              .toLowerCase();
          final fromMs = _toActionDouble(data['from_ms'] ?? target['from_ms']);
          final toMs = _toActionDouble(data['to_ms'] ?? target['to_ms']);
          final rawRanges = data['ranges'] ?? target['ranges'];
          final hasExplicitRangePayload = (fromMs != null && toMs != null) ||
              (rawRanges is List &&
                  rawRanges.any((raw) {
                    if (raw is! Map) return false;
                    final range = Map<String, dynamic>.from(raw);
                    return _toActionDouble(range['from_ms']) != null &&
                        _toActionDouble(range['to_ms']) != null;
                  }));
          if (scope == 'all' ||
              scope == 'all_audio' ||
              scope == 'all_selected_audio' ||
              hasExplicitRangePayload) {
            _showSmallNotice('Skipped unsupported cut action.');
            break;
          }
          final clipIndex = resolveSingleClipIndex(
            failureMessage:
                "I couldn't resolve which clip to cut. Select a clip and ask again.",
          );
          if (clipIndex == null) return;
          final clip = _audioTracks[clipIndex];
          final hasMidiChopHint = (rawOperation.contains('note') ||
                  rawOperation.contains('chop') ||
                  rawOperation.contains('splice') ||
                  rawOperation.contains('slice')) ||
              data.containsKey('subdivision') ||
              data.containsKey('subdivision_divisor') ||
              data.containsKey('grid') ||
              data.containsKey('resolution') ||
              target.containsKey('subdivision') ||
              target.containsKey('subdivision_divisor') ||
              target.containsKey('grid') ||
              target.containsKey('resolution');
          if (clip.isMidi && hasMidiChopHint) {
            final midiActionData = <String, dynamic>{
              ...data,
              'operation': 'chop_notes',
              'target': <String, dynamic>{
                ...target,
                'clip_index': clipIndex,
              },
            };
            await _applyMidiComposeAction(midiActionData);
            break;
          }
          final startMs = clip.offset * 1000.0;
          final endMs = startMs + _clipTimelineDurationMs(clip);
          final cutMs = _toActionDouble(data['cut_ms'] ?? data['time_ms']) ??
              ((startMs + endMs) / 2.0);
          await _handleCutClipAt(clipIndex, cutMs);
          _showSmallNotice('Cut clip.');
          break;
        }
      case 'move':
        {
          final target = _actionTarget(data);

          int? clampRow(int? row) {
            if (row == null || _rowCount <= 0) return null;
            return row.clamp(0, _rowCount - 1);
          }

          final explicitStartMs =
              AssistantActionUtils.resolveMoveMusicalStartMs(
                    data: data,
                    target: target,
                    bpm: _tempo,
                  ) ??
                  _toActionDouble(
                    data['new_start_ms'] ??
                        target['new_start_ms'] ??
                        data['start_ms'] ??
                        target['start_ms'],
                  );
          final explicitDeltaMs =
              AssistantActionUtils.resolveMoveMusicalDeltaMs(
                    data: data,
                    target: target,
                    bpm: _tempo,
                  ) ??
                  _toActionDouble(
                    data['delta_ms'] ??
                        target['delta_ms'] ??
                        data['offset_ms'] ??
                        target['offset_ms'] ??
                        data['shift_ms'] ??
                        target['shift_ms'],
                  );
          final explicitDestRow = clampRow(
            _toActionInt(
              data['new_row_index'] ??
                  target['new_row_index'] ??
                  data['destination_row_index'] ??
                  target['destination_row_index'] ??
                  data['to_row_index'] ??
                  target['to_row_index'],
            ),
          );
          final explicitRowHint = clampRow(
            _toActionInt(data['row_index']) ??
                _toActionInt(target['row_index']),
          );
          final explicitRowDelta = _toActionInt(
                data['delta_rows'] ??
                    target['delta_rows'] ??
                    data['row_delta'] ??
                    target['row_delta'],
              ) ??
              0;
          final direction = (data['direction'] ?? target['direction'] ?? '')
              .toString()
              .trim()
              .toLowerCase();
          final snapTo = (data['snap_to'] ??
                  target['snap_to'] ??
                  data['position'] ??
                  target['position'] ??
                  '')
              .toString()
              .trim()
              .toLowerCase();

          double moveStepMs = (_toActionDouble(
                    data['step_ms'] ??
                        target['step_ms'] ??
                        data['distance_ms'] ??
                        target['distance_ms'] ??
                        data['amount_ms'] ??
                        target['amount_ms'],
                  ) ??
                  0.0)
              .abs();
          if (moveStepMs < 1.0) {
            moveStepMs = (60000.0 / _tempo.clamp(1.0, 400.0))
                .clamp(1.0, 60000.0)
                .toDouble();
          }

          int directionRowDelta = 0;
          double directionStartDeltaMs = 0.0;
          bool moveToStart = snapTo.contains('start') ||
              snapTo.contains('begin') ||
              snapTo == 'zero';
          switch (direction) {
            case 'left':
            case 'earlier':
            case 'back':
            case 'backward':
              directionStartDeltaMs = -moveStepMs;
              break;
            case 'right':
            case 'later':
            case 'forward':
              directionStartDeltaMs = moveStepMs;
              break;
            case 'up':
            case 'above':
              directionRowDelta = -1;
              break;
            case 'down':
            case 'below':
              directionRowDelta = 1;
              break;
            case 'start':
            case 'beginning':
            case 'zero':
              moveToStart = true;
              break;
            default:
              break;
          }

          List<int> clipIndices = _resolveClipIndicesFromActionTarget(data);
          if (clipIndices.isEmpty && moveToStart) {
            clipIndices = List<int>.generate(
              _audioTracks.length,
              (index) => index,
              growable: false,
            );
          }
          if (clipIndices.isEmpty) {
            _insertAssistantChatText(
                "I couldn't resolve which clips to move. Please ask again with a track name if you want a specific target.");
            return;
          }

          final hasHorizontalInstruction = explicitStartMs != null ||
              explicitDeltaMs != null ||
              directionStartDeltaMs != 0.0 ||
              moveToStart;
          final hasVerticalInstruction = explicitDestRow != null ||
              explicitRowDelta != 0 ||
              directionRowDelta != 0;

          if (!hasHorizontalInstruction && !hasVerticalInstruction) {
            _showSmallNotice('Skipped incomplete move action.');
            break;
          }

          bool anyApplied = false;
          for (final clipIndex in clipIndices) {
            if (clipIndex < 0 || clipIndex >= _audioTracks.length) continue;
            final clip = _audioTracks[clipIndex];
            final oldStartMs = clip.offset * 1000.0;
            final oldRow = clip.rowIndex;

            double nextStartMs = oldStartMs;
            if (explicitStartMs != null) {
              nextStartMs = explicitStartMs;
            } else if (explicitDeltaMs != null) {
              nextStartMs = oldStartMs + explicitDeltaMs;
            } else if (directionStartDeltaMs != 0.0) {
              nextStartMs = oldStartMs + directionStartDeltaMs;
            } else if (moveToStart) {
              nextStartMs = 0.0;
            }
            nextStartMs = math.max(0.0, nextStartMs);

            int nextRow = oldRow;
            if (explicitDestRow != null) {
              nextRow = explicitDestRow;
            } else if (directionRowDelta != 0) {
              nextRow = clampRow(oldRow + directionRowDelta) ?? oldRow;
            } else if (explicitRowDelta != 0) {
              nextRow = clampRow(oldRow + explicitRowDelta) ?? oldRow;
            } else if (clipIndices.length == 1 &&
                explicitRowHint != null &&
                explicitRowHint != oldRow) {
              // If there is a single target clip, treat row_index as destination
              // when no other row destination signal exists.
              nextRow = explicitRowHint;
            }

            final rowChanged = nextRow != oldRow;
            final startChanged = (nextStartMs - oldStartMs).abs() > 0.5;
            if (!rowChanged && !startChanged) continue;

            await _undoManager.execute(
              MoveClipAction(
                tracks: _audioTracks,
                originalIndex: clipIndex,
                oldOffset: clip.offset,
                oldRow: clip.rowIndex,
                newOffset: nextStartMs / 1000.0,
                newRow: nextRow,
                onChange: () {
                  clip.rowId = _rowIdAt(clip.rowIndex);
                  unawaited(_syncClipTimingToEngine(clipIndex));
                  _updateOverallDurationIfNeeded();
                },
              ),
            );
            anyApplied = true;
          }

          if (!anyApplied) {
            _showSmallNotice('Move made no changes.');
            break;
          }

          if (mounted) setState(() {});
          _showSmallNotice(
            'Moved ${clipIndices.length} clip${clipIndices.length == 1 ? '' : 's'}.',
          );
          break;
        }
      case 'stretch':
        {
          final clipIndex = resolveSingleClipIndex();
          if (clipIndex == null) return;
          final clip = _audioTracks[clipIndex];
          final target = _actionTarget(data);
          final explicitDurationMs = _toActionDouble(
            data['timeline_duration_ms'] ??
                data['duration_ms'] ??
                target['timeline_duration_ms'] ??
                target['duration_ms'] ??
                data['new_duration_ms'] ??
                target['new_duration_ms'],
          );
          final deltaDurationMs = _toActionDouble(
            data['delta_duration_ms'] ??
                target['delta_duration_ms'] ??
                data['duration_delta_ms'] ??
                target['duration_delta_ms'],
          );
          final factor = _toActionDouble(
            data['factor'] ??
                target['factor'] ??
                data['stretch_factor'] ??
                target['stretch_factor'] ??
                data['scale'] ??
                target['scale'],
          );
          final oldDurationMs = _clipTimelineDurationMs(clip);
          final durationMs = explicitDurationMs ??
              ((deltaDurationMs != null)
                  ? (oldDurationMs + deltaDurationMs)
                  : ((factor != null) ? (oldDurationMs * factor) : null));
          if (durationMs == null || clip.isMidi) {
            _insertAssistantChatText(
                "I couldn't resolve the new clip length to stretch.");
            return;
          }
          final newStartMs =
              _toActionDouble(data['new_start_ms'] ?? data['start_ms']);
          _handleStretchClipResize(
            clipIndex,
            durationMs,
            newStartMs: newStartMs,
          );
          await _handleStretchClipResizeCommit(clipIndex);
          _showSmallNotice('Stretched clip.');
          break;
        }
      case 'tempo_follow':
        {
          final targets =
              _resolveClipIndicesFromActionTarget(data, requireAudio: true);
          if (targets.isEmpty) {
            _insertAssistantChatText(
                "I couldn't resolve which audio clips to tempo-align.");
            return;
          }
          final preservePitch =
              _toActionBool(data['preserve_pitch'], fallback: true);
          for (final idx in targets) {
            await _setClipTempoFollowMode(
              idx,
              preservePitch: preservePitch,
              showFeedback: false,
            );
          }
          _showSmallNotice(
              'Tempo mode updated for ${targets.length} clip${targets.length == 1 ? '' : 's'}.');
          break;
        }
      case 'tempo_detect_set_project':
        {
          final clipIndex = resolveSingleClipIndex(requireAudio: true);
          if (clipIndex == null) return;
          final clip = _audioTracks[clipIndex];
          if (clip.isMidi) return;
          await _setProjectTempoFromDetectedClip(clipIndex);
          final preservePitch =
              _toActionBool(data['preserve_pitch'], fallback: true);
          await _setClipTempoFollowMode(
            clipIndex,
            preservePitch: preservePitch,
          );
          _showSmallNotice('Detected clip tempo and updated project tempo.');
          break;
        }
      case 'delete':
        {
          final clipIndices = _resolveClipIndicesFromActionTarget(data);
          if (clipIndices.isEmpty) {
            final clipIndex = resolveSingleClipIndex();
            if (clipIndex == null) return;
            await _handleDeleteClip(clipIndex);
            _showSmallNotice('Deleted clip.');
            break;
          }
          await _handleDeleteClips(clipIndices);
          _showSmallNotice(
              'Deleted ${clipIndices.length} clip${clipIndices.length == 1 ? '' : 's'}.');
        }
        break;
      case 'duplicate':
        {
          var clipIndices = _resolveClipIndicesFromActionTarget(data);
          if (clipIndices.isEmpty) {
            final clipIndex = resolveSingleClipIndex();
            if (clipIndex == null) return;
            clipIndices = <int>[clipIndex];
          }
          final validClipIndices = clipIndices
              .where((i) => i >= 0 && i < _audioTracks.length)
              .toSet()
              .toList(growable: false);
          if (validClipIndices.isEmpty) {
            _insertAssistantChatText(
                "I couldn't resolve which clips to duplicate.");
            return;
          }
          final sourceClips = validClipIndices
              .map((i) => _audioTracks[i])
              .toList(growable: false)
            ..sort((a, b) {
              final byOffset = a.offset.compareTo(b.offset);
              if (byOffset != 0) return byOffset;
              final byRow = a.rowIndex.compareTo(b.rowIndex);
              if (byRow != 0) return byRow;
              return a.engineClipId.compareTo(b.engineClipId);
            });
          final anchorClip = sourceClips.first;
          final anchorStartMs =
              sourceClips.map((clip) => clip.offset * 1000.0).reduce(math.min);
          final groupEndMs = sourceClips
              .map((clip) => _clipTimelineEndMs(clip))
              .reduce(math.max);
          final groupLengthMs =
              math.max(1.0, groupEndMs - anchorStartMs).toDouble();
          final target = _actionTarget(data);
          final baseRow = _resolveRowIndexFromActionTarget(
                data,
                fallbackClipIndex: validClipIndices.first,
              ) ??
              anchorClip.rowIndex;
          final rowStep = _toActionInt(
                data['delta_rows'] ??
                    target['delta_rows'] ??
                    data['row_delta'] ??
                    target['row_delta'] ??
                    data['step_rows'] ??
                    target['step_rows'],
              ) ??
              0;
          final firstPasteMs = AssistantActionUtils.resolveMoveMusicalStartMs(
                data: data,
                target: target,
                bpm: _tempo,
              ) ??
              _toActionDouble(
                data['paste_start_ms'] ??
                    target['paste_start_ms'] ??
                    data['start_ms'] ??
                    target['start_ms'],
              ) ??
              groupEndMs;
          final stepMs = AssistantActionUtils.resolveMoveMusicalDeltaMs(
                data: data,
                target: target,
                bpm: _tempo,
              ) ??
              _toActionDouble(
                data['step_ms'] ??
                    target['step_ms'] ??
                    data['spacing_ms'] ??
                    target['spacing_ms'],
              ) ??
              groupLengthMs;
          final repeatCount = AssistantActionUtils.resolvePlacementRepeatCount(
            data: data,
            target: target,
            bpm: _tempo,
            startMs: firstPasteMs,
            stepMs: stepMs,
          );
          final duplicateCount = validClipIndices.length * repeatCount;
          if (_audioTracks.length + duplicateCount > kNumClips) {
            ScaffoldMessenger.of(context).showSnackBar(SnackBar(
                content: Text(
                    "Max number of audio clips reached ($kNumClips). Unable to add more clips.")));
            return;
          }

          final actions = <EditorUndoAction>[];
          for (int copyIndex = 0; copyIndex < repeatCount; copyIndex++) {
            final groupStartMs = math.max(
              0.0,
              firstPasteMs + (stepMs * copyIndex),
            );
            for (final clip in sourceClips) {
              final offsetDeltaMs = (clip.offset * 1000.0) - anchorStartMs;
              final rowDelta = clip.rowIndex - anchorClip.rowIndex;
              final pasteRow = _rowCount > 0
                  ? (baseRow + rowDelta + (rowStep * copyIndex))
                      .clamp(0, _rowCount - 1)
                  : math.max(0, baseRow + rowDelta + (rowStep * copyIndex));
              final pasteMs = math.max(0.0, groupStartMs + offsetDeltaMs);
              actions.add(
                _buildPasteAction(
                  clip: clip,
                  row: pasteRow,
                  timeMs: pasteMs,
                  trimStart: clip.trimStart,
                  trimEnd: clip.trimEnd,
                ),
              );
            }
          }

          if (actions.length == 1) {
            await _undoManager.execute(actions.first);
          } else {
            await _undoManager.execute(
              CompoundUndoAction(
                sourceClips.length == 1 ? 'Duplicate clip' : 'Duplicate clips',
                actions,
              ),
            );
          }
          _showSmallNotice(
            sourceClips.length == 1
                ? (repeatCount == 1
                    ? 'Duplicated clip.'
                    : 'Duplicated clip $repeatCount times.')
                : (repeatCount == 1
                    ? 'Duplicated ${sourceClips.length} clips.'
                    : 'Duplicated ${sourceClips.length} clips $repeatCount times.'),
          );
          break;
        }
      default:
        _insertAssistantChatText(
            'Unsupported clip edit operation "$operation".');
        break;
    }
  }

  Future<void> _applyProjectEditAction(Map<String, dynamic> data) async {
    final target = _actionTarget(data);
    final operation = (data['operation'] ?? '').toString().trim().toLowerCase();
    switch (operation) {
      case 'set_tempo':
        final rawTempo = _toActionDouble(
          data['tempo_bpm'] ??
              target['tempo_bpm'] ??
              data['bpm'] ??
              target['bpm'],
        );
        if (rawTempo == null || !rawTempo.isFinite || rawTempo <= 0.0) {
          _insertAssistantChatText(
              "I couldn't resolve the target project tempo.");
          return;
        }
        final nextTempo = _clampTempo(rawTempo);
        await _applyProjectTempoChange(nextTempo);
        _showSmallNotice('Project tempo set to ${nextTempo.round()} BPM.');
        return;
      default:
        _insertAssistantChatText(
            'Unsupported project edit operation "$operation".');
        return;
    }
  }

  int _estimateAiSampleInsertWorkUnits(
    String operation,
    List<Map<String, dynamic>> itemMaps,
  ) {
    var total = 0;
    for (final item in itemMaps) {
      final target = _actionTarget(item);
      if (operation == 'replace_audio_clips') {
        final targetClipIndices =
            _resolveClipIndicesFromActionTarget(item, requireAudio: true);
        total += math.max(1, targetClipIndices.length);
        continue;
      }
      final libraryPath = (item['library_path'] ??
              target['library_path'] ??
              item['asset_path'] ??
              target['asset_path'])
          .toString()
          .trim();
      final explicitStartMs = AssistantActionUtils.resolveMoveMusicalStartMs(
        data: item,
        target: target,
        bpm: _tempo,
      );
      final repeatCountHint = _toActionInt(
            item['repeat_count'] ??
                target['repeat_count'] ??
                item['copies'] ??
                target['copies'] ??
                item['count'] ??
                target['count'],
          ) ??
          1;
      final baseTimeMs = explicitStartMs ??
          _toActionDouble(item['start_ms'] ?? target['start_ms']) ??
          AssistantActionUtils.defaultSampleInsertStartMs(
            libraryPath,
            bpm: _tempo,
          );
      final stepMs = AssistantActionUtils.resolveMoveMusicalDeltaMs(
            data: item,
            target: target,
            bpm: _tempo,
          ) ??
          _toActionDouble(
            item['step_ms'] ??
                target['step_ms'] ??
                item['spacing_ms'] ??
                target['spacing_ms'],
          ) ??
          AssistantActionUtils.defaultSampleInsertStepMs(
            libraryPath,
            bpm: _tempo,
            repeatCount: repeatCountHint,
          ) ??
          0.0;
      final resolvedStartMs =
          baseTimeMs ?? _globalAudioClock.inMilliseconds.toDouble();
      total += AssistantActionUtils.resolvePlacementRepeatCount(
        data: item,
        target: target,
        bpm: _tempo,
        startMs: resolvedStartMs,
        stepMs: stepMs,
        preferSpanCoverageOverExplicitCount: true,
      );
    }
    return math.max(1, total);
  }

  Future<void> _applySampleInsertAction(Map<String, dynamic> data) async {
    final operation = (data['operation'] ?? '').toString().trim().toLowerCase();
    if (operation != 'insert_audio_clips' &&
        operation != 'insert_audio_clip' &&
        operation != 'replace_audio_clips') {
      _insertAssistantChatText(
          'Unsupported sample insert operation "$operation".');
      return;
    }

    final rawItems = data['items'];
    final itemMaps = <Map<String, dynamic>>[];
    if (rawItems is List && rawItems.isNotEmpty) {
      for (final raw in rawItems) {
        final item = _toActionMap(raw);
        if (item.isNotEmpty) itemMaps.add(item);
      }
    } else {
      itemMaps.add(data);
    }

    if (itemMaps.isEmpty) {
      _insertAssistantChatText(
          "I couldn't resolve which library samples to insert.");
      return;
    }

    int inserted = 0;
    int replaced = 0;
    int failed = 0;
    var processedUnits = 0;
    var batchCancelled = false;
    final insertedEngineClipIds = LinkedHashSet<int>();
    final totalUnits = _estimateAiSampleInsertWorkUnits(operation, itemMaps);
    final showBatchOverlay = totalUnits > 1;
    if (showBatchOverlay) {
      _beginAiBatchProcessingOverlay(
        totalUnits: totalUnits,
        title: 'Processing Samples',
        message: 'Adding samples to your project.',
      );
    }
    try {
      for (int i = 0; i < itemMaps.length; i++) {
        if (_cancelAiBatchProcessingRequested) break;
        final itemUnitsBefore = processedUnits;
        try {
          final item = itemMaps[i];
          final target = _actionTarget(item);
          final libraryPath = (item['library_path'] ??
                  target['library_path'] ??
                  item['asset_path'] ??
                  target['asset_path'])
              .toString()
              .trim();
          var resolvedPath = await _resolveAiLibrarySamplePath(libraryPath);
          if (resolvedPath == null) {
            final directFilePath =
                (item['file_path'] ?? target['file_path']).toString().trim();
            if (directFilePath.isNotEmpty &&
                _isSampleAudioFile(directFilePath) &&
                File(directFilePath).existsSync()) {
              resolvedPath = directFilePath;
            }
          }
          if (resolvedPath == null) {
            failed++;
            processedUnits += 1;
            if (showBatchOverlay) {
              _updateAiBatchProcessingOverlay(
                completedUnits: processedUnits,
                message: 'Skipping an unavailable sample.',
              );
            }
            continue;
          }

          if (operation == 'replace_audio_clips') {
            final targetClipIndices =
                _resolveClipIndicesFromActionTarget(item, requireAudio: true);
            if (targetClipIndices.isEmpty) {
              failed++;
              processedUnits += 1;
              if (showBatchOverlay) {
                _updateAiBatchProcessingOverlay(
                  completedUnits: processedUnits,
                  message: 'Skipping an unresolved target.',
                );
              }
              continue;
            }
            final targetClips = targetClipIndices
                .where((idx) => idx >= 0 && idx < _audioTracks.length)
                .map((idx) => _audioTracks[idx])
                .where((clip) => !clip.isMidi)
                .toList(growable: false);
            if (targetClips.isEmpty) {
              failed++;
              continue;
            }

            final successfulTargetIndices = <int>[];
            for (final clipIndex in targetClipIndices) {
              if (_cancelAiBatchProcessingRequested) break;
              if (clipIndex < 0 || clipIndex >= _audioTracks.length) {
                failed++;
                processedUnits += 1;
                if (showBatchOverlay) {
                  _updateAiBatchProcessingOverlay(
                    completedUnits: processedUnits,
                    message: 'Skipping an invalid target.',
                  );
                }
                continue;
              }
              final clip = _audioTracks[clipIndex];
              if (clip.isMidi) {
                failed++;
                processedUnits += 1;
                if (showBatchOverlay) {
                  _updateAiBatchProcessingOverlay(
                    completedUnits: processedUnits,
                    message: 'Skipping a MIDI target.',
                  );
                }
                continue;
              }
              final inserted = await _insertAudioFileAtTimeline(
                resolvedPath,
                row: clip.rowIndex,
                timeMs: _clipTimelineStartMs(clip),
                enforceKnownAudioExtension: false,
                uploadMethod: 'ai_library',
                showLoadingOverlay: !showBatchOverlay,
              );
              processedUnits += 1;
              if (showBatchOverlay) {
                _updateAiBatchProcessingOverlay(
                  completedUnits: processedUnits,
                  message: 'Replacing samples in your project.',
                );
              }
              if (inserted) {
                if (_audioTracks.isNotEmpty) {
                  final insertedClip = _audioTracks.last;
                  if (insertedClip.engineClipId >= 0) {
                    insertedEngineClipIds.add(insertedClip.engineClipId);
                  }
                }
                successfulTargetIndices.add(clipIndex);
              } else {
                failed++;
              }
            }
            if (successfulTargetIndices.isNotEmpty) {
              await _handleDeleteClips(successfulTargetIndices);
              replaced += successfulTargetIndices.length;
            }
            continue;
          }

          final explicitStartMs =
              AssistantActionUtils.resolveMoveMusicalStartMs(
            data: item,
            target: target,
            bpm: _tempo,
          );
          final repeatCountHint = _toActionInt(
                item['repeat_count'] ??
                    target['repeat_count'] ??
                    item['copies'] ??
                    target['copies'] ??
                    item['count'] ??
                    target['count'],
              ) ??
              1;
          final baseTimeMs = explicitStartMs ??
              _toActionDouble(item['start_ms'] ?? target['start_ms']) ??
              AssistantActionUtils.defaultSampleInsertStartMs(
                libraryPath,
                bpm: _tempo,
              );
          final baseRow = _resolveInsertionRowIndexFromActionTarget(item);
          final rowStep = _toActionInt(
                item['delta_rows'] ??
                    target['delta_rows'] ??
                    item['row_delta'] ??
                    target['row_delta'] ??
                    item['step_rows'] ??
                    target['step_rows'],
              ) ??
              0;
          final stepMs = AssistantActionUtils.resolveMoveMusicalDeltaMs(
                data: item,
                target: target,
                bpm: _tempo,
              ) ??
              _toActionDouble(
                item['step_ms'] ??
                    target['step_ms'] ??
                    item['spacing_ms'] ??
                    target['spacing_ms'],
              ) ??
              AssistantActionUtils.defaultSampleInsertStepMs(
                libraryPath,
                bpm: _tempo,
                repeatCount: repeatCountHint,
              ) ??
              0.0;
          final resolvedStartMs =
              baseTimeMs ?? _globalAudioClock.inMilliseconds.toDouble();
          final repeatCount = AssistantActionUtils.resolvePlacementRepeatCount(
            data: item,
            target: target,
            bpm: _tempo,
            startMs: resolvedStartMs,
            stepMs: stepMs,
            preferSpanCoverageOverExplicitCount: true,
          );

          for (int copyIndex = 0; copyIndex < repeatCount; copyIndex++) {
            if (_cancelAiBatchProcessingRequested) break;
            final row = math.max(0, baseRow + (rowStep * copyIndex));
            final timeMs = math.max(
              0.0,
              resolvedStartMs + (stepMs * copyIndex),
            );
            final beforeCount = _audioTracks.length;
            final insertedClip = await _insertAudioFileAtTimeline(
              resolvedPath,
              row: row,
              timeMs: timeMs,
              enforceKnownAudioExtension: false,
              uploadMethod: 'ai_library',
              showLoadingOverlay: !showBatchOverlay,
            );
            processedUnits += 1;
            if (showBatchOverlay) {
              _updateAiBatchProcessingOverlay(
                completedUnits: processedUnits,
                message: 'Adding samples to your project.',
              );
            }
            if (!insertedClip) {
              failed++;
              continue;
            }
            inserted++;
            if (_audioTracks.length > beforeCount) {
              final addedClip = _audioTracks.last;
              if (addedClip.engineClipId >= 0) {
                insertedEngineClipIds.add(addedClip.engineClipId);
              }
              await _autoConfigureInsertedLibraryClip(addedClip, libraryPath);
            }
          }
        } catch (error, stackTrace) {
          debugPrint('AI sample insert item failed: $error');
          unawaited(
            CrashReportingService.instance.captureException(
              error,
              stackTrace: stackTrace,
            ),
          );
          failed++;
          if (processedUnits == itemUnitsBefore) {
            processedUnits += 1;
          }
          if (showBatchOverlay) {
            _updateAiBatchProcessingOverlay(
              completedUnits: processedUnits,
              message: 'Skipping a sample that could not be added.',
            );
          }
        }
      }
    } finally {
      batchCancelled = _cancelAiBatchProcessingRequested;
      if (showBatchOverlay) {
        _endAiBatchProcessingOverlay();
      }
    }

    if (insertedEngineClipIds.isNotEmpty && mounted) {
      final selectedIndices = insertedEngineClipIds
          .map(_clipIndexForEngineId)
          .where((idx) => idx >= 0 && idx < _audioTracks.length)
          .toList(growable: false);
      if (selectedIndices.isNotEmpty) {
        final primaryIndex = selectedIndices.last;
        final primaryClip = _audioTracks[primaryIndex];
        setState(() {
          _timelineSelectedClipIndices = List<int>.from(selectedIndices);
          _timelinePrimarySelectedClipIndex = primaryIndex;
          if (_rowCount > 0) {
            _selectedRow = primaryClip.rowIndex.clamp(0, _rowCount - 1).toInt();
          } else {
            _selectedRow = primaryClip.rowIndex;
          }
        });
        unawaited(_syncLiveMidiInputTargetClip());
      }
    }

    if (inserted <= 0 && replaced <= 0) {
      _insertAssistantChatText(operation == 'replace_audio_clips'
          ? "I couldn't resolve any library samples or target clips to replace."
          : "I couldn't resolve any library samples to insert.");
      return;
    }
    if (batchCancelled) {
      if (inserted > 0 || replaced > 0) {
        _showSmallNotice(
          'Stopped after inserting $inserted sample clip${inserted == 1 ? '' : 's'} and replacing $replaced clip${replaced == 1 ? '' : 's'}.',
        );
      } else {
        _showSmallNotice('Stopped sample processing.');
      }
      return;
    }
    if (failed > 0) {
      if (replaced > 0 && inserted > 0) {
        _showSmallNotice(
            'Inserted $inserted sample clip${inserted == 1 ? '' : 's'} and replaced $replaced clip${replaced == 1 ? '' : 's'} ($failed skipped).');
      } else if (replaced > 0) {
        _showSmallNotice(
            'Replaced $replaced clip${replaced == 1 ? '' : 's'} ($failed skipped).');
      } else {
        _showSmallNotice(
            'Inserted $inserted sample clip${inserted == 1 ? '' : 's'} ($failed skipped).');
      }
      return;
    }
    if (replaced > 0 && inserted > 0) {
      _showSmallNotice(
        'Inserted $inserted sample clip${inserted == 1 ? '' : 's'} and replaced $replaced clip${replaced == 1 ? '' : 's'}.',
      );
      return;
    }
    if (replaced > 0) {
      _showSmallNotice(
        'Replaced $replaced clip${replaced == 1 ? '' : 's'}.',
      );
      return;
    }
    _showSmallNotice(
      'Inserted $inserted sample clip${inserted == 1 ? '' : 's'}.',
    );
  }

  double _maxAutomationTimelineMs() {
    return math.max(1.0, _audioOnlyOverallDuration.inMilliseconds.toDouble());
  }

  double _automationUpperBound(double minMs) {
    return math.max(minMs, _maxAutomationTimelineMs()).toDouble();
  }

  double _clampAutomationLengthMs(
    double rawLengthMs, {
    double minMs = 50.0,
  }) {
    return rawLengthMs.clamp(minMs, _automationUpperBound(minMs)).toDouble();
  }

  String _pluginAutomationTargetId(int effectIndex, String paramId) {
    return 'fx:$effectIndex:$paramId';
  }

  String _rowMixAutomationTargetId(String paramId) {
    return 'mix:${_encodeAutomationIdComponent(paramId)}';
  }

  String _masterMixAutomationTargetId(String paramId) {
    return 'master:${_encodeAutomationIdComponent(paramId)}';
  }

  String _pluginAutomationEffectKey(String effectId, int ordinal) {
    final base = effectId.trim().isEmpty ? 'effect' : effectId.trim();
    final safeOrdinal = ordinal < 0 ? 0 : ordinal;
    return '$base#$safeOrdinal';
  }

  String _encodeAutomationIdComponent(String raw) {
    return Uri.encodeComponent(raw.trim());
  }

  String _decodeAutomationIdComponent(String raw) {
    try {
      return Uri.decodeComponent(raw);
    } catch (_) {
      return raw;
    }
  }

  String _pluginAutomationTargetIdFromEffectKey(
    String effectKey,
    String paramId,
  ) {
    return 'fxid:${_encodeAutomationIdComponent(effectKey)}:${_encodeAutomationIdComponent(paramId)}';
  }

  String _masterAutomationTargetIdFromEffectKey(
    String effectKey,
    String paramId,
  ) {
    return 'masterfxid:${_encodeAutomationIdComponent(effectKey)}:${_encodeAutomationIdComponent(paramId)}';
  }

  _ParsedAutomationTargetId _parseAutomationTargetId(String targetId) {
    final trimmed = targetId.trim();
    if (trimmed == 'volume') {
      return const _ParsedAutomationTargetId(
        scope: 'row',
        section: 'volume',
        isVolume: true,
        legacyEffectIndex: -1,
        effectKey: '',
        paramId: 'volume',
        mixParamId: 'volume',
      );
    }

    if (trimmed.startsWith('mix:')) {
      final paramId = _decodeAutomationIdComponent(
        trimmed.substring('mix:'.length),
      );
      return _ParsedAutomationTargetId(
        scope: 'row',
        section: 'mix',
        isVolume: false,
        legacyEffectIndex: -1,
        effectKey: '',
        paramId: paramId,
        mixParamId: paramId,
      );
    }

    if (trimmed.startsWith('master:')) {
      final paramId = _decodeAutomationIdComponent(
        trimmed.substring('master:'.length),
      );
      return _ParsedAutomationTargetId(
        scope: 'master',
        section: 'mix',
        isVolume: false,
        legacyEffectIndex: -1,
        effectKey: '',
        paramId: paramId,
        mixParamId: paramId,
      );
    }

    if (trimmed.startsWith('masterfxid:')) {
      final payload = trimmed.substring('masterfxid:'.length);
      final splitAt = payload.indexOf(':');
      if (splitAt > 0) {
        final encodedEffectKey = payload.substring(0, splitAt);
        final encodedParamId = payload.substring(splitAt + 1);
        return _ParsedAutomationTargetId(
          scope: 'master',
          section: 'effect',
          isVolume: false,
          legacyEffectIndex: -1,
          effectKey: _decodeAutomationIdComponent(encodedEffectKey),
          paramId: _decodeAutomationIdComponent(encodedParamId),
        );
      }
    }

    if (trimmed.startsWith('fxid:')) {
      final payload = trimmed.substring('fxid:'.length);
      final splitAt = payload.indexOf(':');
      if (splitAt > 0) {
        final encodedEffectKey = payload.substring(0, splitAt);
        final encodedParamId = payload.substring(splitAt + 1);
        return _ParsedAutomationTargetId(
          scope: 'row',
          section: 'effect',
          isVolume: false,
          legacyEffectIndex: -1,
          effectKey: _decodeAutomationIdComponent(encodedEffectKey),
          paramId: _decodeAutomationIdComponent(encodedParamId),
        );
      }
    }

    final parts = trimmed.split(':');
    if (parts.length >= 3 && parts.first == 'fx') {
      return _ParsedAutomationTargetId(
        scope: 'row',
        section: 'effect',
        isVolume: false,
        legacyEffectIndex: int.tryParse(parts[1]) ?? -1,
        effectKey: '',
        paramId: parts.sublist(2).join(':'),
      );
    }

    return _ParsedAutomationTargetId(
      scope: 'row',
      section: 'effect',
      isVolume: false,
      legacyEffectIndex: -1,
      effectKey: '',
      paramId: trimmed,
    );
  }

  List<AutomationClipSnapshot> _copyAutomationClipList(
    List<AutomationClipSnapshot> clips,
  ) {
    return clips.map((c) => c.copyWith()).toList(growable: false);
  }

  String _newAutomationPatternId(int row, String targetId) {
    return 'apat_${row}_${targetId}_${DateTime.now().microsecondsSinceEpoch}_${const Uuid().v4()}';
  }

  String _automationTargetLabelFor(int row, String targetId) {
    return _rowAutomationTargets[row]?[targetId]?.label ??
        _fallbackAutomationTargetMeta(targetId).label;
  }

  _AutomationTargetMeta _volumeAutomationTargetMeta() {
    return const _AutomationTargetMeta(
      targetId: 'volume',
      label: 'Volume',
      effectIndex: -1,
      paramId: 'volume',
      type: 'float',
      min: 0.0,
      max: 1.0,
      initialNormalized: 0.75,
    );
  }

  _AutomationTargetMeta _rowGainAutomationTargetMeta({
    double initialNormalized = _kGainUiUnity / _kGainUiMax,
  }) {
    return _AutomationTargetMeta(
      targetId: _rowMixAutomationTargetId('gain'),
      label: 'Track Gain',
      effectIndex: -1,
      paramId: 'gain',
      type: 'float',
      min: _kGainUiMin,
      max: _kGainUiMax,
      initialNormalized: initialNormalized.clamp(0.0, 1.0).toDouble(),
    );
  }

  _AutomationTargetMeta _rowPanAutomationTargetMeta({
    double initialNormalized = 0.5,
  }) {
    return _AutomationTargetMeta(
      targetId: _rowMixAutomationTargetId('pan'),
      label: 'Track Pan',
      effectIndex: -1,
      paramId: 'pan',
      type: 'float',
      min: 0.0,
      max: 1.0,
      initialNormalized: initialNormalized.clamp(0.0, 1.0).toDouble(),
    );
  }

  _AutomationTargetMeta _masterGainAutomationTargetMeta({
    double initialNormalized = _kGainUiUnity / _kGainUiMax,
  }) {
    return _AutomationTargetMeta(
      targetId: _masterMixAutomationTargetId('gain'),
      label: 'Master Gain',
      effectIndex: -1,
      paramId: 'gain',
      type: 'float',
      min: _kGainUiMin,
      max: _kGainUiMax,
      initialNormalized: initialNormalized.clamp(0.0, 1.0).toDouble(),
    );
  }

  _AutomationTargetMeta _masterPanAutomationTargetMeta({
    double initialNormalized = 0.5,
  }) {
    return _AutomationTargetMeta(
      targetId: _masterMixAutomationTargetId('pan'),
      label: 'Master Pan',
      effectIndex: -1,
      paramId: 'pan',
      type: 'float',
      min: 0.0,
      max: 1.0,
      initialNormalized: initialNormalized.clamp(0.0, 1.0).toDouble(),
    );
  }

  Map<String, _AutomationTargetMeta> _defaultAutomationTargetsForRow(int row) {
    final safeRowGain = (row >= 0 && row < _rowGain.length)
        ? (_rowGain[row] / _kGainUiMax).clamp(0.0, 1.0).toDouble()
        : (_kGainUiUnity / _kGainUiMax);
    final safeRowPan = (row >= 0 && row < _rowPan.length)
        ? _rowPan[row].clamp(0.0, 1.0).toDouble()
        : 0.5;
    return <String, _AutomationTargetMeta>{
      'volume': _volumeAutomationTargetMeta(),
      _rowMixAutomationTargetId('gain'): _rowGainAutomationTargetMeta(
        initialNormalized: safeRowGain,
      ),
      _rowMixAutomationTargetId('pan'): _rowPanAutomationTargetMeta(
        initialNormalized: safeRowPan,
      ),
      _masterMixAutomationTargetId('gain'): _masterGainAutomationTargetMeta(
        initialNormalized: (_masterGain / _kGainUiMax).clamp(0.0, 1.0),
      ),
      _masterMixAutomationTargetId('pan'): _masterPanAutomationTargetMeta(
        initialNormalized: _masterPan.clamp(0.0, 1.0),
      ),
    };
  }

  _AutomationTargetMeta _fallbackAutomationTargetMeta(String targetId) {
    if (targetId == 'volume') return _volumeAutomationTargetMeta();
    final parsed = _parseAutomationTargetId(targetId);
    final mixParam = parsed.mixParamId.trim().toLowerCase();
    if (parsed.section == 'mix') {
      if (parsed.isMaster) {
        if (mixParam == 'gain') return _masterGainAutomationTargetMeta();
        if (mixParam == 'pan') return _masterPanAutomationTargetMeta();
      } else {
        if (mixParam == 'gain') return _rowGainAutomationTargetMeta();
        if (mixParam == 'pan') return _rowPanAutomationTargetMeta();
      }
    }
    final fallbackLabel = switch (mixParam) {
      'gain' => parsed.isMaster ? 'Master Gain' : 'Track Gain',
      'pan' => parsed.isMaster ? 'Master Pan' : 'Track Pan',
      _ => parsed.paramId.isNotEmpty ? parsed.paramId : targetId,
    };
    return _AutomationTargetMeta(
      targetId: targetId,
      label: fallbackLabel,
      effectIndex: parsed.legacyEffectIndex,
      paramId: parsed.paramId,
      type: 'float',
      min: 0.0,
      max: 1.0,
      initialNormalized: targetId == 'volume' ? 0.75 : 0.5,
    );
  }

  _AutomationTargetMeta _orphanAutomationTargetMeta(
    String targetId, {
    String? label,
  }) {
    final safeLabel = (label ?? '').trim();
    final base = (_automationTargetMetaFromAnyRow(targetId) ??
            _fallbackAutomationTargetMeta(targetId))
        .copyWith(
      targetId: targetId,
      label: safeLabel.isEmpty ? null : safeLabel,
      isOrphan: true,
      uiVisible: false,
    );
    return base.copyWith(
      label: base.label.trim().isEmpty ? targetId : base.label.trim(),
      isOrphan: true,
      uiVisible: false,
    );
  }

  double _normalizeAutomationValue(
    double? rawValue, {
    required double min,
    required double max,
    double fallback = 0.5,
  }) {
    if (rawValue == null) return fallback.clamp(0.0, 1.0).toDouble();
    final span = max - min;
    if (!span.isFinite || span.abs() < 1e-9) {
      return fallback.clamp(0.0, 1.0).toDouble();
    }
    return ((rawValue - min) / span).clamp(0.0, 1.0).toDouble();
  }

  double _denormalizeAutomationValue(
    double normalized,
    _AutomationTargetMeta target,
  ) {
    if (target.isVolume) {
      return normalized.clamp(0.0, 1.0).toDouble();
    }
    final span = target.max - target.min;
    if (!span.isFinite || span.abs() < 1e-9) {
      return target.min;
    }
    return target.min + span * normalized.clamp(0.0, 1.0).toDouble();
  }

  double _normalizedChoiceAutomationValue(
    Map<String, dynamic> paramMap, {
    double fallback = 0.5,
  }) {
    final choiceKeys = paramMap.keys
        .where((key) => key.startsWith('choice_'))
        .toList(growable: false)
      ..sort((a, b) {
        final ai = int.tryParse(a.substring('choice_'.length)) ?? 0;
        final bi = int.tryParse(b.substring('choice_'.length)) ?? 0;
        return ai.compareTo(bi);
      });
    if (choiceKeys.isEmpty) {
      return fallback.clamp(0.0, 1.0).toDouble();
    }

    final rawValue = (paramMap['value'] ?? '').toString().trim();
    if (rawValue.isNotEmpty) {
      for (int i = 0; i < choiceKeys.length; i++) {
        final choice = (paramMap[choiceKeys[i]] ?? '').toString().trim();
        if (choice == rawValue) {
          if (choiceKeys.length <= 1) return 0.0;
          return (i / (choiceKeys.length - 1)).clamp(0.0, 1.0).toDouble();
        }
      }
    }

    final numericValue = _toActionDouble(paramMap['value']);
    if (numericValue != null) {
      return numericValue.clamp(0.0, 1.0).toDouble();
    }
    return fallback.clamp(0.0, 1.0).toDouble();
  }

  double _initialAutomationNormalizedFromParamMap(
    Map<String, dynamic> paramMap, {
    required double min,
    required double max,
    double fallback = 0.5,
  }) {
    final type = (paramMap['type'] ?? '').toString().trim().toLowerCase();
    switch (type) {
      case 'bool':
        final raw = paramMap['value'];
        if (raw is bool) return raw ? 1.0 : 0.0;
        final numeric = _toActionDouble(raw);
        return ((numeric ?? fallback) >= 0.5 ? 1.0 : 0.0);
      case 'choice':
        return _normalizedChoiceAutomationValue(
          paramMap,
          fallback: fallback,
        );
      default:
        return _normalizeAutomationValue(
          (paramMap['value'] as num?)?.toDouble(),
          min: min,
          max: max,
          fallback: fallback,
        );
    }
  }

  List<Map<String, dynamic>> _toNormalizedAutomationMaps(
    List<AutomationPoint> points,
  ) {
    return points
        .map((p) => <String, dynamic>{
              'x': p.x,
              'value': p.volume.clamp(0.0, 1.0),
            })
        .toList(growable: false);
  }

  Set<String> _automationTargetIdsForRowSync(int row) {
    final ids = <String>{
      'volume',
      _rowMixAutomationTargetId('gain'),
      _rowMixAutomationTargetId('pan'),
    };
    ids.addAll(
      _rowAutomationTargets[row]?.keys ?? const <String>{},
    );
    ids.addAll(
      _rowPluginAutomation[row]?.keys ?? const <String>{},
    );
    ids.addAll(
      _rowAutomationClips[row]?.keys ?? const <String>{},
    );
    return ids;
  }

  Set<String> _masterAutomationTargetIdsForSync() {
    final ids = <String>{
      _masterMixAutomationTargetId('gain'),
      _masterMixAutomationTargetId('pan'),
    };
    for (int row = 0; row < _rowCount; row++) {
      ids.addAll(
        (_rowAutomationTargets[row]?.keys ?? const <String>{})
            .where(_isMasterAutomationTarget),
      );
      ids.addAll(
        (_rowPluginAutomation[row]?.keys ?? const <String>{})
            .where(_isMasterAutomationTarget),
      );
      ids.addAll(
        (_rowAutomationClips[row]?.keys ?? const <String>{})
            .where(_isMasterAutomationTarget),
      );
    }
    return ids;
  }

  Future<void> _syncNativeRowAutomationForRow(int row) async {
    if (row < 0 || row >= _rowCount) return;

    final resolvedVolume = _resolvedAutomationPointsForTarget(row, 'volume');
    await JuceAudioEngine.setTrackAutomationPoints(
      row,
      _toMaps(resolvedVolume),
    );

    final rowGainTargetId = _rowMixAutomationTargetId('gain');
    final resolvedGain = _hasExplicitAutomationForTarget(row, rowGainTargetId)
        ? _resolvedAutomationPointsForTarget(row, rowGainTargetId)
        : const <AutomationPoint>[];
    await JuceAudioEngine.setRowGainAutomationPoints(
      row,
      _toNormalizedAutomationMaps(resolvedGain),
    );

    final rowPanTargetId = _rowMixAutomationTargetId('pan');
    final resolvedPan = _hasExplicitAutomationForTarget(row, rowPanTargetId)
        ? _resolvedAutomationPointsForTarget(row, rowPanTargetId)
        : const <AutomationPoint>[];
    await JuceAudioEngine.setRowPanAutomationPoints(
      row,
      _toNormalizedAutomationMaps(resolvedPan),
    );

    await JuceAudioEngine.clearTrackEffectAutomationForRow(row);

    final targets =
        _rowAutomationTargets[row] ?? const <String, _AutomationTargetMeta>{};
    for (final targetId in _automationTargetIdsForRowSync(row)) {
      if (!_hasExplicitAutomationForTarget(row, targetId)) {
        continue;
      }
      final target =
          targets[targetId] ?? _fallbackAutomationTargetMeta(targetId);
      if (target.isOrphan) continue;
      final parsed = _parseAutomationTargetId(targetId);
      if (target.isVolume || parsed.isMaster || !parsed.isEffectParameter) {
        continue;
      }
      if (target.effectIndex < 0) continue;
      if (target.paramId.trim().isEmpty) continue;

      final safePoints = _resolvedAutomationPointsForTarget(row, targetId);
      await JuceAudioEngine.setTrackEffectAutomationPoints(
        row,
        target.effectIndex,
        target.paramId,
        target.min,
        target.max,
        _toNormalizedAutomationMaps(safePoints),
      );
    }
  }

  Future<void> _syncNativeMasterAutomation() async {
    final masterGainTargetId = _masterMixAutomationTargetId('gain');
    final masterGainPoints =
        _hasExplicitAutomationForTarget(0, masterGainTargetId)
            ? _resolvedAutomationPointsForTarget(0, masterGainTargetId)
            : const <AutomationPoint>[];
    await JuceAudioEngine.setMasterGainAutomationPoints(
      _toNormalizedAutomationMaps(masterGainPoints),
    );

    final masterPanTargetId = _masterMixAutomationTargetId('pan');
    final masterPanPoints =
        _hasExplicitAutomationForTarget(0, masterPanTargetId)
            ? _resolvedAutomationPointsForTarget(0, masterPanTargetId)
            : const <AutomationPoint>[];
    await JuceAudioEngine.setMasterPanAutomationPoints(
      _toNormalizedAutomationMaps(masterPanPoints),
    );

    await JuceAudioEngine.clearMasterEffectAutomation();

    for (final targetId in _masterAutomationTargetIdsForSync()) {
      if (!_hasExplicitAutomationForTarget(0, targetId)) continue;
      final parsed = _parseAutomationTargetId(targetId);
      if (!parsed.isMaster || !parsed.isEffectParameter) continue;
      final target = _automationTargetMetaFromAnyRow(targetId) ??
          _fallbackAutomationTargetMeta(targetId);
      if (target.isOrphan) continue;
      if (target.effectIndex < 0) continue;
      if (target.paramId.trim().isEmpty) continue;

      final safePoints = _resolvedAutomationPointsForTarget(0, targetId);
      await JuceAudioEngine.setMasterEffectAutomationPoints(
        target.effectIndex,
        target.paramId,
        target.min,
        target.max,
        _toNormalizedAutomationMaps(safePoints),
      );
    }
  }

  Future<void> _syncNativeAutomationForRow(
    int row, {
    bool syncMaster = true,
  }) async {
    await _syncNativeRowAutomationForRow(row);
    if (syncMaster) {
      await _syncNativeMasterAutomation();
    }
  }

  Future<void> _syncNativePluginAutomationForRow(int row) async {
    await _syncNativeAutomationForRow(row);
  }

  Future<void> _syncNativeAutomationForAllRows() async {
    for (int row = 0; row < _rowCount; row++) {
      await _syncNativeRowAutomationForRow(row);
    }
    await _syncNativeMasterAutomation();
  }

  static const Map<String, Set<String>> _kAutomationVisibleParamsByEffect =
      <String, Set<String>>{
    'Reverb': <String>{'Room Size', 'Mix', 'Predelay'},
    'Compressor': <String>{
      'Threshold',
      'Attack',
      'Release',
      'Ratio',
      'Makeup',
      'Mix',
    },
    'Limiter': <String>{'Threshold', 'Release', 'Ceiling'},
    'Clipper': <String>{'Threshold', 'Ceiling'},
    'EQ Parametric': <String>{
      'HPF Frequency',
      'HPF Slope',
      'Band 1 Frequency',
      'Band 1 Gain',
      'Band 1 Q',
      'Band 2 Frequency',
      'Band 2 Gain',
      'Band 2 Q',
      'Band 3 Frequency',
      'Band 3 Gain',
      'Band 3 Q',
      'Band 4 Frequency',
      'Band 4 Gain',
      'Band 4 Q',
      'LPF Slope',
      'LPF Frequency',
    },
    'EQ 3-Band': <String>{'Low Gain', 'Mid Gain', 'High Gain'},
    'Delay': <String>{'Delay Time', 'Feedback', 'Mix'},
    'Gain': <String>{'Volume'},
  };

  Set<String>? _visibleAutomationParamsForEffect(String effectName) {
    return _kAutomationVisibleParamsByEffect[effectName.trim()];
  }

  bool _isAutomationTargetVisibleInMenu(_AutomationTargetMeta target) {
    if (target.isVolume) return true;
    if (!target.uiVisible) return false;
    if (target.isOrphan) return false;
    return true;
  }

  Future<List<_DiscoveredAutomationTarget>> _discoverMasterAutomationTargets({
    Map<String, _AutomationTargetMeta> previousTargets =
        const <String, _AutomationTargetMeta>{},
  }) async {
    final masterEffects = await JuceAudioEngine.getMasterEffects();
    var masterEffectIds = await JuceAudioEngine.getMasterEffectIds();
    if (masterEffectIds.length != masterEffects.length) {
      masterEffectIds = List<String>.from(masterEffects);
    }
    final signature = _automationDiscoverySignature(
      <List<String>>[masterEffects, masterEffectIds],
    );
    final cached = _masterAutomationDiscoveryCache;
    if (cached != null && cached.signature == signature) {
      return _cloneDiscoveredAutomationTargets(cached.targets);
    }

    final discovered = <_DiscoveredAutomationTarget>[];
    final masterEffectDisplayLabels = buildAutomationEffectDisplayLabels(
      effectNames: masterEffects,
      fallbackIds: masterEffectIds,
    );
    final masterEffectOrdinalById = <String, int>{};
    for (int effectIndex = 0;
        effectIndex < masterEffects.length;
        effectIndex++) {
      final params =
          await JuceAudioEngine.getMasterPluginParameters(effectIndex);
      final effectName = masterEffects[effectIndex].trim();
      final visibleParams = _visibleAutomationParamsForEffect(effectName);
      final displayEffectName = effectIndex < masterEffectDisplayLabels.length
          ? masterEffectDisplayLabels[effectIndex].displayName
          : effectName;
      final rawEffectId = (effectIndex < masterEffectIds.length
              ? masterEffectIds[effectIndex]
              : effectName)
          .trim();
      final effectIdentity = rawEffectId.isNotEmpty
          ? rawEffectId
          : (effectName.isNotEmpty ? effectName : 'effect');
      final effectOrdinal = masterEffectOrdinalById.update(
        effectIdentity,
        (value) => value + 1,
        ifAbsent: () => 0,
      );
      final effectKey =
          _pluginAutomationEffectKey(effectIdentity, effectOrdinal);
      for (final p in params) {
        final type = (p['type'] ?? '').toString().trim().toLowerCase();
        if (type != 'float' && type != 'bool' && type != 'choice') continue;

        final rawId = (p['id'] ?? p['name'] ?? '').toString().trim();
        final rawName = (p['name'] ?? rawId).toString().trim();
        if (rawId.isEmpty || rawName.isEmpty) continue;
        final isVisible =
            visibleParams == null || visibleParams.contains(rawName);

        final min =
            type == 'float' ? ((p['min'] as num?)?.toDouble() ?? 0.0) : 0.0;
        final max =
            type == 'float' ? ((p['max'] as num?)?.toDouble() ?? 1.0) : 1.0;
        final targetId =
            _masterAutomationTargetIdFromEffectKey(effectKey, rawId);
        final label = displayEffectName.isEmpty
            ? 'Master • $rawName'
            : 'Master • $displayEffectName • $rawName';
        final previousTarget = previousTargets[targetId];
        final fallbackNormalized =
            (previousTarget?.initialNormalized ?? 0.5).clamp(0.0, 1.0);
        final currentNormalized = _initialAutomationNormalizedFromParamMap(
          p,
          min: min,
          max: max,
          fallback: fallbackNormalized,
        );

        discovered.add(
          _DiscoveredAutomationTarget(
            meta: _AutomationTargetMeta(
              targetId: targetId,
              label: label,
              effectIndex: effectIndex,
              paramId: rawId,
              type: type,
              min: min,
              max: max,
              initialNormalized: currentNormalized,
              uiVisible: isVisible,
            ),
            scope: 'master',
            effectKey: effectKey,
          ),
        );
      }
    }
    _masterAutomationDiscoveryCache = _AutomationDiscoveryCacheEntry(
      signature: signature,
      targets: _cloneDiscoveredAutomationTargets(discovered),
    );
    return discovered;
  }

  void _scheduleAutomationTargetsRefreshForRow(int row) {
    if (row < 0 || row >= _rowCount) return;
    if (_allRowsAutomationTargetsRefreshInFlight) {
      _allRowsAutomationTargetsRefreshQueued = true;
      return;
    }
    if (_rowAutomationTargetRefreshInFlight.contains(row)) {
      _rowAutomationTargetRefreshQueued.add(row);
      return;
    }
    _rowAutomationTargetRefreshInFlight.add(row);
    unawaited(() async {
      try {
        while (true) {
          _rowAutomationTargetRefreshQueued.remove(row);
          await _refreshAutomationTargetsForRow(row);
          if (!_rowAutomationTargetRefreshQueued.remove(row)) {
            break;
          }
        }
      } finally {
        _rowAutomationTargetRefreshInFlight.remove(row);
      }
    }());
  }

  void _scheduleAutomationTargetsRefreshForAllRows() {
    if (_allRowsAutomationTargetsRefreshInFlight) {
      _allRowsAutomationTargetsRefreshQueued = true;
      return;
    }
    _allRowsAutomationTargetsRefreshInFlight = true;
    _rowAutomationTargetRefreshInFlight.clear();
    _rowAutomationTargetRefreshQueued.clear();
    unawaited(() async {
      try {
        while (true) {
          _allRowsAutomationTargetsRefreshQueued = false;
          await _refreshAutomationTargetsForAllRows();
          if (!_allRowsAutomationTargetsRefreshQueued) {
            break;
          }
        }
      } finally {
        _allRowsAutomationTargetsRefreshInFlight = false;
      }
    }());
  }

  Future<void> _refreshAutomationTargetsForRow(
    int row, {
    bool setStateWhenDone = true,
    bool syncNativeWhenDone = true,
    List<_DiscoveredAutomationTarget>? sharedMasterTargets,
  }) async {
    if (row < 0 || row >= _rowCount) return;

    final previousTargets = Map<String, _AutomationTargetMeta>.from(
      _rowAutomationTargets[row] ?? const <String, _AutomationTargetMeta>{},
    );
    final discovered = <String, _AutomationTargetMeta>{
      'volume': _volumeAutomationTargetMeta(),
      _rowMixAutomationTargetId('gain'): _rowGainAutomationTargetMeta(
        initialNormalized: (_rowGain[row] / _kGainUiMax).clamp(0.0, 1.0),
      ),
      _rowMixAutomationTargetId('pan'): _rowPanAutomationTargetMeta(
        initialNormalized: _rowPan[row].clamp(0.0, 1.0),
      ),
      _masterMixAutomationTargetId('gain'): _masterGainAutomationTargetMeta(
        initialNormalized: (_masterGain / _kGainUiMax).clamp(0.0, 1.0),
      ),
      _masterMixAutomationTargetId('pan'): _masterPanAutomationTargetMeta(
        initialNormalized: _masterPan.clamp(0.0, 1.0),
      ),
    };
    final discoveredByEffectKeyAndParam = <String, _AutomationTargetMeta>{};
    final discoveredByLegacyIndexAndParam = <String, _AutomationTargetMeta>{};
    final discoveredByParam = <String, List<_AutomationTargetMeta>>{};

    void recordDiscoveredTarget(
      _AutomationTargetMeta meta, {
      required String scope,
      String effectKey = '',
    }) {
      discovered[meta.targetId] = meta;
      final paramLower = meta.paramId.trim().toLowerCase();
      if (paramLower.isEmpty) return;
      if (effectKey.trim().isNotEmpty) {
        discoveredByEffectKeyAndParam[
            '$scope\u0000${effectKey.trim()}\u0000$paramLower'] = meta;
      }
      if (meta.effectIndex >= 0) {
        discoveredByLegacyIndexAndParam[
            '$scope\u0000${meta.effectIndex}\u0000$paramLower'] = meta;
      }
      discoveredByParam
          .putIfAbsent(
              '$scope\u0000$paramLower', () => <_AutomationTargetMeta>[])
          .add(meta);
    }

    final rowId = _rowIdAt(row);
    final effects = await JuceAudioEngine.getTrackEffectsForRow(row);
    var effectInstanceIds =
        await JuceAudioEngine.getTrackEffectInstanceIdsForRow(row);
    if (effectInstanceIds.length != effects.length) {
      effectInstanceIds = List<String>.filled(effects.length, '');
    }
    var effectIds = await JuceAudioEngine.getTrackEffectIdsForRow(row);
    if (effectIds.length != effects.length) {
      effectIds = List<String>.from(effects);
    }
    final rowSignature = _automationDiscoverySignature(
      <List<String>>[effects, effectIds, effectInstanceIds],
    );
    final cachedRowDiscovery =
        rowId >= 0 ? _rowAutomationDiscoveryCache[rowId] : null;
    if (cachedRowDiscovery != null &&
        cachedRowDiscovery.signature == rowSignature) {
      for (final entry in cachedRowDiscovery.targets) {
        recordDiscoveredTarget(
          entry.meta.copyWith(),
          scope: entry.scope,
          effectKey: entry.effectKey,
        );
      }
    } else {
      final effectDisplayLabels = buildAutomationEffectDisplayLabels(
        effectNames: effects,
        fallbackIds: effectIds,
      );
      final effectOrdinalById = <String, int>{};
      final discoveredRowTargets = <_DiscoveredAutomationTarget>[];
      for (int effectIndex = 0; effectIndex < effects.length; effectIndex++) {
        final params =
            await JuceAudioEngine.getTrackPluginParameters(row, effectIndex);
        final effectName = effects[effectIndex].trim();
        final visibleParams = _visibleAutomationParamsForEffect(effectName);
        final displayEffectName = effectIndex < effectDisplayLabels.length
            ? effectDisplayLabels[effectIndex].displayName
            : effectName;
        final rawInstanceId = (effectIndex < effectInstanceIds.length
                ? effectInstanceIds[effectIndex]
                : '')
            .trim();
        final rawEffectId = (effectIndex < effectIds.length
                ? effectIds[effectIndex]
                : effectName)
            .trim();
        final effectIdentity = rawEffectId.isNotEmpty
            ? rawEffectId
            : (effectName.isNotEmpty ? effectName : 'effect');
        final effectOrdinal = effectOrdinalById.update(
          effectIdentity,
          (value) => value + 1,
          ifAbsent: () => 0,
        );
        final effectKey = rawInstanceId.isNotEmpty
            ? 'inst:$rawInstanceId'
            : _pluginAutomationEffectKey(effectIdentity, effectOrdinal);
        for (final p in params) {
          final type = (p['type'] ?? '').toString().trim().toLowerCase();
          if (type != 'float' && type != 'bool' && type != 'choice') continue;

          final rawId = (p['id'] ?? p['name'] ?? '').toString().trim();
          final rawName = (p['name'] ?? rawId).toString().trim();
          if (rawId.isEmpty || rawName.isEmpty) continue;
          final isVisible =
              visibleParams == null || visibleParams.contains(rawName);

          final min =
              type == 'float' ? ((p['min'] as num?)?.toDouble() ?? 0.0) : 0.0;
          final max =
              type == 'float' ? ((p['max'] as num?)?.toDouble() ?? 1.0) : 1.0;
          final targetId =
              _pluginAutomationTargetIdFromEffectKey(effectKey, rawId);
          final label = displayEffectName.isEmpty
              ? rawName
              : '$displayEffectName • $rawName';
          final previousTarget = previousTargets[targetId];
          final fallbackNormalized =
              (previousTarget?.initialNormalized ?? 0.5).clamp(0.0, 1.0);
          final currentNormalized = _initialAutomationNormalizedFromParamMap(
            p,
            min: min,
            max: max,
            fallback: fallbackNormalized,
          );

          final entry = _DiscoveredAutomationTarget(
            meta: _AutomationTargetMeta(
              targetId: targetId,
              label: label,
              effectIndex: effectIndex,
              paramId: rawId,
              type: type,
              min: min,
              max: max,
              initialNormalized: currentNormalized,
              uiVisible: isVisible,
            ),
            scope: 'row',
            effectKey: effectKey,
          );
          discoveredRowTargets.add(entry);
          recordDiscoveredTarget(
            entry.meta,
            scope: entry.scope,
            effectKey: entry.effectKey,
          );
        }
      }
      if (rowId >= 0) {
        _rowAutomationDiscoveryCache[rowId] = _AutomationDiscoveryCacheEntry(
          signature: rowSignature,
          targets: _cloneDiscoveredAutomationTargets(discoveredRowTargets),
        );
      }
    }

    final masterTargets = sharedMasterTargets ??
        await _discoverMasterAutomationTargets(
          previousTargets: previousTargets,
        );
    for (final entry in masterTargets) {
      recordDiscoveredTarget(
        entry.meta,
        scope: entry.scope,
        effectKey: entry.effectKey,
      );
    }

    _AutomationTargetMeta? resolveRemappedTarget(String originalTargetId) {
      if (originalTargetId == 'volume') return discovered['volume'];
      final existing = discovered[originalTargetId];
      if (existing != null) return existing;

      final previousMeta = previousTargets[originalTargetId] ??
          _fallbackAutomationTargetMeta(originalTargetId);
      final parsed = _parseAutomationTargetId(originalTargetId);
      final normalizedParamId =
          (parsed.paramId.isNotEmpty ? parsed.paramId : previousMeta.paramId)
              .trim()
              .toLowerCase();
      if (normalizedParamId.isEmpty) return null;

      if (parsed.effectKey.isNotEmpty) {
        final byEffectKey = discoveredByEffectKeyAndParam[
            '${parsed.scope}\u0000${parsed.effectKey}\u0000$normalizedParamId'];
        if (byEffectKey != null) return byEffectKey;
      }

      if (parsed.legacyEffectIndex >= 0) {
        final byLegacy = discoveredByLegacyIndexAndParam[
            '${parsed.scope}\u0000${parsed.legacyEffectIndex}\u0000$normalizedParamId'];
        if (byLegacy != null) return byLegacy;
      }

      // For fxid targets, instance ids can change after restoring a project.
      // Fall back to lane metadata (effectIndex + paramId) captured at save.
      if (previousMeta.effectIndex >= 0) {
        final bySavedLaneEffectIndex = discoveredByLegacyIndexAndParam[
            '${parsed.scope}\u0000${previousMeta.effectIndex}\u0000$normalizedParamId'];
        if (bySavedLaneEffectIndex != null) return bySavedLaneEffectIndex;
      }

      final candidates =
          discoveredByParam['${parsed.scope}\u0000$normalizedParamId'] ??
              const <_AutomationTargetMeta>[];
      if (candidates.isEmpty) return null;

      final previousLabelLower = previousMeta.label.trim().toLowerCase();
      if (previousLabelLower.isNotEmpty) {
        final byLabel = candidates
            .where((candidate) =>
                candidate.label.trim().toLowerCase() == previousLabelLower)
            .toList(growable: false);
        if (byLabel.length == 1) {
          return byLabel.first;
        }
      }

      return null;
    }

    _AutomationTargetMeta orphanMetaForTarget(
      String targetId, {
      Iterable<AutomationClipSnapshot> clipHints =
          const <AutomationClipSnapshot>[],
    }) {
      String? labelHint;
      for (final clip in clipHints) {
        final label = clip.label.trim();
        if (label.isNotEmpty) {
          labelHint = label;
          break;
        }
      }
      return _orphanAutomationTargetMeta(targetId, label: labelHint);
    }

    final pluginByTarget = Map<String, List<AutomationPoint>>.from(
      _rowPluginAutomation[row] ?? const <String, List<AutomationPoint>>{},
    );
    final remappedPlugin = <String, List<AutomationPoint>>{};
    for (final entry in pluginByTarget.entries) {
      final originalTargetId = entry.key;
      if (originalTargetId == 'volume') continue;

      final resolvedTarget = resolveRemappedTarget(originalTargetId);
      final resolvedTargetId = resolvedTarget?.targetId ?? originalTargetId;
      final targetMeta =
          resolvedTarget ?? orphanMetaForTarget(originalTargetId);
      discovered[resolvedTargetId] = targetMeta;

      final safePoints = _sanitizeAutomationPointsForTarget(
        row,
        resolvedTargetId,
        entry.value,
      );
      final existing =
          remappedPlugin[resolvedTargetId] ?? const <AutomationPoint>[];
      remappedPlugin[resolvedTargetId] = _sanitizeAutomationPointsForTarget(
        row,
        resolvedTargetId,
        <AutomationPoint>[
          ...existing.map((p) => p.copy()),
          ...safePoints.map((p) => p.copy()),
        ],
      );
    }

    final clipsByTarget = Map<String, List<AutomationClipSnapshot>>.from(
      _rowAutomationClips[row] ??
          const <String, List<AutomationClipSnapshot>>{},
    );
    final remappedClips = <String, List<AutomationClipSnapshot>>{};
    for (final entry in clipsByTarget.entries) {
      final originalTargetId = entry.key;
      if (originalTargetId == 'volume') {
        discovered[originalTargetId] = _volumeAutomationTargetMeta();
        remappedClips[originalTargetId] = _sanitizeAutomationClipsForTarget(
          row,
          originalTargetId,
          entry.value.map((c) => c.copyWith()).toList(growable: false),
        );
        continue;
      }

      final resolvedTarget = resolveRemappedTarget(originalTargetId);
      final resolvedTargetId = resolvedTarget?.targetId ?? originalTargetId;
      final targetMeta = resolvedTarget ??
          orphanMetaForTarget(
            originalTargetId,
            clipHints: entry.value,
          );
      discovered[resolvedTargetId] = targetMeta;

      final safeClips = _sanitizeAutomationClipsForTarget(
        row,
        resolvedTargetId,
        entry.value.map((c) => c.copyWith()).toList(growable: false),
      );
      if (safeClips.isEmpty) continue;
      final existing =
          remappedClips[resolvedTargetId] ?? const <AutomationClipSnapshot>[];
      remappedClips[resolvedTargetId] = _sanitizeAutomationClipsForTarget(
        row,
        resolvedTargetId,
        <AutomationClipSnapshot>[
          ...existing.map((c) => c.copyWith()),
          ...safeClips.map((c) => c.copyWith()),
        ],
      );
    }

    _rowPluginAutomation[row] = remappedPlugin;
    _rowAutomationClips[row] = remappedClips;
    _rowAutomationTargets[row] = discovered;
    final selected = _rowSelectedAutomationTarget[row];
    final selectedMeta = selected == null ? null : discovered[selected];
    if (selected == null ||
        selectedMeta == null ||
        !_isAutomationTargetVisibleInMenu(selectedMeta)) {
      final fallback = discovered.containsKey('volume')
          ? 'volume'
          : discovered.values
              .firstWhere(
                _isAutomationTargetVisibleInMenu,
                orElse: () => _volumeAutomationTargetMeta(),
              )
              .targetId;
      _rowSelectedAutomationTarget[row] = fallback;
    }

    if (setStateWhenDone) {
      _refreshAudioEditorView();
    }

    if (syncNativeWhenDone) {
      await _syncNativePluginAutomationForRow(row);
    }
  }

  Future<void> _refreshAutomationTargetsForAllRows({
    bool syncNativeWhenDone = true,
  }) async {
    final sharedMasterTargets = await _discoverMasterAutomationTargets();
    for (int row = 0; row < _rowCount; row++) {
      await _refreshAutomationTargetsForRow(
        row,
        setStateWhenDone: false,
        syncNativeWhenDone: false,
        sharedMasterTargets: sharedMasterTargets,
      );
      if (syncNativeWhenDone) {
        await _syncNativePluginAutomationForRow(row);
      }
    }
    _refreshAudioEditorView();
  }

  bool _hasPendingAutomationTargetRemap(int row) {
    if (row < 0 || row >= _rowCount) return false;

    bool needsRemap(String targetId) {
      if (targetId == 'volume') return false;
      final meta = _rowAutomationTargets[row]?[targetId];
      return meta == null || meta.isOrphan;
    }

    for (final targetId
        in (_rowPluginAutomation[row]?.keys ?? const <String>{})) {
      if (needsRemap(targetId)) return true;
    }
    for (final targetId
        in (_rowAutomationClips[row]?.keys ?? const <String>{})) {
      if (needsRemap(targetId)) return true;
    }
    return false;
  }

  Future<void> _stabilizeAutomationTargetsAfterProjectLoad() async {
    for (int attempt = 0; attempt < 4; attempt++) {
      final hasPending = List<int>.generate(_rowCount, (index) => index)
          .any(_hasPendingAutomationTargetRemap);
      if (!hasPending) return;
      await Future.delayed(const Duration(milliseconds: 120));
      await _refreshAutomationTargetsForAllRows();
    }
  }

  List<Map<String, dynamic>> _automationTargetsForRowUi(int row) {
    if (row < 0 || row >= _rowCount) return const <Map<String, dynamic>>[];
    final targets = _rowAutomationTargets[row] ??
        <String, _AutomationTargetMeta>{
          'volume': _volumeAutomationTargetMeta()
        };
    final values =
        targets.values.where(_isAutomationTargetVisibleInMenu).toList(
              growable: false,
            )..sort((a, b) {
            if (a.isVolume && !b.isVolume) return -1;
            if (!a.isVolume && b.isVolume) return 1;
            if (a.isOrphan && !b.isOrphan) return 1;
            if (!a.isOrphan && b.isOrphan) return -1;
            return a.label.toLowerCase().compareTo(b.label.toLowerCase());
          });
    return values.map((target) {
      final map = target.toUiMap();
      map['hasAutomationData'] =
          _hasUserAutomationDataForTarget(row, target.targetId);
      return map;
    }).toList(growable: false);
  }

  String _selectedAutomationTargetIdForRow(int row) {
    if (row < 0 || row >= _rowCount) return 'volume';
    final selected = _rowSelectedAutomationTarget[row];
    final selectedMeta =
        selected == null ? null : _rowAutomationTargets[row]?[selected];
    if (selectedMeta != null &&
        _isAutomationTargetVisibleInMenu(selectedMeta)) {
      return selected!;
    }
    return 'volume';
  }

  void _setSelectedAutomationTargetIdForRow(int row, String targetId) {
    if (row < 0 || row >= _rowCount) return;
    final targets = _rowAutomationTargets[row] ??
        <String, _AutomationTargetMeta>{
          'volume': _volumeAutomationTargetMeta()
        };
    final selectedMeta = targets[targetId];
    if (selectedMeta == null ||
        !_isAutomationTargetVisibleInMenu(selectedMeta)) {
      targetId = 'volume';
    }
    _rowSelectedAutomationTarget[row] = targetId;
    if (mounted) setState(() {});
    _scheduleProjectAutosave();
  }

  List<AutomationPoint> _defaultAutomationPointsForTarget(
    int row,
    String targetId,
  ) {
    double normalized = targetId == 'volume' ? 0.75 : 0.5;
    final parsed = _parseAutomationTargetId(targetId);
    if (parsed.isMixParameter) {
      switch (parsed.mixParamId.trim().toLowerCase()) {
        case 'gain':
          normalized = (parsed.isMaster
                  ? (_masterGain / _kGainUiMax)
                  : ((row >= 0 && row < _rowCount)
                      ? (_rowGain[row] / _kGainUiMax)
                      : (_kGainUiUnity / _kGainUiMax)))
              .clamp(0.0, 1.0)
              .toDouble();
          break;
        case 'pan':
          normalized = (parsed.isMaster
                  ? _masterPan
                  : ((row >= 0 && row < _rowCount) ? _rowPan[row] : 0.5))
              .clamp(0.0, 1.0)
              .toDouble();
          break;
        case 'volume':
          normalized = 0.75;
          break;
        default:
          break;
      }
    }
    _AutomationTargetMeta? target;
    if (row >= 0 && row < _rowCount) {
      target = _rowAutomationTargets[row]?[targetId];
    } else {
      target = _automationTargetMetaFromAnyRow(targetId);
    }
    if (target != null) {
      normalized = target.initialNormalized.clamp(0.0, 1.0).toDouble();
    }
    return <AutomationPoint>[
      AutomationPoint(x: 0.0, volume: normalized),
    ];
  }

  List<AutomationClipSnapshot> _clipsForAutomationTarget(
    int row,
    String targetId,
  ) {
    if (row < 0 || row >= _rowCount) return const <AutomationClipSnapshot>[];
    final rowMap = _rowAutomationClips[row];
    final existing = rowMap?[targetId];
    if (existing == null) return const <AutomationClipSnapshot>[];
    return existing;
  }

  List<AutomationPoint> _sanitizeAutomationClipPointsRelative(
    double lengthMs,
    List<AutomationPoint> points, {
    required double fallbackValue,
  }) {
    final safeLength = lengthMs.clamp(50.0, double.infinity).toDouble();
    final sanitized = points
        .map((p) => AutomationPoint(
              x: p.x.clamp(0.0, safeLength).toDouble(),
              volume: p.volume.clamp(0.0, 1.0).toDouble(),
            ))
        .toList(growable: false)
      ..sort((a, b) => a.x.compareTo(b.x));

    if (sanitized.isEmpty) {
      final fallback = fallbackValue.clamp(0.0, 1.0).toDouble();
      return <AutomationPoint>[
        AutomationPoint(x: 0.0, volume: fallback),
      ];
    }
    if (sanitized.length == 1) {
      final only = sanitized.first;
      return <AutomationPoint>[
        AutomationPoint(x: 0.0, volume: only.volume),
      ];
    }
    return sanitized;
  }

  List<AutomationClipSnapshot> _sanitizeAutomationClipsForTarget(
    int row,
    String targetId,
    List<AutomationClipSnapshot> clips,
  ) {
    final maxMs = _maxAutomationTimelineMs();
    final fallbackValue = targetId == 'volume' ? 0.75 : 0.5;
    final targetLabel = _automationTargetLabelFor(row, targetId);
    final seenIds = <String>{};
    int idCounter = 0;

    final out = <AutomationClipSnapshot>[];
    for (final clip in clips) {
      final safeLength = _clampAutomationLengthMs(clip.lengthMs);
      final maxStart = math.max(0.0, maxMs - safeLength);
      final safeStart = clip.startMs.clamp(0.0, maxStart).toDouble();
      final safeVisualRow =
          clip.row.clamp(0, math.max(0, _rowCount - 1)).toInt();

      var id = clip.id.trim();
      if (id.isEmpty || seenIds.contains(id)) {
        id = 'ac_${row}_${targetId}_${idCounter}_${const Uuid().v4()}';
      }
      idCounter++;
      seenIds.add(id);

      final safePoints = _sanitizeAutomationClipPointsRelative(
        safeLength,
        clip.points,
        fallbackValue: fallbackValue,
      );

      out.add(
        clip.copyWith(
          id: id,
          row: safeVisualRow,
          targetId: targetId,
          lane: math.max(0, clip.lane).toInt(),
          label: clip.label.trim().isEmpty ? targetLabel : clip.label.trim(),
          startMs: safeStart,
          lengthMs: safeLength,
          points: safePoints,
        ),
      );
    }

    out.sort((a, b) {
      final timeCmp = a.startMs.compareTo(b.startMs);
      if (timeCmp != 0) return timeCmp;
      return a.id.compareTo(b.id);
    });
    return out;
  }

  int _defaultAutomationClipRowForSourceRow(int row) {
    if (_rowCount <= 0) return 0;
    return (row + 1).clamp(0, _rowCount - 1).toInt();
  }

  int _preferredAutomationClipRowForTarget(int row, String targetId) {
    if (!_isMasterAutomationTarget(targetId) || _rowCount <= 0) {
      return _defaultAutomationClipRowForSourceRow(row);
    }
    final occupiedRows = _audioTracks
        .map((clip) => clip.rowIndex)
        .where((rowIndex) => rowIndex >= 0 && rowIndex < _rowCount)
        .toSet();
    for (int candidate = 0; candidate < _rowCount; candidate++) {
      if (!occupiedRows.contains(candidate)) {
        return candidate;
      }
    }
    return 0;
  }

  List<AutomationPoint> _pointsForAutomationTarget(int row, String targetId) {
    if (row < 0 || row >= _rowCount) return const <AutomationPoint>[];
    if (targetId == 'volume') return _rowVolumeAutomation[row];
    final rowMap = _rowPluginAutomation[row];
    final existing = rowMap?[targetId];
    if (existing != null) return existing;
    return _defaultAutomationPointsForTarget(row, targetId);
  }

  List<AutomationPoint>? _storedAutomationPointsForTargetOrNull(
    int row,
    String targetId,
  ) {
    if (row < 0 || row >= _rowCount) return null;
    if (targetId == 'volume') return _rowVolumeAutomation[row];
    return _rowPluginAutomation[row]?[targetId];
  }

  bool _hasExplicitAutomationForTarget(int row, String targetId) {
    if (targetId == 'volume') return true;
    if (_isMasterAutomationTarget(targetId)) {
      for (int sourceRow = 0; sourceRow < _rowCount; sourceRow++) {
        final lanePoints = _rowPluginAutomation[sourceRow]?[targetId];
        if (lanePoints != null && lanePoints.isNotEmpty) {
          return true;
        }
        final clips = _rowAutomationClips[sourceRow]?[targetId];
        if (clips != null && clips.isNotEmpty) {
          return true;
        }
      }
      return false;
    }
    final lanePoints = _rowPluginAutomation[row]?[targetId];
    if (lanePoints != null && lanePoints.isNotEmpty) {
      return true;
    }
    final clips = _rowAutomationClips[row]?[targetId];
    return clips != null && clips.isNotEmpty;
  }

  bool _hasUserAutomationDataForTarget(int row, String targetId) {
    if (row < 0 || row >= _rowCount) return false;

    if (targetId == 'volume') {
      final points = _rowVolumeAutomation[row];
      if (points.length > 1) return true;
      if (points.isNotEmpty && (points.first.volume - 0.75).abs() > 1e-6) {
        return true;
      }
      final clips = _rowAutomationClips[row]?['volume'];
      return clips != null && clips.isNotEmpty;
    }

    return _hasExplicitAutomationForTarget(row, targetId);
  }

  bool _isMasterAutomationTarget(String targetId) {
    return _parseAutomationTargetId(targetId).isMaster;
  }

  _AutomationTargetMeta? _automationTargetMetaFromAnyRow(String targetId) {
    for (int row = 0; row < _rowCount; row++) {
      final meta = _rowAutomationTargets[row]?[targetId];
      if (meta != null) return meta;
    }
    return null;
  }

  List<AutomationPoint> _evaluationAutomationLanePointsForTarget(
    int row,
    String targetId,
  ) {
    if (!_isMasterAutomationTarget(targetId)) {
      return _sanitizeAutomationPointsForTarget(
        row,
        targetId,
        _pointsForAutomationTarget(row, targetId),
      );
    }

    for (int sourceRow = 0; sourceRow < _rowCount; sourceRow++) {
      final explicit =
          _storedAutomationPointsForTargetOrNull(sourceRow, targetId);
      if (explicit == null) continue;
      return _sanitizeAutomationPointsForTarget(
        sourceRow,
        targetId,
        explicit,
      );
    }

    return _sanitizeAutomationPointsForTarget(
      row,
      targetId,
      _defaultAutomationPointsForTarget(row, targetId),
    );
  }

  List<AutomationClipSnapshot> _evaluationAutomationClipsForTarget(
    int row,
    String targetId,
  ) {
    if (!_isMasterAutomationTarget(targetId)) {
      return _sanitizeAutomationClipsForTarget(
        row,
        targetId,
        _clipsForAutomationTarget(row, targetId),
      );
    }

    final combined = <AutomationClipSnapshot>[];
    for (int sourceRow = 0; sourceRow < _rowCount; sourceRow++) {
      final safe = _sanitizeAutomationClipsForTarget(
        sourceRow,
        targetId,
        _clipsForAutomationTarget(sourceRow, targetId),
      );
      combined.addAll(safe.map((clip) => clip.copyWith()));
    }
    combined.sort((a, b) {
      final timeCmp = a.startMs.compareTo(b.startMs);
      if (timeCmp != 0) return timeCmp;
      final laneCmp = a.lane.compareTo(b.lane);
      if (laneCmp != 0) return laneCmp;
      final rowCmp = a.row.compareTo(b.row);
      if (rowCmp != 0) return rowCmp;
      return a.id.compareTo(b.id);
    });
    return combined;
  }

  List<AutomationPoint> _sanitizeAutomationPointsForTarget(
    int row,
    String targetId,
    List<AutomationPoint> points,
  ) {
    final maxMs = _maxAutomationTimelineMs();
    final sanitized = points
        .map((p) => AutomationPoint(
              x: p.x.clamp(0.0, maxMs).toDouble(),
              volume: p.volume.clamp(0.0, 1.0).toDouble(),
            ))
        .toList(growable: false)
      ..sort((a, b) => a.x.compareTo(b.x));

    if (sanitized.isEmpty) {
      final defaults = _defaultAutomationPointsForTarget(row, targetId);
      return defaults.map((p) => p.copy()).toList(growable: false);
    }

    if (sanitized.length == 1) {
      final only = sanitized.first;
      return <AutomationPoint>[
        AutomationPoint(x: 0.0, volume: only.volume),
      ];
    }
    return sanitized;
  }

  double _evaluateAutomationClipAtRelativeMs(
    AutomationClipSnapshot clip,
    double relativeMs, {
    double fallback = 0.5,
  }) {
    final safeRel = relativeMs.clamp(0.0, clip.lengthMs).toDouble();
    return _evaluateAutomationAtMs(clip.points, safeRel, fallback: fallback);
  }

  double _resolvedAutomationValueAtMs(
    int row,
    String targetId,
    double timeMs, {
    List<AutomationPoint>? lanePointsOverride,
    List<AutomationClipSnapshot>? clipOverride,
  }) {
    final lanePoints = lanePointsOverride ??
        _evaluationAutomationLanePointsForTarget(row, targetId);
    final baseValue = _evaluateAutomationAtMs(
      lanePoints,
      timeMs,
      fallback: targetId == 'volume' ? 0.75 : 0.5,
    );

    final clips =
        clipOverride ?? _evaluationAutomationClipsForTarget(row, targetId);
    if (clips.isEmpty) return baseValue;

    final active = activeAutomationClipAtTime(clips, timeMs);
    if (active == null) return baseValue;
    final rel = timeMs - active.startMs;
    return _evaluateAutomationClipAtRelativeMs(
      active,
      rel,
      fallback: baseValue,
    );
  }

  List<AutomationPoint> _resolvedAutomationPointsForTarget(
    int row,
    String targetId,
  ) {
    final maxMs = _maxAutomationTimelineMs();
    final lanePoints = _evaluationAutomationLanePointsForTarget(row, targetId);
    final clips = _evaluationAutomationClipsForTarget(row, targetId);
    if (clips.isEmpty) {
      return lanePoints.map((p) => p.copy()).toList(growable: false);
    }

    final times = <double>{0.0, maxMs};
    for (final p in lanePoints) {
      times.add(p.x.clamp(0.0, maxMs).toDouble());
    }
    for (final clip in clips) {
      final start = clip.startMs.clamp(0.0, maxMs).toDouble();
      final end = (clip.startMs + clip.lengthMs).clamp(0.0, maxMs).toDouble();
      if (end <= start) continue;
      times.add(start);
      times.add(end);
      times.add((start - 0.001).clamp(0.0, maxMs).toDouble());
      times.add((end + 0.001).clamp(0.0, maxMs).toDouble());
      for (final p in clip.points) {
        final abs = (clip.startMs + p.x).clamp(start, end).toDouble();
        times.add(abs);
      }
    }

    final sortedTimes = times.toList(growable: false)..sort();
    final out = <AutomationPoint>[];
    double? lastX;
    double? lastValue;
    for (final t in sortedTimes) {
      final x = t.clamp(0.0, maxMs).toDouble();
      if (lastX != null && (x - lastX).abs() < 1e-7) {
        continue;
      }
      final value = _resolvedAutomationValueAtMs(
        row,
        targetId,
        x,
        lanePointsOverride: lanePoints,
        clipOverride: clips,
      ).clamp(0.0, 1.0);
      if (lastValue != null && lastX != null) {
        final unchanged = (value - lastValue).abs() < 1e-7;
        if (unchanged && (x - lastX).abs() < 0.0005) {
          continue;
        }
      }
      out.add(AutomationPoint(x: x, volume: value.toDouble()));
      lastX = x;
      lastValue = value.toDouble();
    }

    return _sanitizeAutomationPointsForTarget(row, targetId, out);
  }

  double _evaluateAutomationAtMs(
    List<AutomationPoint> points,
    double timeMs, {
    double fallback = 0.5,
  }) {
    if (points.isEmpty) return fallback;
    if (timeMs <= points.first.x) return points.first.volume;
    if (timeMs >= points.last.x) return points.last.volume;
    for (int i = 0; i < points.length - 1; i++) {
      final a = points[i];
      final b = points[i + 1];
      if (timeMs < a.x || timeMs > b.x) continue;
      final span = (b.x - a.x).abs();
      if (span < 1e-6) return b.volume;
      final t = ((timeMs - a.x) / (b.x - a.x)).clamp(0.0, 1.0);
      return a.volume + ((b.volume - a.volume) * t);
    }
    return points.last.volume;
  }

  Future<void> _syncAutomationTargetToCurrentTime(
    int row,
    String targetId,
  ) async {
    if (targetId == 'volume') return;
    if (!_hasExplicitAutomationForTarget(row, targetId)) return;
    final target = _rowAutomationTargets[row]?[targetId] ??
        _automationTargetMetaFromAnyRow(targetId) ??
        _fallbackAutomationTargetMeta(targetId);
    if (target.isVolume) return;
    final parsed = _parseAutomationTargetId(targetId);
    final timeMs = _globalAudioClock.inMilliseconds.toDouble();
    final normalized = _resolvedAutomationValueAtMs(
      row,
      targetId,
      timeMs,
    ).clamp(0.0, 1.0);
    final value = _denormalizeAutomationValue(normalized, target);
    if (parsed.isMaster) {
      if (parsed.isMixParameter) {
        switch (parsed.mixParamId.trim().toLowerCase()) {
          case 'gain':
            await JuceAudioEngine.setMasterGain(value);
            break;
          case 'pan':
            await JuceAudioEngine.setMasterPan(value);
            break;
          default:
            break;
        }
      } else if (parsed.isEffectParameter && target.effectIndex >= 0) {
        await JuceAudioEngine.setMasterEffect(
          target.effectIndex,
          target.paramId,
          value,
        );
      }
    } else if (parsed.isMixParameter) {
      switch (parsed.mixParamId.trim().toLowerCase()) {
        case 'gain':
          await JuceAudioEngine.setRowGain(row, value);
          break;
        case 'pan':
          await JuceAudioEngine.setRowPan(row, value);
          break;
        default:
          break;
      }
    } else if (parsed.isEffectParameter && target.effectIndex >= 0) {
      await JuceAudioEngine.setTrackEffect(
        row,
        target.effectIndex,
        target.paramId,
        value,
      );
    }
    _lastAppliedAutomationNormalized['$row|$targetId'] = normalized.toDouble();
  }

  Future<void> _setAutomationTargetPointsWithUndo(
    int row,
    String targetId,
    List<AutomationPoint> newPoints, {
    List<AutomationPoint>? oldPointsOverride,
  }) async {
    if (row < 0 || row >= _rowCount) return;
    if (targetId == 'volume') {
      await _setRowAutomationWithUndo(row, newPoints);
      return;
    }

    final oldPoints =
        (oldPointsOverride ?? _pointsForAutomationTarget(row, targetId))
            .map((p) => p.copy())
            .toList(growable: false);
    final safePoints =
        _sanitizeAutomationPointsForTarget(row, targetId, newPoints);

    await _undoManager.execute(
      SetTargetAutomationPointsAction(
        row: row,
        targetId: targetId,
        oldPoints: oldPoints,
        newPoints: safePoints,
        applyToState: (r, laneId, points) {
          setState(() {
            final rowMap = _rowPluginAutomation.putIfAbsent(
                r, () => <String, List<AutomationPoint>>{});
            rowMap[laneId] =
                points.map((p) => p.copy()).toList(growable: false);
          });
        },
        onApplied: (r, laneId, _) async {
          _lastAppliedAutomationNormalized.remove('$r|$laneId');
          await _syncNativePluginAutomationForRow(r);
          await _syncAutomationTargetToCurrentTime(r, laneId);
        },
      ),
    );
  }

  List<AutomationLaneSnapshot> _automationLanesForRowSave(int row) {
    if (row < 0 || row >= _rowCount) return const <AutomationLaneSnapshot>[];
    final lanes = <AutomationLaneSnapshot>[];
    final addedTargetIds = <String>{};

    final volumePoints = _sanitizeAutomationPointsForTarget(
      row,
      'volume',
      _rowVolumeAutomation[row],
    );
    lanes.add(_volumeAutomationTargetMeta().toLaneSnapshot(volumePoints));
    addedTargetIds.add('volume');

    final rowPlugin =
        _rowPluginAutomation[row] ?? const <String, List<AutomationPoint>>{};
    final targets =
        _rowAutomationTargets[row] ?? const <String, _AutomationTargetMeta>{};
    rowPlugin.forEach((targetId, points) {
      if (targetId == 'volume') return;
      final safePoints =
          _sanitizeAutomationPointsForTarget(row, targetId, points);
      if (safePoints.isEmpty) return;
      final target =
          targets[targetId] ?? _fallbackAutomationTargetMeta(targetId);
      lanes.add(target.toLaneSnapshot(safePoints));
      addedTargetIds.add(targetId);
    });

    // Persist metadata for clip-only targets so target remapping can recover
    // plugin automation when effect instance ids change between sessions.
    final clipTargets = _rowAutomationClips[row] ??
        const <String, List<AutomationClipSnapshot>>{};
    for (final entry in clipTargets.entries) {
      final targetId = entry.key;
      if (targetId == 'volume' || addedTargetIds.contains(targetId)) continue;
      if (entry.value.isEmpty) continue;
      final target =
          targets[targetId] ?? _fallbackAutomationTargetMeta(targetId);
      final seedPoints = _defaultAutomationPointsForTarget(row, targetId);
      final safePoints =
          _sanitizeAutomationPointsForTarget(row, targetId, seedPoints);
      lanes.add(target.toLaneSnapshot(safePoints));
      addedTargetIds.add(targetId);
    }

    return lanes;
  }

  void _restoreAutomationLanesForRow(
    int row,
    List<AutomationLaneSnapshot> lanes, {
    String? selectedTargetId,
  }) {
    if (row < 0 || row >= _rowCount) return;
    final rowPlugin = <String, List<AutomationPoint>>{};
    final rowTargets = <String, _AutomationTargetMeta>{
      'volume': _volumeAutomationTargetMeta(),
    };

    for (final lane in lanes) {
      final targetId = lane.targetId.trim();
      if (targetId.isEmpty) continue;
      final safePoints = _sanitizeAutomationPointsForTarget(
        row,
        targetId,
        lane.points.map((p) => p.copy()).toList(growable: false),
      );
      if (targetId == 'volume') {
        _rowVolumeAutomation[row] = safePoints;
        continue;
      }
      rowPlugin[targetId] = safePoints;
      rowTargets[targetId] = _AutomationTargetMeta.fromLaneSnapshot(lane);
    }

    _rowPluginAutomation[row] = rowPlugin;
    _rowAutomationTargets[row] = rowTargets;
    final fallbackTarget = rowTargets.containsKey('volume')
        ? 'volume'
        : (rowTargets.keys.isNotEmpty ? rowTargets.keys.first : 'volume');
    _rowSelectedAutomationTarget[row] =
        (selectedTargetId != null && rowTargets.containsKey(selectedTargetId))
            ? selectedTargetId
            : fallbackTarget;
  }

  List<AutomationClipSnapshot> _automationClipsForRowSave(int row) {
    if (row < 0 || row >= _rowCount) {
      return const <AutomationClipSnapshot>[];
    }
    final rowMap = _rowAutomationClips[row] ??
        const <String, List<AutomationClipSnapshot>>{};
    final out = <AutomationClipSnapshot>[];
    for (final entry in rowMap.entries) {
      final targetId = entry.key;
      final safe = _sanitizeAutomationClipsForTarget(
        row,
        targetId,
        entry.value,
      );
      out.addAll(safe.map((clip) => clip.copyWith()));
    }
    out.sort((a, b) {
      final targetCmp = a.targetId.compareTo(b.targetId);
      if (targetCmp != 0) return targetCmp;
      final laneCmp = a.lane.compareTo(b.lane);
      if (laneCmp != 0) return laneCmp;
      final timeCmp = a.startMs.compareTo(b.startMs);
      if (timeCmp != 0) return timeCmp;
      return a.id.compareTo(b.id);
    });
    return out;
  }

  List<AutomationLaneSnapshot> _pluginAutomationLanesForRowSave(int row) {
    return _automationLanesForRowSave(row)
        .where((lane) => lane.targetId != 'volume')
        .map(
          (lane) => AutomationLaneSnapshot(
            targetId: lane.targetId,
            label: lane.label,
            effectIndex: lane.effectIndex,
            paramId: lane.paramId,
            type: lane.type,
            min: lane.min,
            max: lane.max,
            points: lane.points.map((point) => point.copy()).toList(
                  growable: false,
                ),
          ),
        )
        .toList(growable: false);
  }

  List<AutomationClipSnapshot> _pluginAutomationClipsForRowSave(int row) {
    return _automationClipsForRowSave(row)
        .where((clip) => clip.targetId != 'volume')
        .map((clip) => clip.copyWith())
        .toList(growable: false);
  }

  void _restoreAutomationClipsForRow(
    int row,
    List<AutomationClipSnapshot> clips,
  ) {
    if (row < 0 || row >= _rowCount) return;
    final grouped = <String, List<AutomationClipSnapshot>>{};
    for (final clip in clips) {
      final targetId = clip.targetId.trim().isEmpty ? 'volume' : clip.targetId;
      grouped.putIfAbsent(targetId, () => <AutomationClipSnapshot>[]).add(
            clip.copyWith(
              targetId: targetId,
            ),
          );
    }

    final sanitized = <String, List<AutomationClipSnapshot>>{};
    for (final entry in grouped.entries) {
      sanitized[entry.key] = _sanitizeAutomationClipsForTarget(
        row,
        entry.key,
        entry.value,
      );
    }
    _rowAutomationClips[row] = sanitized;
  }

  Future<_CopiedRowEffectsEntry> _captureCopiedRowEffectsEntry(int row) async {
    return _CopiedRowEffectsEntry(
      effects: await captureRowSnapshot(row, rowId: _rowIdAt(row)),
      automationLanes: _pluginAutomationLanesForRowSave(row),
      automationClips: _pluginAutomationClipsForRowSave(row),
      selectedAutomationTargetId: _selectedAutomationTargetIdForRow(row),
    );
  }

  Future<void> _applyCopiedRowEffectsEntry(
    int row,
    _CopiedRowEffectsEntry entry,
  ) async {
    if (row < 0 || row >= _rowCount) return;

    await restoreRowSnapshot(
      RowEffectsSnapshot(
        row,
        entry.effects.effects,
        rowId: _rowIdAt(row),
      ),
    );

    final preservedVolume = _rowVolumeAutomation[row]
        .map((point) => point.copy())
        .toList(growable: false);
    final lanes = <AutomationLaneSnapshot>[
      _volumeAutomationTargetMeta().toLaneSnapshot(preservedVolume),
      ...entry.automationLanes.map(
        (lane) => AutomationLaneSnapshot(
          targetId: lane.targetId,
          label: lane.label,
          effectIndex: lane.effectIndex,
          paramId: lane.paramId,
          type: lane.type,
          min: lane.min,
          max: lane.max,
          points: lane.points.map((point) => point.copy()).toList(
                growable: false,
              ),
        ),
      ),
    ];

    setState(() {
      _restoreAutomationLanesForRow(
        row,
        lanes,
        selectedTargetId: entry.selectedAutomationTargetId,
      );
      _restoreAutomationClipsForRow(row, entry.automationClips);
    });

    await _refreshAutomationTargetsForRow(
      row,
      setStateWhenDone: false,
      syncNativeWhenDone: false,
    );
    await _syncNativeAutomationForRow(row);
    _refreshRowFx(row);
    if (mounted) setState(() {});
  }

  Future<void> _copyRowEffects(int row) async {
    if (row < 0 || row >= _rowCount) return;
    final snapshot = await _captureCopiedRowEffectsEntry(row);
    final clipboard = _EffectsClipboardEntry(
      effects: snapshot.effects.effects
          .map(
            (fx) => EffectSnapshot(
              fx.effectId,
              fx.bypassed,
              Map<String, dynamic>.from(fx.params),
            ),
          )
          .toList(growable: false),
      automationLanes: snapshot.automationLanes
          .map(
            (lane) => AutomationLaneSnapshot(
              targetId: lane.targetId,
              label: lane.label,
              effectIndex: lane.effectIndex,
              paramId: lane.paramId,
              type: lane.type,
              min: lane.min,
              max: lane.max,
              points: lane.points.map((point) => point.copy()).toList(
                    growable: false,
                  ),
            ),
          )
          .toList(growable: false),
      automationClips: snapshot.automationClips
          .map((clip) => clip.copyWith())
          .toList(growable: false),
      selectedAutomationTargetId: snapshot.selectedAutomationTargetId,
    );
    if (mounted) {
      setState(() {
        _copiedEffects = clipboard;
      });
    } else {
      _copiedEffects = clipboard;
    }
    _showSmallNotice('Copied row effects.');
  }

  Future<void> _pasteRowEffects(int row) async {
    if (row < 0 || row >= _rowCount) return;
    final clipboard = _copiedEffects;
    if (clipboard == null) {
      _showSmallNotice('Copy effects first.');
      return;
    }

    final before = await _captureCopiedRowEffectsEntry(row);
    final after = _CopiedRowEffectsEntry(
      effects: RowEffectsSnapshot(
        row,
        clipboard.effects
            .map(
              (fx) => EffectSnapshot(
                fx.effectId,
                fx.bypassed,
                Map<String, dynamic>.from(fx.params),
              ),
            )
            .toList(growable: false),
        rowId: _rowIdAt(row),
      ),
      automationLanes: clipboard.automationLanes
          .map(
            (lane) => AutomationLaneSnapshot(
              targetId: lane.targetId,
              label: lane.label,
              effectIndex: lane.effectIndex,
              paramId: lane.paramId,
              type: lane.type,
              min: lane.min,
              max: lane.max,
              points: lane.points.map((point) => point.copy()).toList(
                    growable: false,
                  ),
            ),
          )
          .toList(growable: false),
      automationClips:
          clipboard.automationClips.map((clip) => clip.copyWith()).toList(
                growable: false,
              ),
      selectedAutomationTargetId: clipboard.selectedAutomationTargetId,
    );

    await _undoManager.execute(
      _RowEffectsAutomationSnapshotAction(
        descriptionText: 'Paste track effects',
        before: before,
        after: after,
        applySnapshot: (snap) => _applyCopiedRowEffectsEntry(row, snap),
      ),
    );
    _recordProducerManualEdit('row_fx_paste', <String, Object?>{
      'row': row,
      'effect_count': after.effects.effects.length,
      'automation_lane_count': after.automationLanes.length,
      'automation_clip_count': after.automationClips.length,
    });
    _showSmallNotice('Pasted row effects.');
  }

  Future<void> _clearRowEffects(int row) async {
    if (row < 0 || row >= _rowCount) return;
    final before = await _captureCopiedRowEffectsEntry(row);
    final hasEffects = before.effects.effects.isNotEmpty;
    final hasAutomation =
        before.automationLanes.isNotEmpty || before.automationClips.isNotEmpty;
    if (!hasEffects && !hasAutomation) {
      _showSmallNotice('This row has no effects to clear.');
      return;
    }

    await _undoManager.execute(
      _RowEffectsAutomationSnapshotAction(
        descriptionText: 'Clear track effects',
        before: before,
        after: _CopiedRowEffectsEntry(
          effects: RowEffectsSnapshot(row, const <EffectSnapshot>[],
              rowId: _rowIdAt(row)),
          automationLanes: const <AutomationLaneSnapshot>[],
          automationClips: const <AutomationClipSnapshot>[],
          selectedAutomationTargetId: 'volume',
        ),
        applySnapshot: (snap) => _applyCopiedRowEffectsEntry(row, snap),
      ),
    );
    _recordProducerManualEdit('row_fx_clear', <String, Object?>{
      'row': row,
      'effect_count': before.effects.effects.length,
      'automation_lane_count': before.automationLanes.length,
      'automation_clip_count': before.automationClips.length,
    });
    _showSmallNotice('Cleared row effects.');
  }

