  Future<void> _setAutomationClipsForTargetWithUndo(
    int row,
    String targetId,
    List<AutomationClipSnapshot> newClips, {
    List<AutomationClipSnapshot>? oldClipsOverride,
  }) async {
    if (row < 0 || row >= _rowCount) return;
    final oldClips = _copyAutomationClipList(
      oldClipsOverride ?? _clipsForAutomationTarget(row, targetId),
    );
    final safeClips =
        _sanitizeAutomationClipsForTarget(row, targetId, newClips);
    if (safeClips.isNotEmpty) {
      await _ensureAutomationClipDisplayRowExists(row);
    }

    await _undoManager.execute(
      SetTargetAutomationClipsAction(
        row: row,
        targetId: targetId,
        oldClips: oldClips,
        newClips: safeClips,
        applyToState: (r, laneId, clips) {
          setState(() {
            final rowMap = _rowAutomationClips.putIfAbsent(
                r, () => <String, List<AutomationClipSnapshot>>{});
            rowMap[laneId] = _copyAutomationClipList(clips);
          });
        },
        onApplied: (r, _, __) async {
          await _syncNativeAutomationForRow(r);
        },
      ),
    );
  }

  Future<void> _ensureAutomationClipDisplayRowExists(int sourceRow) async {
    if (sourceRow < 0 || sourceRow >= _rowCount) return;
    if (sourceRow + 1 < _rowCount) return;
    if (_rowCount >= kMaxRows) return;
    await _addRowImpl();
  }

  Future<void> _ensureLoadedAutomationDisplayRowsExist() async {
    if (_rowCount <= 0 || _rowCount >= kMaxRows) return;
    final lastRow = _rowCount - 1;
    final rowMap = _rowAutomationClips[lastRow];
    if (rowMap == null) return;
    final hasAutomationClips = rowMap.values.any((clips) => clips.isNotEmpty);
    if (!hasAutomationClips) return;
    await _addRowImpl();
  }

  void _triggerMasterHalos(List<String> haloKeys) {
    final mapped = haloKeys
        .map((key) => key.trim())
        .where((key) => key.isNotEmpty)
        .map(HaloKey.new)
        .toList(growable: false);
    if (mapped.isEmpty) return;
    _mixHighlighter.trigger(mapped,
        duration: const Duration(milliseconds: 800));
  }

  String? _findAutomationTargetIdForEffectParameter({
    required int effectIndex,
    required String paramId,
    required bool master,
    int? row,
  }) {
    final normalizedParamId = paramId.trim();
    if (normalizedParamId.isEmpty) return null;

    Iterable<int> candidateRows;
    if (master) {
      candidateRows = List<int>.generate(_rowCount, (i) => i);
    } else {
      if (row == null || row < 0 || row >= _rowCount) return null;
      candidateRows = <int>[row];
    }

    for (final candidateRow in candidateRows) {
      final targets = _rowAutomationTargets[candidateRow];
      if (targets == null) continue;
      for (final entry in targets.entries) {
        if (entry.value.isOrphan) continue;
        final parsed = _parseAutomationTargetId(entry.key);
        if (parsed.isMaster != master) continue;
        if (entry.value.effectIndex != effectIndex) continue;
        if (entry.value.paramId.trim() != normalizedParamId) continue;
        return entry.key;
      }
    }
    return null;
  }

  double _normalizeAutomationTargetValue(
    _AutomationTargetMeta target,
    dynamic value,
  ) {
    final fallback = target.initialNormalized.clamp(0.0, 1.0).toDouble();
    switch (target.type.trim().toLowerCase()) {
      case 'bool':
        if (value is bool) return value ? 1.0 : 0.0;
        final numeric = _toActionDouble(value);
        if (numeric != null) {
          return numeric >= 0.5 ? 1.0 : 0.0;
        }
        return fallback;
      case 'choice':
        final numeric = _toActionDouble(value);
        if (numeric != null) {
          return numeric.clamp(0.0, 1.0).toDouble();
        }
        return fallback;
      default:
        final numeric = _toActionDouble(value);
        return _normalizeAutomationValue(
          numeric,
          min: target.min,
          max: target.max,
          fallback: fallback,
        );
    }
  }

  void _updateAutomationTargetBaselineForEffectParameter({
    required int effectIndex,
    required String paramId,
    required dynamic value,
    required bool master,
    int? row,
  }) {
    final targetId = _findAutomationTargetIdForEffectParameter(
      effectIndex: effectIndex,
      paramId: paramId,
      master: master,
      row: row,
    );
    if (targetId == null || targetId.isEmpty) return;

    final candidateRows = master
        ? List<int>.generate(_rowCount, (index) => index)
        : <int>[if (row != null) row];
    for (final candidateRow in candidateRows) {
      if (candidateRow < 0 || candidateRow >= _rowCount) continue;
      final rowTargets = _rowAutomationTargets[candidateRow];
      final target = rowTargets?[targetId];
      if (target == null) continue;
      final normalized = _normalizeAutomationTargetValue(target, value);
      rowTargets![targetId] = target.copyWith(initialNormalized: normalized);
    }
  }

  Future<void> _createAutomationClipForTarget({
    required int row,
    required String targetId,
    String? label,
    int lane = 0,
    double? startMs,
    double? lengthMs,
    double? initialNormalized,
  }) async {
    if (row < 0 || row >= _rowCount) return;
    final targetMeta = _rowAutomationTargets[row]?[targetId] ??
        _automationTargetMetaFromAnyRow(targetId) ??
        _fallbackAutomationTargetMeta(targetId);
    final clipLabel = (label ?? targetMeta.label).trim();
    final safeStartMs = (startMs ?? _globalAudioClock.inMilliseconds.toDouble())
        .clamp(0.0, _maxAutomationTimelineMs())
        .toDouble();
    final safeLengthMs = _clampAutomationLengthMs(
      lengthMs ?? _defaultAutomationClipLengthMs(),
    );
    final normalized = (initialNormalized ?? targetMeta.initialNormalized)
        .clamp(0.0, 1.0)
        .toDouble();
    final before = _copyAutomationClipList(
      _clipsForAutomationTarget(row, targetId),
    );
    final next = <AutomationClipSnapshot>[
      ...before.map((clip) => clip.copyWith()),
      AutomationClipSnapshot(
        id: _newAutomationClipId(row, targetId),
        targetId: targetId,
        label: clipLabel.isEmpty ? targetId : clipLabel,
        row: _preferredAutomationClipRowForTarget(row, targetId),
        lane: math.max(0, lane),
        startMs: safeStartMs,
        lengthMs: safeLengthMs,
        muted: false,
        points: <AutomationPoint>[
          AutomationPoint(x: 0.0, volume: normalized),
        ],
      ),
    ];
    setState(() {
      _rowSelectedAutomationTarget[row] = targetId;
    });
    await _setAutomationClipsForTargetWithUndo(
      row,
      targetId,
      next,
      oldClipsOverride: before,
    );
    _showSmallNotice('Created automation clip.');
  }

  Future<void> _requestMasterMixAutomationClip(String paramId) async {
    if (_rowCount <= 0) {
      _showSmallNotice('Add a row before creating automation clips.');
      return;
    }
    final row = _selectedRow.clamp(0, _rowCount - 1).toInt();
    final targetId = _masterMixAutomationTargetId(paramId);
    final label = switch (paramId.trim().toLowerCase()) {
      'gain' => 'Master Gain',
      'pan' => 'Master Pan',
      _ => 'Master ${paramId.trim()}',
    };
    await _createAutomationClipForTarget(
      row: row,
      targetId: targetId,
      label: label,
    );
  }

  Future<void> _requestMasterEffectAutomationClip(
    int effectIndex,
    String effectName,
    String paramId,
    String paramName,
  ) async {
    if (_rowCount <= 0) {
      _showSmallNotice('Add a row before creating automation clips.');
      return;
    }
    final row = _selectedRow.clamp(0, _rowCount - 1).toInt();
    await _refreshAutomationTargetsForRow(
      row,
      setStateWhenDone: false,
      syncNativeWhenDone: false,
    );
    final targetId = _findAutomationTargetIdForEffectParameter(
      effectIndex: effectIndex,
      paramId: paramId,
      master: true,
    );
    if (targetId == null || targetId.isEmpty) {
      _showSmallNotice('Could not resolve that automation target.');
      return;
    }
    final targetMeta = _automationTargetMetaFromAnyRow(targetId);
    final resolvedLabel = (targetMeta?.label ?? '').trim();
    final label = resolvedLabel.isNotEmpty
        ? resolvedLabel
        : (effectName.trim().isEmpty
            ? paramName.trim()
            : 'Master • ${effectName.trim()} • ${paramName.trim()}');
    await _createAutomationClipForTarget(
      row: row,
      targetId: targetId,
      label: label.trim().isEmpty ? targetId : label,
    );
  }

  Future<void> _revealMasterAutomationTarget(String targetId) async {
    final parsed = _parseAutomationTargetId(targetId);
    final targetMeta = _automationTargetMetaFromAnyRow(targetId) ??
        _fallbackAutomationTargetMeta(targetId);
    setState(() {
      _setActiveTopPopup(_TopPopupType.master);
    });
    await Future<void>.delayed(const Duration(milliseconds: 40));
    if (!mounted) return;

    if (parsed.isMixParameter) {
      _masterRackContentKey.currentState?.showVolumeTab();
      switch (parsed.mixParamId.trim().toLowerCase()) {
        case 'gain':
          _triggerMasterHalos(<String>[
            'master:gain',
            'master:param:gain',
          ]);
          break;
        case 'pan':
          _triggerMasterHalos(<String>[
            'master:pan',
            'master:param:pan',
          ]);
          break;
      }
      return;
    }

    _masterRackContentKey.currentState?.showEffectsTab();
    if (targetMeta.isOrphan) {
      _showSmallNotice(
        'This automation clip is orphaned. Undo the plugin removal or re-add the plugin to relink it.',
      );
      return;
    }
    await Future<void>.delayed(const Duration(milliseconds: 40));
    if (!mounted) return;
    final revealer = _masterParameterRevealer;
    if (revealer != null &&
        targetMeta.effectIndex >= 0 &&
        targetMeta.paramId.trim().isNotEmpty) {
      await revealer(targetMeta.effectIndex, targetMeta.paramId);
    }
  }

  List<AutomationPoint> _sanitizeAutomationPoints(
    int row,
    List<AutomationPoint> points,
  ) {
    final maxMs =
        math.max(1.0, _audioOnlyOverallDuration.inMilliseconds.toDouble());
    final sanitized = points
        .map((p) => AutomationPoint(
              x: p.x.clamp(0.0, maxMs).toDouble(),
              volume: p.volume.clamp(0.0, 1.0).toDouble(),
            ))
        .toList()
      ..sort((a, b) => a.x.compareTo(b.x));

    if (sanitized.isEmpty) {
      return <AutomationPoint>[
        AutomationPoint(x: 0.0, volume: 1.0),
      ];
    }

    if (sanitized.length == 1) {
      final only = sanitized.first;
      return <AutomationPoint>[
        AutomationPoint(x: 0.0, volume: only.volume),
      ];
    }
    return sanitized;
  }

  Future<void> _setRowAutomationWithUndo(
    int row,
    List<AutomationPoint> newPoints,
  ) async {
    if (row < 0 || row >= _rowVolumeAutomation.length) return;
    final oldPoints = _rowVolumeAutomation[row]
        .map((p) => AutomationPoint(x: p.x, volume: p.volume))
        .toList(growable: false);
    final safePoints = _sanitizeAutomationPoints(row, newPoints);
    await _undoManager.execute(
      SetAutomationPointsAction(
        row: row,
        oldPoints: oldPoints,
        newPoints: safePoints,
        applyToState: (r, points) {
          setState(() {
            _rowVolumeAutomation[r] = points
                .map((p) => AutomationPoint(x: p.x, volume: p.volume))
                .toList();
          });
        },
        onApplied: (r, _) async {
          await _syncNativeAutomationForRow(r);
        },
      ),
    );
  }

  String? _resolveAutomationTargetIdFromAction(
    int row,
    Map<String, dynamic> data, {
    bool allowVolumeFallback = true,
  }) {
    final target = _actionTarget(data);
    final targets =
        _rowAutomationTargets[row] ?? const <String, _AutomationTargetMeta>{};
    if (targets.isEmpty) {
      return allowVolumeFallback ? 'volume' : null;
    }

    final scope = (data['scope'] ?? target['scope'] ?? '')
        .toString()
        .trim()
        .toLowerCase();
    final restrictToMaster = scope == 'master' ||
        scope == 'master_bus' ||
        scope == 'master-bus' ||
        scope == 'masterbus';
    final restrictToRow = scope == 'row' ||
        scope == 'track' ||
        scope == 'channel' ||
        scope == 'group' ||
        scope == 'bus';

    bool scopeAllowsTarget(_AutomationTargetMeta meta) {
      if (meta.isOrphan) return false;
      final isMasterTarget = _parseAutomationTargetId(meta.targetId).isMaster;
      if (restrictToMaster) return isMasterTarget;
      if (restrictToRow) return !isMasterTarget;
      return true;
    }

    String? pickTargetId(dynamic raw) {
      final id = (raw ?? '').toString().trim();
      if (id.isEmpty) return null;
      if (targets.containsKey(id)) {
        final exactMeta = targets[id]!;
        if (scopeAllowsTarget(exactMeta)) return id;
        return null;
      }
      final parsed = _parseAutomationTargetId(id);
      if (parsed.isVolume || id.toLowerCase() == 'volume') {
        if (restrictToMaster) return null;
        final volumeMeta = targets['volume'];
        return volumeMeta != null && scopeAllowsTarget(volumeMeta)
            ? 'volume'
            : null;
      }
      final parsedParamLower = parsed.paramId.trim().toLowerCase();
      if (parsedParamLower.isEmpty) return null;
      final pluginTargets = targets.values.where(
        (meta) => !meta.isVolume && scopeAllowsTarget(meta),
      );
      if (parsed.effectKey.isNotEmpty) {
        final byEffectKey = pluginTargets.where((meta) {
          final candidateParsed = _parseAutomationTargetId(meta.targetId);
          return candidateParsed.effectKey == parsed.effectKey &&
              meta.paramId.trim().toLowerCase() == parsedParamLower;
        }).toList(growable: false);
        if (byEffectKey.length == 1) {
          return byEffectKey.first.targetId;
        }
      }
      if (parsed.legacyEffectIndex >= 0) {
        final byLegacyIndex = pluginTargets
            .where((meta) =>
                meta.effectIndex == parsed.legacyEffectIndex &&
                meta.paramId.trim().toLowerCase() == parsedParamLower)
            .toList(growable: false);
        if (byLegacyIndex.length == 1) {
          return byLegacyIndex.first.targetId;
        }
      }
      return null;
    }

    bool matchesToken(String haystack, String needle) {
      final h = haystack.trim().toLowerCase();
      final n = needle.trim().toLowerCase();
      if (h.isEmpty || n.isEmpty) return false;
      return h.contains(n) || n.contains(h);
    }

    final explicit = pickTargetId(data['automation_target_id']) ??
        pickTargetId(target['automation_target_id']) ??
        pickTargetId(data['target_id']) ??
        pickTargetId(target['target_id']) ??
        pickTargetId(data['lane_id']) ??
        pickTargetId(target['lane_id']);
    if (explicit != null) return explicit;

    final effectIndex = _toActionInt(data['effect_index'] ??
        target['effect_index'] ??
        data['effect'] ??
        target['effect']);
    final paramId = (data['param_id'] ??
            target['param_id'] ??
            data['parameter_id'] ??
            target['parameter_id'] ??
            data['param'] ??
            target['param'])
        .toString()
        .trim();
    final paramName = (data['param_name'] ??
            target['param_name'] ??
            data['parameter'] ??
            target['parameter'] ??
            data['name'] ??
            target['name'])
        .toString()
        .trim()
        .toLowerCase();
    final effectName = (data['effect_name'] ??
            target['effect_name'] ??
            data['plugin_name'] ??
            target['plugin_name'] ??
            data['plugin'] ??
            target['plugin'] ??
            data['effect'] ??
            target['effect'])
        .toString()
        .trim()
        .toLowerCase();

    if (!restrictToMaster && effectIndex != null && paramId.isNotEmpty) {
      final byDirectId = _pluginAutomationTargetId(effectIndex, paramId);
      if (targets.containsKey(byDirectId) &&
          scopeAllowsTarget(targets[byDirectId]!)) {
        return byDirectId;
      }
    }

    int? resolvedEffectIndex = effectIndex;
    if (resolvedEffectIndex == null && effectName.isNotEmpty) {
      final matchingEffectIndices = targets.values
          .where((meta) {
            if (meta.isVolume || !scopeAllowsTarget(meta)) return false;
            return matchesToken(meta.label, effectName) ||
                matchesToken(meta.paramId, effectName);
          })
          .map((meta) => meta.effectIndex)
          .where((i) => i >= 0)
          .toSet()
          .toList(growable: false);
      if (matchingEffectIndices.length == 1) {
        resolvedEffectIndex = matchingEffectIndices.first;
      }
    }

    if (resolvedEffectIndex != null) {
      final scoped = targets.values
          .where((meta) =>
              !meta.isVolume &&
              scopeAllowsTarget(meta) &&
              meta.effectIndex == resolvedEffectIndex)
          .toList(growable: false);
      if (scoped.isNotEmpty) {
        if (paramId.isNotEmpty) {
          final lowered = paramId.toLowerCase();
          for (final meta in scoped) {
            if (meta.paramId.toLowerCase() == lowered) return meta.targetId;
          }
        }
        if (paramName.isNotEmpty) {
          for (final meta in scoped) {
            final label = meta.label.toLowerCase();
            final pid = meta.paramId.toLowerCase();
            if (matchesToken(label, paramName) ||
                matchesToken(pid, paramName)) {
              return meta.targetId;
            }
          }
        }
        if (scoped.length == 1) return scoped.first.targetId;
      }
    }

    if (paramId.isNotEmpty) {
      final lowered = paramId.toLowerCase();
      for (final meta in targets.values) {
        if (meta.isVolume || !scopeAllowsTarget(meta)) continue;
        if (meta.paramId.toLowerCase() == lowered) return meta.targetId;
      }
    }

    if (paramName.isNotEmpty) {
      for (final meta in targets.values) {
        if (meta.isVolume || !scopeAllowsTarget(meta)) continue;
        final label = meta.label.toLowerCase();
        final pid = meta.paramId.toLowerCase();
        if (matchesToken(label, paramName) || matchesToken(pid, paramName)) {
          return meta.targetId;
        }
      }
    }

    final pluginIntent = effectName.isNotEmpty ||
        resolvedEffectIndex != null ||
        paramId.isNotEmpty ||
        paramName.isNotEmpty;
    if (pluginIntent && !allowVolumeFallback) {
      return null;
    }

    if (restrictToMaster) {
      return null;
    }

    return 'volume';
  }

  bool _isPluginAutomationIntent(Map<String, dynamic> data) {
    final target = _actionTarget(data);

    bool hasField(String key) {
      final value = data[key] ?? target[key];
      if (value == null) return false;
      if (value is String) return value.trim().isNotEmpty;
      if (value is num) return true;
      return true;
    }

    if (hasField('automation_target_id') ||
        hasField('target_id') ||
        hasField('lane_id') ||
        hasField('effect_index') ||
        hasField('effect_name') ||
        hasField('plugin_name') ||
        hasField('plugin') ||
        hasField('param_id') ||
        hasField('parameter_id') ||
        hasField('param_name') ||
        hasField('parameter')) {
      final explicitTargetId = (data['automation_target_id'] ??
              target['automation_target_id'] ??
              data['target_id'] ??
              target['target_id'])
          .toString()
          .trim()
          .toLowerCase();
      if (explicitTargetId == 'volume') return false;
      return true;
    }

    final template = (data['template'] ??
            target['template'] ??
            data['pattern'] ??
            target['pattern'] ??
            '')
        .toString()
        .trim()
        .toLowerCase();
    if (template == 'filter_sweep' ||
        template == 'lowpass_sweep' ||
        template == 'highpass_sweep' ||
        template == 'reverb_tail') {
      return true;
    }

    return false;
  }

  double _normalizedActionValueForTarget(
    dynamic rawValue,
    _AutomationTargetMeta target, {
    String valueMode = '',
    double fallback = 0.5,
  }) {
    final raw = _toActionDouble(rawValue);
    if (raw == null) return fallback.clamp(0.0, 1.0).toDouble();
    if (target.isVolume) {
      return raw.clamp(0.0, 1.0).toDouble();
    }

    final mode = valueMode.trim().toLowerCase();
    if (mode == 'real' || mode == 'absolute' || mode == 'native') {
      return _normalizeAutomationValue(
        raw,
        min: target.min,
        max: target.max,
        fallback: fallback,
      );
    }
    if (mode == 'normalized' || mode == '0to1') {
      return raw.clamp(0.0, 1.0).toDouble();
    }

    if (raw < 0.0 || raw > 1.0) {
      return _normalizeAutomationValue(
        raw,
        min: target.min,
        max: target.max,
        fallback: fallback,
      );
    }
    return raw.clamp(0.0, 1.0).toDouble();
  }

  String _normalizeAutomationEditOperation(String raw) {
    // Legacy mapping reference: 'set' || 'replace' => 'set_points'
    switch (raw.trim().toLowerCase()) {
      case 'set':
      case 'replace':
        return 'set_points';
      case 'ramp':
      case 'curve':
      case 'add_curve':
        return 'add_ramp';
      case 'create':
      case 'add':
      case 'add_clip':
      case 'new_clip':
      case 'insert_clip':
      case 'create_clip':
        return 'create_clip';
      case 'duplicate':
      case 'clone':
      case 'clone_clip':
      case 'duplicate_clip':
        return 'duplicate_clip';
      case 'move':
      case 'move_clip':
        return 'move_clip';
      case 'remove_clip':
      case 'delete_clip':
        return 'delete_clip';
      case 'clear_clip':
      case 'remove_all_clips':
      case 'clear_clips':
        return 'clear_clips';
      case 'mute':
      case 'mute_clip':
        return 'mute_clip';
      case 'unmute':
      case 'unmute_clip':
        return 'unmute_clip';
      case 'toggle_mute':
      case 'toggle_clip_mute':
        return 'toggle_clip_mute';
      case 'replace_clip_points':
        return 'set_clip_points';
      case 'template':
      case 'apply_template':
      case 'generate_template':
        return 'apply_template';
      default:
        return raw.trim().toLowerCase();
    }
  }

  bool _automationClipListsEqual(
    List<AutomationClipSnapshot> a,
    List<AutomationClipSnapshot> b,
  ) {
    if (identical(a, b)) return true;
    if (a.length != b.length) return false;
    for (int i = 0; i < a.length; i++) {
      final x = a[i];
      final y = b[i];
      if (x.id != y.id ||
          x.targetId != y.targetId ||
          x.label != y.label ||
          x.patternId != y.patternId ||
          x.row != y.row ||
          x.lane != y.lane ||
          x.muted != y.muted ||
          (x.startMs - y.startMs).abs() > 1e-6 ||
          (x.lengthMs - y.lengthMs).abs() > 1e-6) {
        return false;
      }
      if (x.points.length != y.points.length) return false;
      for (int p = 0; p < x.points.length; p++) {
        final xp = x.points[p];
        final yp = y.points[p];
        if ((xp.x - yp.x).abs() > 1e-6 ||
            (xp.volume - yp.volume).abs() > 1e-6) {
          return false;
        }
      }
    }
    return true;
  }

  double _defaultAutomationClipLengthMs() {
    final msPerBeat = 60000.0 / _tempo.clamp(1.0, 400.0);
    final oneBarMs = msPerBeat * 4.0;
    final maxMs = _maxAutomationTimelineMs();
    return oneBarMs.clamp(200.0, math.max(200.0, maxMs)).toDouble();
  }

  String _newAutomationClipId(int row, String targetId) {
    return 'ac_${row}_${targetId}_${DateTime.now().microsecondsSinceEpoch}_${const Uuid().v4()}';
  }

  int? _resolveAutomationClipIndexFromAction(
    int row,
    String targetId,
    Map<String, dynamic> data,
  ) {
    final clips = _clipsForAutomationTarget(row, targetId);
    if (clips.isEmpty) return null;
    final target = _actionTarget(data);
    final explicitIndex = _toActionInt(data['clip_index'] ??
        target['clip_index'] ??
        data['automation_clip_index'] ??
        target['automation_clip_index']);
    if (explicitIndex != null &&
        explicitIndex >= 0 &&
        explicitIndex < clips.length) {
      return explicitIndex;
    }

    final explicitId = (data['clip_id'] ??
            target['clip_id'] ??
            data['automation_clip_id'] ??
            target['automation_clip_id'] ??
            '')
        .toString()
        .trim();
    if (explicitId.isNotEmpty) {
      final idx = clips.indexWhere((clip) => clip.id == explicitId);
      if (idx >= 0) return idx;
    }

    final explicitPatternId = (data['pattern_id'] ??
            target['pattern_id'] ??
            data['automation_pattern_id'] ??
            target['automation_pattern_id'] ??
            '')
        .toString()
        .trim();
    if (explicitPatternId.isNotEmpty) {
      final idx = clips
          .indexWhere((clip) => clip.patternId.trim() == explicitPatternId);
      if (idx >= 0) return idx;
    }

    final atMs = _toActionDouble(
      data['at_ms'] ??
          target['at_ms'] ??
          data['time_ms'] ??
          target['time_ms'] ??
          data['start_ms'] ??
          target['start_ms'],
    );
    if (atMs != null && atMs.isFinite) {
      for (int i = 0; i < clips.length; i++) {
        final clip = clips[i];
        final endMs = clip.startMs + clip.lengthMs;
        if (atMs >= clip.startMs && atMs <= endMs) {
          return i;
        }
      }
      int nearest = 0;
      double nearestDist = (clips.first.startMs - atMs).abs();
      for (int i = 1; i < clips.length; i++) {
        final dist = (clips[i].startMs - atMs).abs();
        if (dist < nearestDist) {
          nearest = i;
          nearestDist = dist;
        }
      }
      return nearest;
    }

    return clips.length - 1;
  }

  List<AutomationPoint> _automationTemplatePointsRelative(
    String templateRaw,
    double lengthMs, {
    required double startValue,
    required double endValue,
    String direction = 'up',
  }) {
    final safeLength = lengthMs.clamp(80.0, double.infinity).toDouble();
    final start = startValue.clamp(0.0, 1.0).toDouble();
    final end = endValue.clamp(0.0, 1.0).toDouble();
    final template = templateRaw.trim().toLowerCase();
    final dirDown = direction.trim().toLowerCase() == 'down';

    if (template == 'sidechain' ||
        template == 'sidechain_pump' ||
        template == 'pump') {
      return <AutomationPoint>[
        AutomationPoint(x: 0.0, volume: 1.0),
        AutomationPoint(x: safeLength * 0.08, volume: 0.14),
        AutomationPoint(x: safeLength * 0.36, volume: 0.78),
        AutomationPoint(x: safeLength, volume: 1.0),
      ];
    }

    if (template == 'reverb_tail' ||
        template == 'tail' ||
        template == 'decay') {
      return <AutomationPoint>[
        AutomationPoint(x: 0.0, volume: 0.05),
        AutomationPoint(x: safeLength * 0.12, volume: 1.0),
        AutomationPoint(x: safeLength * 0.45, volume: 0.56),
        AutomationPoint(x: safeLength, volume: 0.12),
      ];
    }

    if (template == 'filter_sweep' ||
        template == 'sweep' ||
        template == 'lowpass_sweep' ||
        template == 'highpass_sweep') {
      final from = dirDown ? 1.0 : 0.0;
      final to = dirDown ? 0.0 : 1.0;
      return <AutomationPoint>[
        AutomationPoint(x: 0.0, volume: from),
        AutomationPoint(x: safeLength, volume: to),
      ];
    }

    if (template == 'auto_pan' ||
        template == 'autopan' ||
        template == 'stereo_motion' ||
        template == 'stereo_direction' ||
        template == 'pan_motion' ||
        template == 'left_right_motion') {
      final startsRight = direction.trim().toLowerCase() == 'right';
      final nearStartSide = startsRight ? 0.84 : 0.16;
      final nearOppositeSide = startsRight ? 0.16 : 0.84;
      final settleSide = startsRight ? 0.74 : 0.26;
      return <AutomationPoint>[
        AutomationPoint(x: 0.0, volume: 0.5),
        AutomationPoint(x: safeLength * 0.16, volume: nearStartSide),
        AutomationPoint(x: safeLength * 0.34, volume: 0.5),
        AutomationPoint(x: safeLength * 0.56, volume: nearOppositeSide),
        AutomationPoint(x: safeLength * 0.78, volume: settleSide),
        AutomationPoint(x: safeLength, volume: 0.5),
      ];
    }

    return <AutomationPoint>[
      AutomationPoint(x: 0.0, volume: start),
      AutomationPoint(x: safeLength, volume: end),
    ];
  }

  Future<void> _applyAutomationEditAction(Map<String, dynamic> data) async {
    final target = _actionTarget(data);
    final rawOperation =
        (data['operation'] ?? '').toString().trim().toLowerCase();
    var operation = _normalizeAutomationEditOperation(rawOperation);
    if (operation == 'clear') {
      final clearScope = (data['clear_scope'] ??
              target['clear_scope'] ??
              data['scope'] ??
              target['scope'] ??
              '')
          .toString()
          .trim()
          .toLowerCase();
      if (clearScope.contains('clip')) {
        operation = 'clear_clips';
      }
    }
    final clipIndex = _resolveClipIndexFromActionTarget(data);
    final row = _resolveRowIndexFromActionTarget(
      data,
      fallbackClipIndex: clipIndex,
    );
    if (row == null) {
      _insertAssistantChatText(
          "I couldn't resolve which track automation to edit.");
      return;
    }

    final pluginIntent = _isPluginAutomationIntent(data);
    final requestedScope = (data['scope'] ?? target['scope'] ?? '')
        .toString()
        .trim()
        .toLowerCase();
    final wantsMasterScope = requestedScope == 'master' ||
        requestedScope == 'master_bus' ||
        requestedScope == 'master-bus' ||
        requestedScope == 'masterbus';
    final targetId = _resolveAutomationTargetIdFromAction(
      row,
      data,
      allowVolumeFallback: !pluginIntent && !wantsMasterScope,
    );
    if (targetId == null || targetId.isEmpty) {
      final hasPluginTargets = (_rowAutomationTargets[row] ?? const {})
          .values
          .any((meta) => !meta.isVolume && !meta.isOrphan);
      if (pluginIntent) {
        if (!hasPluginTargets) {
          _insertAssistantChatText(
              "That track has no automatable plugin parameters yet. Add an effect first.");
        } else {
          _insertAssistantChatText(
              "I couldn't resolve which plugin parameter to automate. Specify plugin + parameter (for example: effect_name + param_name).");
        }
      } else if (wantsMasterScope) {
        _insertAssistantChatText(
            "I couldn't resolve which master parameter to automate. Specify master gain, master pan, or the master effect + parameter.");
      } else {
        _insertAssistantChatText(
            "I couldn't resolve which automation target to edit.");
      }
      return;
    }
    final targetMeta = _rowAutomationTargets[row]?[targetId] ??
        _fallbackAutomationTargetMeta(targetId);
    final valueMode = (data['value_mode'] ??
            target['value_mode'] ??
            data['value_domain'] ??
            target['value_domain'] ??
            '')
        .toString();
    final normalizedTemplate = (data['template'] ??
            target['template'] ??
            data['pattern'] ??
            target['pattern'] ??
            '')
        .toString()
        .trim()
        .toLowerCase();
    final defaultSpanMs = (60000.0 / _tempo.clamp(1.0, 400.0) * 4.0)
        .clamp(120.0, _automationUpperBound(120.0))
        .toDouble();

    Future<void> applyClipList(
      List<AutomationClipSnapshot> nextClips, {
      List<AutomationClipSnapshot>? beforeOverride,
    }) async {
      final oldClips = _copyAutomationClipList(
        beforeOverride ?? _clipsForAutomationTarget(row, targetId),
      );
      final safeClips =
          _sanitizeAutomationClipsForTarget(row, targetId, nextClips);
      if (_automationClipListsEqual(oldClips, safeClips)) {
        return;
      }
      await _setAutomationClipsForTargetWithUndo(
        row,
        targetId,
        safeClips,
        oldClipsOverride: oldClips,
      );
    }

    bool wantsSharedCopy(Map<String, dynamic> source) {
      final mode = (source['copy_mode'] ??
              source['duplicate_mode'] ??
              source['clone_mode'] ??
              source['copy_style'] ??
              '')
          .toString()
          .trim()
          .toLowerCase();
      if (mode.isEmpty) return true;
      return mode == 'shared' ||
          mode == 'linked' ||
          mode == 'shallow' ||
          mode == 'clone' ||
          source['shared'] == true ||
          source['linked'] == true;
    }

    List<AutomationClipSnapshot> applySharedPatternPoints(
      List<AutomationClipSnapshot> clips,
      int clipIndex,
      List<AutomationPoint> points,
    ) {
      if (clipIndex < 0 || clipIndex >= clips.length) return clips;
      final source = clips[clipIndex];
      final patternId = source.patternId.trim();
      if (patternId.isEmpty) {
        final updated = List<AutomationClipSnapshot>.from(clips);
        updated[clipIndex] = source.copyWith(points: points);
        return updated;
      }
      return clips
          .map(
            (clip) => clip.patternId.trim() == patternId
                ? clip.copyWith(points: points)
                : clip.copyWith(),
          )
          .toList(growable: false);
    }

    if (operation == 'clear_clips') {
      await applyClipList(const <AutomationClipSnapshot>[]);
      _showSmallNotice('Cleared automation clips.');
      return;
    }

    final isKickSyncedSidechainTemplate = operation == 'apply_template' &&
        (normalizedTemplate == 'sidechain_from_kick' ||
            normalizedTemplate == 'kick_sidechain' ||
            normalizedTemplate == 'duck_to_kick' ||
            normalizedTemplate == 'kick_duck');
    if (isKickSyncedSidechainTemplate) {
      final sourceClipIndex =
          _resolveKickSourceClipIndexFromAction(data, targetRow: row);
      if (sourceClipIndex == null ||
          sourceClipIndex < 0 ||
          sourceClipIndex >= _audioTracks.length) {
        _insertAssistantChatText(
            "I couldn't find a kick source clip for sidechain automation.");
        return;
      }
      final sourceClip = _audioTracks[sourceClipIndex];
      if (sourceClip.isMidi) {
        _insertAssistantChatText(
            'Kick-synced sidechain needs an audio source clip.');
        return;
      }

      final lengthMs = (_toActionDouble(
                data['length_ms'] ??
                    target['length_ms'] ??
                    data['duration_ms'] ??
                    target['duration_ms'],
              ) ??
              (60000.0 / _tempo.clamp(1.0, 400.0)))
          .clamp(80.0, _automationUpperBound(80.0))
          .toDouble();
      final minSpacingMs = (_toActionDouble(
                data['min_spacing_ms'] ??
                    target['min_spacing_ms'] ??
                    data['event_spacing_ms'] ??
                    target['event_spacing_ms'],
              ) ??
              math.max(80.0, lengthMs * 0.42))
          .clamp(40.0, 4000.0)
          .toDouble();
      final thresholdStd = (_toActionDouble(
                data['transient_threshold_std'] ??
                    target['transient_threshold_std'] ??
                    data['transient_sensitivity'] ??
                    target['transient_sensitivity'] ??
                    data['sensitivity'] ??
                    target['sensitivity'],
              ) ??
              1.25)
          .clamp(0.25, 4.0)
          .toDouble();
      final lowpassHz = (_toActionDouble(
                data['kick_lowpass_hz'] ??
                    target['kick_lowpass_hz'] ??
                    data['lowpass_hz'] ??
                    target['lowpass_hz'],
              ) ??
              220.0)
          .clamp(80.0, 1200.0)
          .toDouble();
      final maxEvents = (_toActionInt(
                data['max_events'] ?? target['max_events'],
              ) ??
              256)
          .clamp(1, 2048);
      final offsetMs = (_toActionDouble(
                data['offset_ms'] ?? target['offset_ms'],
              ) ??
              0.0)
          .toDouble();
      final fromMs = _toActionDouble(data['from_ms'] ?? target['from_ms']);
      final toMs = _toActionDouble(data['to_ms'] ?? target['to_ms']);

      var eventMs = await _detectKickTimelineOnsetsMsForClip(
        sourceClip,
        cutoffHz: lowpassHz,
        thresholdStd: thresholdStd,
        minSpacingMs: minSpacingMs,
        maxEvents: maxEvents,
      );
      if (eventMs.isEmpty) {
        _insertAssistantChatText(
            'No kick transients were detected for automatic sidechain.');
        return;
      }

      if (fromMs != null || toMs != null) {
        final startWindow = (fromMs ?? 0.0).toDouble();
        final endWindow = (toMs ?? _maxAutomationTimelineMs()).toDouble();
        eventMs = eventMs
            .where((x) => x >= startWindow && x <= endWindow)
            .toList(growable: false);
      }
      if (eventMs.isEmpty) {
        _insertAssistantChatText(
            'Kick transients were found, but none were in the requested time range.');
        return;
      }

      final recoverValue = _normalizedActionValueForTarget(
        data['recover_value'] ??
            data['end_value'] ??
            data['max_value'] ??
            target['recover_value'] ??
            target['end_value'] ??
            target['max_value'],
        targetMeta,
        valueMode: valueMode,
        fallback: targetId == 'volume' ? 1.0 : 0.8,
      );
      final duckValue = _normalizedActionValueForTarget(
        data['duck_value'] ??
            data['min_value'] ??
            data['depth'] ??
            target['duck_value'] ??
            target['min_value'] ??
            target['depth'],
        targetMeta,
        valueMode: valueMode,
        fallback: targetId == 'volume' ? 0.16 : 0.2,
      );
      final attackMs =
          (_toActionDouble(data['attack_ms'] ?? target['attack_ms']) ??
                  math.min(22.0, lengthMs * 0.2))
              .clamp(2.0, math.max(2.0, lengthMs * 0.7))
              .toDouble();
      final releaseRatio =
          (_toActionDouble(data['release_ratio'] ?? target['release_ratio']) ??
                  0.38)
              .clamp(0.08, 0.95)
              .toDouble();
      final recoveryMs =
          (lengthMs * releaseRatio).clamp(attackMs + 1.0, lengthMs).toDouble();
      final midValue =
          (duckValue + (recoverValue - duckValue) * 0.58).clamp(0.0, 1.0);
      final replaceExisting = _toActionBool(
        data['replace_existing'] ?? target['replace_existing'],
        fallback: false,
      );

      final before = _copyAutomationClipList(_clipsForAutomationTarget(
        row,
        targetId,
      ));
      final working = List<AutomationClipSnapshot>.from(before);
      final requestedLane = math.max(
        0,
        _toActionInt(
              data['lane_index'] ??
                  target['lane_index'] ??
                  data['lane'] ??
                  target['lane'],
            ) ??
            0,
      );
      if (replaceExisting && eventMs.isNotEmpty) {
        final regionStart = (eventMs.first + offsetMs) - lengthMs * 0.25;
        final regionEnd = (eventMs.last + offsetMs) + lengthMs * 1.1;
        working.removeWhere((clip) {
          final clipEnd = clip.startMs + clip.lengthMs;
          return clipEnd >= regionStart && clip.startMs <= regionEnd;
        });
      }

      final maxTimelineMs = _maxAutomationTimelineMs();
      int created = 0;
      final label = (data['label'] ??
              target['label'] ??
              _automationTargetLabelFor(row, targetId))
          .toString()
          .trim();
      for (final onsetMs in eventMs) {
        final startMs = (onsetMs + offsetMs).clamp(0.0, maxTimelineMs);
        if (startMs + 4.0 >= maxTimelineMs) continue;
        final clippedLength =
            math.min(lengthMs, math.max(40.0, maxTimelineMs - startMs));
        if (clippedLength <= 40.0) continue;

        final points = <AutomationPoint>[
          AutomationPoint(x: 0.0, volume: recoverValue),
          AutomationPoint(
              x: attackMs.clamp(1.0, clippedLength), volume: duckValue),
          AutomationPoint(
              x: recoveryMs.clamp(attackMs + 1.0, clippedLength),
              volume: midValue.toDouble()),
          AutomationPoint(x: clippedLength, volume: recoverValue),
        ];

        working.add(
          AutomationClipSnapshot(
            id: _newAutomationClipId(row, targetId),
            targetId: targetId,
            label: label.isEmpty
                ? _automationTargetLabelFor(row, targetId)
                : label,
            row: _preferredAutomationClipRowForTarget(row, targetId),
            lane: requestedLane,
            startMs: startMs.toDouble(),
            lengthMs: clippedLength.toDouble(),
            muted: false,
            points: points,
          ),
        );
        created++;
      }

      if (created <= 0) {
        _insertAssistantChatText(
            "I couldn't place sidechain clips in the current timeline range.");
        return;
      }

      await applyClipList(working, beforeOverride: before);
      _showSmallNotice('Created $created kick-synced sidechain clips.');
      return;
    }

    if (operation == 'create_clip' || operation == 'apply_template') {
      final before = _copyAutomationClipList(_clipsForAutomationTarget(
        row,
        targetId,
      ));
      final startMs = (_toActionDouble(
                data['start_ms'] ?? target['start_ms'] ?? data['at_ms'],
              ) ??
              _globalAudioClock.inMilliseconds.toDouble())
          .clamp(0.0, _maxAutomationTimelineMs());
      final lengthMs = (_toActionDouble(
                data['length_ms'] ??
                    target['length_ms'] ??
                    data['duration_ms'] ??
                    target['duration_ms'],
              ) ??
              _defaultAutomationClipLengthMs())
          .clamp(80.0, _automationUpperBound(80.0));
      final startValue = _normalizedActionValueForTarget(
        data['start_value'] ?? data['from_value'],
        targetMeta,
        valueMode: valueMode,
        fallback: targetId == 'volume' ? 0.75 : 0.5,
      );
      final endValue = _normalizedActionValueForTarget(
        data['end_value'] ?? data['to_value'],
        targetMeta,
        valueMode: valueMode,
        fallback: targetId == 'volume' ? 0.75 : 0.5,
      );
      final template = normalizedTemplate;
      final direction =
          (data['direction'] ?? target['direction'] ?? 'up').toString();
      final rawPoints = (data['points'] as List?) ?? const [];
      final clipPoints = <AutomationPoint>[];
      for (final raw in rawPoints) {
        final m = _toActionMap(raw);
        final x = _toActionDouble(m['x_ms'] ?? m['x'] ?? m['time_ms']);
        final rawValue = m['value'] ??
            m['volume'] ??
            m['normalized_value'] ??
            m['normalized'] ??
            m['real_value'] ??
            m['native_value'];
        if (x == null || rawValue == null) continue;
        final pointValueMode = (m['value_mode'] ?? valueMode).toString();
        final normalized = _normalizedActionValueForTarget(
          rawValue,
          targetMeta,
          valueMode: pointValueMode,
          fallback: targetId == 'volume' ? 0.75 : 0.5,
        );
        clipPoints.add(
          AutomationPoint(
            x: x,
            volume: normalized,
          ),
        );
      }
      final points = clipPoints.isNotEmpty
          ? clipPoints
          : _automationTemplatePointsRelative(
              template.isEmpty ? 'ramp' : template,
              lengthMs,
              startValue: startValue,
              endValue: endValue,
              direction: direction,
            );
      final label = (data['label'] ??
              target['label'] ??
              _automationTargetLabelFor(row, targetId))
          .toString()
          .trim();
      final muted = _toActionBool(
        data['muted'] ?? target['muted'],
        fallback: false,
      );
      final requestedLane = math.max(
        0,
        _toActionInt(
              data['lane_index'] ??
                  target['lane_index'] ??
                  data['lane'] ??
                  target['lane'],
            ) ??
            0,
      );
      final clip = AutomationClipSnapshot(
        id: _newAutomationClipId(row, targetId),
        targetId: targetId,
        label: label.isEmpty ? _automationTargetLabelFor(row, targetId) : label,
        patternId: (data['pattern_id'] ?? target['pattern_id'] ?? '')
            .toString()
            .trim(),
        row: _preferredAutomationClipRowForTarget(row, targetId),
        lane: requestedLane,
        startMs: startMs.toDouble(),
        lengthMs: lengthMs.toDouble(),
        muted: muted,
        points: points,
      );
      await applyClipList([...before, clip], beforeOverride: before);
      _showSmallNotice('Created automation clip.');
      return;
    }

    if (operation == 'duplicate_clip') {
      final before = _copyAutomationClipList(_clipsForAutomationTarget(
        row,
        targetId,
      ));
      final sourceIndex =
          _resolveAutomationClipIndexFromAction(row, targetId, data);
      if (sourceIndex == null ||
          sourceIndex < 0 ||
          sourceIndex >= before.length) {
        _insertAssistantChatText(
            "I couldn't find an automation clip to duplicate.");
        return;
      }
      final sharedCopy = wantsSharedCopy(data) || wantsSharedCopy(target);
      final working = List<AutomationClipSnapshot>.from(before);
      final source = working[sourceIndex];
      final patternId = sharedCopy
          ? (source.patternId.trim().isNotEmpty
              ? source.patternId.trim()
              : _newAutomationPatternId(row, targetId))
          : '';
      if (sharedCopy && source.patternId.trim().isEmpty) {
        working[sourceIndex] = source.copyWith(patternId: patternId);
      }
      final nextStart = (_toActionDouble(
                data['start_ms'] ??
                    target['start_ms'] ??
                    data['paste_start_ms'] ??
                    target['paste_start_ms'],
              ) ??
              (source.startMs + source.lengthMs))
          .toDouble();
      final duplicated = working[sourceIndex].copyWith(
        id: _newAutomationClipId(row, targetId),
        patternId: patternId,
        startMs: nextStart,
      );
      await applyClipList([...working, duplicated], beforeOverride: before);
      _showSmallNotice(
        sharedCopy
            ? 'Created shared automation clip.'
            : 'Duplicated automation clip.',
      );
      return;
    }

    if (operation == 'move_clip' ||
        operation == 'delete_clip' ||
        operation == 'mute_clip' ||
        operation == 'unmute_clip' ||
        operation == 'toggle_clip_mute' ||
        operation == 'set_clip_points' ||
        operation == 'make_unique_clip' ||
        operation == 'make_unique') {
      final before = _copyAutomationClipList(_clipsForAutomationTarget(
        row,
        targetId,
      ));
      final clipIdx =
          _resolveAutomationClipIndexFromAction(row, targetId, data);
      if (clipIdx == null || clipIdx < 0 || clipIdx >= before.length) {
        _insertAssistantChatText("I couldn't find that automation clip.");
        return;
      }

      if (operation == 'delete_clip') {
        final next = List<AutomationClipSnapshot>.from(before)
          ..removeAt(clipIdx);
        await applyClipList(next, beforeOverride: before);
        _showSmallNotice('Deleted automation clip.');
        return;
      }

      final working = List<AutomationClipSnapshot>.from(before);
      final current = working[clipIdx];

      if (operation == 'move_clip') {
        final explicitStartMs = _toActionDouble(
          data['start_ms'] ??
              target['start_ms'] ??
              data['new_start_ms'] ??
              target['new_start_ms'],
        );
        final deltaMs = _toActionDouble(
          data['delta_ms'] ??
              target['delta_ms'] ??
              data['offset_ms'] ??
              target['offset_ms'] ??
              data['shift_ms'] ??
              target['shift_ms'],
        );
        final direction = (data['direction'] ?? target['direction'] ?? '')
            .toString()
            .trim()
            .toLowerCase();
        final stepMs = (_toActionDouble(
                  data['step_ms'] ??
                      target['step_ms'] ??
                      data['amount_ms'] ??
                      target['amount_ms'],
                ) ??
                (defaultSpanMs / 4.0))
            .abs()
            .clamp(20.0, _automationUpperBound(20.0));
        final directionDelta = switch (direction) {
          'left' || 'earlier' || 'back' || 'backward' => -stepMs,
          'right' || 'later' || 'forward' => stepMs,
          _ => 0.0,
        };
        final startMs = explicitStartMs ??
            (current.startMs + (deltaMs ?? 0.0) + directionDelta);
        final lengthMs = _toActionDouble(
              data['length_ms'] ??
                  target['length_ms'] ??
                  data['duration_ms'] ??
                  target['duration_ms'],
            ) ??
            current.lengthMs;
        final laneIndex = _toActionInt(
          data['lane_index'] ??
              target['lane_index'] ??
              data['lane'] ??
              target['lane'],
        );
        final nextLane =
            laneIndex == null ? current.lane : math.max(0, laneIndex);
        if ((startMs - current.startMs).abs() < 0.5 &&
            (lengthMs - current.lengthMs).abs() < 0.5 &&
            nextLane == current.lane) {
          _insertAssistantChatText(
              "I couldn't resolve where to move that automation clip.");
          return;
        }
        working[clipIdx] = current.copyWith(
          startMs: startMs,
          lengthMs: lengthMs,
          lane: nextLane,
        );
        await applyClipList(working, beforeOverride: before);
        _showSmallNotice('Moved automation clip.');
        return;
      }

      if (operation == 'mute_clip' ||
          operation == 'unmute_clip' ||
          operation == 'toggle_clip_mute') {
        final nextMuted = switch (operation) {
          'mute_clip' => true,
          'unmute_clip' => false,
          _ => !current.muted,
        };
        working[clipIdx] = current.copyWith(muted: nextMuted);
        await applyClipList(working, beforeOverride: before);
        _showSmallNotice(
            nextMuted ? 'Muted automation clip.' : 'Unmuted automation clip.');
        return;
      }

      if (operation == 'make_unique_clip' || operation == 'make_unique') {
        if (current.patternId.trim().isEmpty) {
          _showSmallNotice('Automation clip is already unique.');
          return;
        }
        working[clipIdx] = current.copyWith(patternId: '');
        await applyClipList(working, beforeOverride: before);
        _showSmallNotice('Made automation clip unique.');
        return;
      }

      if (operation == 'set_clip_points') {
        final rawPoints = (data['points'] as List?) ?? const [];
        final points = <AutomationPoint>[];
        for (final raw in rawPoints) {
          final m = _toActionMap(raw);
          final x = _toActionDouble(m['x_ms'] ?? m['x'] ?? m['time_ms']);
          final rawValue = m['value'] ??
              m['volume'] ??
              m['normalized_value'] ??
              m['normalized'] ??
              m['real_value'] ??
              m['native_value'];
          if (x == null || rawValue == null) continue;
          final pointValueMode = (m['value_mode'] ?? valueMode).toString();
          final normalized = _normalizedActionValueForTarget(
            rawValue,
            targetMeta,
            valueMode: pointValueMode,
            fallback: targetId == 'volume' ? 0.75 : 0.5,
          );
          points.add(AutomationPoint(x: x, volume: normalized));
        }
        if (points.isEmpty) {
          _insertAssistantChatText("I need clip automation points to apply.");
          return;
        }
        final next = applySharedPatternPoints(working, clipIdx, points);
        await applyClipList(next, beforeOverride: before);
        _showSmallNotice('Updated automation clip points.');
        return;
      }
    }

    if (operation == 'clear') {
      if (targetId == 'volume') {
        final maxMs =
            math.max(1.0, _audioOnlyOverallDuration.inMilliseconds.toDouble());
        await _setRowAutomationWithUndo(row, <AutomationPoint>[
          AutomationPoint(x: 0.0, volume: 1.0),
          AutomationPoint(x: maxMs, volume: 1.0),
        ]);
      } else {
        await _setAutomationTargetPointsWithUndo(
          row,
          targetId,
          _defaultAutomationPointsForTarget(row, targetId),
        );
      }
      _showSmallNotice('Cleared automation.');
      return;
    }

    if (operation == 'add_ramp') {
      final rawFromMs = _toActionDouble(
            data['from_ms'] ??
                target['from_ms'] ??
                data['start_ms'] ??
                target['start_ms'],
          ) ??
          _globalAudioClock.inMilliseconds.toDouble();
      final fromMs =
          rawFromMs.clamp(0.0, _maxAutomationTimelineMs()).toDouble();
      final rawToMs = _toActionDouble(
            data['to_ms'] ??
                target['to_ms'] ??
                data['end_ms'] ??
                target['end_ms'],
          ) ??
          (fromMs + defaultSpanMs);
      final toMs = math.max(fromMs + 40.0, rawToMs);
      final direction = (data['direction'] ?? target['direction'] ?? '')
          .toString()
          .trim()
          .toLowerCase();

      final existingValue = _resolvedAutomationValueAtMs(
        row,
        targetId,
        fromMs,
      );
      final parsedStartValue = _normalizedActionValueForTarget(
        data['start_value'] ?? data['from_value'],
        targetMeta,
        valueMode: valueMode,
        fallback: existingValue,
      );
      final parsedEndValue = _normalizedActionValueForTarget(
        data['end_value'] ?? data['to_value'],
        targetMeta,
        valueMode: valueMode,
        fallback: direction == 'down'
            ? (parsedStartValue - 0.35).clamp(0.0, 1.0).toDouble()
            : direction == 'up'
                ? (parsedStartValue + 0.35).clamp(0.0, 1.0).toDouble()
                : parsedStartValue,
      );
      final next = _pointsForAutomationTarget(row, targetId)
          .map((p) => p.copy())
          .toList(growable: true);
      next.add(AutomationPoint(x: fromMs, volume: parsedStartValue));
      next.add(AutomationPoint(x: toMs, volume: parsedEndValue));
      await _setAutomationTargetPointsWithUndo(row, targetId, next);
      _showSmallNotice('Added automation ramp.');
      return;
    }

    final rawPoints = (data['points'] as List?) ?? const [];
    final points = <AutomationPoint>[];
    for (final raw in rawPoints) {
      final m = _toActionMap(raw);
      final x = _toActionDouble(m['x_ms'] ?? m['x'] ?? m['time_ms']);
      final rawValue = m['value'] ??
          m['volume'] ??
          m['normalized_value'] ??
          m['normalized'] ??
          m['real_value'] ??
          m['native_value'];
      if (x == null || rawValue == null) continue;
      final pointValueMode = (m['value_mode'] ?? valueMode).toString();
      final normalized = _normalizedActionValueForTarget(
        rawValue,
        targetMeta,
        valueMode: pointValueMode,
        fallback: targetId == 'volume' ? 1.0 : 0.5,
      );
      points.add(AutomationPoint(x: x, volume: normalized));
    }

    if (points.isEmpty) {
      if (operation == 'set_points') {
        final fromMs = (_toActionDouble(
                  data['from_ms'] ??
                      target['from_ms'] ??
                      data['start_ms'] ??
                      target['start_ms'],
                ) ??
                _globalAudioClock.inMilliseconds.toDouble())
            .clamp(0.0, _maxAutomationTimelineMs())
            .toDouble();
        final toMs = (_toActionDouble(
                  data['to_ms'] ??
                      target['to_ms'] ??
                      data['end_ms'] ??
                      target['end_ms'],
                ) ??
                (fromMs + defaultSpanMs))
            .clamp(fromMs + 40.0, _maxAutomationTimelineMs())
            .toDouble();
        final direction = (data['direction'] ?? target['direction'] ?? '')
            .toString()
            .trim()
            .toLowerCase();
        final base = _resolvedAutomationValueAtMs(
          row,
          targetId,
          fromMs,
        );
        final v0 = _normalizedActionValueForTarget(
          data['start_value'] ?? data['from_value'] ?? data['value'],
          targetMeta,
          valueMode: valueMode,
          fallback: base,
        );
        final v1 = _normalizedActionValueForTarget(
          data['end_value'] ?? data['to_value'],
          targetMeta,
          valueMode: valueMode,
          fallback: direction == 'down'
              ? (v0 - 0.35).clamp(0.0, 1.0).toDouble()
              : direction == 'up'
                  ? (v0 + 0.35).clamp(0.0, 1.0).toDouble()
                  : v0,
        );
        await _setAutomationTargetPointsWithUndo(
            row, targetId, <AutomationPoint>[
          AutomationPoint(x: fromMs, volume: v0),
          AutomationPoint(x: toMs, volume: v1),
        ]);
        _showSmallNotice('Set automation points.');
        return;
      }
      _insertAssistantChatText(
          "I need automation points to apply (time/value pairs).");
      return;
    }

    await _setAutomationTargetPointsWithUndo(row, targetId, points);
    _showSmallNotice('Set automation points.');
  }

  int? _pitchClassFromToken(String token) {
    return AssistantActionUtils.pitchClassFromToken(token);
  }

  int? _midiPitchFromRaw(dynamic raw, {int fallbackOctave = 3}) {
    return AssistantActionUtils.midiPitchFromRaw(
      raw,
      fallbackOctave: fallbackOctave,
    );
  }

  int? _rootMidiFromChordToken(String token, {int octave = 2}) {
    return AssistantActionUtils.rootMidiFromChordToken(token, octave: octave);
  }

  List<String> _progressionTokensFromActionData(Map<String, dynamic> data) {
    final target = _actionTarget(data);
    final rawProgression = data['progression'] ??
        target['progression'] ??
        data['chords'] ??
        target['chords'] ??
        data['pattern'] ??
        target['pattern'] ??
        data['sequence'] ??
        target['sequence'] ??
        data['text'] ??
        target['text'] ??
        data['request'] ??
        target['request'];
    return AssistantActionUtils.progressionTokensFromRaw(rawProgression);
  }

  List<MidiNote> _fallbackMidiNotesFromProgression(Map<String, dynamic> data) {
    final tokens = _progressionTokensFromActionData(data);
    if (tokens.isEmpty) return const <MidiNote>[];
    final target = _actionTarget(data);
    final operation = (data['operation'] ?? '').toString().trim().toLowerCase();

    final beatsPerChord = _toActionDouble(data['beats_per_chord'] ??
            target['beats_per_chord'] ??
            data['chord_length_beats'] ??
            target['chord_length_beats']) ??
        4.0;
    final notesPerChord =
        (_toActionInt(data['notes_per_chord'] ?? target['notes_per_chord']) ??
                4)
            .clamp(1, 8)
            .toInt();
    final isBassline = operation == 'compose_bassline';
    final octave = (_toActionInt(data['octave'] ?? target['octave']) ??
            (isBassline ? 2 : 3))
        .clamp(-1, 8)
        .toInt();
    final velocity =
        (_toActionDouble(data['velocity'] ?? target['velocity']) ?? 0.78)
            .clamp(0.2, 1.0)
            .toDouble();

    return AssistantActionUtils.fallbackMidiNotesFromProgression(
      progressionRaw: tokens,
      beatsPerChord: beatsPerChord,
      notesPerChord: notesPerChord,
      octave: octave,
      velocity: velocity,
      mode: isBassline ? 'bass' : 'chords',
      noteIdPrefix: 'ai_prog',
    );
  }

  bool _notesContainPolyphony(List<MidiNote> notes) {
    if (notes.length < 2) return false;
    final byStart = <int, int>{};
    for (final note in notes) {
      final bucket = (note.startBeat * 1000.0).round();
      final nextCount = (byStart[bucket] ?? 0) + 1;
      if (nextCount >= 2) return true;
      byStart[bucket] = nextCount;
    }
    return false;
  }

  String _preferredAiInstrumentIdForNewMidiClip(
    Map<String, dynamic> data,
    Map<String, dynamic> target,
    String operation,
    List<MidiNote> notes,
  ) {
    final explicitInstrumentId =
        (data['instrument_id'] ?? target['instrument_id'] ?? '')
            .toString()
            .trim();
    if (explicitInstrumentId.isNotEmpty) {
      return explicitInstrumentId;
    }

    if (operation == 'compose_bassline') {
      return 'mixroom.sub_bass';
    }

    final progressionTokens = _progressionTokensFromActionData(data);
    final requestedNotesPerChord = _toActionInt(
          data['notes_per_chord'] ?? target['notes_per_chord'],
        ) ??
        0;
    final likelyHarmony = progressionTokens.isNotEmpty ||
        requestedNotesPerChord > 1 ||
        _notesContainPolyphony(notes);

    if (likelyHarmony) {
      for (final candidate in const <String>[
        kPreferredPianoInstrumentId,
        'mixroom.warm_keys',
        'mixroom.velvet_ep',
        'mixroom.fm_keys',
        'mixroom.house_organ',
        'mixroom.vanilla_poly',
      ]) {
        if (_findInstrumentSpecById(candidate) != null) {
          return candidate;
        }
      }
    }

    for (final candidate in const <String>[
      kPreferredPianoInstrumentId,
      'mixroom.basic_synth',
      'mixroom.vanilla_poly',
      'mixroom.warm_keys',
    ]) {
      if (_findInstrumentSpecById(candidate) != null) {
        return candidate;
      }
    }

    return 'mixroom.sub_bass';
  }

  String _resolveAiInstrumentIdFromActionData(
    Map<String, dynamic> data,
    Map<String, dynamic> target,
    String fallbackInstrumentId,
  ) {
    final explicitInstrumentId =
        (data['instrument_id'] ?? target['instrument_id'] ?? '')
            .toString()
            .trim();
    if (explicitInstrumentId.isNotEmpty &&
        _findInstrumentSpecById(explicitInstrumentId) != null) {
      return explicitInstrumentId;
    }

    final requestedName =
        (data['instrument_name'] ?? target['instrument_name'] ?? '')
            .toString()
            .trim();
    if (requestedName.isNotEmpty) {
      final matchedSpec = _findLegacySfzSpecByToken(requestedName);
      final matchedId = (matchedSpec?['id'] as String?)?.trim() ?? '';
      if (matchedId.isNotEmpty) {
        return matchedId;
      }
    }

    return fallbackInstrumentId;
  }

  bool _shouldCreateFreshMidiClip(
    Map<String, dynamic> data,
    Map<String, dynamic> target,
    String operation,
  ) {
    if (operation == 'create_clip') return true;
    return _toActionBool(
          data['create_new_clip'] ?? target['create_new_clip'],
        ) ||
        _toActionBool(
          data['prefer_new_clip'] ?? target['prefer_new_clip'],
        );
  }

  bool _shouldPreserveExistingMidiNotes(
    Map<String, dynamic> data,
    Map<String, dynamic> target,
    String operation,
  ) {
    if (operation != 'replace_notes' && operation != 'append_notes') {
      return false;
    }
    return _toActionBool(
      data['preserve_existing_notes'] ?? target['preserve_existing_notes'],
    );
  }

  double? _resolveMidiTargetLengthBeats(
    Map<String, dynamic> data,
    Map<String, dynamic> target,
  ) {
    return AssistantActionUtils.resolveMidiTargetLengthBeatsFromAction(
      data,
      target: target,
    );
  }

  List<MidiNote> _resizeMidiNotesToTargetLength(
    List<MidiNote> sourceNotes,
    double targetBeats,
  ) {
    if (sourceNotes.isEmpty || !targetBeats.isFinite || targetBeats <= 0.0) {
      return const <MidiNote>[];
    }
    final sorted = sourceNotes.map((n) => n.copy()).toList(growable: false)
      ..sort((a, b) {
        final byStart = a.startBeat.compareTo(b.startBeat);
        if (byStart != 0) return byStart;
        final byPitch = a.pitch.compareTo(b.pitch);
        if (byPitch != 0) return byPitch;
        return a.id.compareTo(b.id);
      });
    final cycleBeats = sorted
        .map((n) => n.startBeat + n.lengthBeats)
        .fold<double>(0.0, math.max);
    if (!cycleBeats.isFinite || cycleBeats <= 0.0) {
      return const <MidiNote>[];
    }

    final out = <MidiNote>[];
    final repeats = math.max(1, (targetBeats / cycleBeats).ceil());
    const epsilon = 1e-6;
    for (int repeat = 0; repeat < repeats; repeat++) {
      final beatOffset = repeat * cycleBeats;
      for (int i = 0; i < sorted.length; i++) {
        final note = sorted[i];
        final startBeat = note.startBeat + beatOffset;
        if (startBeat >= targetBeats - epsilon) continue;
        final remaining = targetBeats - startBeat;
        if (remaining <= epsilon) continue;
        out.add(
          MidiNote(
            id: 'ai_resize_${repeat}_$i',
            pitch: note.pitch,
            startBeat: startBeat,
            lengthBeats: math.min(note.lengthBeats, remaining),
            velocity: note.velocity,
          ),
        );
      }
    }
    return out;
  }

  List<MidiNote> _midiNotesFromActionData(Map<String, dynamic> data) {
    final rawNotes = (data['notes'] as List?) ?? const [];
    final out = <MidiNote>[];
    int i = 0;
    for (final raw in rawNotes) {
      final m = _toActionMap(raw);
      final startBeat = AssistantActionUtils.resolveMidiNoteStartBeat(m);
      final lengthBeats = AssistantActionUtils.resolveMidiNoteLengthBeats(m);
      final velocity =
          AssistantActionUtils.normalizeMidiVelocity(m['velocity']) ?? 0.8;
      if (startBeat == null || lengthBeats == null) continue;

      final pitches = <int>[];
      final singlePitch = _midiPitchFromRaw(
        m['pitch'] ?? m['midi'] ?? m['note'] ?? m['note_name'],
      );
      if (singlePitch != null) {
        pitches.add(singlePitch.clamp(0, 127).toInt());
      }

      final rawChordPitches = m['pitches'];
      if (rawChordPitches is List) {
        for (final rawPitch in rawChordPitches) {
          final chordPitch = _midiPitchFromRaw(rawPitch);
          if (chordPitch != null) {
            pitches.add(chordPitch.clamp(0, 127).toInt());
          }
        }
      }

      if (pitches.isEmpty) continue;

      for (final pitch in pitches) {
        out.add(
          MidiNote(
            id: 'ai_note_${DateTime.now().microsecondsSinceEpoch}_${i++}',
            pitch: pitch,
            startBeat: math.max(0.0, startBeat),
            lengthBeats: math.max(0.0625, lengthBeats),
            velocity: velocity.clamp(0.0, 1.0).toDouble(),
          ),
        );
      }
    }
    return out;
  }

  int _midiSubdivisionFromActionData(
    Map<String, dynamic> data, {
    int fallback = 16,
  }) {
    final target = _actionTarget(data);

    int? parseSubdivision(dynamic raw) {
      if (raw is num) return raw.round();
      if (raw is! String) return null;

      final text = raw.trim().toLowerCase();
      if (text.isEmpty) return null;

      int? out;
      final fraction = RegExp(r'^1\s*/\s*(\d+)$').firstMatch(text);
      if (fraction != null) {
        out = int.tryParse(fraction.group(1) ?? '');
      }
      out ??= int.tryParse(text);
      if (out == null) {
        final embedded = RegExp(r'(\d+)').firstMatch(text);
        if (embedded != null) {
          out = int.tryParse(embedded.group(1) ?? '');
        }
      }
      out ??= () {
        if (text.contains('whole')) return 1;
        if (text.contains('half')) return 2;
        if (text.contains('quarter')) return 4;
        if (text.contains('8th') || text.contains('eighth')) return 8;
        if (text.contains('16th') || text.contains('sixteenth')) return 16;
        if (text.contains('32nd') || text.contains('thirty-second')) return 32;
        if (text.contains('64th') || text.contains('sixty-fourth')) return 64;
        return null;
      }();
      if (out == null || out <= 0) return null;
      if (text.contains('triplet')) {
        out = math.max(1, ((out * 3.0) / 2.0).round());
      }
      return out;
    }

    int? resolved;
    for (final raw in <dynamic>[
      data['subdivision'],
      target['subdivision'],
      data['subdivision_divisor'],
      target['subdivision_divisor'],
      data['grid'],
      target['grid'],
      data['resolution'],
      target['resolution'],
      data['note_value'],
      target['note_value'],
    ]) {
      final parsed = parseSubdivision(raw);
      if (parsed != null) {
        resolved = parsed;
        break;
      }
    }

    if (resolved == null) {
      final stepBeats = _toActionDouble(
        data['step_beats'] ??
            target['step_beats'] ??
            data['beats_per_slice'] ??
            target['beats_per_slice'] ??
            data['slice_beats'] ??
            target['slice_beats'],
      );
      if (stepBeats != null && stepBeats.isFinite && stepBeats > 0.0) {
        resolved = (4.0 / stepBeats).round();
      }
    }

    return (resolved ?? fallback).clamp(1, 128).toInt();
  }

  List<MidiNote> _chopMidiNotesFromActionData(
    Map<String, dynamic> data,
    List<MidiNote> sourceNotes, {
    int? subdivision,
  }) {
    final target = _actionTarget(data);
    final safeSubdivision = subdivision ??
        _midiSubdivisionFromActionData(
          data,
          fallback: 16,
        );
    final stepBeats = _toActionDouble(
      data['step_beats'] ??
          target['step_beats'] ??
          data['beats_per_slice'] ??
          target['beats_per_slice'] ??
          data['slice_beats'] ??
          target['slice_beats'],
    );
    final sustainRatio = (_toActionDouble(
              data['sustain_ratio'] ??
                  target['sustain_ratio'] ??
                  data['gate'] ??
                  target['gate'] ??
                  data['length_ratio'] ??
                  target['length_ratio'],
            ) ??
            1.0)
        .clamp(0.05, 1.0)
        .toDouble();
    final minLengthBeats = (_toActionDouble(
              data['min_length_beats'] ?? target['min_length_beats'],
            ) ??
            0.03125)
        .clamp(0.0005, 4.0)
        .toDouble();
    final velocityDecayPerSlice = (_toActionDouble(
              data['velocity_decay_per_slice'] ??
                  target['velocity_decay_per_slice'] ??
                  data['decay_per_slice'] ??
                  target['decay_per_slice'] ??
                  data['velocity_decay'] ??
                  target['velocity_decay'] ??
                  data['stutter_decay'] ??
                  target['stutter_decay'],
            ) ??
            0.0)
        .clamp(-1.0, 1.0)
        .toDouble();
    final velocityJitter = (_toActionDouble(
              data['velocity_jitter'] ??
                  target['velocity_jitter'] ??
                  data['humanize_velocity_jitter'] ??
                  target['humanize_velocity_jitter'],
            ) ??
            0.0)
        .clamp(0.0, 1.0)
        .toDouble();
    final velocityFloor = (_toActionDouble(
              data['velocity_floor'] ??
                  target['velocity_floor'] ??
                  data['min_velocity'] ??
                  target['min_velocity'],
            ) ??
            0.05)
        .clamp(0.0, 1.0)
        .toDouble();
    final fromBeat = _toActionDouble(
      data['from_beat'] ?? target['from_beat'] ?? data['start_beat'],
    );
    final toBeat = _toActionDouble(
      data['to_beat'] ?? target['to_beat'] ?? data['end_beat'],
    );

    return AssistantActionUtils.chopMidiNotes(
      notes: sourceNotes,
      subdivision: safeSubdivision,
      stepBeats: stepBeats,
      sustainRatio: sustainRatio,
      minLengthBeats: minLengthBeats,
      velocityDecayPerSlice: velocityDecayPerSlice,
      velocityJitter: velocityJitter,
      velocityFloor: velocityFloor,
      fromBeat: fromBeat,
      toBeat: toBeat,
      noteIdPrefix: 'ai_chop',
    );
  }

  Future<void> _applyMidiComposeAction(
    Map<String, dynamic> data, {
    int? chatFlowId,
  }) async {
    final operation = _normalizeMidiComposeOperation(
      (data['operation'] ?? '').toString().trim().toLowerCase(),
    );
    final target = _actionTarget(data);
    final forceCreateNewClip =
        _shouldCreateFreshMidiClip(data, target, operation);

    if (operation == 'convert_audio_to_midi') {
      final sourceClipIndex = _resolveSingleClipIndexWithFallback(
        data,
        requireAudio: true,
      );
      if (sourceClipIndex == null ||
          sourceClipIndex < 0 ||
          sourceClipIndex >= _audioTracks.length) {
        _insertAssistantChatText(
            "I couldn't resolve which audio clip to convert to MIDI.");
        return;
      }
      await _convertAudioClipToMidi(
        sourceClipIndex,
        data,
        target,
        chatFlowId,
      );
      return;
    }

    int? clipIndex;
    if (!forceCreateNewClip) {
      clipIndex = _resolveSingleClipIndexWithFallback(
        data,
        requireMidi: true,
      );
      if (clipIndex == null) {
        final rowHint = _resolveRowIndexFromActionTarget(data);
        if (rowHint != null) {
          final midiCandidates = <int>[];
          for (int i = 0; i < _audioTracks.length; i++) {
            final clip = _audioTracks[i];
            if (!clip.isMidi) continue;
            if (clip.rowIndex != rowHint) continue;
            midiCandidates.add(i);
          }
          clipIndex = _pickPreferredClipIndex(midiCandidates);
        }
      }
    }

    if (operation == 'chop_notes') {
      if (clipIndex == null ||
          clipIndex < 0 ||
          clipIndex >= _audioTracks.length) {
        _insertAssistantChatText(
            "I couldn't resolve which MIDI clip to chop. Select a MIDI clip and ask again.");
        return;
      }
      final clip = _audioTracks[clipIndex];
      if (!clip.isMidi) {
        _insertAssistantChatText('The selected clip is not a MIDI clip.');
        return;
      }
      if (clip.midiNotes.isEmpty) {
        _insertAssistantChatText('The target MIDI clip has no notes to chop.');
        return;
      }

      final oldNotes = clip.midiNotes.map((n) => n.copy()).toList();
      final oldParams = Map<String, double>.from(clip.instrumentParams);
      final oldInstrumentId = clip.instrumentId;
      final oldInstrumentName = clip.instrumentName;
      final subdivision = _midiSubdivisionFromActionData(data, fallback: 16);
      final decayPerSlice = (_toActionDouble(
                data['velocity_decay_per_slice'] ??
                    data['decay_per_slice'] ??
                    data['velocity_decay'] ??
                    data['stutter_decay'],
              ) ??
              0.0)
          .toDouble();
      final nextNotes = _chopMidiNotesFromActionData(
        data,
        oldNotes,
        subdivision: subdivision,
      );

      if (_midiNotesEqual(oldNotes, nextNotes)) {
        _showSmallNotice('MIDI notes already match that chop grid.');
        return;
      }

      await _undoManager.execute(
        EditMidiClipAction(
          tracks: _audioTracks,
          originalIndex: clipIndex,
          oldNotes: oldNotes,
          newNotes: nextNotes,
          oldInstrumentId: oldInstrumentId,
          oldInstrumentName: oldInstrumentName,
          oldInstrumentParams: oldParams,
          newInstrumentId: oldInstrumentId,
          newInstrumentName: oldInstrumentName,
          newInstrumentParams: oldParams,
          applyToClip: (target, notesToApply, nextInstrumentId,
              nextInstrumentName, nextParams) async {
            target.midiNotes = notesToApply.map((n) => n.copy()).toList();
            target.instrumentId = nextInstrumentId;
            target.instrumentName = nextInstrumentName;
            target.instrumentParams = Map<String, double>.from(nextParams);
            target.sourceTempoBpm = _clampTempo(_tempo);
            target.stretchToProjectTempo = true;
            target.tempoStretchPreservePitch = true;
            final updatedLive = await _updateMidiClipEventsLive(target);
            if (updatedLive) {
              final clipIdx = _clipIndexForEngineId(target.engineClipId);
              if (clipIdx >= 0) {
                await _syncClipTimingToEngine(clipIdx);
              }
              await _syncClipMixToEngine(target);
              _updateOverallDurationIfNeeded();
            } else {
              final reloaded = await _reloadMidiTrackLive(target);
              if (!reloaded && mounted) {
                _showSmallNotice('Could not update this MIDI clip.');
              }
            }
            if (mounted) setState(() {});
          },
        ),
      );
      final withDecay = decayPerSlice.abs() > 0.0001;
      _showSmallNotice(
        withDecay
            ? 'Chopped MIDI notes to 1/$subdivision with velocity decay.'
            : 'Chopped MIDI notes to 1/$subdivision.',
      );
      return;
    }

    if (operation == 'transpose_notes') {
      if (clipIndex == null ||
          clipIndex < 0 ||
          clipIndex >= _audioTracks.length) {
        _insertAssistantChatText(
            "I couldn't resolve which MIDI clip to transpose. Select a MIDI clip and ask again.");
        return;
      }
      final clip = _audioTracks[clipIndex];
      if (!clip.isMidi) {
        _insertAssistantChatText('The selected clip is not a MIDI clip.');
        return;
      }
      if (clip.midiNotes.isEmpty) {
        _insertAssistantChatText(
            'The target MIDI clip has no notes to transpose.');
        return;
      }

      final semitones = ((_toActionDouble(data['semitones']) ?? 0.0) +
              ((_toActionDouble(data['octaves']) ?? 0.0) * 12.0))
          .round();
      if (semitones == 0) {
        _showSmallNotice('MIDI notes already match that pitch.');
        return;
      }

      final oldNotes = clip.midiNotes.map((n) => n.copy()).toList();
      final oldParams = Map<String, double>.from(clip.instrumentParams);
      final oldInstrumentId = clip.instrumentId;
      final oldInstrumentName = clip.instrumentName;
      final nextNotes = oldNotes
          .map((n) => MidiNote(
                id: n.id,
                pitch: (n.pitch + semitones).clamp(0, 127).toInt(),
                startBeat: n.startBeat,
                lengthBeats: n.lengthBeats,
                velocity: n.velocity,
              ))
          .toList(growable: false);

      await _undoManager.execute(
        EditMidiClipAction(
          tracks: _audioTracks,
          originalIndex: clipIndex,
          oldNotes: oldNotes,
          newNotes: nextNotes,
          oldInstrumentId: oldInstrumentId,
          oldInstrumentName: oldInstrumentName,
          oldInstrumentParams: oldParams,
          newInstrumentId: oldInstrumentId,
          newInstrumentName: oldInstrumentName,
          newInstrumentParams: oldParams,
          applyToClip: (target, notesToApply, nextInstrumentId,
              nextInstrumentName, nextParams) async {
            target.midiNotes = notesToApply.map((n) => n.copy()).toList();
            target.instrumentId = nextInstrumentId;
            target.instrumentName = nextInstrumentName;
            target.instrumentParams = Map<String, double>.from(nextParams);
            target.sourceTempoBpm = _clampTempo(_tempo);
            target.stretchToProjectTempo = true;
            target.tempoStretchPreservePitch = true;
            final updatedLive = await _updateMidiClipEventsLive(target);
            if (updatedLive) {
              final clipIdx = _clipIndexForEngineId(target.engineClipId);
              if (clipIdx >= 0) {
                await _syncClipTimingToEngine(clipIdx);
              }
              await _syncClipMixToEngine(target);
              _updateOverallDurationIfNeeded();
            } else {
              final reloaded = await _reloadMidiTrackLive(target);
              if (!reloaded && mounted) {
                _showSmallNotice('Could not update this MIDI clip.');
              }
            }
            if (mounted) setState(() {});
          },
        ),
      );
      final direction = semitones > 0 ? 'up' : 'down';
      final amount = semitones.abs() == 12
          ? '1 octave'
          : semitones.abs() % 12 == 0
              ? '${(semitones.abs() / 12).round()} octaves'
              : '${semitones.abs()} semitones';
      _showSmallNotice('Shifted MIDI notes $direction by $amount.');
      return;
    }

    final preserveExistingNotes =
        _shouldPreserveExistingMidiNotes(data, target, operation);
    var notes = _midiNotesFromActionData(data);
    if (notes.isEmpty) {
      notes = _fallbackMidiNotesFromProgression(data);
    }
    if (notes.isEmpty &&
        clipIndex != null &&
        clipIndex >= 0 &&
        clipIndex < _audioTracks.length) {
      final sourceClip = _audioTracks[clipIndex];
      if (sourceClip.isMidi &&
          sourceClip.midiNotes.isNotEmpty &&
          AssistantActionUtils.hasStyleDrivenMidiGenerationDirectives(
            data,
            target: target,
          )) {
        notes = AssistantActionUtils.generateStyledMidiNotesFromSource(
          sourceNotes: sourceClip.midiNotes,
          data: data,
          target: target,
          noteIdPrefix: 'ai_style',
        );
      }
    }
    if (notes.isEmpty &&
        clipIndex != null &&
        clipIndex >= 0 &&
        clipIndex < _audioTracks.length &&
        preserveExistingNotes) {
      final clip = _audioTracks[clipIndex];
      if (!clip.isMidi) {
        _insertAssistantChatText('The selected clip is not a MIDI clip.');
        return;
      }
      if (clip.midiNotes.isEmpty) {
        _insertAssistantChatText(
            'The target MIDI clip has no notes to extend yet.');
        return;
      }
      final targetLengthBeats = _resolveMidiTargetLengthBeats(data, target);
      if (targetLengthBeats == null) {
        _insertAssistantChatText(
            'I need a target MIDI length in measures or beats for that edit.');
        return;
      }
      final oldNotes = clip.midiNotes.map((n) => n.copy()).toList();
      final nextNotes = _resizeMidiNotesToTargetLength(
        oldNotes,
        targetLengthBeats,
      );
      if (nextNotes.isEmpty) {
        _insertAssistantChatText("I couldn't reshape that MIDI clip cleanly.");
        return;
      }
      if (_midiNotesEqual(oldNotes, nextNotes)) {
        _showSmallNotice('That MIDI clip is already that long.');
        return;
      }
      final oldParams = Map<String, double>.from(clip.instrumentParams);
      final oldInstrumentId = clip.instrumentId;
      final oldInstrumentName = clip.instrumentName;
      await _undoManager.execute(
        EditMidiClipAction(
          tracks: _audioTracks,
          originalIndex: clipIndex,
          oldNotes: oldNotes,
          newNotes: nextNotes,
          oldInstrumentId: oldInstrumentId,
          oldInstrumentName: oldInstrumentName,
          oldInstrumentParams: oldParams,
          newInstrumentId: oldInstrumentId,
          newInstrumentName: oldInstrumentName,
          newInstrumentParams: oldParams,
          applyToClip: (targetClip, notesToApply, nextInstrumentId,
              nextInstrumentName, nextParams) async {
            targetClip.midiNotes = notesToApply.map((n) => n.copy()).toList();
            targetClip.instrumentId = nextInstrumentId;
            targetClip.instrumentName = nextInstrumentName;
            targetClip.instrumentParams = Map<String, double>.from(nextParams);
            targetClip.sourceTempoBpm = _clampTempo(_tempo);
            targetClip.stretchToProjectTempo = true;
            targetClip.tempoStretchPreservePitch = true;
            final updatedLive = await _updateMidiClipEventsLive(targetClip);
            if (updatedLive) {
              final clipIdx = _clipIndexForEngineId(targetClip.engineClipId);
              if (clipIdx >= 0) {
                await _syncClipTimingToEngine(clipIdx);
              }
              await _syncClipMixToEngine(targetClip);
              _updateOverallDurationIfNeeded();
            } else {
              final reloaded = await _reloadMidiTrackLive(targetClip);
              if (!reloaded && mounted) {
                _showSmallNotice('Could not update this MIDI clip.');
              }
            }
            if (mounted) setState(() {});
          },
        ),
      );
      final roundedMeasures = targetLengthBeats / 4.0;
      final lengthLabel = roundedMeasures == roundedMeasures.roundToDouble()
          ? '${roundedMeasures.round()} bars'
          : '${targetLengthBeats.toStringAsFixed(1)} beats';
      _showSmallNotice('Extended MIDI clip to $lengthLabel.');
      return;
    }
    if (notes.isEmpty) {
      _insertAssistantChatText(
          "I need MIDI notes (or a chord progression) to write this part.");
      return;
    }

    final targetLengthBeats = _resolveMidiTargetLengthBeats(data, target);
    if (targetLengthBeats != null &&
        targetLengthBeats.isFinite &&
        targetLengthBeats > 0.0) {
      final currentSpan = notes
          .map((n) => n.startBeat + n.lengthBeats)
          .fold<double>(0.0, math.max);
      if (currentSpan > 0.0 && currentSpan < targetLengthBeats - 1e-6) {
        notes = _resizeMidiNotesToTargetLength(notes, targetLengthBeats);
      }
    }

    if (clipIndex == null ||
        clipIndex < 0 ||
        clipIndex >= _audioTracks.length) {
      final preferredInstrumentId = _preferredAiInstrumentIdForNewMidiClip(
        data,
        target,
        operation,
        notes,
      );
      final row = _resolveInsertionRowIndexFromActionTarget(data);
      final instrumentId = _resolveAiInstrumentIdFromActionData(
        data,
        target,
        preferredInstrumentId,
      );
      final instrumentName = (data['instrument_name'] ??
              target['instrument_name'] ??
              _instrumentNameFromId(instrumentId))
          .toString()
          .trim();
      final startMs = _toActionDouble(data['start_ms'] ?? target['start_ms']) ??
          _globalAudioClock.inMilliseconds.toDouble();
      final beforeTrackCount = _audioTracks.length;
      final addMidiAction = AddMidiClipAction(
        addMidiClip: ({
          required String instrumentId,
          required String instrumentName,
          required Map<String, double> instrumentParams,
          required List<MidiNote> midiNotes,
          required int row,
          required double timeMs,
        }) =>
            _addMidiTrack(
          instrumentId: instrumentId,
          instrumentName: instrumentName,
          instrumentParams: instrumentParams,
          midiNotes: midiNotes,
          row: row,
          timeMs: timeMs,
          label: data['label']?.toString(),
        ),
        tracks: _audioTracks,
        instrumentId: instrumentId,
        instrumentName: instrumentName.isEmpty ? instrumentId : instrumentName,
        instrumentParams:
            _instrumentParamsFromSpec(_instrumentSpecById(instrumentId)),
        midiNotes: notes,
        row: row,
        timeMs: math.max(0.0, startMs),
      );
      await _undoManager.execute(addMidiAction);
      if (_audioTracks.length == beforeTrackCount) {
        _insertAssistantChatText(
          _isSampledInstrumentId(instrumentId)
              ? "I couldn't load that sampled instrument for live MIDI playback."
              : "I couldn't create that MIDI clip.",
        );
        return;
      }
      _showSmallNotice('Created MIDI clip from AI notes.');
      return;
    }

    final clip = _audioTracks[clipIndex];
    if (!clip.isMidi) {
      _insertAssistantChatText('The selected clip is not a MIDI clip.');
      return;
    }

    final append = _toActionBool(
      data['append'],
      fallback: operation.contains('append'),
    );
    final oldNotes = clip.midiNotes.map((n) => n.copy()).toList();
    final oldParams = Map<String, double>.from(clip.instrumentParams);
    final oldInstrumentId = clip.instrumentId;
    final oldInstrumentName = clip.instrumentName;

    List<MidiNote> nextNotes = notes.map((n) => n.copy()).toList();
    if (append) {
      final explicitAppendStartBeat =
          _toActionDouble(data['append_start_beat']);
      double appendStartBeat = explicitAppendStartBeat ?? 0.0;
      final appendAtEnd = _toActionBool(
        data['append_at_end'],
        fallback: !preserveExistingNotes,
      );
      if (appendAtEnd && oldNotes.isNotEmpty) {
        appendStartBeat =
            oldNotes.map((n) => n.startBeat + n.lengthBeats).reduce(math.max);
      } else if (explicitAppendStartBeat == null && preserveExistingNotes) {
        appendStartBeat = 0.0;
      }
      nextNotes = [
        ...oldNotes.map((n) => n.copy()),
        ...notes.map((n) => MidiNote(
              id: 'ai_note_${DateTime.now().microsecondsSinceEpoch}_${n.pitch}',
              pitch: n.pitch,
              startBeat: n.startBeat + appendStartBeat,
              lengthBeats: n.lengthBeats,
              velocity: n.velocity,
            )),
      ];
    }

    await _undoManager.execute(
      EditMidiClipAction(
        tracks: _audioTracks,
        originalIndex: clipIndex,
        oldNotes: oldNotes,
        newNotes: nextNotes,
        oldInstrumentId: oldInstrumentId,
        oldInstrumentName: oldInstrumentName,
        oldInstrumentParams: oldParams,
        newInstrumentId: oldInstrumentId,
        newInstrumentName: oldInstrumentName,
        newInstrumentParams: oldParams,
        applyToClip: (target, notesToApply, nextInstrumentId,
            nextInstrumentName, nextParams) async {
          target.midiNotes = notesToApply.map((n) => n.copy()).toList();
          target.instrumentId = nextInstrumentId;
          target.instrumentName = nextInstrumentName;
          target.instrumentParams = Map<String, double>.from(nextParams);
          target.sourceTempoBpm = _clampTempo(_tempo);
          target.stretchToProjectTempo = true;
          target.tempoStretchPreservePitch = true;
          final updatedLive = await _updateMidiClipEventsLive(target);
          if (updatedLive) {
            final clipIdx = _clipIndexForEngineId(target.engineClipId);
            if (clipIdx >= 0) {
              await _syncClipTimingToEngine(clipIdx);
            }
            await _syncClipMixToEngine(target);
            _updateOverallDurationIfNeeded();
          } else {
            final reloaded = await _reloadMidiTrackLive(target);
            if (!reloaded && mounted) {
              _showSmallNotice('Could not update this MIDI clip.');
            }
          }
          if (mounted) setState(() {});
        },
      ),
    );
    _showSmallNotice(
      append ? 'Appended MIDI notes.' : 'Updated MIDI notes.',
    );
  }

  Future<_RowLayoutSnapshotAction?> _ensureDedicatedOutputRowBelow({
    required int sourceRow,
  }) async {
    if (sourceRow < 0) return null;
    final targetRow = sourceRow + 1;
    if (targetRow >= kMaxRows) return null;

    final hasExistingRowBelow = _rowCount > targetRow;
    final rowBelowHasAnyClip = hasExistingRowBelow &&
        _audioTracks.any((clip) => clip.rowIndex == targetRow);
    if (hasExistingRowBelow && !rowBelowHasAnyClip) {
      return null;
    }
    if (!hasExistingRowBelow && _rowCount >= kMaxRows) {
      return null;
    }

    final before = await _captureRowLayoutSnapshot();
    final inserted = await _insertRowBelowImpl(sourceRow);
    if (!inserted) return null;
    final after = await _captureRowLayoutSnapshot();
    if (after.rows.length == before.rows.length) return null;

    return _RowLayoutSnapshotAction(
      descriptionText: 'Insert row for audio-to-MIDI clip',
      before: before,
      after: after,
      applySnapshot: _applyRowLayoutSnapshot,
    );
  }

  Future<void> _convertAudioClipToMidi(
    int sourceClipIndex,
    Map<String, dynamic> data,
    Map<String, dynamic> target,
    int? chatFlowId,
  ) async {
    final sourceClip = _audioTracks[sourceClipIndex];
    if (sourceClip.isMidi) {
      _insertAssistantChatText('Audio-to-MIDI only works on audio clips.');
      return;
    }

    final sourceRow = sourceClip.rowIndex;
    if (sourceRow < 0 || sourceRow >= kMaxRows - 1) {
      _insertAssistantChatText(
          'I need an available row below that clip to place the MIDI result.');
      return;
    }

    _showSmallNotice('Converting audio to MIDI...');
    final notes = await _transcribeAudioClipToMidiNotes(sourceClip);
    if (chatFlowId != null) {
      _throwIfChatFlowStopped(chatFlowId);
    }
    if (notes.isEmpty) {
      _insertAssistantChatText(
          "I couldn't extract stable notes from that audio clip.");
      return;
    }

    final defaultInstrumentId = _preferredAiInstrumentIdForNewMidiClip(
      data,
      target,
      'convert_audio_to_midi',
      notes,
    );
    final instrumentId = _resolveAiInstrumentIdFromActionData(
      data,
      target,
      defaultInstrumentId,
    );
    final instrumentName = (data['instrument_name'] ??
            target['instrument_name'] ??
            _instrumentNameFromId(instrumentId))
        .toString()
        .trim();
    final clipLabel = (data['label']?.toString().trim().isNotEmpty ?? false)
        ? data['label'].toString().trim()
        : sourceClip.label.trim().isEmpty
            ? 'Audio to MIDI'
            : '${sourceClip.label} MIDI';
    final startMs = _clipTimelineStartMs(sourceClip);

    final rowLayoutAction = await _ensureDedicatedOutputRowBelow(
      sourceRow: sourceRow,
    );
    if (_rowCount <= sourceRow + 1) {
      if (rowLayoutAction != null) {
        await rowLayoutAction.undo();
      }
      _insertAssistantChatText(
          'I could not create a dedicated row below that clip for the MIDI result.');
      return;
    }
    final targetRow = (sourceRow + 1).clamp(0, _rowCount - 1).toInt();
    final addMidiAction = AddMidiClipAction(
      addMidiClip: ({
        required String instrumentId,
        required String instrumentName,
        required Map<String, double> instrumentParams,
        required List<MidiNote> midiNotes,
        required int row,
        required double timeMs,
      }) =>
          _addMidiTrack(
        instrumentId: instrumentId,
        instrumentName: instrumentName,
        instrumentParams:
            _instrumentParamsFromSpec(_instrumentSpecById(instrumentId)),
        midiNotes: midiNotes,
        row: row,
        timeMs: timeMs,
        label: clipLabel,
      ),
      tracks: _audioTracks,
      instrumentId: instrumentId,
      instrumentName: instrumentName.isEmpty
          ? _instrumentNameFromId(instrumentId)
          : instrumentName,
      instrumentParams:
          _instrumentParamsFromSpec(_instrumentSpecById(instrumentId)),
      midiNotes: notes,
      row: targetRow,
      timeMs: startMs,
    );

    try {
      final beforeCount = _audioTracks.length;
      await _undoManager.executeWithoutAdd(addMidiAction);
      final added = _audioTracks.length == beforeCount + 1;
      if (!added) {
        throw StateError('Failed to add audio-to-MIDI clip.');
      }

      if (rowLayoutAction != null) {
        await _undoManager.addWithoutExecute(
          CompoundUndoAction(
            'Convert audio to MIDI',
            <EditorUndoAction>[
              rowLayoutAction,
              addMidiAction,
            ],
          ),
        );
      } else {
        await _undoManager.addWithoutExecute(addMidiAction);
      }
      _showSmallNotice('Created MIDI clip below the source audio.');
    } catch (error) {
      debugPrint('Audio-to-MIDI conversion failed: $error');
      await addMidiAction.undo();
      if (rowLayoutAction != null) {
        await rowLayoutAction.undo();
      }
      _insertAssistantChatText(
          "I couldn't place the MIDI clip for that audio.");
    }
  }

  Future<void> _applyStemSeparateAction(Map<String, dynamic> data) async {
    final target = _actionTarget(data);
    final clipIndices =
        _resolveClipIndicesFromActionTarget(data, requireAudio: true);
    if (clipIndices.isEmpty) {
      _insertAssistantChatText(
          "I couldn't resolve which audio clip to separate.");
      return;
    }

    final scope = (target['scope'] ?? data['scope'] ?? '')
        .toString()
        .trim()
        .toLowerCase();
    final explicitMany =
        ((data['clip_indices'] as List?)?.isNotEmpty ?? false) ||
            ((target['clip_indices'] as List?)?.isNotEmpty ?? false) ||
            scope == 'all' ||
            scope == 'all_audio' ||
            scope == 'selected' ||
            scope == 'selection';

    final targets = explicitMany
        ? clipIndices
        : <int>[
            _resolveSingleClipIndexWithFallback(
                  data,
                  requireAudio: true,
                ) ??
                clipIndices.first
          ];

    int success = 0;
    for (final clipIndex in targets) {
      final ok = await _performStemSeparationForClip(
        clipIndex,
        showInlineFailureNotice: !explicitMany,
      );
      if (ok) success++;
    }

    if (success <= 0) {
      if (explicitMany) {
        _showSmallNotice('Stem separation failed for target clips.');
      }
      return;
    }

    if (explicitMany && success > 1) {
      _showSmallNotice('Created stems for $success clips.');
    }
  }

  Future<void> _applyRoleOverrideAction(Map<String, dynamic> data) async {
    final operation =
        (data['operation'] ?? 'set').toString().trim().toLowerCase();
    final row = _resolveRowIndexFromActionTarget(data);
    if (row == null) {
      _insertAssistantChatText(
          "I couldn't resolve which track role to update.");
      return;
    }

    if (operation == 'clear' ||
        operation == 'remove' ||
        operation == 'unset' ||
        operation == 'delete') {
      final cleared = _chatPipeline.clearRoleOverride(row);
      if (cleared) {
        _showSmallNotice(
          'Cleared role override for ${_rowDisplayName(row)}.',
        );
      } else {
        _showSmallNotice(
          '${_rowDisplayName(row)} had no role override set.',
        );
      }
      return;
    }

    final target = _actionTarget(data);
    final role = (data['role'] ?? target['role'] ?? '').toString().trim();
    if (role.isEmpty) {
      _insertAssistantChatText(
          'I need a role value to apply (vocals, drums, bass, guitar, synth, other).');
      return;
    }

    final applied = _chatPipeline.setRoleOverride(rowIndex: row, role: role);
    if (!applied) {
      _insertAssistantChatText(
          'Unsupported role "$role". Use vocals, drums, bass, guitar, synth, or other.');
      return;
    }

    final roleText = role.toLowerCase().trim();
    _showSmallNotice(
      '${_rowDisplayName(row)} role override set to $roleText.',
    );
  }

  Future<void> _handleStemSeparationForClip(int clipIndex) async {
    await _performStemSeparationForClip(clipIndex);
  }

  Future<_RowLayoutSnapshotAction?> _ensureStemOutputRowsBelow({
    required int sourceRow,
    required int stemCount,
  }) async {
    if (sourceRow < 0 || stemCount <= 0) return null;

    final requiredBottomRow = sourceRow + stemCount;
    if (_rowCount > requiredBottomRow) return null;

    final before = await _captureRowLayoutSnapshot();
    while (_rowCount <= requiredBottomRow) {
      if (_rowCount >= kMaxRows) {
        await _applyRowLayoutSnapshot(before);
        return null;
      }
      final added = await _addRowImpl();
      if (!added) {
        await _applyRowLayoutSnapshot(before);
        return null;
      }
    }

    final after = await _captureRowLayoutSnapshot();
    if (after.rows.length == before.rows.length) return null;

    return _RowLayoutSnapshotAction(
      descriptionText: 'Add rows for stem separation',
      before: before,
      after: after,
      applySnapshot: _applyRowLayoutSnapshot,
    );
  }

  Future<bool> _performStemSeparationForClip(
    int clipIndex, {
    bool showInlineFailureNotice = true,
  }) async {
    if (clipIndex < 0 || clipIndex >= _audioTracks.length) return false;
    final clip = _audioTracks[clipIndex];
    if (clip.isMidi) {
      if (showInlineFailureNotice) {
        _showSmallNotice('Stem separation is only available for audio clips.');
      }
      return false;
    }
    if (_audioTracks.length + 2 > kNumClips) {
      if (showInlineFailureNotice) {
        _showSmallNotice(
            "Max number of audio clips reached ($kNumClips). Unable to add more clips.");
      }
      return false;
    }

    final sourcePath = clip.file.path;
    final source = File(sourcePath);
    if (!source.existsSync()) {
      if (showInlineFailureNotice) {
        _showSmallNotice('Selected clip file was not found.');
      }
      return false;
    }

    final audioDir = ProjectManager.audioDir(_projectDir);
    await audioDir.create(recursive: true);
    final stem = p.basenameWithoutExtension(source.path);
    final ts = DateTime.now().millisecondsSinceEpoch;
    final vocalFile = File(p.join(audioDir.path, '${stem}_vocals_$ts.wav'));
    final instrumentalFile =
        File(p.join(audioDir.path, '${stem}_instrumental_$ts.wav'));

    if (showInlineFailureNotice) {
      _showSmallNotice('Splitting stems...');
    }
    try {
      await _spleeterStemSeparator.separateVocalsInstrumental(
        inputPath: source.path,
        vocalsOutputPath: vocalFile.path,
        instrumentalOutputPath: instrumentalFile.path,
      );
    } catch (e) {
      debugPrint('Spleeter stem separation failed: $e');
      if (showInlineFailureNotice) {
        _showSmallNotice('Stem separation failed.');
      }
      return false;
    }

    if (!vocalFile.existsSync() || !instrumentalFile.existsSync()) {
      if (showInlineFailureNotice) {
        _showSmallNotice('Stem separation failed.');
      }
      return false;
    }

    final row = clip.rowIndex;
    const stemCount = 2;
    final vocalsRow = row + 1;
    final instrumentalRow = row + 2;
    if (instrumentalRow >= kMaxRows) {
      if (showInlineFailureNotice) {
        _showSmallNotice(
          'Need two rows below this clip for stem separation, but the row limit was reached.',
        );
      }
      return false;
    }

    final rowLayoutAction = await _ensureStemOutputRowsBelow(
      sourceRow: row,
      stemCount: stemCount,
    );
    if (_rowCount <= instrumentalRow) {
      if (showInlineFailureNotice) {
        _showSmallNotice(
          'Could not create rows below this clip for the separated stems.',
        );
      }
      return false;
    }

    final startMs = clip.offset * 1000.0;
    final trimStart = clip.trimStart;
    final trimEnd = clip.trimEnd;

    final addVocals = AddAudioTrackAction(
      addTrack: ({
        required File file,
        required int row,
        required double timeMs,
        Duration? trimStartRequested,
        Duration? trimEndRequested,
      }) =>
          _addAudioTrackFromProjectFile(
        projectAudioFile: file,
        label: clip.label.trim().isEmpty
            ? 'Vocals Stem'
            : '${clip.label} (Vocals)',
        row: row,
        timeMs: timeMs,
        trimStartRequested: trimStartRequested,
        trimEndRequested: trimEndRequested,
        gain: clip.gain,
        sourceTempoBpm: clip.sourceTempoBpm,
        stretchToProjectTempo: clip.stretchToProjectTempo,
        tempoStretchPreservePitch: clip.tempoStretchPreservePitch,
      ),
      tracks: _audioTracks,
      file: vocalFile,
      row: vocalsRow,
      timeMs: startMs,
      trimStart: trimStart,
      trimEnd: trimEnd,
    );

    final addInstrumental = AddAudioTrackAction(
      addTrack: ({
        required File file,
        required int row,
        required double timeMs,
        Duration? trimStartRequested,
        Duration? trimEndRequested,
      }) =>
          _addAudioTrackFromProjectFile(
        projectAudioFile: file,
        label: clip.label.trim().isEmpty
            ? 'Instrumental Stem'
            : '${clip.label} (Instrumental)',
        row: row,
        timeMs: timeMs,
        trimStartRequested: trimStartRequested,
        trimEndRequested: trimEndRequested,
        gain: clip.gain,
        sourceTempoBpm: clip.sourceTempoBpm,
        stretchToProjectTempo: clip.stretchToProjectTempo,
        tempoStretchPreservePitch: clip.tempoStretchPreservePitch,
      ),
      tracks: _audioTracks,
      file: instrumentalFile,
      row: instrumentalRow,
      timeMs: startMs,
      trimStart: trimStart,
      trimEnd: trimEnd,
    );

    final actions = <EditorUndoAction>[
      if (rowLayoutAction != null) rowLayoutAction,
      addVocals,
      addInstrumental,
    ];

    var vocalsAdded = false;
    var instrumentalAdded = false;
    try {
      final beforeCount = _audioTracks.length;
      await _undoManager.executeWithoutAdd(addVocals);
      vocalsAdded = _audioTracks.length == beforeCount + 1;
      if (!vocalsAdded) {
        throw StateError('Failed to add vocal stem clip.');
      }

      await _undoManager.executeWithoutAdd(addInstrumental);
      instrumentalAdded = _audioTracks.length == beforeCount + 2;
      if (!instrumentalAdded) {
        throw StateError('Failed to add instrumental stem clip.');
      }

      await _undoManager.addWithoutExecute(
        CompoundUndoAction('Separate stems', actions),
      );
    } catch (e) {
      debugPrint('Failed to place separated stems on new rows: $e');
      if (instrumentalAdded) {
        await addInstrumental.undo();
      }
      if (vocalsAdded) {
        await addVocals.undo();
      }
      if (rowLayoutAction != null) {
        await rowLayoutAction.undo();
      }
      if (showInlineFailureNotice) {
        _showSmallNotice('Stem separation failed.');
      }
      return false;
    }

    if (showInlineFailureNotice) {
      _showSmallNotice('Created vocal/instrumental stems.');
    }
    return true;
  }

  Future<int> applyMixingResult(
    MixingResult mix, {
    bool emitActionSummaries = true,
  }) async {
    if (mix.isNoOp || mix.actions.isEmpty) return 0;

    final List<EditorUndoAction> groupedActions = [];
    void emitActionSummary(String text) {
      if (!emitActionSummaries) return;
      _insertSystemChatText(text);
    }

    List<int> rowCandidatesFromAction(Map<String, dynamic> data) {
      if (_rowCount <= 0) return const <int>[];
      final target = _toActionMap(data['target']);
      final candidates = LinkedHashSet<int>();

      void add(dynamic raw, {bool preferOneBased = false}) {
        final parsed = _toActionInt(raw);
        if (parsed == null) return;
        void addIfValid(int idx) {
          if (idx >= 0 && idx < _rowCount) {
            candidates.add(idx);
          }
        }

        final oneBased = parsed - 1;
        if (preferOneBased) {
          if (parsed > 0) addIfValid(oneBased);
          addIfValid(parsed);
          return;
        }
        addIfValid(parsed);
        if (parsed > 0) {
          addIfValid(oneBased);
        }
      }

      add(data['row_index']);
      add(target['row_index']);
      add(data['track_index']);
      add(target['track_index']);
      add(data['row']);
      add(target['row']);
      add(data['target_row_index']);
      add(target['target_row_index']);
      add(data['target_row']);
      add(target['target_row']);
      add(data['row_number'], preferOneBased: true);
      add(target['row_number'], preferOneBased: true);
      add(data['track_number'], preferOneBased: true);
      add(target['track_number'], preferOneBased: true);
      add(data['track'], preferOneBased: true);
      add(target['track'], preferOneBased: true);

      return candidates.toList(growable: false);
    }

    for (final a in mix.actions) {
      switch (a.type) {
        case 'set_row_gain':
          final rowCandidates = rowCandidatesFromAction(a.data);
          if (rowCandidates.isEmpty) continue;
          final row = rowCandidates.first;
          final mode = a.data['mode'] ?? 'delta';

          final oldGain = _rowGain[row];
          double newGain;

          if (mode == 'set') {
            newGain = (a.data['value'] as num).toDouble().clamp(0.0, 3.0);
          } else {
            final delta = (a.data['delta'] as num).toDouble();
            newGain = (oldGain + delta).clamp(0.0, 3.0);
          }

          // _undoManager.execute(
          //   SetRowGainAction(
          //     row: row,
          //     oldGain: oldGain,
          //     newGain: newGain,
          //     applyToState: (r, g) {
          //       setState(() {
          //         _rowGain[r] = g;
          //       });
          //     },
          //   ),
          // );

          EditorUndoAction finalAct = SetRowGainAction(
            row: row,
            oldGain: oldGain,
            newGain: newGain,
            applyToState: (r, g) {
              setState(() {
                _rowGain[r] = g;
              });
            },
          );

          _undoManager.executeWithoutAdd(
            finalAct,
          ); // need this so that you can make a compound undo action while preserving execute order
          groupedActions.add(finalAct);

          _mixHighlighter
              .trigger([HaloKey('row:$row'), HaloKey('row:$row:mixer')]);

          final summary =
              '• Adjusted Gain from ${_gainToDb(oldGain)} to ${_gainToDb(newGain)} on ${_rowDisplayName(row)} •';
          emitActionSummary(summary);

          continue;

        case 'set_row_pan':
          final rowCandidates = rowCandidatesFromAction(a.data);
          if (rowCandidates.isEmpty) continue;
          final row = rowCandidates.first;

          final oldPan01 = _rowPan[row]; // 0..1

          double newPan01;

          if (a.data.containsKey('value')) {
            // ABSOLUTE SET (0..1, center = 0.5)
            newPan01 = (a.data['value'] as num).toDouble().clamp(0.0, 1.0);
          } else {
            // DELTA in signed space (-1..+1)
            final deltaSigned = (a.data['delta'] as num).toDouble();

            final oldPanSigned = (oldPan01 * 2.0) - 1.0;
            final newPanSigned = (oldPanSigned + deltaSigned).clamp(-1.0, 1.0);
            newPan01 = ((newPanSigned + 1.0) * 0.5).clamp(0.0, 1.0);
          }

          // _undoManager.execute(
          //   SetRowPanAction(
          //     row: row,
          //     oldPan: oldPan01,
          //     newPan: newPan01,
          //     applyToState: (r, p) {
          //       setState(() {
          //         _rowPan[r] = p;
          //       });
          //     },
          //   ),
          // );

          EditorUndoAction finalAct = SetRowPanAction(
            row: row,
            oldPan: oldPan01,
            newPan: newPan01,
            applyToState: (r, p) {
              setState(() {
                _rowPan[r] = p;
              });
            },
          );

          _undoManager.executeWithoutAdd(
            finalAct,
          ); // need this so that you can make a compound undo action while preserving execute order
          groupedActions.add(finalAct);

          final summary =
              '• Adjusted pan from ${panToText(oldPan01)} to ${panToText(newPan01)} on ${_rowDisplayName(row)} •';
          emitActionSummary(summary);
          continue;

        case 'set_master_gain':
          {
            final mode = a.data['mode'] ?? 'delta';
            final oldGain = _masterGain;

            final double newGain;
            if (mode == 'set') {
              newGain = (a.data['value'] as num).toDouble().clamp(0.0, 3.0);
            } else {
              final delta = (a.data['delta'] as num?)?.toDouble() ?? 0.0;
              newGain = (oldGain + delta).clamp(0.0, 3.0);
            }

            final finalAct = SetMasterGainAction(
              oldGain: oldGain,
              newGain: newGain,
              applyToState: (g) {
                setState(() {
                  _masterGain = g;
                });
              },
            );

            await _undoManager.executeWithoutAdd(finalAct);
            groupedActions.add(finalAct);

            emitActionSummary(
              '• Adjusted Master Gain from ${_gainToDb(oldGain)} to ${_gainToDb(newGain)} •',
            );
            continue;
          }

        case 'set_master_pan':
          {
            final oldPan01 = _masterPan;
            final mode = (a.data['mode'] as String?) ?? 'delta';

            final double newPan01;
            if (mode == 'set' || a.data.containsKey('value')) {
              newPan01 = (a.data['value'] as num).toDouble().clamp(0.0, 1.0);
            } else {
              final deltaSigned = (a.data['delta'] as num?)?.toDouble() ?? 0.0;
              final oldPanSigned = (oldPan01 * 2.0) - 1.0;
              final nextSigned = (oldPanSigned + deltaSigned).clamp(-1.0, 1.0);
              newPan01 = ((nextSigned + 1.0) * 0.5).clamp(0.0, 1.0);
            }

            final finalAct = SetMasterPanAction(
              oldPan: oldPan01,
              newPan: newPan01,
              applyToState: (p) {
                setState(() {
                  _masterPan = p;
                });
              },
            );

            await _undoManager.executeWithoutAdd(finalAct);
            groupedActions.add(finalAct);

            emitActionSummary(
              '• Adjusted Master Pan from ${panToText(oldPan01)} to ${panToText(newPan01)} •',
            );
            continue;
          }

        case 'delete_effect':
          {
            final contains =
                (a.data['effect_name_contains'] as String).toLowerCase();
            final rowCandidates = rowCandidatesFromAction(a.data);
            if (rowCandidates.isEmpty) continue;

            int? appliedRow;
            String? removedEffectName;
            EditorUndoAction? appliedAction;
            for (final row in rowCandidates) {
              final effects = await JuceAudioEngine.getTrackEffectsForRow(row);
              final idx =
                  effects.indexWhere((e) => e.toLowerCase().contains(contains));
              if (idx == -1) continue;
              final effectName = effects[idx];
              final beforeCount = effects.length;
              final act = RemoveEffectAction(
                row: row,
                effectIndex: idx,
                pathOrName: effectName,
                onChange: () {
                  setState(() {});
                  _refreshRowFx(row);
                  unawaited(_refreshAutomationTargetsForRow(row));
                },
              );
              await _undoManager.executeWithoutAdd(act);
              final afterEffects =
                  await JuceAudioEngine.getTrackEffectsForRow(row);
              final removed = afterEffects.length < beforeCount ||
                  !afterEffects
                      .any((e) => e.toLowerCase() == effectName.toLowerCase());
              if (!removed) {
                continue;
              }
              appliedRow = row;
              removedEffectName = effectName;
              appliedAction = act;
              break;
            }

            if (appliedRow == null ||
                removedEffectName == null ||
                appliedAction == null) {
              continue;
            }

            groupedActions.add(appliedAction);

            _mixHighlighter.trigger([
              HaloKey('row:$appliedRow'),
              HaloKey('row:$appliedRow:effects_tab'),
              HaloKey('row:$appliedRow:fx_list'),
              HaloKey('row:$appliedRow:fx_contains:$contains'),
            ]);

            emitActionSummary(
              '• Removed $removedEffectName from ${_rowDisplayName(appliedRow)} •',
            );
            continue;
          }

        case 'delete_master_effect':
          {
            final contains =
                (a.data['effect_name_contains'] as String).toLowerCase();
            final effects = await JuceAudioEngine.getMasterEffects();
            final idx =
                effects.indexWhere((e) => e.toLowerCase().contains(contains));
            if (idx == -1) continue;

            final finalAct = RemoveMasterEffectAction(
              effectIndex: idx,
              pathOrName: effects[idx],
              onChange: () {
                setState(() {});
                unawaited(_refreshAutomationTargetsForAllRows());
              },
            );

            await _undoManager.executeWithoutAdd(finalAct);
            groupedActions.add(finalAct);

            emitActionSummary('• Removed ${effects[idx]} from Master Bus •');
            continue;
          }

        case 'ensure_effect':
          final contains =
              (a.data['effect_name_contains'] as String).toLowerCase();
          final rowCandidates = rowCandidatesFromAction(a.data);
          if (rowCandidates.isEmpty) continue;

          final effectName = pickMixroomEffect(contains);
          if (effectName == null) continue;

          int? appliedRow;
          EditorUndoAction? appliedAction;
          for (final row in rowCandidates) {
            final effects = await JuceAudioEngine.getTrackEffectsForRow(row);
            final already =
                effects.indexWhere((e) => e.toLowerCase().contains(contains));
            if (already != -1) {
              appliedRow = row;
              break;
            }
            final beforeCount = effects.length;
            final act = InsertEffectAction(
              row: row,
              pathOrName: effectName,
              onChange: () {
                setState(() {});
                _refreshRowFx(row);
                unawaited(_refreshAutomationTargetsForRow(row));
              },
            );
            await _undoManager.executeWithoutAdd(act);
            final afterEffects =
                await JuceAudioEngine.getTrackEffectsForRow(row);
            final inserted = afterEffects.length > beforeCount &&
                afterEffects.any(
                  (e) =>
                      e.toLowerCase().contains(contains) ||
                      e.toLowerCase().contains(effectName.toLowerCase()),
                );
            if (!inserted) {
              continue;
            }
            appliedRow = row;
            appliedAction = act;
            break;
          }

          if (appliedRow == null) continue;
          if (appliedAction != null) {
            groupedActions.add(appliedAction);
          }

          _mixHighlighter.trigger([
            HaloKey('row:$appliedRow'),
            HaloKey('row:$appliedRow:effects_tab'),
            HaloKey('row:$appliedRow:fx_list'),
            HaloKey('row:$appliedRow:fx_contains:$contains'),
          ]);

          if (appliedAction != null) {
            final summary =
                '• Added $effectName to ${_rowDisplayName(appliedRow)} •';
            emitActionSummary(summary);
          }
          continue;

        case 'ensure_master_effect':
          {
            final contains =
                (a.data['effect_name_contains'] as String).toLowerCase();
            final effects = await JuceAudioEngine.getMasterEffects();
            final already =
                effects.indexWhere((e) => e.toLowerCase().contains(contains));
            if (already != -1) continue;

            final effectName = pickMixroomEffect(contains);
            if (effectName == null) continue;

            final finalAct = InsertMasterEffectAction(
              pathOrName: effectName,
              onChange: () {
                setState(() {});
                unawaited(_refreshAutomationTargetsForAllRows());
              },
            );

            await _undoManager.executeWithoutAdd(finalAct);
            groupedActions.add(finalAct);

            emitActionSummary('• Added $effectName to Master Bus •');
            continue;
          }

        case 'adjust_effect_param_by_name':
          {
            final rowCandidates = rowCandidatesFromAction(a.data);
            if (rowCandidates.isEmpty) continue;
            final row = rowCandidates.first;
            final effectContains =
                (a.data['effect_name_contains'] as String).toLowerCase();

            final skipIfMissing =
                (a.data['skip_if_missing_effect'] as bool?) ?? true;

            final effects = await JuceAudioEngine.getTrackEffectsForRow(row);
            final fxIndex = effects
                .indexWhere((e) => e.toLowerCase().contains(effectContains));
            if (fxIndex == -1) {
              if (skipIfMissing) continue;
              // else: you could ensure_effect first; but typically model emits ensure_effect already
              continue;
            }

            final paramsRaw =
                await JuceAudioEngine.getTrackPluginParameters(row, fxIndex);
            final params =
                paramsRaw.map((e) => Map<String, dynamic>.from(e)).toList();

            final exactParamName = a.data['param_name'] as String?;
            final containsAny = (a.data['param_name_contains_any'] as List?)
                ?.map((e) => e.toString())
                .toList();

            final picked = _pickParam(params,
                exactName: exactParamName, containsAny: containsAny);
            if (picked == null) continue;

            final paramId = (picked['id'] as String?) ??
                (picked['name'] as String); // robust
            final paramName = (picked['name'] as String?) ?? paramId;
            final current = (picked['value'] as num).toDouble();

            final double? pMin =
                picked['min'] is num ? (picked['min'] as num).toDouble() : null;
            final double? pMax =
                picked['max'] is num ? (picked['max'] as num).toDouble() : null;

            final clamp01 = (a.data['clamp_0_1'] as bool?) ?? false;

            final mode = (a.data['mode'] as String?) ?? 'delta';

            double next = current;

            if (mode == 'set') {
              if (a.data.containsKey('value_norm') &&
                  pMin != null &&
                  pMax != null) {
                final vn =
                    (a.data['value_norm'] as num).toDouble().clamp(0.0, 1.0);
                next = pMin + (pMax - pMin) * vn;
              } else {
                next = (a.data['value'] as num).toDouble();
              }
            } else {
              // delta mode
              double delta;
              if (a.data.containsKey('delta_norm')) {
                final dn = (a.data['delta_norm'] as num).toDouble();
                if (pMin != null && pMax != null) {
                  delta = dn * (pMax - pMin);
                } else {
                  delta = dn;
                }
              } else {
                delta = (a.data['delta'] as num).toDouble();
              }
              next = current + delta;
            }

            // -----------------------------
            // HARD SAFETY CLAMPS (action-level)
            // -----------------------------
            final double? hardMin = a.data['clamp_min'] is num
                ? (a.data['clamp_min'] as num).toDouble()
                : null;
            final double? hardMax = a.data['clamp_max'] is num
                ? (a.data['clamp_max'] as num).toDouble()
                : null;

            // Apply hard clamps FIRST (authoritative)
            if (hardMin != null || hardMax != null) {
              final lo = hardMin ?? double.negativeInfinity;
              final hi = hardMax ?? double.infinity;
              next = next.clamp(lo, hi);
            }

            // -----------------------------
            // Plugin range clamp
            // -----------------------------
            if (pMin != null && pMax != null) {
              next = next.clamp(pMin, pMax);
            } else if (clamp01) {
              next = next.clamp(0.0, 1.0);
            }

            // await _undoManager.execute(
            //   SetEffectParamAction(
            //     row: row,
            //     effectIndex: fxIndex,
            //     paramId: paramName, // if your engine needs name instead, use paramName
            //     oldValue: current,
            //     newValue: next,
            //     onChange: () {
            //       setState(() {});
            //       _refreshRowFx(row);
            //     },
            //   ),
            // );

            EditorUndoAction finalAct = SetEffectParamAction(
              row: row,
              effectIndex: fxIndex,
              paramId:
                  paramName, // if your engine needs name instead, use paramName
              oldValue: current,
              newValue: next,
              onChange: () {
                setState(() {});
                _refreshRowFx(row);
              },
            );

            await _undoManager.executeWithoutAdd(
              finalAct,
            ); // need this so that you can make a compound undo action while preserving execute order
            groupedActions.add(finalAct);

            _mixHighlighter.trigger([
              HaloKey('row:$row'),
              HaloKey('row:$row:effects_tab'),
              HaloKey('row:$row:fx_list'),
              HaloKey('row:$row:fx_index:$fxIndex'),
              HaloKey(
                  'row:$row:fx_index:$fxIndex:param:$paramId'), // TODO: put paramName instead of paramId maybe
            ]);

            emitActionSummary(
              '• Adjusted $paramName from ${current.toStringAsFixed(2)} to ${next.toStringAsFixed(2)} on ${effects[fxIndex]} (${_rowDisplayName(row)}) •',
            );
            continue;
          }

        case 'adjust_master_effect_param_by_name':
          {
            final effectContains =
                (a.data['effect_name_contains'] as String).toLowerCase();
            final skipIfMissing =
                (a.data['skip_if_missing_effect'] as bool?) ?? true;

            final effects = await JuceAudioEngine.getMasterEffects();
            final fxIndex = effects
                .indexWhere((e) => e.toLowerCase().contains(effectContains));
            if (fxIndex == -1) {
              if (skipIfMissing) continue;
              continue;
            }

            final paramsRaw =
                await JuceAudioEngine.getMasterPluginParameters(fxIndex);
            final params =
                paramsRaw.map((e) => Map<String, dynamic>.from(e)).toList();

            final exactParamName = a.data['param_name'] as String?;
            final containsAny = (a.data['param_name_contains_any'] as List?)
                ?.map((e) => e.toString())
                .toList();

            final picked = _pickParam(params,
                exactName: exactParamName, containsAny: containsAny);
            if (picked == null) continue;

            final paramId =
                (picked['id'] as String?) ?? (picked['name'] as String);
            final paramName = (picked['name'] as String?) ?? paramId;
            final current = (picked['value'] as num).toDouble();

            final double? pMin =
                picked['min'] is num ? (picked['min'] as num).toDouble() : null;
            final double? pMax =
                picked['max'] is num ? (picked['max'] as num).toDouble() : null;

            final clamp01 = (a.data['clamp_0_1'] as bool?) ?? false;
            final mode = (a.data['mode'] as String?) ?? 'delta';

            double next = current;
            if (mode == 'set') {
              if (a.data.containsKey('value_norm') &&
                  pMin != null &&
                  pMax != null) {
                final vn =
                    (a.data['value_norm'] as num).toDouble().clamp(0.0, 1.0);
                next = pMin + (pMax - pMin) * vn;
              } else {
                next = (a.data['value'] as num).toDouble();
              }
            } else {
              double delta;
              if (a.data.containsKey('delta_norm')) {
                final dn = (a.data['delta_norm'] as num).toDouble();
                if (pMin != null && pMax != null) {
                  delta = dn * (pMax - pMin);
                } else {
                  delta = dn;
                }
              } else {
                delta = (a.data['delta'] as num).toDouble();
              }
              next = current + delta;
            }

            final double? hardMin = a.data['clamp_min'] is num
                ? (a.data['clamp_min'] as num).toDouble()
                : null;
            final double? hardMax = a.data['clamp_max'] is num
                ? (a.data['clamp_max'] as num).toDouble()
                : null;

            if (hardMin != null || hardMax != null) {
              final lo = hardMin ?? double.negativeInfinity;
              final hi = hardMax ?? double.infinity;
              next = next.clamp(lo, hi);
            }

            if (pMin != null && pMax != null) {
              next = next.clamp(pMin, pMax);
            } else if (clamp01) {
              next = next.clamp(0.0, 1.0);
            }

            final finalAct = SetMasterEffectParamAction(
              effectIndex: fxIndex,
              paramId: paramName,
              oldValue: current,
              newValue: next,
              onChange: () {
                setState(() {});
                unawaited(_refreshAutomationTargetsForAllRows());
              },
            );

            await _undoManager.executeWithoutAdd(finalAct);
            groupedActions.add(finalAct);

            emitActionSummary(
              '• Adjusted $paramName from ${current.toStringAsFixed(2)} to ${next.toStringAsFixed(2)} on ${effects[fxIndex]} (Master Bus) •',
            );
            continue;
          }

        case 'hard_reset_row_fx':
          {
            final rowCandidates = rowCandidatesFromAction(a.data);
            if (rowCandidates.isEmpty) continue;
            final row = rowCandidates.first;

            // Query actual FX list
            final effects = await JuceAudioEngine.getTrackEffectsForRow(row);

            if (effects.isEmpty) continue;

            // IMPORTANT: delete back-to-front to keep indices valid
            for (int fxIndex = effects.length - 1; fxIndex >= 0; fxIndex--) {
              final fxName = effects[fxIndex];

              EditorUndoAction act = RemoveEffectAction(
                row: row,
                effectIndex: fxIndex,
                pathOrName: fxName,
                onChange: () {
                  setState(() {});
                  _refreshRowFx(row);
                  unawaited(_refreshAutomationTargetsForRow(row));
                },
              );

              await _undoManager.executeWithoutAdd(act);
              groupedActions.add(act);
            }

            emitActionSummary(
              '• Removed all effects on ${_rowDisplayName(row)} •',
            );

            continue;
          }

        case 'hard_reset_master_fx':
          {
            final effects = await JuceAudioEngine.getMasterEffects();
            if (effects.isEmpty) continue;

            for (int fxIndex = effects.length - 1; fxIndex >= 0; fxIndex--) {
              final fxName = effects[fxIndex];
              final act = RemoveMasterEffectAction(
                effectIndex: fxIndex,
                pathOrName: fxName,
                onChange: () {
                  setState(() {});
                  unawaited(_refreshAutomationTargetsForAllRows());
                },
              );

              await _undoManager.executeWithoutAdd(act);
              groupedActions.add(act);
            }

            emitActionSummary('• Removed all effects on Master Bus •');
            continue;
          }

        default:
          // Unknown / noop → ignore safely
          continue;
      }
    }
    if (groupedActions.isEmpty) return 0;

    await _undoManager.addWithoutExecute(
        CompoundUndoAction('AI mixing adjustments', groupedActions));
    return groupedActions.length;
  }

  static const String _kAiRequestFailureMessage =
      "I couldn't complete that request just now. Please try again.";
  static const String _kAiApplyFailureMessage =
      "I understood the request, but I couldn't apply that change, so nothing changed.";

  void _reportAiChatFailure(
    Object error,
    StackTrace stackTrace, {
    required String stage,
  }) {
    aiDebugLog('audio-editor', 'ai chat failure stage=$stage error=$error');
    unawaited(
      CrashReportingService.instance.captureException(
        error,
        stackTrace: stackTrace,
      ),
    );
  }

  Map<String, dynamic> _aiObservabilityFromMeta(Map<String, dynamic>? meta) {
    if (meta == null) return const <String, dynamic>{};
    final raw = meta['observability'];
    if (raw is Map<String, dynamic>) {
      return raw;
    }
    if (raw is Map) {
      return raw.cast<String, dynamic>();
    }
    return const <String, dynamic>{};
  }

  int? _aiObservabilityInt(Map<String, dynamic> observability, String key) {
    final value = observability[key];
    if (value is int) return value;
    if (value is num) return value.toInt();
    return null;
  }

  String? _aiObservabilityString(
      Map<String, dynamic> observability, String key) {
    final value = observability[key]?.toString().trim() ?? '';
    return value.isEmpty ? null : value;
  }

  bool? _aiObservabilityBool(Map<String, dynamic> observability, String key) {
    final value = observability[key];
    if (value is bool) return value;
    return null;
  }

  Map<String, dynamic> _aiMap(dynamic raw) {
    if (raw is Map<String, dynamic>) return raw;
    if (raw is Map) return raw.cast<String, dynamic>();
    return const <String, dynamic>{};
  }

  Map<String, dynamic> _aiUsageFromMeta(Map<String, dynamic>? meta) {
    if (meta == null) return const <String, dynamic>{};
    return _aiMap(meta['usage']);
  }

  Map<String, dynamic> _aiSoftErrorFromMeta(Map<String, dynamic>? meta) {
    if (meta == null) return const <String, dynamic>{};
    return _aiMap(meta['soft_error']);
  }

  int? _aiAsInt(Object? raw) {
    if (raw is int) return raw;
    if (raw is num) return raw.toInt();
    if (raw is String) return int.tryParse(raw.trim());
    return null;
  }

  double? _aiAsDouble(Object? raw) {
    if (raw is double) return raw;
    if (raw is num) return raw.toDouble();
    if (raw is String) return double.tryParse(raw.trim());
    return null;
  }

  int? _aiFirstInt(List<Object?> candidates) {
    for (final candidate in candidates) {
      final value = _aiAsInt(candidate);
      if (value != null) return value;
    }
    return null;
  }

  double? _aiFirstDouble(List<Object?> candidates) {
    for (final candidate in candidates) {
      final value = _aiAsDouble(candidate);
      if (value != null) return value;
    }
    return null;
  }

  int _aiCachedPromptTokensFromUsage(Map<String, dynamic> usage) {
    for (final key in const <String>[
      'input_tokens_details',
      'prompt_tokens_details',
    ]) {
      final details = _aiMap(usage[key]);
      final cached = _aiAsInt(details['cached_tokens']);
      if (cached != null) return cached;
    }
    return 0;
  }

  int? _aiUsagePromptTokens(Map<String, dynamic>? meta) {
    final usage = _aiUsageFromMeta(meta);
    final observability = _aiObservabilityFromMeta(meta);
    return _aiFirstInt(<Object?>[
      usage['input_tokens'],
      usage['prompt_tokens'],
      usage['tokens_prompt'],
      usage['prompt_token_count'],
      observability['input_tokens'],
      observability['prompt_tokens'],
      observability['tokens_prompt'],
      observability['prompt_token_count'],
    ]);
  }

  int? _aiUsageCompletionTokens(Map<String, dynamic>? meta) {
    final usage = _aiUsageFromMeta(meta);
    final observability = _aiObservabilityFromMeta(meta);
    return _aiFirstInt(<Object?>[
      usage['output_tokens'],
      usage['completion_tokens'],
      usage['tokens_completion'],
      usage['completion_token_count'],
      observability['output_tokens'],
      observability['completion_tokens'],
      observability['tokens_completion'],
      observability['completion_token_count'],
    ]);
  }

  int? _aiUsageTotalTokens(Map<String, dynamic>? meta) {
    final usage = _aiUsageFromMeta(meta);
    final observability = _aiObservabilityFromMeta(meta);
    final direct = _aiFirstInt(<Object?>[
      usage['total_tokens'],
      usage['tokens_total'],
      usage['token_count'],
      observability['total_tokens'],
      observability['tokens_total'],
      observability['token_count'],
    ]);
    if (direct != null) return direct;
    final prompt = _aiUsagePromptTokens(meta);
    final completion = _aiUsageCompletionTokens(meta);
    if (prompt != null || completion != null) {
      return (prompt ?? 0) + (completion ?? 0);
    }
    return null;
  }

  int? _aiUsageCachedPromptTokens(Map<String, dynamic>? meta) {
    final usage = _aiUsageFromMeta(meta);
    final observability = _aiObservabilityFromMeta(meta);
    final direct = _aiFirstInt(<Object?>[
      meta?['cached_prompt_tokens'],
      usage['cached_prompt_tokens'],
      usage['prompt_cached_tokens'],
      observability['cached_prompt_tokens'],
      observability['prompt_cached_tokens'],
    ]);
    if (direct != null) return direct;
    final fromUsageDetails = _aiCachedPromptTokensFromUsage(usage);
    return fromUsageDetails > 0 ? fromUsageDetails : null;
  }

  double? _aiUsageEstimatedCostUsd(Map<String, dynamic>? meta) {
    final usage = _aiUsageFromMeta(meta);
    final observability = _aiObservabilityFromMeta(meta);
    final direct = _aiFirstDouble(<Object?>[
      usage['estimated_cost_usd'],
      usage['cost_usd'],
      usage['total_cost_usd'],
      usage['usd_cost'],
      usage['total_usd'],
      observability['estimated_cost_usd'],
      observability['cost_usd'],
      observability['total_cost_usd'],
      observability['usd_cost'],
      observability['total_usd'],
    ]);
    if (direct != null) return direct;

    final promptCost = _aiFirstDouble(<Object?>[
      usage['input_cost_usd'],
      usage['prompt_cost_usd'],
      observability['input_cost_usd'],
      observability['prompt_cost_usd'],
    ]);
    final completionCost = _aiFirstDouble(<Object?>[
      usage['output_cost_usd'],
      usage['completion_cost_usd'],
      observability['output_cost_usd'],
      observability['completion_cost_usd'],
    ]);
    if (promptCost != null || completionCost != null) {
      return (promptCost ?? 0) + (completionCost ?? 0);
    }
    return null;
  }

  String? _aiSoftErrorCodeFromMeta(Map<String, dynamic>? meta) {
    final softError = _aiSoftErrorFromMeta(meta);
    final code = (softError['code'] ?? '').toString().trim();
    return code.isEmpty ? null : code;
  }

  Future<void> _trackAiResponseOutcome({
    required String promptTraceId,
    required String aiFeature,
    required String projectId,
    Map<String, dynamic>? meta,
    String? fallbackErrorCode,
  }) async {
    final observability = _aiObservabilityFromMeta(meta);
    final runtimeConfigFingerprint =
        _aiObservabilityString(observability, 'runtime_config_fingerprint');
    final hasSystemPromptOverride =
        _aiObservabilityBool(observability, 'has_system_prompt_override');
    final modelName = _aiObservabilityString(observability, 'effective_model');
    final latencyMs = _aiFirstInt(<Object?>[
      observability['provider_roundtrip_ms'],
      observability['openai_api_ms'],
      observability['proxy_roundtrip_ms'],
    ]);
    final softErrorCode = _aiSoftErrorCodeFromMeta(meta);
    final errorCode = softErrorCode ?? fallbackErrorCode;
    if ((errorCode ?? '').trim().isNotEmpty) {
      await AnalyticsService.instance.track(
        AnalyticsEvents.aiResponseFailed(
          projectId: projectId,
          aiFeature: aiFeature,
          errorCode: errorCode!,
          promptTraceId: promptTraceId,
          runtimeConfigFingerprint: runtimeConfigFingerprint,
          hasSystemPromptOverride: hasSystemPromptOverride,
        ),
      );
      return;
    }

    await AnalyticsService.instance.track(
      AnalyticsEvents.aiResponseCompleted(
        projectId: projectId,
        aiFeature: aiFeature,
        modelName: modelName,
        promptTraceId: promptTraceId,
        runtimeConfigFingerprint: runtimeConfigFingerprint,
        hasSystemPromptOverride: hasSystemPromptOverride,
        latencyMs: latencyMs,
        tokensPrompt: _aiUsagePromptTokens(meta),
        tokensCompletion: _aiUsageCompletionTokens(meta),
        tokensTotal: _aiUsageTotalTokens(meta),
        cachedPromptTokens: _aiUsageCachedPromptTokens(meta),
        estimatedCostUsd: _aiUsageEstimatedCostUsd(meta),
      ),
    );
  }

  Future<void> _trackAiPromptCycleCompleted({
    required String promptTraceId,
    required String aiFeature,
    required String projectId,
    required Map<String, dynamic>? meta,
    required String toolName,
    required int promptCycleTotalMs,
    int? applyMixMs,
  }) async {
    final observability = _aiObservabilityFromMeta(meta);
    final modelName = _aiObservabilityString(observability, 'effective_model');
    final runtimeConfigFingerprint =
        _aiObservabilityString(observability, 'runtime_config_fingerprint');
    final hasSystemPromptOverride =
        _aiObservabilityBool(observability, 'has_system_prompt_override');
    final event = AnalyticsEvents.aiPromptCycleCompleted(
      projectId: projectId,
      aiFeature: aiFeature,
      promptTraceId: promptTraceId,
      toolName: toolName.isEmpty ? null : toolName,
      modelName: modelName,
      runtimeConfigFingerprint: runtimeConfigFingerprint,
      hasSystemPromptOverride: hasSystemPromptOverride,
      projectStatsMs: _aiObservabilityInt(observability, 'project_stats_ms'),
      proxyRoundtripMs:
          _aiObservabilityInt(observability, 'proxy_roundtrip_ms'),
      responseParseMs: _aiObservabilityInt(observability, 'response_parse_ms'),
      mixPlanMs: _aiObservabilityInt(observability, 'mix_plan_ms'),
      mixModelHeuristicMs:
          _aiObservabilityInt(observability, 'mix_model_heuristic_ms'),
      mixModelOnnxMs: _aiObservabilityInt(observability, 'mix_model_onnx_ms'),
      applyMixMs: applyMixMs,
