  Widget _transportSegment({
    required IconData icon,
    required VoidCallback? onTap,
    BorderRadius? radius,
    double iconSize = 20,
    Color? iconColor,
    Color? backgroundColor,
    Color? borderColor,
    List<BoxShadow>? boxShadow,
    String? haloKey,
  }) {
    final resolvedRadius = radius ?? BorderRadius.zero;
    Widget segmentChild = Material(
      color: Colors.transparent,
      borderRadius: resolvedRadius,
      clipBehavior: Clip.antiAlias,
      child: InkWell(
        borderRadius: resolvedRadius,
        splashFactory: InkRipple.splashFactory,
        splashColor: Colors.white.withValues(alpha: 0.14),
        highlightColor: Colors.white.withValues(alpha: 0.06),
        overlayColor: WidgetStateProperty.resolveWith<Color?>(
          (states) {
            if (states.contains(WidgetState.pressed)) {
              return Colors.white.withValues(alpha: 0.18);
            }
            if (states.contains(WidgetState.hovered)) {
              return Colors.white.withValues(alpha: 0.08);
            }
            if (states.contains(WidgetState.focused)) {
              return Colors.white.withValues(alpha: 0.10);
            }
            return Colors.transparent;
          },
        ),
        onTap: onTap,
        child: AnimatedContainer(
          duration: const Duration(milliseconds: 120),
          decoration: BoxDecoration(
            color: backgroundColor ?? Colors.transparent,
            borderRadius: resolvedRadius,
            border: borderColor != null ? Border.all(color: borderColor) : null,
            boxShadow: boxShadow,
          ),
          child: Center(
            child: Icon(icon, size: iconSize, color: iconColor ?? Colors.white),
          ),
        ),
      ),
    );

    if (haloKey != null && haloKey.isNotEmpty) {
      segmentChild = Halo(
        highlighter: _mixHighlighter,
        haloKey: HaloKey(haloKey),
        borderRadius: resolvedRadius,
        child: segmentChild,
      );
    }

    return Expanded(
      child: segmentChild,
    );
  }

