                                            builder: (context, t, child) {
                                              final clampedT =
                                                  t.clamp(0.0, 1.0);
                                              return Transform.translate(
                                                offset: Offset(
                                                    0, (1 - clampedT) * 22),
                                                child: Opacity(
                                                  opacity: clampedT,
                                                  child: ClipRect(
                                                    child: Align(
                                                      alignment:
